--
-- Name: fun_actualizarvalores(date, integer, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_actualizarvalores(fecha date, tracodigo integer, asicodigo integer) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$

DECLARE resultado character varying;
DECLARE identificador character varying;

BEGIN
identificador ='0'::character varying;
IF tracodigo <> 0 then  
identificador = (select tra.tra_identificador from asistencias.tbltrabajadores_tra as tra where tra.tra_codigo = tracodigo);
end IF;
 
-----actualziar calulos horas trabajadas, tardanzas, falta implementar
WITH subquery AS (
	 select * from  asistencias.fun_recalculogeneral (fecha::date,0, identificador,asicodigo)
)
UPDATE asistencias.tblasistencias_asi
SET asi_tardeingreso = subquery.IngresoTarde,
    asi_tardeingresorefrigerio  = subquery.TardeRefrigerio,
    asi_horas_trabajadas = subquery.horas_trabajadas,
    asi_horas_atrabajar = subquery.horas_atrabajar,
    asi_horas1 = 0,
    asi_horas2 = 0,
    asi_nocturno = subquery.dhr_nocturno
FROM subquery
WHERE asistencias.tblasistencias_asi.asi_codigo = subquery.asi_codigo;

 
  resultado ='OK';
 RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.fun_actualizarvalores(fecha date, tracodigo integer, asicodigo integer) OWNER TO postgres;

--
-- Name: fun_actualizarvaloresall(date, date, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_actualizarvaloresall(fechaini date, fechafin date, ident character varying) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$

DECLARE resultado character varying;
DECLARE tracodigo integer;
DECLARE varLoop RECORD;

BEGIN

 RAISE NOTICE 'vaasi  %',  fechaini::date;
FOR varLoop IN SELECT ASI.asi_codigo,tra.tra_identificador
    FROM 
      asistencias.tblasistencias_asi as asi
      inner join  asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = asi.tra_codigo
      where  case when ident = '' then true else tra.tra_identificador = ident end and asi.asi_fecha BETWEEN  fechaini::date and fechafin::date
       order by asi.asi_fecha asc,asi.asi_ingreso asc,tra.tra_apellidopaterno ASC 

  LOOP
     
       RAISE NOTICE 'vaasicodigo  %',  varLoop.asi_codigo::integer;
       RAISE NOTICE 'vaasi  %',  fechaini::date;
        WITH subquery AS (
           select * from  asistencias.fun_recalculogeneral (fechaini::date,0, '0',varLoop.asi_codigo::integer)
        )
        UPDATE asistencias.tblasistencias_asi
        SET asi_tardeingreso = subquery.IngresoTarde,
            asi_tardeingresorefrigerio  = subquery.TardeRefrigerio,
            asi_horas_trabajadas = subquery.horas_trabajadas,
            asi_horas_atrabajar = subquery.horas_atrabajar,
            asi_horas1 = 0,
            asi_horas2 = 0,
            asi_nocturno = subquery.dhr_nocturno
        FROM subquery
        WHERE asistencias.tblasistencias_asi.asi_codigo = subquery.asi_codigo;
        
  END LOOP;



 
  resultado ='OK';
 RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.fun_actualizarvaloresall(fechaini date, fechafin date, ident character varying) OWNER TO postgres;

