CREATE FUNCTION asistencias.fun_anual(anio character, trabajadorcodigo character varying, vararecodigo integer) RETURNS TABLE(tra_codigo integer, tra_nomcompleto character varying, tra_dni character varying, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, ene_1 double precision, feb_1 double precision, mar_1 double precision, abr_1 double precision, may_1 double precision, jun_1 double precision, jul_1 double precision, ago_1 double precision, set_1 double precision, act_1 double precision, nov_1 double precision, dic_1 double precision, ene_2 double precision, feb_2 double precision, mar_2 double precision, abr_2 double precision, may_2 double precision, jun_2 double precision, jul_2 double precision, ago_2 double precision, set_2 double precision, act_2 double precision, nov_2 double precision, dic_2 double precision, ene_3 double precision, feb_3 double precision, mar_3 double precision, abr_3 double precision, may_3 double precision, jun_3 double precision, jul_3 double precision, ago_3 double precision, set_3 double precision, act_3 double precision, nov_3 double precision, dic_3 double precision, ene_4 double precision, feb_4 double precision, mar_4 double precision, abr_4 double precision, may_4 double precision, jun_4 double precision, jul_4 double precision, ago_4 double precision, set_4 double precision, act_4 double precision, nov_4 double precision, dic_4 double precision, ene_5 double precision, feb_5 double precision, mar_5 double precision, abr_5 double precision, may_5 double precision, jun_5 double precision, jul_5 double precision, ago_5 double precision, set_5 double precision, act_5 double precision, nov_5 double precision, dic_5 double precision, ene_6 double precision, feb_6 double precision, mar_6 double precision, abr_6 double precision, may_6 double precision, jun_6 double precision, jul_6 double precision, ago_6 double precision, set_6 double precision, act_6 double precision, nov_6 double precision, dic_6 double precision, ene_7 double precision, feb_7 double precision, mar_7 double precision, abr_7 double precision, may_7 double precision, jun_7 double precision, jul_7 double precision, ago_7 double precision, set_7 double precision, act_7 double precision, nov_7 double precision, dic_7 double precision, ene_8 double precision, feb_8 double precision, mar_8 double precision, abr_8 double precision, may_8 double precision, jun_8 double precision, jul_8 double precision, ago_8 double precision, set_8 double precision, act_8 double precision, nov_8 double precision, dic_8 double precision, ene_9 double precision, feb_9 double precision, mar_9 double precision, abr_9 double precision, may_9 double precision, jun_9 double precision, jul_9 double precision, ago_9 double precision, set_9 double precision, act_9 double precision, nov_9 double precision, dic_9 double precision, ene_10 double precision, feb_10 double precision, mar_10 double precision, abr_10 double precision, may_10 double precision, jun_10 double precision, jul_10 double precision, ago_10 double precision, set_10 double precision, act_10 double precision, nov_10 double precision, dic_10 double precision, ene_11 double precision, feb_11 double precision, mar_11 double precision, abr_11 double precision, may_11 double precision, jun_11 double precision, jul_11 double precision, ago_11 double precision, set_11 double precision, act_11 double precision, nov_11 double precision, dic_11 double precision, ene_12 double precision, feb_12 double precision, mar_12 double precision, abr_12 double precision, may_12 double precision, jun_12 double precision, jul_12 double precision, ago_12 double precision, set_12 double precision, act_12 double precision, nov_12 double precision, dic_12 double precision, ene_13 double precision, feb_13 double precision, mar_13 double precision, abr_13 double precision, may_13 double precision, jun_13 double precision, jul_13 double precision, ago_13 double precision, set_13 double precision, act_13 double precision, nov_13 double precision, dic_13 double precision, ene_14 double precision, feb_14 double precision, mar_14 double precision, abr_14 double precision, may_14 double precision, jun_14 double precision, jul_14 double precision, ago_14 double precision, set_14 double precision, act_14 double precision, nov_14 double precision, dic_14 double precision)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD;  
  tmar2 RECORD;
  varTracodigo character varying;
 -- trep RECORD;
BEGIN
varTracodigo := '0';
IF trabajadorcodigo <> '' THEN
    select tem.tra_codigo::character varying
    INTO varTracodigo
    from asistencias.tbltrabajadores_tra as tem where tem.tra_identificador = CAST(trabajadorcodigo AS VARCHAR);
END IF;

--Desde este punto es una tabla temporal de la horas extras
CREATE TEMPORARY TABLE tmarcacionesExtras (
cod integer,
tipo character varying,
tra_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
ingresoR timestamp without time zone,
salidaR timestamp without time zone,
hor_codigo integer,
horas1 double precision default 0,--tarde regrigerio
horas2 double precision default 0,
horas double precision default 0, -- horas trabajadas
hora_atrabajar double precision default 0,
tardeingreso double precision default 0,
tarderefrigerio double precision default 0
); 
  asi.asi_ingreso ,asi.asi_salida,asi.asi_salidarefrigerio,asi.asi_ingresorefrigerio ,
  asi.asi_horas_atrabajar,asi.asi_horas_trabajadas,
  case when asi.asi_tardeingreso > 0 then asi.asi_tardeingreso else 0 end
  ,case when asi.asi_tardeingresorefrigerio > 0 then asi.asi_tardeingresorefrigerio else 0 end ,
  asi.hor_codigo
  --,case when asi.mar_martipo in ('A','X') then  asi.asi_horas_trabajadas + coalesce(extract(epoch from age( asi.asi_ingresorefrigerio,asi.asi_salidarefrigerio)),0)  else asi.asi_horas_trabajadas   end    
  from asistencias.tblasistencias_asi as asi
 WHERE cast(asi.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end)
 and asi.mar_martipo is not null and asi.mar_martipo <> 'U');

--****************************************************************************************************
--segunda tablatempral temporal 
 CREATE TEMPORARY TABLE tmarcaciones (
feriado char(1),
tra_codigo integer,
hor_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,
horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision default 0,
horas_tardesalida double precision default 0,
tipo character varying,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,
e_permisomasivojustificado boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
h_permisomasivojustificado double precision,

horas_trabajadas_remuneradas double precision
);

--ingresa las marcacaiones normales y remuneradas
ingreso, salida, ingresorefrigerio ,salidarefrigerio,
horas_atrabajar, horas_trabajadas, horas_tardeingreso,horas_tardesalida,tipo,horas_trabajadas_remuneradas)
(select cal.cal_tipo ,asi.tra_codigo, asi.hor_codigo,asi.asi_fecha,
  asi.asi_ingreso ,asi.asi_salida,asi.asi_salidarefrigerio,asi.asi_ingresorefrigerio ,
  asi.asi_horas_atrabajar, asi.asi_horas_trabajadas,
  case when asi.asi_tardeingreso > 0 then asi.asi_tardeingreso else 0 end
  ,case when asi.asi_tardeingresorefrigerio > 0 then asi.asi_tardeingresorefrigerio else 0 end 
  , asi.mar_martipo,
  CASE WHEN asi.asi_horas_trabajadas = asi.asi_horas_atrabajar THEN 0 ELSE asi.asi_horas_atrabajar END 
   from asistencias.tblasistencias_asi as asi
  inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = asi.asi_fecha
 WHERE cast(asi.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end)
 and EXTRACT(year from asi.asi_fecha) = anio::integer 
 and (asi.mar_martipo is null or asi.mar_martipo = 'U' ) );


---llena lo dias sin marcacaiones
cal.cal_tipo,
tra.tra_codigo,
hor.hor_codigo,
fht.fht_fecha,
(extract(epoch from age( 
case when dhr.dhr_nocturno 
  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
  else cast(now() as date)+ dhr.dhr_salida end
  ,cast(now() as date) + dhr.dhr_ingreso  
  ) ) - (case when dhr.dhr_increfrigerio then  0 else (dhr.dhr_tiemporefrigerio *60)  end) )/*/3600*/  as nhoras

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
--left join asistencias.tblasistencias_asi as asi on fht.fht_fecha <> asi.asi_fecha
WHERE cast(tra.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end)
and EXTRACT(year from fht.fht_fecha) = anio::integer and 
 fht.fht_fecha not in (
 select asi.asi_fecha from asistencias.tblasistencias_asi as asi where  EXTRACT(year from asi.asi_fecha) = anio::integer and
 cast(asi.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end ) and (asi.mar_martipo is null ) order by asi.asi_fecha )
order  by fht.fht_fecha asc
);

--ingresa los permisos
FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo  left join asistencias.tbltrabajadores_tra as a on p.tra_codigo = a.tra_codigo where
                cast(P.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end) LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcaciones SET e_comision = true, h_comision= tmarcaciones.horas_trabajadas
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcaciones SET e_vacaciones = true , h_vacaciones = tmarcaciones.horas_atrabajar 
  WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin and 
        CASE WHEN rvacaciones.are_codigo IN (161,171) THEN  tmarcaciones.feriado <> 'F' and  TRIM(to_char(tmarcaciones.fecha, 'Day'))  <> TRIM('Sunday   ') ELSE TRUE END and 
        case when rvacaciones.are_codigo = 161 and rvacaciones.tra_codigo <> 371 then    TRIM(to_char(tmarcaciones.fecha, 'Day'))  <> TRIM('Saturday ') else true  END  ;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcaciones SET e_medico= true , h_medico = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcaciones SET e_permisos = true , h_permisos = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcaciones SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcaciones SET e_compensacion  = true , h_compensacion  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
  -- permiso masivo justificado
   IF rvacaciones.tip_codigo = 24 THEN 
   UPDATE tmarcaciones SET e_permisomasivojustificado  = true , h_permisomasivojustificado  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;       
END LOOP;

