 FOR tra2 IN Select * from  asistencias.tbltrabajadores_tra as trab  
            inner join asistencias.tblareas_are as are on are.are_codigo = trab.are_codigo
            inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = trab.pue_codigo
            WHERE cast(trab.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end) LOOP 

--horas trabajadas 1
(coalesce((select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date ) and t.tipo is null AND t.feriado  <>'F'),0)
  +coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date ) and td.tipo ='A'),0)) /3600,
(coalesce((select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date ) and t.tipo is null AND t.feriado  <>'F'),0)
  +coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date ) and td.tipo ='A'),0)) /3600,
(coalesce((select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date ) and t.tipo is null AND t.feriado  <>'F'),0)
