coalesce(trep.set_1 , 0) +coalesce(trep.set_3 , 0) +coalesce(trep.set_4 , 0) + coalesce(trep.set_5 , 0) + coalesce(trep.set_14 , 0) - coalesce(trep.set_8 , 0) - coalesce(trep.set_7 , 0) - coalesce(trep.set_6 , 0) as set_12,
coalesce(trep.act_1 , 0) +coalesce(trep.act_3 , 0) +coalesce(trep.act_4 , 0) + coalesce(trep.act_5 , 0) + coalesce(trep.act_14 , 0) - coalesce(trep.act_8 , 0) - coalesce(trep.act_7 , 0) - coalesce(trep.act_6 , 0) as act_12,
coalesce(trep.nov_1 , 0) +coalesce(trep.nov_3 , 0) +coalesce(trep.nov_4 , 0) + coalesce(trep.nov_5 , 0) + coalesce(trep.nov_14 , 0) - coalesce(trep.nov_8 , 0) - coalesce(trep.nov_7 , 0) - coalesce(trep.nov_6 , 0) as nov_12,
coalesce(trep.dic_1 , 0) +coalesce(trep.dic_3 , 0) +coalesce(trep.dic_4 , 0) + coalesce(trep.dic_5 , 0) + coalesce(trep.dic_14 , 0) - coalesce(trep.dic_8 , 0) - coalesce(trep.dic_7 , 0) - coalesce(trep.dic_6 , 0) as dic_12,
--diferencia acumulada 
coalesce(trep.ene_1 , 0) +coalesce(trep.ene_3 , 0) +coalesce(trep.ene_4 , 0) + coalesce(trep.ene_5 , 0) + coalesce(trep.ene_14 , 0) - coalesce(trep.ene_8 , 0) - coalesce(trep.ene_7 , 0) -coalesce(trep.ene_6 , 0) as ene_13,
coalesce(trep.feb_1 , 0) +coalesce(trep.feb_3 , 0) +coalesce(trep.feb_4 , 0) + coalesce(trep.feb_5 , 0) + coalesce(trep.feb_14 , 0) - coalesce(trep.feb_8 , 0) - coalesce(trep.feb_7 , 0) -coalesce(trep.feb_6 , 0) as feb_13,
coalesce(trep.mar_1 , 0) +coalesce(trep.mar_3 , 0) +coalesce(trep.mar_4 , 0) + coalesce(trep.mar_5 , 0) + coalesce(trep.mar_14 , 0) - coalesce(trep.mar_8 , 0) - coalesce(trep.mar_7 , 0) -coalesce(trep.mar_6 , 0) as mar_13,
coalesce(trep.abr_1 , 0) +coalesce(trep.abr_3 , 0) +coalesce(trep.abr_4 , 0) + coalesce(trep.abr_5 , 0) + coalesce(trep.abr_14 , 0) - coalesce(trep.abr_8 , 0) - coalesce(trep.abr_7 , 0) -coalesce(trep.abr_6 , 0) as abr_13,
coalesce(trep.may_1 , 0) +coalesce(trep.may_3 , 0) +coalesce(trep.may_4 , 0) + coalesce(trep.may_5 , 0) + coalesce(trep.may_14 , 0) - coalesce(trep.may_8 , 0) - coalesce(trep.may_7 , 0) -coalesce(trep.may_6 , 0) as may_13,
coalesce(trep.jun_1 , 0) +coalesce(trep.jun_3 , 0) +coalesce(trep.jun_4 , 0) + coalesce(trep.jun_5 , 0) + coalesce(trep.jun_14 , 0) - coalesce(trep.jun_8 , 0) - coalesce(trep.jun_7 , 0) -coalesce(trep.jun_6 , 0) as jun_13,
coalesce(trep.jul_1 , 0) +coalesce(trep.jul_3 , 0) +coalesce(trep.jul_4 , 0) + coalesce(trep.jul_5 , 0) + coalesce(trep.jul_14 , 0) - coalesce(trep.jul_8 , 0) - coalesce(trep.jul_7 , 0) -coalesce(trep.jul_6 , 0) as jul_13,
coalesce(trep.ago_1 , 0) +coalesce(trep.ago_3 , 0) +coalesce(trep.ago_4 , 0) + coalesce(trep.ago_5 , 0) + coalesce(trep.ago_14 , 0) - coalesce(trep.ago_8 , 0) - coalesce(trep.ago_7 , 0) -coalesce(trep.ago_6 , 0) as ago_13,
coalesce(trep.set_1 , 0) +coalesce(trep.set_3 , 0) +coalesce(trep.set_4 , 0) + coalesce(trep.set_5 , 0) + coalesce(trep.set_14 , 0) - coalesce(trep.set_8 , 0) - coalesce(trep.set_7 , 0) -coalesce(trep.set_6 , 0) as set_13,
coalesce(trep.act_1 , 0) +coalesce(trep.act_3 , 0) +coalesce(trep.act_4 , 0) + coalesce(trep.act_5 , 0) + coalesce(trep.act_14 , 0) - coalesce(trep.act_8 , 0) - coalesce(trep.act_7 , 0) -coalesce(trep.act_6 , 0) as act_13,
coalesce(trep.nov_1 , 0) +coalesce(trep.nov_3 , 0) +coalesce(trep.nov_4 , 0) + coalesce(trep.nov_5 , 0) + coalesce(trep.nov_14 , 0) - coalesce(trep.nov_8 , 0) - coalesce(trep.nov_7 , 0) -coalesce(trep.nov_6 , 0) as nov_13,
coalesce(trep.dic_1 , 0) +coalesce(trep.dic_3 , 0) +coalesce(trep.dic_4 , 0) + coalesce(trep.dic_5 , 0) + coalesce(trep.dic_14 , 0) - coalesce(trep.dic_8 , 0) - coalesce(trep.dic_7 , 0) -coalesce(trep.dic_6 , 0) as dic_13,

 --horas extras remuneradas

coalesce(trep.ene_11 , 0) + coalesce(trep.ene_12 , 0) as ene_14,
coalesce(trep.feb_11 , 0) + coalesce(trep.feb_12 , 0) as feb_14,
coalesce(trep.mar_11 , 0) + coalesce(trep.mar_12 , 0) as mar_14,
coalesce(trep.abr_11 , 0) + coalesce(trep.abr_12 , 0) as abr_14,
coalesce(trep.may_11 , 0) + coalesce(trep.may_12 , 0) as may_14,
coalesce(trep.jun_11 , 0) + coalesce(trep.jun_12 , 0) as jun_14,
coalesce(trep.jul_11 , 0) + coalesce(trep.jul_12 , 0) as jul_14,
coalesce(trep.ago_11 , 0) + coalesce(trep.ago_12 , 0) as ago_14,
coalesce(trep.set_11 , 0) + coalesce(trep.set_12 , 0) as set_14,
coalesce(trep.act_11 , 0) + coalesce(trep.act_12 , 0) as act_14,
coalesce(trep.nov_11 , 0) + coalesce(trep.nov_12 , 0) as nov_14,
coalesce(trep.dic_11 , 0) + coalesce(trep.dic_12 , 0) as dic_14

 from trespuestas as trep);



            
 RETURN QUERY EXECUTE 'SELECT * FROM treporte';
END;
$$;


ALTER FUNCTION asistencias.fun_anual(anio character, trabajadorcodigo character varying, vararecodigo integer) OWNER TO postgres;

--
-- Name: fun_asistenciaall(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_asistenciaall(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, pue_nombre character varying, fecha date, tipodescripcion character varying, tardansa character varying, tardansarefrigerio character varying, are_nombre character varying, dhr_dia character varying, hora1 character varying, hora2 character varying, hora3 character varying, hora4 character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY select 
f.emp_razon ,f.emp_ruc,
f.tra_codigo ,f.tra_nombre ,f.tra_apellidopaterno,f.tra_apellidomaterno, f.tra_dni,f.tra_identificador,
f.pue_nombre,f.fecha ,
--dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
case when (f.fuerahorario) 
    THEN
          'Fuera Horario'
    ELSE 
        (CASE WHEN (f.tipodescripcion is  null)
            THEN
               CASE WHEN (f.ingreso is not null or f.salida is not null or f.ingresorefrigerio is  not null or f.salidarefrigerio is not null) 
          THEN 'Marco' ELSE 'No Marco' END
        --     WHEN (f.tipodescripcion is null) THEN 'No Marco'
            ELSE f.tipodescripcion
          END)
END as tipodescripcion
/*,tra_estado,
are_codigo,are_nombre,pue_codigo  ,hor_codigo ,hor_nombre,

dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida */
/*
, CASE WHEN (to_char(ingreso, 'hh:MI')) > to_char((dhr_ingreso + dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN ingreso - (cast(ingreso as date)+ dhr_ingreso) END as tardansa 
, CASE WHEN (to_char(salidarefrigerio + dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((ingresorefrigerio + dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI') 
 THEN salidarefrigerio - (ingresorefrigerio  + dhr_tiemporefrigerio * (interval '1 minute')) END as tardansarefrigerio
*/
 ,cast( CASE WHEN (to_char(f.ingreso, 'hh:MI')) > to_char((f.dhr_ingreso + f.dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN 'IT' else '' END as varchar)as tardansa 
, cast( CASE WHEN (to_char(f.salidarefrigerio + f.dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((f.ingresorefrigerio + f.dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI') 
 THEN 'TR' else '' END as varchar)as tardansarefrigerio,
 f.are_nombre,
 f.dhr_dia,

cast( to_char(f.ingreso, 'HH24:MI:SS') as varchar)as hora1,  
cast( to_char(f.salidarefrigerio, 'HH24:MI:SS') as varchar) as hora2,
cast( to_char(f.ingresorefrigerio, 'HH24:MI:SS') as varchar) as hora3,
cast( to_char(f.salida, 'HH24:MI:SS') as varchar)  as hora4  ,
  f.are_codigo
 from asistencias.fun_global 
 ( fechaini ,  fechafin ,  codarea ,  codhorario ,  codtrabajador )as f
 order by f.are_codigo , f.tra_codigo , f.fecha ;
--('2016-01-01','2019-01-01', 0,0,'') as f



    
END;
$$;


