f.emp_razon ,f.emp_ruc,
f.tra_codigo ,f.tra_nombre ,f.tra_apellidopaterno,f.tra_apellidomaterno, f.tra_dni,f.tra_identificador,
f.pue_nombre,f.fecha ,
--dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
/*case when (f.fuerahorario) 
    THEN
          'Trabajo Autorizado'
    ELSE*/ 
        CASE WHEN (f.tipodescripcion is  null)
            THEN
               CASE WHEN (f.ingreso is not null or f.salida is not null or f.ingresorefrigerio is  not null or f.salidarefrigerio is not null or f.ingresoextra is not null or f.salidaextra is not null or f.ingresorefrigerioextra is  not null or f.salidarefrigerioextra is not null) 
              THEN f.descripcion_marc ELSE 'No Marco' 
              END
