            ELSE (case when f.hor_codigo = 9999 
                  THEN  (case when (TRIM(f.descripcion_marc) = 'Horario Libre' or f.descripcion_marc is null ) then f.tipodescripcion else  (f.tipodescripcion ||chr(10) ||f.descripcion_marc) end )
                  ELSE( CASE WHEN (f.tipodescripcion != 'Feriado' ) THEN f.tipodescripcion  ELSE (case when (TRIM(f.descripcion_marc) = 'Horario Normal' or f.descripcion_marc is null ) then f.tipodescripcion else  (f.tipodescripcion ||chr(10) ||f.descripcion_marc) end )END  )END)
          
END as tipodescripcion


 ,(case when f.hor_codigo = 9999 or f.hor_codigo = 131 then '' else (cast( CASE WHEN (to_char(f.ingreso, 'hh:MI')) > to_char((f.dhr_ingreso + f.dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN 'IT' else '' END as varchar))end ) as tardansa 
,(case when f.hor_codigo = 9999 or f.hor_codigo = 131 then '' else (cast( CASE WHEN (to_char(f.salidarefrigerio + f.dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((f.ingresorefrigerio + f.dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI') 
 THEN 'TR' else '' END as varchar))end ) as tardansarefrigerio,
 f.are_nombre,
 f.dhr_dia,

cast( to_char(f.ingreso, 'HH24:MI:SS') as varchar)as hora1,  
cast( to_char(f.salidarefrigerio, 'HH24:MI:SS') as varchar) as hora2,
cast( to_char(f.ingresorefrigerio, 'HH24:MI:SS') as varchar) as hora3,
cast( to_char(f.salida, 'HH24:MI:SS') as varchar)  as hora4  ,
cast( to_char(f.ingresoextra, 'HH24:MI:SS') as varchar)as horaextra1,  
cast( to_char(f.salidarefrigerioextra, 'HH24:MI:SS') as varchar) as horaextra2,
cast( to_char(f.ingresorefrigerioextra, 'HH24:MI:SS') as varchar) as horaextra3,
cast( to_char(f.salidaextra, 'HH24:MI:SS') as varchar)  as horaextra4  ,
f.ingresoextra2 as horaextra21,  
f.salidarefrigerioextra2  as horaextra22,
f.ingresorefrigerioextra2  as horaextra23,
f.salidaextra2  as horaextra24  ,
  f.are_codigo,f.hor_nombre
 from asistencias.fun_global3 
 ( fechaini ,  fechafin ,  codarea ,  codhorario ,  codtrabajador )as f
 order by f.are_codigo , f.tra_codigo , f.fecha ;
--('2016-01-01','2019-01-01', 0,0,'') as f



    
END;
$$;


ALTER FUNCTION asistencias.fun_asistenciaall3(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_asistenciaallbat(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_asistenciaallbat(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, pue_nombre character varying, fecha date, tipodescripcion character varying, tardansa character varying, tardansarefrigerio character varying, are_nombre character varying, dhr_dia character varying, hora1 character varying, hora2 character varying, hora3 character varying, hora4 character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY select 
f.emp_razon ,f.emp_ruc,
f.tra_codigo ,f.tra_nombre ,f.tra_apellidopaterno,f.tra_apellidomaterno, f.tra_dni,f.tra_identificador,
f.pue_nombre,f.fecha ,
--dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
/*CASE WHEN (f.tipodescripcion is  null) and (f.dhr_ingreso is not null or f.dhr_salida is not null or f.dhr_salidarefrigerio is not null or f.dhr_ingresorefrigerio is not null) 
       THEN 'Marco'
     WHEN (f.tipodescripcion is null) THEN 'No Marco'
       ELSE f.tipodescripcion
END as tipodescripcion*/
CASE WHEN (f.tipodescripcion is  null)
    THEN
       CASE WHEN (f.ingreso is not null or f.salida is not null or f.ingresorefrigerio is  not null or f.salidarefrigerio is not null) 
	THEN 'Marco' ELSE 'No Marco' END
--     WHEN (f.tipodescripcion is null) THEN 'No Marco'
    ELSE f.tipodescripcion
END as tipodescripcion
/*,tra_estado,
are_codigo,are_nombre,pue_codigo  ,hor_codigo ,hor_nombre,

dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida */
/*
, CASE WHEN (to_char(ingreso, 'hh:MI')) > to_char((dhr_ingreso + dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN ingreso - (cast(ingreso as date)+ dhr_ingreso) END as tardansa 
, CASE WHEN (to_char(salidarefrigerio + dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((ingresorefrigerio + dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI') 
 THEN salidarefrigerio - (ingresorefrigerio  + dhr_tiemporefrigerio * (interval '1 minute')) END as tardansarefrigerio
*/
 ,cast( CASE WHEN (to_char(f.ingreso, 'hh:MI')) > to_char((f.dhr_ingreso + f.dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN 'IT' else '' END as varchar)as tardansa 
, cast( CASE WHEN (to_char(f.salidarefrigerio + f.dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((f.ingresorefrigerio + f.dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI') 
 THEN 'TR' else '' END as varchar)as tardansarefrigerio,
 f.are_nombre,
 f.dhr_dia,

cast( to_char(f.ingreso, 'HH24:MI:SS') as varchar)as hora1,  
cast( to_char(f.salidarefrigerio, 'HH24:MI:SS') as varchar) as hora2,
cast( to_char(f.ingresorefrigerio, 'HH24:MI:SS') as varchar) as hora3,
cast( to_char(f.salida, 'HH24:MI:SS') as varchar)  as hora4  ,
  f.are_codigo
 from asistencias.fun_globalbat 
 ( fechaini ,  fechafin ,  codarea ,  codhorario ,  codtrabajador )as f
 order by f.are_codigo , f.tra_codigo , f.fecha ;
--('2016-01-01','2019-01-01', 0,0,'') as f



    
END;
$$;


