ALTER FUNCTION asistencias.fun_asistenciaallbat_3(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_asistencias(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_asistencias(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(rank bigint, emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, htr_id integer, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, dhr_dia character varying, ingreso character varying, salida character varying, ingresorefrigerio character varying, salidarefrigerio character varying, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, _comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, e_permisomasivojustificado boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, h_permisomasivojustificado double precision, tipodescripcion character varying, tardansa character varying, tardansarefrigerio character varying, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_ingresorefrigerio time without time zone, dhr_salidarefrigerio time without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD; 
  nombredia character varying; 
  mmarcaciones RECORD;
  ingresotemp character varying;
  marcacionesx RECORD;
  descripcionmarcacion character varying;
  htrRecord RECORD;
  htrId integer;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALL (
rank bigint,  
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,

htr_id integer, 
are_codigo integer,
are_nombre character varying(50),

pue_codigo integer,
pue_nombre character varying(50),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,

dhr_dia character varying(12),

ingreso varchar,
salida varchar,
ingresorefrigerio varchar,
salidarefrigerio varchar,


horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,
e_permisomasivojustificado boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
h_permisomasivojustificado double precision,
tipodescripcion varchar(100),

tardansa varchar(2),
tardansarefrigerio varchar(2),

dhr_ingreso time(0),
dhr_salida time(0),
dhr_ingresorefrigerio time(0),
dhr_salidarefrigerio time(0)
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,dhr_dia ,tipodescripcion,
ingreso,ingresorefrigerio ,salidarefrigerio,salida ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,
tardansa,tardansarefrigerio,
dhr_ingreso,dhr_salida,dhr_ingresorefrigerio,dhr_salidarefrigerio)
(
select  row_number() over (order by tra.tra_codigo ) as rank, 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo ,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,
--are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,
--hor.hor_codigo,hor.hor_nombre,
case when  are2.are_codigo IS NULL THEN (SELECT a.are_codigo from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblareas_are as a on a.are_codigo = h.are_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE are2.are_codigo END  AS are2_codigo ,
case when  are2.are_nombre IS NULL THEN (SELECT a.are_nombre from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblareas_are as a on a.are_codigo = h.are_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1)  ELSE are2.are_nombre END  AS are2_nombre ,
case when  pue2.pue_codigo IS NULL THEN (SELECT p.pue_codigo from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblpuestos_pue as p on p.pue_codigo = h.pue_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE pue2.pue_codigo END  AS pue2_codigo ,
case when  pue2.pue_nombre IS NULL THEN (SELECT p.pue_nombre from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblpuestos_pue as p on p.pue_codigo = h.pue_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE pue2.pue_nombre END  AS pue2_nombre ,
case WHEN hor2.hor_codigo is null then  hor.hor_codigo ELSE case when hor.hor_codigo = hor2.hor_codigo then hor.hor_codigo else  hor2.hor_codigo end END  as hor2_codigo,
case WHEN hor2.hor_codigo is null then  hor.hor_nombre ELSE case when hor.hor_codigo = hor2.hor_codigo then  hor.hor_nombre else  concat(hor.hor_nombre,' / ',hor2.hor_nombre) end END as hor2_nombre ,
fht.fht_fecha as fecha ,dhr.dhr_dia,
case when cal.cal_tipo ='N' then
      case when asi.asi_tipomarca is null 
      then  (case when  hor.hor_codigo = 116 then 'DESCANSO' else 
      'No Marco' end ) else  asi.asi_tipomarca end 
  else  case when asi.asi_tipomarca is null then 'Feriado' else  concat('Feriado' , ' / ', asi.asi_tipomarca )end
 end as tipodescripcion,
 -- asi.asi_tipomarca , asi.mar_martipo, asi.asi_fecha ,

  cast( to_char(asi.asi_ingreso::time, 'HH24:MI:SS') as varchar) as hora1 ,
  cast( to_char(asi.asi_salidarefrigerio::time, 'HH24:MI:SS') as varchar) as hora2,
   cast( to_char(asi.asi_ingresorefrigerio::time, 'HH24:MI:SS') as varchar) as hora3,
   cast( to_char(asi.asi_salida::time, 'HH24:MI:SS') as varchar) as hora4,

  --asi.asi_nocturno ,
  --asi.asi_tipooperacion,

  asi.asi_horas_atrabajar ,
  asi.asi_horas_trabajadas,
  asi.asi_tardeingreso ,
  asi.asi_tardeingresorefrigerio 
   ,(case when hor.hor_codigo = 9999 or hor.hor_codigo = 131 then '' else (cast( CASE WHEN (to_char(asi.asi_ingreso, 'hh:MI')) > to_char((dhr.dhr_ingreso + dhr.dhr_tolingreso * (interval '1 minute')), 'hh:MI')
 THEN 'IT' else '' END as varchar))end ) as tardansa
,(case when hor.hor_codigo = 9999 or hor.hor_codigo = 131 then '' else   (cast( CASE WHEN (to_char(asi.asi_ingresorefrigerio  , 'hh:MI')) > to_char((dhr.dhr_salidarefrigerio + dhr.dhr_tiemporefrigerio * (interval '1 minute') + dhr.dhr_tolingresorefrigerio * (interval '1 minute') ), 'hh:MI') -- (cast( CASE WHEN (to_char(asi.asi_salidarefrigerio + dhr.dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((asi.asi_ingresorefrigerio + dhr.dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI')
 THEN 'TR' else '' END as varchar))end ) as tardansarefrigerio,
dhr.dhr_ingreso, dhr.dhr_salida, dhr.dhr_salidarefrigerio,dhr.dhr_ingresorefrigerio
from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
left join asistencias.tblasistencias_asi as asi on asi.tra_codigo=tra.tra_codigo and asi.asi_fecha = fht.fht_fecha
left join asistencias.tblareas_are as are2 on are2.are_codigo = asi.are_codigo
left join asistencias.tblpuestos_pue as pue2 on pue2.pue_codigo = asi.pue_codigo
left join asistencias.tblhorarios_hor  as hor2 on hor2.hor_codigo = asi.hor_codigo 
, asistencias.tblempresa_emp as emp
where
fht.fht_fecha  BETWEEN fechaini::date and fechafin::date and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador )  end)
and tra.tra_estado = true
order by are.are_nombre, tra.tra_codigo, fht.fht_fecha asc, asi.asi_ingreso asc, asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc, asi.asi_salida asc
);


FOR rvacaciones IN Select p.*,t.* from asistencias.tblpermisos_per as p 
                  inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo 
                  inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = p.tra_codigo
                  inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo 
                  where cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
                  cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador )  end)

  LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcacionesALL SET e_comision = true, h_comision= tmarcacionesALL.horas_trabajadas 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcacionesALL SET e_vacaciones = true , h_vacaciones = tmarcacionesALL.horas_atrabajar 
    , tipodescripcion =  rvacaciones.tip_nombre 
  WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcacionesALL SET e_medico= true , h_medico = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcacionesALL SET e_permisos = true , h_permisos = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcacionesALL SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcacionesALL SET e_compensacion  = true , h_compensacion  = tmarcacionesALL.horas_atrabajar
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;   
   -- permiso masivo justificado
   IF rvacaciones.tip_codigo = 24 THEN 
   UPDATE tmarcacionesALL SET e_permisomasivojustificado  = true , h_permisomasivojustificado  = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
      
END LOOP;
            

FOR htrRecord IN SELECT * FROM tmarcacionesALL order by fecha asc,are_nombre asc, tra_apellidopaterno asc , tra_apellidomaterno asc, tra_nombre asc, ingreso asc , ingresorefrigerio ASC, salidarefrigerio ASC

  LOOP
      SELECT h.htr_id INTO htrId from asistencias.tblhistorialtrabajadores_htr as h where h.tra_codigo=htrRecord.tra_codigo and htrRecord.are_codigo =  h.are_codigo and htrRecord.pue_codigo = h.pue_codigo and  htrRecord.fecha BETWEEN h.htr_fecinicio and  h.htr_fecfin  limit 1 ;

      IF htrId IS NOT NULL THEN 

        UPDATE tmarcacionesALL
               SET htr_id = htrId
        WHERE tmarcacionesALL.rank = htrRecord.rank ;
	htrId= null;
      END IF;

END LOOP;

 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALL order by tra_apellidopaterno asc , tra_apellidomaterno asc, tra_nombre asc,fecha asc ,htr_id asc,are_nombre asc,  ingreso asc,ingresorefrigerio asc,salidarefrigerio asc,salida asc';
 DROP TABLE tmarcacionesALL;
END;
$$;


ALTER FUNCTION asistencias.fun_asistencias(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_asistencias(date, date, integer, integer, character varying, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_asistencias(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying, parseccion character varying) RETURNS TABLE(rank bigint, emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, htr_id integer, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, dhr_dia character varying, ingreso character varying, salida character varying, ingresorefrigerio character varying, salidarefrigerio character varying, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, _comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, e_permisomasivojustificado boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, h_permisomasivojustificado double precision, tipodescripcion character varying, tardansa character varying, tardansarefrigerio character varying, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_ingresorefrigerio time without time zone, dhr_salidarefrigerio time without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD; 
  nombredia character varying; 
  mmarcaciones RECORD;
  ingresotemp character varying;
  marcacionesx RECORD;
  descripcionmarcacion character varying;
  htrRecord RECORD;
  htrId integer;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALL (
rank bigint,  
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,

htr_id integer, 
are_codigo integer,
are_nombre character varying(50),

pue_codigo integer,
pue_nombre character varying(50),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,

dhr_dia character varying(12),

ingreso varchar,
salida varchar,
ingresorefrigerio varchar,
salidarefrigerio varchar,


horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,
e_permisomasivojustificado boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
h_permisomasivojustificado double precision,
tipodescripcion varchar(100),

tardansa varchar(2),
tardansarefrigerio varchar(2),

dhr_ingreso time(0),
dhr_salida time(0),
dhr_ingresorefrigerio time(0),
dhr_salidarefrigerio time(0)
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,dhr_dia ,tipodescripcion,
ingreso,ingresorefrigerio ,salidarefrigerio,salida ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,
tardansa,tardansarefrigerio,
dhr_ingreso,dhr_salida,dhr_ingresorefrigerio,dhr_salidarefrigerio)
(
select  row_number() over (order by tra.tra_codigo ) as rank, 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo ,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,
--are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,
--hor.hor_codigo,hor.hor_nombre,
case when  are2.are_codigo IS NULL THEN (SELECT a.are_codigo from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblareas_are as a on a.are_codigo = h.are_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE are2.are_codigo END  AS are2_codigo ,
case when  are2.are_nombre IS NULL THEN (SELECT a.are_nombre from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblareas_are as a on a.are_codigo = h.are_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1)  ELSE are2.are_nombre END  AS are2_nombre ,
case when  pue2.pue_codigo IS NULL THEN (SELECT p.pue_codigo from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblpuestos_pue as p on p.pue_codigo = h.pue_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE pue2.pue_codigo END  AS pue2_codigo ,
case when  pue2.pue_nombre IS NULL THEN (SELECT p.pue_nombre from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblpuestos_pue as p on p.pue_codigo = h.pue_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE pue2.pue_nombre END  AS pue2_nombre ,
case WHEN hor2.hor_codigo is null then  hor.hor_codigo ELSE case when hor.hor_codigo = hor2.hor_codigo then hor.hor_codigo else  hor2.hor_codigo end END  as hor2_codigo,
case WHEN hor2.hor_codigo is null then  hor.hor_nombre ELSE case when hor.hor_codigo = hor2.hor_codigo then  hor.hor_nombre else  concat(hor.hor_nombre,' / ',hor2.hor_nombre) end END as hor2_nombre ,
fht.fht_fecha as fecha ,dhr.dhr_dia,
case when cal.cal_tipo ='N' then
      case when asi.asi_tipomarca is null 
      then  (case when  hor.hor_codigo = 116 then 'DESCANSO' else 
      'No Marco' end ) else  asi.asi_tipomarca end 
  else  case when asi.asi_tipomarca is null then 'Feriado' else  concat('Feriado' , ' / ', asi.asi_tipomarca )end
 end as tipodescripcion,
 -- asi.asi_tipomarca , asi.mar_martipo, asi.asi_fecha ,

  cast( to_char(asi.asi_ingreso::time, 'HH24:MI:SS') as varchar) as hora1 ,
  cast( to_char(asi.asi_salidarefrigerio::time, 'HH24:MI:SS') as varchar) as hora2,
   cast( to_char(asi.asi_ingresorefrigerio::time, 'HH24:MI:SS') as varchar) as hora3,
   cast( to_char(asi.asi_salida::time, 'HH24:MI:SS') as varchar) as hora4,

  --asi.asi_nocturno ,
  --asi.asi_tipooperacion,

  asi.asi_horas_atrabajar ,
  asi.asi_horas_trabajadas,
  asi.asi_tardeingreso ,
  asi.asi_tardeingresorefrigerio 
   ,(case when hor.hor_codigo = 9999 or hor.hor_codigo = 131 then '' else (cast( CASE WHEN (to_char(asi.asi_ingreso, 'hh:MI')) > to_char((dhr.dhr_ingreso + dhr.dhr_tolingreso * (interval '1 minute')), 'hh:MI')
 THEN 'IT' else '' END as varchar))end ) as tardansa
,(case when hor.hor_codigo = 9999 or hor.hor_codigo = 131 then '' else   (cast( CASE WHEN (to_char(asi.asi_ingresorefrigerio  , 'hh:MI')) > to_char((dhr.dhr_salidarefrigerio + dhr.dhr_tiemporefrigerio * (interval '1 minute') + dhr.dhr_tolingresorefrigerio * (interval '1 minute') ), 'hh:MI') -- (cast( CASE WHEN (to_char(asi.asi_salidarefrigerio + dhr.dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((asi.asi_ingresorefrigerio + dhr.dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI')
 THEN 'TR' else '' END as varchar))end ) as tardansarefrigerio,
dhr.dhr_ingreso, dhr.dhr_salida, dhr.dhr_salidarefrigerio,dhr.dhr_ingresorefrigerio
from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
left join asistencias.tblasistencias_asi as asi on asi.tra_codigo=tra.tra_codigo and asi.asi_fecha = fht.fht_fecha
left join asistencias.tblareas_are as are2 on are2.are_codigo = asi.are_codigo
left join asistencias.tblpuestos_pue as pue2 on pue2.pue_codigo = asi.pue_codigo
left join asistencias.tblhorarios_hor  as hor2 on hor2.hor_codigo = asi.hor_codigo 
, asistencias.tblempresa_emp as emp
where
fht.fht_fecha  BETWEEN fechaini::date and fechafin::date and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
tra.tra_seccion LIKE parseccion and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador )  end)
and tra.tra_estado = true
order by are.are_nombre, tra.tra_codigo, fht.fht_fecha asc, asi.asi_ingreso asc, asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc, asi.asi_salida asc
);


FOR rvacaciones IN Select p.*,t.* from asistencias.tblpermisos_per as p 
                  inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo 
                  inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = p.tra_codigo
                  inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo 
                  where cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
                  cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador )  end)

  LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcacionesALL SET e_comision = true, h_comision= tmarcacionesALL.horas_trabajadas 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcacionesALL SET e_vacaciones = true , h_vacaciones = tmarcacionesALL.horas_atrabajar 
    , tipodescripcion =  rvacaciones.tip_nombre 
  WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcacionesALL SET e_medico= true , h_medico = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcacionesALL SET e_permisos = true , h_permisos = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcacionesALL SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcacionesALL SET e_compensacion  = true , h_compensacion  = tmarcacionesALL.horas_atrabajar
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;   
   -- permiso masivo justificado
   IF rvacaciones.tip_codigo = 24 THEN 
   UPDATE tmarcacionesALL SET e_permisomasivojustificado  = true , h_permisomasivojustificado  = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
      
END LOOP;
            

FOR htrRecord IN SELECT * FROM tmarcacionesALL order by fecha asc,are_nombre asc, tra_apellidopaterno asc , tra_apellidomaterno asc, tra_nombre asc, ingreso asc , ingresorefrigerio ASC, salidarefrigerio ASC

  LOOP
      SELECT h.htr_id INTO htrId from asistencias.tblhistorialtrabajadores_htr as h where h.tra_codigo=htrRecord.tra_codigo and htrRecord.are_codigo =  h.are_codigo and htrRecord.pue_codigo = h.pue_codigo and  htrRecord.fecha BETWEEN h.htr_fecinicio and  h.htr_fecfin  limit 1 ;

      IF htrId IS NOT NULL THEN 

        UPDATE tmarcacionesALL
               SET htr_id = htrId
        WHERE tmarcacionesALL.rank = htrRecord.rank ;
	htrId= null;
      END IF;

END LOOP;

 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALL order by tra_apellidopaterno asc , tra_apellidomaterno asc, tra_nombre asc,fecha asc ,htr_id asc,are_nombre asc,  ingreso asc,ingresorefrigerio asc,salidarefrigerio asc,salida asc';
 DROP TABLE tmarcacionesALL;
END;
$$;


ALTER FUNCTION asistencias.fun_asistencias(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying, parseccion character varying) OWNER TO postgres;

--
-- Name: fun_asistencias2(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_asistencias2(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(rank bigint, emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, htr_id integer, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, dhr_dia character varying, ingreso character varying, salida character varying, ingresorefrigerio character varying, salidarefrigerio character varying, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, e_comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, tipodescripcion character varying, tardansa character varying, tardansarefrigerio character varying, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_ingresorefrigerio time without time zone, dhr_salidarefrigerio time without time zone, tardanzahora character varying, tardanzarefrigeriohora character varying, horasextrahora character varying, horastrabajadashora character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD; 
  nombredia character varying; 
  mmarcaciones RECORD;
  ingresotemp character varying;
  marcacionesx RECORD;
  descripcionmarcacion character varying;
  htrRecord RECORD;
  htrId integer;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALL (
rank bigint,  
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,

htr_id integer, 
are_codigo integer,
are_nombre character varying(50),

pue_codigo integer,
pue_nombre character varying(50),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,

dhr_dia character varying(12),

ingreso varchar,
salida varchar,
ingresorefrigerio varchar,
salidarefrigerio varchar,


horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
tipodescripcion varchar(100),

tardansa varchar(2),
tardansarefrigerio varchar(2),

dhr_ingreso time(0),
dhr_salida time(0),
dhr_ingresorefrigerio time(0),
dhr_salidarefrigerio time(0),
tardanzaHora character varying,
tardanzarefrigerioHora character varying,
horasextraHora character varying,
horastrabajadasHora character varying
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,dhr_dia ,tipodescripcion,
ingreso,ingresorefrigerio ,salidarefrigerio,salida ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,
tardansa,tardansarefrigerio,
dhr_ingreso,dhr_salida,dhr_ingresorefrigerio,dhr_salidarefrigerio,
tardanzaHora,tardanzarefrigerioHora,horasextraHora,horastrabajadasHora)
(
select  row_number() over (order by tra.tra_codigo ) as rank, 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo ,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,
--are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,
--hor.hor_codigo,hor.hor_nombre,
case when  are2.are_codigo IS NULL THEN (SELECT a.are_codigo from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblareas_are as a on a.are_codigo = h.are_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE are2.are_codigo END  AS are2_codigo ,
case when  are2.are_nombre IS NULL THEN (SELECT a.are_nombre from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblareas_are as a on a.are_codigo = h.are_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1)  ELSE are2.are_nombre END  AS are2_nombre ,
case when  pue2.pue_codigo IS NULL THEN (SELECT p.pue_codigo from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblpuestos_pue as p on p.pue_codigo = h.pue_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE pue2.pue_codigo END  AS pue2_codigo ,
case when  pue2.pue_nombre IS NULL THEN (SELECT p.pue_nombre from asistencias.tblhistorialtrabajadores_htr as h inner join asistencias.tblpuestos_pue as p on p.pue_codigo = h.pue_codigo where h.tra_codigo=tra.tra_codigo and fht.fht_fecha >= h.htr_fecinicio and fht.fht_fecha <= h.htr_fecfin  limit 1 )  ELSE pue2.pue_nombre END  AS pue2_nombre ,
case WHEN hor2.hor_codigo is null then  hor.hor_codigo ELSE case when hor.hor_codigo = hor2.hor_codigo then hor.hor_codigo else  hor2.hor_codigo end END  as hor2_codigo,
case WHEN hor2.hor_codigo is null then  hor.hor_nombre ELSE case when hor.hor_codigo = hor2.hor_codigo then  hor.hor_nombre else  concat(hor.hor_nombre,' / ',hor2.hor_nombre) end END as hor2_nombre ,
fht.fht_fecha as fecha ,dhr.dhr_dia,
case when cal.cal_tipo ='N' then
      case when asi.asi_tipomarca is null 
      then  (case when  hor.hor_codigo = 116 then 'DESCANSO' else 
      'No Marco' end ) else  asi.asi_tipomarca end 
  else  case when asi.asi_tipomarca is null then 'Feriado' else  concat('Feriado' , ' / ', asi.asi_tipomarca )end
 end as tipodescripcion,
 -- asi.asi_tipomarca , asi.mar_martipo, asi.asi_fecha ,

  cast( to_char(asi.asi_ingreso::time, 'HH24:MI:SS') as varchar) as hora1 ,
  cast( to_char(asi.asi_salidarefrigerio::time, 'HH24:MI:SS') as varchar) as hora2,
   cast( to_char(asi.asi_ingresorefrigerio::time, 'HH24:MI:SS') as varchar) as hora3,
   cast( to_char(asi.asi_salida::time, 'HH24:MI:SS') as varchar) as hora4,

  --asi.asi_nocturno ,
  --asi.asi_tipooperacion,

  asi.asi_horas_atrabajar ,
  asi.asi_horas_trabajadas,
  asi.asi_tardeingreso ,
  asi.asi_tardeingresorefrigerio 
   ,(case when hor.hor_codigo = 9999 or hor.hor_codigo = 131 then '' else (cast( CASE WHEN (to_char(asi.asi_ingreso, 'hh:MI')) > to_char((dhr.dhr_ingreso + dhr.dhr_tolingreso * (interval '1 minute')), 'hh:MI')
 THEN 'IT' else '' END as varchar))end ) as tardansa
,(case when hor.hor_codigo = 9999 or hor.hor_codigo = 131 then '' else   (cast( CASE WHEN (to_char(asi.asi_ingresorefrigerio  , 'hh:MI')) > to_char((dhr.dhr_salidarefrigerio + dhr.dhr_tiemporefrigerio * (interval '1 minute') + dhr.dhr_tolingresorefrigerio * (interval '1 minute') ), 'hh:MI') -- (cast( CASE WHEN (to_char(asi.asi_salidarefrigerio + dhr.dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((asi.asi_ingresorefrigerio + dhr.dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI')
 THEN 'TR' else '' END as varchar))end ) as tardansarefrigerio,
 
dhr.dhr_ingreso, dhr.dhr_salida, dhr.dhr_salidarefrigerio,dhr.dhr_ingresorefrigerio,

/*
 cast( to_char( (  case when substring(case when asi.hor_codigo<>9999 then (cast(CASE WHEN (to_char(asi.asi_ingreso, 'hh:MI')) > to_char((dhr.dhr_ingreso + dhr.dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN asi.asi_ingreso - (cast(asi.asi_ingreso as date)+ dhr.dhr_ingreso) END as varchar) ) end,1,1) <> '-' then case when asi.hor_codigo<>9999 then (cast(CASE WHEN (to_char(asi.asi_ingreso, 'hh:MI')) > to_char((dhr.dhr_ingreso + dhr.dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN asi.asi_ingreso - (cast(asi.asi_ingreso as date)+ dhr.dhr_ingreso) END as varchar) ) end else null end
  )::time, 'HH24:MI:SS') as varchar)  as tardanzaHora,
*/
(case when (asi.asi_tardeingreso > 0 and asi.asi_tardeingreso is not NULL)  then cast( to_char( (asi.asi_tardeingreso * INTERVAL'1 sec' ), 'HH24:MI:SS') as varchar) else null end ) as tardanzaHora,
(case when asi.asi_tardeingresorefrigerio is not null and asi.asi_tardeingresorefrigerio > 0 then cast( to_char(  (asi.asi_tardeingresorefrigerio * INTERVAL'1 sec' )  ,'HH24:MI:SS') as varchar)  else null end) as tardansarefrigerioHora,
(case when ( asi.asi_horas_trabajadas - asi_horas_atrabajar) is not null and ( asi.asi_horas_trabajadas - asi_horas_atrabajar) > 0 then cast( to_char(  (  ( asi.asi_horas_trabajadas - asi_horas_atrabajar) * INTERVAL'1 sec' ) ,'HH24:MI:SS') as varchar) else null end) as horaExtraHora,
(case when asi.asi_horas_trabajadas is not null and asi.asi_horas_trabajadas > 0 then  cast( to_char(  (asi.asi_horas_trabajadas * INTERVAL'1 sec' ) ,'HH24:MI:SS') as varchar)  else null end) as horastrabajadasHora
 
from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
left join asistencias.tblasistencias_asi as asi on asi.tra_codigo=tra.tra_codigo and asi.asi_fecha = fht.fht_fecha
left join asistencias.tblareas_are as are2 on are2.are_codigo = asi.are_codigo
left join asistencias.tblpuestos_pue as pue2 on pue2.pue_codigo = asi.pue_codigo
left join asistencias.tblhorarios_hor  as hor2 on hor2.hor_codigo = asi.hor_codigo 
, asistencias.tblempresa_emp as emp
where
fht.fht_fecha  BETWEEN fechaini::date and fechafin::date and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador )  end)
and tra.tra_estado = true
order by are.are_nombre, tra.tra_codigo, fht.fht_fecha asc, asi.asi_ingreso asc, asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc, asi.asi_salida asc
);


FOR rvacaciones IN Select p.*,t.* from asistencias.tblpermisos_per as p 
                  inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo 
                  inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = p.tra_codigo
                  inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo 
                  where cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
                  cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador )  end)

  LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcacionesALL SET e_comision = true, h_comision= tmarcacionesALL.horas_trabajadas 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcacionesALL SET e_vacaciones = true , h_vacaciones = tmarcacionesALL.horas_atrabajar 
    , tipodescripcion =  rvacaciones.tip_nombre 
  WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcacionesALL SET e_medico= true , h_medico = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcacionesALL SET e_permisos = true , h_permisos = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcacionesALL SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcacionesALL SET e_compensacion  = true , h_compensacion  = tmarcacionesALL.horas_atrabajar
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
      
END LOOP;
            

FOR htrRecord IN SELECT * FROM tmarcacionesALL order by fecha asc,are_nombre asc, tra_apellidopaterno asc , tra_apellidomaterno asc, tra_nombre asc, ingreso asc , ingresorefrigerio ASC, salidarefrigerio ASC

  LOOP
      SELECT h.htr_id INTO htrId from asistencias.tblhistorialtrabajadores_htr as h where h.tra_codigo=htrRecord.tra_codigo and htrRecord.are_codigo =  h.are_codigo and htrRecord.pue_codigo = h.pue_codigo and  htrRecord.fecha BETWEEN h.htr_fecinicio and  h.htr_fecfin  limit 1 ;

      IF htrId IS NOT NULL THEN 

        UPDATE tmarcacionesALL
               SET htr_id = htrId
        WHERE tmarcacionesALL.rank = htrRecord.rank ;
	htrId= null;
      END IF;

END LOOP;

 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALL order by fecha asc ,htr_id asc,are_nombre asc, tra_apellidopaterno asc , tra_apellidomaterno asc, tra_nombre asc, ingreso asc';
 DROP TABLE tmarcacionesALL;
END;
$$;


ALTER FUNCTION asistencias.fun_asistencias2(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_cartexall(character); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_cartexall(anio character) RETURNS TABLE(tra_codigo integer, ene_1 double precision, feb_1 double precision, mar_1 double precision, abr_1 double precision, may_1 double precision, jun_1 double precision, jul_1 double precision, ago_1 double precision, set_1 double precision, act_1 double precision, nov_1 double precision, dic_1 double precision, ene_2 double precision, feb_2 double precision, mar_2 double precision, abr_2 double precision, may_2 double precision, jun_2 double precision, jul_2 double precision, ago_2 double precision, set_2 double precision, act_2 double precision, nov_2 double precision, dic_2 double precision, ene_3 double precision, feb_3 double precision, mar_3 double precision, abr_3 double precision, may_3 double precision, jun_3 double precision, jul_3 double precision, ago_3 double precision, set_3 double precision, act_3 double precision, nov_3 double precision, dic_3 double precision, ene_4 double precision, feb_4 double precision, mar_4 double precision, abr_4 double precision, may_4 double precision, jun_4 double precision, jul_4 double precision, ago_4 double precision, set_4 double precision, act_4 double precision, nov_4 double precision, dic_4 double precision, ene_5 double precision, feb_5 double precision, mar_5 double precision, abr_5 double precision, may_5 double precision, jun_5 double precision, jul_5 double precision, ago_5 double precision, set_5 double precision, act_5 double precision, nov_5 double precision, dic_5 double precision, ene_6 double precision, feb_6 double precision, mar_6 double precision, abr_6 double precision, may_6 double precision, jun_6 double precision, jul_6 double precision, ago_6 double precision, set_6 double precision, act_6 double precision, nov_6 double precision, dic_6 double precision, ene_7 double precision, feb_7 double precision, mar_7 double precision, abr_7 double precision, may_7 double precision, jun_7 double precision, jul_7 double precision, ago_7 double precision, set_7 double precision, act_7 double precision, nov_7 double precision, dic_7 double precision, ene_8 double precision, feb_8 double precision, mar_8 double precision, abr_8 double precision, may_8 double precision, jun_8 double precision, jul_8 double precision, ago_8 double precision, set_8 double precision, act_8 double precision, nov_8 double precision, dic_8 double precision, ene_9 double precision, feb_9 double precision, mar_9 double precision, abr_9 double precision, may_9 double precision, jun_9 double precision, jul_9 double precision, ago_9 double precision, set_9 double precision, act_9 double precision, nov_9 double precision, dic_9 double precision, ene_10 double precision, feb_10 double precision, mar_10 double precision, abr_10 double precision, may_10 double precision, jun_10 double precision, jul_10 double precision, ago_10 double precision, set_10 double precision, act_10 double precision, nov_10 double precision, dic_10 double precision, ene_11 double precision, feb_11 double precision, mar_11 double precision, abr_11 double precision, may_11 double precision, jun_11 double precision, jul_11 double precision, ago_11 double precision, set_11 double precision, act_11 double precision, nov_11 double precision, dic_11 double precision, ene_12 double precision, feb_12 double precision, mar_12 double precision, abr_12 double precision, may_12 double precision, jun_12 double precision, jul_12 double precision, ago_12 double precision, set_12 double precision, act_12 double precision, nov_12 double precision, dic_12 double precision, ene_13 double precision, feb_13 double precision, mar_13 double precision, abr_13 double precision, may_13 double precision, jun_13 double precision, jul_13 double precision, ago_13 double precision, set_13 double precision, act_13 double precision, nov_13 double precision, dic_13 double precision, are_nombre character varying, pue_nombre character varying, nomcompleto text, tra_dni character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY 
select
n.tra_codigo,
coalesce(n.ene_1 , 0) +coalesce(n.ene_3 , 0) +coalesce(n.ene_4 , 0) + coalesce(n.ene_5 , 0) -coalesce(n.ene_8 , 0) as ene_1,
coalesce(n.feb_1 , 0) +coalesce(n.feb_3 , 0) +coalesce(n.feb_4 , 0) + coalesce(n.feb_5 , 0) -coalesce(n.feb_8 , 0) as feb_1,
coalesce(n.mar_1 , 0) +coalesce(n.mar_3 , 0) +coalesce(n.mar_4 , 0) + coalesce(n.mar_5 , 0) -coalesce(n.mar_8 , 0) as mar_1,
coalesce(n.abr_1 , 0) +coalesce(n.abr_3 , 0) +coalesce(n.abr_4 , 0) + coalesce(n.abr_5 , 0) -coalesce(n.abr_8 , 0) as abr_1,
coalesce(n.may_1 , 0) +coalesce(n.may_3 , 0) +coalesce(n.may_4 , 0) + coalesce(n.may_5 , 0) -coalesce(n.may_8 , 0) as may_1,
coalesce(n.jun_1 , 0) +coalesce(n.jun_3 , 0) +coalesce(n.jun_4 , 0) + coalesce(n.jun_5 , 0) -coalesce(n.jun_8 , 0) as jun_1,
