CREATE FUNCTION asistencias.fun_cartexall(anio character, trabajadorcodigo character, area integer) RETURNS TABLE(tra_codigo integer, ene_1 double precision, feb_1 double precision, mar_1 double precision, abr_1 double precision, may_1 double precision, jun_1 double precision, jul_1 double precision, ago_1 double precision, set_1 double precision, act_1 double precision, nov_1 double precision, dic_1 double precision, ene_2 double precision, feb_2 double precision, mar_2 double precision, abr_2 double precision, may_2 double precision, jun_2 double precision, jul_2 double precision, ago_2 double precision, set_2 double precision, act_2 double precision, nov_2 double precision, dic_2 double precision, ene_3 double precision, feb_3 double precision, mar_3 double precision, abr_3 double precision, may_3 double precision, jun_3 double precision, jul_3 double precision, ago_3 double precision, set_3 double precision, act_3 double precision, nov_3 double precision, dic_3 double precision, ene_4 double precision, feb_4 double precision, mar_4 double precision, abr_4 double precision, may_4 double precision, jun_4 double precision, jul_4 double precision, ago_4 double precision, set_4 double precision, act_4 double precision, nov_4 double precision, dic_4 double precision, ene_5 double precision, feb_5 double precision, mar_5 double precision, abr_5 double precision, may_5 double precision, jun_5 double precision, jul_5 double precision, ago_5 double precision, set_5 double precision, act_5 double precision, nov_5 double precision, dic_5 double precision, ene_6 double precision, feb_6 double precision, mar_6 double precision, abr_6 double precision, may_6 double precision, jun_6 double precision, jul_6 double precision, ago_6 double precision, set_6 double precision, act_6 double precision, nov_6 double precision, dic_6 double precision, ene_7 double precision, feb_7 double precision, mar_7 double precision, abr_7 double precision, may_7 double precision, jun_7 double precision, jul_7 double precision, ago_7 double precision, set_7 double precision, act_7 double precision, nov_7 double precision, dic_7 double precision, ene_8 double precision, feb_8 double precision, mar_8 double precision, abr_8 double precision, may_8 double precision, jun_8 double precision, jul_8 double precision, ago_8 double precision, set_8 double precision, act_8 double precision, nov_8 double precision, dic_8 double precision, ene_9 double precision, feb_9 double precision, mar_9 double precision, abr_9 double precision, may_9 double precision, jun_9 double precision, jul_9 double precision, ago_9 double precision, set_9 double precision, act_9 double precision, nov_9 double precision, dic_9 double precision, ene_10 double precision, feb_10 double precision, mar_10 double precision, abr_10 double precision, may_10 double precision, jun_10 double precision, jul_10 double precision, ago_10 double precision, set_10 double precision, act_10 double precision, nov_10 double precision, dic_10 double precision, ene_11 double precision, feb_11 double precision, mar_11 double precision, abr_11 double precision, may_11 double precision, jun_11 double precision, jul_11 double precision, ago_11 double precision, set_11 double precision, act_11 double precision, nov_11 double precision, dic_11 double precision, ene_12 double precision, feb_12 double precision, mar_12 double precision, abr_12 double precision, may_12 double precision, jun_12 double precision, jul_12 double precision, ago_12 double precision, set_12 double precision, act_12 double precision, nov_12 double precision, dic_12 double precision, ene_13 double precision, feb_13 double precision, mar_13 double precision, abr_13 double precision, may_13 double precision, jun_13 double precision, jul_13 double precision, ago_13 double precision, set_13 double precision, act_13 double precision, nov_13 double precision, dic_13 double precision, are_nombre character varying, pue_nombre character varying, nomcompleto text, tra_dni character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
var_sql VARCHAR;
var_codtra integer;
BEGIN

IF trabajadorcodigo <> '' THEN
select tem.tra_codigo
INTO var_codtra
 from asistencias.tbltrabajadores_tra as tem where tem.tra_identificador = CAST(trabajadorcodigo AS VARCHAR);
var_sql := ' where n.tra_codigo ='|| var_codtra;
ELSIF area <> 0 THEN
 var_sql := ' where tra.are_codigo ='|| area; 
ELSE  
var_sql := '';
END IF;
RETURN QUERY EXECUTE 'select
n.tra_codigo,
coalesce(n.ene_1 , 0) +coalesce(n.ene_3 , 0) +coalesce(n.ene_4 , 0) + coalesce(n.ene_5 , 0) -coalesce(n.ene_8 , 0) as ene_1,
coalesce(n.feb_1 , 0) +coalesce(n.feb_3 , 0) +coalesce(n.feb_4 , 0) + coalesce(n.feb_5 , 0) -coalesce(n.feb_8 , 0) as feb_1,
coalesce(n.mar_1 , 0) +coalesce(n.mar_3 , 0) +coalesce(n.mar_4 , 0) + coalesce(n.mar_5 , 0) -coalesce(n.mar_8 , 0) as mar_1,
coalesce(n.abr_1 , 0) +coalesce(n.abr_3 , 0) +coalesce(n.abr_4 , 0) + coalesce(n.abr_5 , 0) -coalesce(n.abr_8 , 0) as abr_1,
coalesce(n.may_1 , 0) +coalesce(n.may_3 , 0) +coalesce(n.may_4 , 0) + coalesce(n.may_5 , 0) -coalesce(n.may_8 , 0) as may_1,
coalesce(n.jun_1 , 0) +coalesce(n.jun_3 , 0) +coalesce(n.jun_4 , 0) + coalesce(n.jun_5 , 0) -coalesce(n.jun_8 , 0) as jun_1,
coalesce(n.jul_1 , 0) +coalesce(n.jul_3 , 0) +coalesce(n.jul_4 , 0) + coalesce(n.jul_5 , 0) -coalesce(n.jul_8 , 0) as jul_1,
coalesce(n.ago_1 , 0) +coalesce(n.ago_3 , 0) +coalesce(n.ago_4 , 0) + coalesce(n.ago_5 , 0) -coalesce(n.ago_8 , 0) as ago_1,
coalesce(n.set_1 , 0) +coalesce(n.set_3 , 0) +coalesce(n.set_4 , 0) + coalesce(n.set_5 , 0) -coalesce(n.set_8 , 0) as set_1,
coalesce(n.act_1 , 0) +coalesce(n.act_3 , 0) +coalesce(n.act_4 , 0) + coalesce(n.act_5 , 0) -coalesce(n.act_8 , 0) as act_1,
coalesce(n.nov_1 , 0) +coalesce(n.nov_3 , 0) +coalesce(n.nov_4 , 0) + coalesce(n.nov_5 , 0) -coalesce(n.nov_8 , 0) as nov_1,
coalesce(n.dic_1 , 0) +coalesce(n.dic_3 , 0) +coalesce(n.dic_4 , 0) + coalesce(n.dic_5 , 0) -coalesce(n.dic_8 , 0) as dic_1,

