var_sql VARCHAR;
var_codtra integer;
BEGIN

IF trabajadorcodigo <> '' THEN
select tem.tra_codigo
INTO var_codtra
 from asistencias.tbltrabajadores_tra as tem where tem.tra_identificador = CAST(trabajadorcodigo AS VARCHAR);
var_sql := ' where n.tra_codigo ='|| var_codtra;
ELSIF area <> 0 THEN
 var_sql := ' where tra.are_codigo ='|| area; 
ELSE  
var_sql := '';
END IF;
RETURN QUERY EXECUTE 'select
n.tra_codigo,
coalesce(n.ene_1 , 0) +coalesce(n.ene_3 , 0) +coalesce(n.ene_4 , 0) + coalesce(n.ene_5 , 0) -coalesce(n.ene_8 , 0) as ene_1,
