coalesce(n.jul_1 , 0) +coalesce(n.jul_3 , 0) +coalesce(n.jul_4 , 0) + coalesce(n.jul_5 , 0) -coalesce(n.jul_8 , 0) as jul_1,
coalesce(n.ago_1 , 0) +coalesce(n.ago_3 , 0) +coalesce(n.ago_4 , 0) + coalesce(n.ago_5 , 0) -coalesce(n.ago_8 , 0) as ago_1,
coalesce(n.set_1 , 0) +coalesce(n.set_3 , 0) +coalesce(n.set_4 , 0) + coalesce(n.set_5 , 0) -coalesce(n.set_8 , 0) as set_1,
coalesce(n.act_1 , 0) +coalesce(n.act_3 , 0) +coalesce(n.act_4 , 0) + coalesce(n.act_5 , 0) -coalesce(n.act_8 , 0) as act_1,
