coalesce(n.mar_1 , 0) +coalesce(n.mar_3 , 0) +coalesce(n.mar_4 , 0) + coalesce(n.mar_5 , 0) + coalesce(n.mar_14 , 0) -coalesce(n.mar_8 , 0) -coalesce(n.mar_6 , 0) as mar_12,
coalesce(n.abr_1 , 0) +coalesce(n.abr_3 , 0) +coalesce(n.abr_4 , 0) + coalesce(n.abr_5 , 0) + coalesce(n.abr_14 , 0) -coalesce(n.abr_8 , 0) -coalesce(n.abr_6 , 0) as abr_12,
