 --horas extras remuneradas
 CASE WHEN coalesce(n.ene_11 , 0) = coalesce(n.ene_6 , 0) THEN coalesce(n.ene_11 , 0) +coalesce(n.ene_12 , 0) ELSE ( case when coalesce(n.ene_11 , 0) > 0  then  coalesce(n.ene_11 , 0) - coalesce(n.ene_14 , 0)  + coalesce(n.ene_12 , 0) ELSE coalesce(n.ene_12 , 0) end) END  as ene_14,
 CASE WHEN coalesce(n.feb_11 , 0) = coalesce(n.feb_6 , 0) THEN coalesce(n.feb_11 , 0) +coalesce(n.feb_12 , 0) ELSE ( case when coalesce(n.feb_11 , 0) > 0  then  coalesce(n.feb_11 , 0) - coalesce(n.feb_14 , 0)  + coalesce(n.feb_12 , 0) ELSE coalesce(n.feb_12 , 0) end) END  as feb_14,
 CASE WHEN coalesce(n.mar_11 , 0) = coalesce(n.mar_6 , 0) THEN coalesce(n.mar_11 , 0) +coalesce(n.mar_12 , 0) ELSE ( case when coalesce(n.mar_11 , 0) > 0  then  coalesce(n.mar_11 , 0) - coalesce(n.mar_14 , 0) + coalesce(n.mar_12 , 0) ELSE coalesce(n.mar_12 , 0) end) END  as mar_14,
