 CASE WHEN coalesce(n.may_11 , 0) = coalesce(n.may_6 , 0) THEN coalesce(n.may_11 , 0) +coalesce(n.may_12 , 0) ELSE ( case when coalesce(n.may_11 , 0) > 0  then  coalesce(n.may_11 , 0) - coalesce(n.may_14 , 0)  + coalesce(n.may_12 , 0) ELSE coalesce(n.may_12 , 0) end) END  as may_14,
