 CASE WHEN coalesce(n.ago_11 , 0) = coalesce(n.ago_6 , 0) THEN coalesce(n.ago_11 , 0) +coalesce(n.ago_12 , 0) ELSE ( case when coalesce(n.ago_11 , 0) > 0  then  coalesce(n.ago_11 , 0) - coalesce(n.ago_14 , 0) + coalesce(n.ago_12 , 0) ELSE coalesce(n.ago_12 , 0) end) END  as ago_14,
 CASE WHEN coalesce(n.set_11 , 0) = coalesce(n.set_6 , 0) THEN coalesce(n.set_11 , 0) +coalesce(n.set_12 , 0) ELSE ( case when coalesce(n.set_11 , 0) > 0  then  coalesce(n.set_11 , 0) - coalesce(n.set_14 , 0)  + coalesce(n.set_12 , 0) ELSE coalesce(n.set_12 , 0) end) END  as set_14,
