 CASE WHEN coalesce(n.nov_11 , 0) = coalesce(n.nov_6 , 0) THEN coalesce(n.nov_11 , 0) +coalesce(n.nov_12 , 0) ELSE ( case when coalesce(n.nov_11 , 0) > 0  then  coalesce(n.nov_11 , 0) - coalesce(n.nov_14 , 0) + coalesce(n.nov_12 , 0) ELSE coalesce(n.nov_12 , 0) end) END  as nov_14,
 CASE WHEN coalesce(n.dic_11 , 0) = coalesce(n.dic_6 , 0) THEN coalesce(n.dic_11 , 0) +coalesce(n.dic_12 , 0) ELSE ( case when coalesce(n.dic_11 , 0) > 0  then  coalesce(n.dic_11 , 0) - coalesce(n.dic_14 , 0) + coalesce(n.dic_12 , 0) ELSE coalesce(n.dic_12 , 0) end) END  as dic_14,

