coalesce(n.nov_12 , 0)   as nov_15,
coalesce(n.dic_12 , 0)   as dic_15,
 

are.are_nombre,
are.are_codigo,
pue.pue_nombre,
(tra.tra_nombre ||'' ''|| tra.tra_apellidopaterno ||'' ''|| tra.tra_apellidomaterno ) as nomcompleto,
tra.tra_dni
 from  asistencias.psgcardex3(CAST('||anio||' AS VARCHAR), CAST('||var_codtra||' AS VARCHAR)) as n
inner join asistencias.tbltrabajadores_tra  as tra on tra.tra_codigo = n.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo'|| var_sql ;
    
END;
$$;


ALTER FUNCTION asistencias.fun_cartexall3(anio character, trabajadorcodigo character, area integer) OWNER TO postgres;

--
-- Name: fun_corregirpermisos(integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_corregirpermisos(tracodigo integer) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE t RECORD;
DECLARE pr RECORD;
DECLARE resultado character varying;
DECLARE fechahora_temp time(0);
DECLARE marcodigo_temp INTEGER;
DECLARE tipoInimar varchar;
DECLARE tipoFinmar varchar;
DECLARE fechorIni timestamp(0);
DECLARE fechorFin timestamp(0);

BEGIN


 FOR pr IN select p.tra_codigo, p.per_fechaini, p.per_fechafin, p.per_codigo,p.tip_codigo,
                p.per_usrcreacion,p.per_usrmodificacion from asistencias.tblpermisos_per as p where   tip_codigo in(18,19) and 
                case when tracodigo = 0 then true else p.tra_codigo = tracodigo end order by p.tra_codigo, p.per_fechaini
         LOOP


         FOR t IN SELECT 
          tra.tra_codigo,
          tra.are_codigo,
          tra.pue_codigo,                        
          hor.hor_codigo,
          dhr.dhr_ingreso,
          dhr.dhr_salida,
          dhr.dhr_salidarefrigerio,
          dhr.dhr_ingresorefrigerio,
          dhr.dhr_day,
          fht.fht_fecha
        FROM 
          asistencias.tbltrabajadores_tra  tra
          inner join asistencias.tblfechahorario_fht as fht on fht.tra_codigo = tra.tra_codigo
          inner join asistencias.tblhorarios_hor as hor on fht.hor_codigo = hor.hor_codigo
          inner join asistencias.tbldethorarios_dhr dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
          where tra.tra_codigo = pr.tra_codigo  and fht.fht_fecha = pr.per_fechaini::date  and hor.hor_codigo <> 9999
          order by 1
          
         LOOP
         
             IF pr.tip_codigo = 20  THEN --PERMISO Mañana
                tipoInimar = '1N';
                fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
                tipoFinmar = '4N';
                fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
             ELSIF pr.tip_codigo = 21 THEN --permiso tarde
                tipoInimar = '1O';
                fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
                tipoFinmar = '4O';
                fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
             ELSIF pr.tip_codigo = 22  THEN -- permiso justificado mañana
                tipoInimar = '1J';
                fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
                tipoFinmar = '4J';
                fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
             ELSIF pr.tip_codigo = 23 THEN -- permiso justificado tarde
                tipoInimar = '1F';
                fechorIni =  (t.fht_f-echa || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
                tipoFinmar = '4F';
                fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
             ELSIF pr.tip_codigo = 18  THEN -- vacaciones mañana
                tipoInimar = '1V';
                fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
                tipoFinmar = '4V';
                fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
             ELSIF pr.tip_codigo = 19 THEN -- vacaciones tarde
                tipoInimar = '1B';
                fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
                tipoFinmar = '4B';
                fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
             END IF;


                    asistencias.tblmarcaciones_mar
                  (
                    tra_codigo,
                    mar_tipo,
                    mar_fechahora,
                    rel_codigo,
                    mar_usrcreacion,
                    mar_feccreacion,
                    mar_masiva
                  )
                  values(
                  t.tra_codigo,
                  tipoInimar, 
                  fechorIni,
                  1,
                  coalesce(pr.per_usrmodificacion, pr.per_usrcreacion),
                  now(),
                  4
                  ),
                  (
                  t.tra_codigo,
                  tipoFinmar, 
                  fechorFin,
                  1,
                  coalesce(pr.per_usrmodificacion, pr.per_usrcreacion),
                  now(),
                  4
                  );
             
          
        END LOOP;
end loop;   
 
  resultado ='OK';
 RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.fun_corregirpermisos(tracodigo integer) OWNER TO postgres;

--
-- Name: fun_crearmarcaciones(bigint); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_crearmarcaciones(v_bol_id bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
v_respuesta varchar;
v_fechaingreso timestamp without time zone;
----
v_fecha date;
v_tra_codigo integer;
v_ingreso time without time zone;
v_salida time without time zone;
v_salidarefrigerio time without time zone;
v_nocturno boolean;
v_tiemporef integer;


BEGIN 

select 
fht.fht_fecha , fht.tra_codigo , dhr.dhr_ingreso ,dhr.dhr_salida , dhr.dhr_salidarefrigerio , dhr.dhr_nocturno , dhr.dhr_tiemporefrigerio 
INTO v_fecha ,v_tra_codigo , v_ingreso ,v_salida , v_salidarefrigerio , v_nocturno , v_tiemporef
 from
asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
where fht.fht_codigo = v_bol_id;

IF v_ingreso <> '00:00:00' THEN
  v_fechaingreso = v_fecha + v_ingreso - interval '1min' *5;
  v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
  
	values(v_tra_codigo ,'I', v_fechaingreso ,20 ); 
  
END IF;
IF v_nocturno THEN
  v_fecha = v_fecha  + interval '1day' *1;
END IF;
IF v_salida <> '00:00:00' THEN
  v_fechaingreso = v_fecha + v_salida;
  v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
  
	values(v_tra_codigo ,'S', v_fechaingreso ,20 ); 
END IF;

IF v_salidarefrigerio <> '00:00:00' THEN
  v_fechaingreso = v_fecha + v_salidarefrigerio;
  v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(9-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
	values(v_tra_codigo ,'IR', v_fechaingreso ,20 ); 
  v_fechaingreso = v_fechaingreso + interval '1min'  * (v_tiemporef-5);
  v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));  
	values(v_tra_codigo ,'SR', v_fechaingreso ,20 );   
END IF;
v_respuesta := cast(v_fechaingreso as varchar);
RETURN v_respuesta;

END;
$$;


