ALTER FUNCTION asistencias.fun_crearmarcaciones_2(tracodigo integer, marfecha date) OWNER TO postgres;

--
-- Name: fun_crearmarcaciones_3(integer, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_crearmarcaciones_3(tracodigo integer, marfecha date) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
v_respuesta varchar;
v_fechaingreso timestamp without time zone;
----
v_fecha date;
v_fecha2 date;
v_tra_codigo_m2 integer;
v_tra_codigo integer;
v_tra_codigo2 integer;
v_ingreso time without time zone;
v_salida time without time zone;
v_salidarefrigerio time without time zone;
v_nocturno boolean;
v_tiemporef integer;


BEGIN 

select 
  fht.fht_fecha , fht.tra_codigo  , dhr.dhr_ingreso ,dhr.dhr_salida , dhr.dhr_salidarefrigerio , dhr.dhr_nocturno , dhr.dhr_tiemporefrigerio 
  INTO v_fecha ,v_tra_codigo , v_ingreso ,v_salida , v_salidarefrigerio , v_nocturno , v_tiemporef
   from asistencias.tblfechahorario_fht as fht
  inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
  inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
  inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
 where fht.tra_codigo = tracodigo and fht.fht_fecha = marfecha;
  

  IF v_ingreso <> '00:00:00' THEN
    v_fechaingreso = v_fecha + v_ingreso - interval '1min' *5;
    v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
    values(v_tra_codigo ,'I', v_fechaingreso ,20 ,'H'); 
 
  END IF;
  IF v_nocturno THEN
    v_fecha = v_fecha  + interval '1day' *1;
  END IF;
  IF v_salida <> '00:00:00' THEN
    v_fechaingreso = v_fecha + v_salida;
    v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
    
    values(v_tra_codigo ,'S', v_fechaingreso ,20 ,'H'); 
 
  END IF;

  IF v_salidarefrigerio <> '00:00:00' THEN
    v_fechaingreso = v_fecha + v_salidarefrigerio;
    v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(9-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
    values(v_tra_codigo ,'IR', v_fechaingreso ,20 ,'H'); 
 

    v_fechaingreso = v_fecha + v_salidarefrigerio;
    v_fechaingreso = v_fechaingreso + interval '1min'  * (v_tiemporef-5);
    v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));  
    values(v_tra_codigo ,'SR', v_fechaingreso ,20 ,'H');   
 
  END IF;

  v_respuesta := cast(v_fechaingreso as varchar);



RETURN v_respuesta;

END;
$$;


ALTER FUNCTION asistencias.fun_crearmarcaciones_3(tracodigo integer, marfecha date) OWNER TO postgres;

--
-- Name: fun_crearmarcaciones_3(integer, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_crearmarcaciones_3(tracodigo integer, marfecha date, cantmarc integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
v_respuesta varchar;
v_fechaingreso timestamp without time zone;
----
v_fecha date;
v_fecha2 date;
v_tra_codigo_m2 integer;
v_tra_codigo integer;
v_tra_codigo2 integer;
v_ingreso time without time zone;
v_salida time without time zone;
v_salidarefrigerio time without time zone;
v_nocturno boolean;
v_tiemporef integer;
v_hoyfecha date;


BEGIN 
v_hoyfecha = CAST(NOW() AS DATE);

select 
  fht.fht_fecha , fht.tra_codigo  , dhr.dhr_ingreso ,dhr.dhr_salida , dhr.dhr_salidarefrigerio , dhr.dhr_nocturno , dhr.dhr_tiemporefrigerio 
  INTO v_fecha ,v_tra_codigo , v_ingreso ,v_salida , v_salidarefrigerio , v_nocturno , v_tiemporef
   from asistencias.tblfechahorario_fht as fht
  inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
  inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
  inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
 where fht.tra_codigo = tracodigo and fht.fht_fecha = marfecha;
  

  IF v_ingreso <> '00:00:00' THEN
    IF cantmarc = 0 OR cantmarc >= 1 THEN
      v_fechaingreso = v_fecha + v_ingreso - interval '1min' *5;
      v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
      values(v_tra_codigo ,'I', v_fechaingreso ,20 ,'H'); 
    END IF;
  END IF;

  IF v_nocturno THEN
    v_fecha = v_fecha  + interval '1day' *1;
  END IF;
  IF v_salida <> '00:00:00' THEN
    IF cantmarc = 0 OR cantmarc = 4  THEN
      v_fechaingreso = v_fecha + v_salida;
      v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
      values(v_tra_codigo ,'S', v_fechaingreso ,20 ,'H'); 
     END IF;
  END IF;

  IF v_salidarefrigerio <> '00:00:00' THEN
    IF cantmarc = 0 OR cantmarc >= 2 THEN
      v_fechaingreso = v_fecha + v_salidarefrigerio;
      v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(9-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));
      values(v_tra_codigo ,'IR', v_fechaingreso ,20 ,'H'); 
    END IF;

 
    IF cantmarc = 0 OR cantmarc >= 3 THEN
      v_fechaingreso = v_fecha + v_salidarefrigerio;
      v_fechaingreso = v_fechaingreso + interval '1min'  * (v_tiemporef-5);
      v_fechaingreso = v_fechaingreso + (interval '1min'  * cast((random()*(14-1)) as int )) + (interval '1sec'  * cast((random()*(60-1)) as int ));  
      values(v_tra_codigo ,'SR', v_fechaingreso ,20 ,'H');   
    END IF;
  END IF;

  v_respuesta := cast(v_fechaingreso as varchar);



RETURN v_respuesta;

END;
$$;


ALTER FUNCTION asistencias.fun_crearmarcaciones_3(tracodigo integer, marfecha date, cantmarc integer) OWNER TO postgres;

