ALTER FUNCTION asistencias.fun_crearregistrosfalsos_2() OWNER TO postgres;

--
-- Name: fun_crearregistrosfalsos_3(); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_crearregistrosfalsos_3() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
v_respuesta varchar;
DECLARE det RECORD;
DECLARE det1 RECORD;
BEGIN 

CREATE TEMPORARY TABLE tmarcacionesFalsas (
tra_codigo integer,
fecha date
);
FOR det IN select * from asistencias.tblmarcaciones_mar as m order by m.mar_fechahora LOOP

	select det.tra_codigo, det.mar_fechahora where not exists (select  mar2.tra_codigo,mar2.fecha from tmarcacionesFalsas as mar2 where mar2.tra_codigo =  det.tra_codigo and mar2.fecha = det.mar_fechahora::date);

END LOOP;     
   

FOR det IN select * from tmarcacionesFalsas LOOP

select asistencias.fun_crearmarcaciones_3(det.tra_codigo,det.fecha) into v_respuesta;
END LOOP;     

---horario liber 
FOR det1 IN select m.tra_codigo, m.mar_fechahora,  f.hor_codigo , m.mar_tipo from asistencias.tblmarcaciones_mar as m 
inner join asistencias.tblfechahorario_fht as f on f.tra_codigo = m.tra_codigo 
where f.hor_codigo = 9999 and m.mar_fechahora::date = f.fht_fecha  and m.mar_tipo in ('I','IR','SR','S')
order by m.mar_fechahora
 LOOP

--insert into tmarcacionesFalsas (tra_codigo,fecha,tipomarc) 
--	select det.tra_codigo, det.mar_fechahora,'L' where not exists (select  mar2.tra_codigo,mar2.fecha from tmarcacionesFalsas as mar2 where mar2.tra_codigo =  det.tra_codigo and mar2.fecha = det.mar_fechahora::date);
    values(det1.tra_codigo ,det1.mar_tipo, det1.mar_fechahora ,20 ,'L');   

END LOOP;  



v_respuesta := 'fin';
RETURN v_respuesta;

END;
$$;


ALTER FUNCTION asistencias.fun_crearregistrosfalsos_3() OWNER TO postgres;

--
-- Name: fun_crearregistrosfalsos_3(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_crearregistrosfalsos_3(fechaini date, fechafin date) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
v_respuesta varchar;
DECLARE det RECORD;
DECLARE det1 RECORD;
DECLARE hoyfecha date;
BEGIN 

hoyfecha := cast(now() as date);

CREATE TEMPORARY TABLE tmarcacionesFalsas (
tra_codigo integer,
fecha date,
cantmarc integer
);

FOR det IN select * from asistencias.tblmarcaciones_mar as m where  CAST(m.mar_fechahora as date)  BETWEEN fechaini and fechafin  order by m.mar_fechahora LOOP

  IF cast(det.mar_fechahora as date) <= (hoyfecha - interval '1 day')::date THEN 
    select det.tra_codigo, det.mar_fechahora,0 where not exists (select  mar2.tra_codigo,mar2.fecha from tmarcacionesFalsas as mar2 where mar2.tra_codigo =  det.tra_codigo and mar2.fecha = det.mar_fechahora::date);
  ELSE 
    select det.tra_codigo, det.mar_fechahora where not exists (select  mar2.tra_codigo,mar2.fecha from tmarcacionesFalsas as mar2 where mar2.tra_codigo =  det.tra_codigo and mar2.fecha = det.mar_fechahora::date);
    IF TRIM(det.mar_tipo) = 'I' THEN --AND TRIM(det.mar_tipo) <> 'IR' AND TRIM(det.mar_tipo) = 'SR' AND TRIM(det.mar_tipo) = 'R'  THEN
      update tmarcacionesFalsas set  cantmarc = 1  where  tra_codigo = det.tra_codigo and fecha = cast(det.mar_fechahora as date);
    ELSIF TRIM(det.mar_tipo) = 'IR' THEN
      update tmarcacionesFalsas set  cantmarc = 2  where  tra_codigo = det.tra_codigo and fecha = cast(det.mar_fechahora as date);
    ELSIF TRIM(det.mar_tipo) = 'SR' THEN
      update tmarcacionesFalsas set  cantmarc = 3  where  tra_codigo = det.tra_codigo and fecha = cast(det.mar_fechahora as date);
    ELSIF TRIM(det.mar_tipo) = 'S' THEN
      IF det.mar_fechahora::DATE = hoyfecha AND  det.mar_fechahora::TIME <= '7:00:00'
        THEN DELETE FROM tmarcacionesFalsas WHERE tra_codigo = det.tra_codigo and fecha = cast(det.mar_fechahora as date);
        ELSE update tmarcacionesFalsas set  cantmarc = 4  where  tra_codigo = det.tra_codigo and fecha = cast(det.mar_fechahora as date);
      END IF;
    END IF;
    
  END IF;
END LOOP;     
   

FOR det IN select * from tmarcacionesFalsas LOOP

select asistencias.fun_crearmarcaciones_3(det.tra_codigo,det.fecha,det.cantmarc) into v_respuesta;
END LOOP;     

---horario liber 
FOR det1 IN select m.tra_codigo, m.mar_fechahora,  f.hor_codigo , m.mar_tipo from asistencias.tblmarcaciones_mar as m 
inner join asistencias.tblfechahorario_fht as f on f.tra_codigo = m.tra_codigo 
where f.hor_codigo = 9999 and m.mar_fechahora::date = f.fht_fecha  and m.mar_tipo in ('I','IR','SR','S') AND
cast(m.mar_fechahora as date)  BETWEEN fechaini and fechafin
order by m.mar_fechahora
 LOOP

--insert into tmarcacionesFalsas (tra_codigo,fecha,tipomarc) 
--  select det.tra_codigo, det.mar_fechahora,'L' where not exists (select  mar2.tra_codigo,mar2.fecha from tmarcacionesFalsas as mar2 where mar2.tra_codigo =  det.tra_codigo and mar2.fecha = det.mar_fechahora::date);
    values(det1.tra_codigo ,det1.mar_tipo, det1.mar_fechahora ,20 ,'L');   

END LOOP;  



v_respuesta := 'fin';
RETURN v_respuesta;

END;
$$;


ALTER FUNCTION asistencias.fun_crearregistrosfalsos_3(fechaini date, fechafin date) OWNER TO postgres;

--
-- Name: fun_global(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_global(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, fuerahorario boolean, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_salidarefrigerio time without time zone, dhr_ingresorefrigerio time without time zone, dhr_dia character varying, dhr_tolingreso integer, dhr_tolingresorefrigerio integer, dhr_tiemporefrigerio integer, dhr_day character varying, dhr_nocturno boolean, ingreso timestamp without time zone, salida timestamp without time zone, ingresorefrigerio timestamp without time zone, salidarefrigerio timestamp without time zone, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, e_comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, tipodescripcion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD; 
  nombredia character varying; 
  mmarcaciones RECORD;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALL (
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,
  
are_codigo integer,
are_nombre character varying(100),

pue_codigo integer,
pue_nombre character varying(100),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,
fuerahorario boolean,
dhr_ingreso time without time zone,
dhr_salida time without time zone,
dhr_salidarefrigerio time without time zone,
dhr_ingresorefrigerio time without time zone,
dhr_dia character varying(12),
dhr_tolingreso integer,
dhr_tolingresorefrigerio integer,
dhr_tiemporefrigerio integer,
dhr_day character varying(12),
dhr_nocturno boolean NOT NULL DEFAULT false,

ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,

horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
tipodescripcion varchar(100)
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,fuerahorario,
dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,tipodescripcion)
(
select 
f.emp_razon,f.emp_ruc,f.emp_direccion,f.cal_tipo,
f.tra_codigo,f.tra_nombre,f.tra_apellidopaterno,f.tra_apellidomaterno,
f.tra_dni,f.tra_identificador,f.tra_estado,
f.are_codigo ,f.are_nombre ,f.pue_codigo ,f.pue_nombre ,f.hor_codigo ,f.hor_nombre ,
f.fht_fecha , false,
f.dhr_ingreso,f.dhr_salida,f.dhr_salidarefrigerio ,f.dhr_ingresorefrigerio,
f.dhr_dia ,f.dhr_tolingreso,f.dhr_tolingresorefrigerio ,f.dhr_tiemporefrigerio , f.dhr_day, f.dhr_nocturno,
 f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  - coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 ))/*/3600*/ as horasdia,
case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso ) 
   then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600 */
   else 0 end as IngresoTarde,
case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
   then extract(epoch from age( f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio ))/* /3600 */
   else 0 end   as TardeRefrigerio,

   f.tipodescripcion
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,
are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,hor.hor_codigo ,hor.hor_nombre ,
fht.fht_fecha ,
dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_salidarefrigerio ,dhr.dhr_ingresorefrigerio,
dhr.dhr_dia ,dhr.dhr_tolingreso,dhr.dhr_tolingresorefrigerio ,dhr.dhr_tiemporefrigerio, dhr.dhr_day ,dhr.dhr_nocturno,
case 
when dhr.dhr_ingreso <> '00:00:00' THEN
(case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'I' OR m.mar_tipo='1X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'I' OR m.mar_tipo='1X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end)

END 
as ingreso,
CASE
when dhr.dhr_salida <> '00:00:00' THEN
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'S' OR m.mar_tipo = '4X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'S' OR m.mar_tipo = '4X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end 
END 
 as salida,
 case
 when dhr.dhr_salidarefrigerio <> '00:00:00' THEN
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'IR' OR m.mar_tipo = '2X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'IR' OR m.mar_tipo = '2X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end 
END 
 as ingresorefrigerio,
 case
 when dhr.dhr_ingresorefrigerio <> '00:00:00' THEN
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'SR' OR m.mar_tipo = '3X')and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'SR' OR m.mar_tipo = '3X')and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end 
END
 as salidarefrigerio,

/*
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salida,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingresorefrigerio,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salidarefrigerio,
*/
(extract(epoch from age( 
case when dhr.dhr_nocturno 
  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
  else cast(now() as date)+ dhr.dhr_salida end
  ,cast(now() as date) + dhr.dhr_ingreso  
  ) ) -(dhr.dhr_tiemporefrigerio *60)  ) /*/3600*/  as nhoras,

case when cal.cal_tipo ='N' then null else 'Feriado' end as tipodescripcion

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
, asistencias.tblempresa_emp as emp
where 
fht.fht_fecha  BETWEEN fechaini and fechafin and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador  )  end)
and tra.tra_estado = true
) as f);

--se toman las marcaciones sin horarios de la tabla marcaciones, dela cual se filtrara para ser actualizadas en las fechas con esta excepcion de carencia de horario, y se puede ingresar el tipo de descripcion fuera de horario
FOR mmarcaciones IN SELECT mar.mar_fechahora, mar.tra_codigo,mar.mar_tipo ,(select dia_semana(mar.mar_fechahora::date)) as dia  from asistencias.tblmarcaciones_mar as mar 
inner join asistencias.tblfechahorario_fht as fht on mar.tra_codigo = fht.tra_codigo and mar.mar_fechahora::date = fht.fht_fecha
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day') 
where dhr.dhr_ingreso = '00:00:00' and dhr.dhr_salida = '00:00:00' and dhr.dhr_salidarefrigerio = '00:00:00' and  dhr.dhr_ingresorefrigerio = '00:00:00'  and mar.mar_fechahora between fechaini and fechafin 
LOOP

--select count(*) from tmarcacionesALL as tmar where   tmar. = mmarcaciones.tra_codigo 

select marca.dhr_dia INTO nombredia from tmarcacionesALL as marca where marca.tra_codigo = mmarcaciones.tra_codigo and marca.fecha = mmarcaciones.mar_fechahora::date;  
IF mmarcaciones.mar_tipo = 'I' OR mmarcaciones.mar_tipo = '1X' then
update tmarcacionesALL as tmarca set ingreso = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
ELSIF mmarcaciones.mar_tipo = 'S' OR mmarcaciones.mar_tipo = '4X' then
  --IF mmarcaciones.mar_fechahora::time > '00:00:00' 
    IF nombredia <> mmarcaciones.dia then
     update tmarcacionesALL as tmarca set salida = mmarcaciones.mar_fechahora  , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date - CAST('1 days' AS INTERVAL);
    ELSE   update tmarcacionesALL as tmarca set salida = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
    END IF;
ELSIF mmarcaciones.mar_tipo = 'IR' OR mmarcaciones.mar_tipo = '2X' then
    IF nombredia <> mmarcaciones.dia then
     update tmarcacionesALL as tmarca set ingresorefrigerio = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date - CAST('1 days' AS INTERVAL);
    ELSE update tmarcacionesALL as tmarca set ingresorefrigerio = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
    END IF;
ELSIF mmarcaciones.mar_tipo = 'SR' OR mmarcaciones.mar_tipo = '3X' then
    IF nombredia <> mmarcaciones.dia then 
    update tmarcacionesALL as tmarca set salidarefrigerio = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date - CAST('1 days' AS INTERVAL);
      ELSE update tmarcacionesALL as tmarca set salidarefrigerio = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
     END IF;
END IF;
END LOOP;

FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcacionesALL SET e_comision = true, h_comision= tmarcacionesALL.horas_trabajadas 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcacionesALL SET e_vacaciones = true , h_vacaciones = tmarcacionesALL.horas_atrabajar 
  , tipodescripcion =  rvacaciones.tip_nombre 
  WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcacionesALL SET e_medico= true , h_medico = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcacionesALL SET e_permisos = true , h_permisos = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcacionesALL SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcacionesALL SET e_compensacion  = true , h_compensacion  = tmarcacionesALL.horas_atrabajar
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
      
END LOOP;
            
 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALL';
END;
$$;


ALTER FUNCTION asistencias.fun_global(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_global1(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_global1(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, fuerahorario boolean, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_salidarefrigerio time without time zone, dhr_ingresorefrigerio time without time zone, dhr_dia character varying, dhr_tolingreso integer, dhr_tolingresorefrigerio integer, dhr_tiemporefrigerio integer, dhr_day character varying, dhr_nocturno boolean, ingreso timestamp without time zone, salida timestamp without time zone, ingresorefrigerio timestamp without time zone, salidarefrigerio timestamp without time zone, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, e_comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, tipodescripcion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD; 
  nombredia character varying; 
  mmarcaciones RECORD;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALL (
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,
  
are_codigo integer,
are_nombre character varying(100),

pue_codigo integer,
pue_nombre character varying(100),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,
fuerahorario boolean,
dhr_ingreso time without time zone,
dhr_salida time without time zone,
dhr_salidarefrigerio time without time zone,
dhr_ingresorefrigerio time without time zone,
dhr_dia character varying(12),
dhr_tolingreso integer,
dhr_tolingresorefrigerio integer,
dhr_tiemporefrigerio integer,
dhr_day character varying(12),
dhr_nocturno boolean NOT NULL DEFAULT false,

ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,

horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
tipodescripcion varchar(100)
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,fuerahorario,
dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,tipodescripcion)
(
select 
f.emp_razon,f.emp_ruc,f.emp_direccion,f.cal_tipo,
f.tra_codigo,f.tra_nombre,f.tra_apellidopaterno,f.tra_apellidomaterno,
f.tra_dni,f.tra_identificador,f.tra_estado,
f.are_codigo ,f.are_nombre ,f.pue_codigo ,f.pue_nombre ,f.hor_codigo ,f.hor_nombre ,
f.fht_fecha , false,
f.dhr_ingreso,f.dhr_salida,f.dhr_salidarefrigerio ,f.dhr_ingresorefrigerio,
f.dhr_dia ,f.dhr_tolingreso,f.dhr_tolingresorefrigerio ,f.dhr_tiemporefrigerio , f.dhr_day, f.dhr_nocturno,
 f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  - coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 ))/*/3600*/ as horasdia,
case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso ) 
   then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600 */
   else 0 end as IngresoTarde,
case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
   then extract(epoch from age( f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio ))/* /3600 */
   else 0 end   as TardeRefrigerio,

   f.tipodescripcion
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,
are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,hor.hor_codigo ,hor.hor_nombre ,
fht.fht_fecha ,
dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_salidarefrigerio ,dhr.dhr_ingresorefrigerio,
dhr.dhr_dia ,dhr.dhr_tolingreso,dhr.dhr_tolingresorefrigerio ,dhr.dhr_tiemporefrigerio, dhr.dhr_day ,dhr.dhr_nocturno,
case 
when dhr.dhr_ingreso <> '00:00:00' THEN
(case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'I' OR m.mar_tipo='1X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'I' OR m.mar_tipo='1X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end)

END 
as ingreso,
CASE
when dhr.dhr_salida <> '00:00:00' THEN
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'S' OR m.mar_tipo = '4X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'S' OR m.mar_tipo = '4X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end 
END 
 as salida,
 case
 when dhr.dhr_salidarefrigerio <> '00:00:00' THEN
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'IR' OR m.mar_tipo = '2X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'IR' OR m.mar_tipo = '2X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end 
END 
 as ingresorefrigerio,
 case
 when dhr.dhr_ingresorefrigerio <> '00:00:00' THEN
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'SR' OR m.mar_tipo = '3X')and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'SR' OR m.mar_tipo = '3X')and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end 
END
 as salidarefrigerio,

/*
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salida,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingresorefrigerio,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salidarefrigerio,
*/
(extract(epoch from age( 
case when dhr.dhr_nocturno 
  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
  else cast(now() as date)+ dhr.dhr_salida end
  ,cast(now() as date) + dhr.dhr_ingreso  
  ) ) -(dhr.dhr_tiemporefrigerio *60)  ) /*/3600*/  as nhoras,

case when cal.cal_tipo ='N' then null else 'Feriado' end as tipodescripcion

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and  hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
, asistencias.tblempresa_emp as emp
where 
fht.fht_fecha  BETWEEN fechaini and fechafin and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador  )  end)
and tra.tra_estado = true
) as f);


--horario libre
emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,fuerahorario,
dhr_dia ,dhr_day,
ingreso,salida,ingresorefrigerio ,salidarefrigerio  
,horas_trabajadas  ,tipodescripcion)
(
select 
f.emp_razon,f.emp_ruc,f.emp_direccion,f.cal_tipo,
f.tra_codigo,f.tra_nombre,f.tra_apellidopaterno,f.tra_apellidomaterno,
f.tra_dni,f.tra_identificador,f.tra_estado,
f.are_codigo ,f.are_nombre ,f.pue_codigo ,f.pue_nombre ,f.hor_codigo ,f.hor_nombre ,
f.fht_fecha , false,

f.dhr_dia , f.dhr_day, 
 f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,
(extract(epoch from age( f.salida,f.ingreso))  - coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 ))/*/3600*/ as horasdia,

   f.tipodescripcion
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,
are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,hor.hor_codigo ,hor.hor_nombre ,
fht.fht_fecha ,

dhr.dhr_dia , dhr.dhr_day ,
 (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'I' OR m.mar_tipo='1X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
as ingreso,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'S' OR m.mar_tipo = '4X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 as salida,
 (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'IR' OR m.mar_tipo = '2X') and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 as ingresorefrigerio,
 (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where (m.mar_tipo = 'SR' OR m.mar_tipo = '3X')and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 as salidarefrigerio,


case when cal.cal_tipo ='N' then null else 'Feriado' end as tipodescripcion

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo = 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
, asistencias.tblempresa_emp as emp
where 
fht.fht_fecha  BETWEEN fechaini and fechafin and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador  )  end)
and tra.tra_estado = true
) as f);

--se toman las marcaciones sin horarios de la tabla marcaciones, dela cual se filtrara para ser actualizadas en las fechas con esta excepcion de carencia de horario, y se puede ingresar el tipo de descripcion fuera de horario
FOR mmarcaciones IN SELECT mar.mar_fechahora, mar.tra_codigo,mar.mar_tipo ,(select dia_semana(mar.mar_fechahora::date)) as dia  from asistencias.tblmarcaciones_mar as mar 
inner join asistencias.tblfechahorario_fht as fht on mar.tra_codigo = fht.tra_codigo and mar.mar_fechahora::date = fht.fht_fecha
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day') 
where dhr.dhr_ingreso = '00:00:00' and dhr.dhr_salida = '00:00:00' and dhr.dhr_salidarefrigerio = '00:00:00' and  dhr.dhr_ingresorefrigerio = '00:00:00'  and mar.mar_fechahora between fechaini and fechafin 
LOOP

--select count(*) from tmarcacionesALL as tmar where   tmar. = mmarcaciones.tra_codigo 

select marca.dhr_dia INTO nombredia from tmarcacionesALL as marca where marca.tra_codigo = mmarcaciones.tra_codigo and marca.fecha = mmarcaciones.mar_fechahora::date;  
IF mmarcaciones.mar_tipo = 'I' OR mmarcaciones.mar_tipo = '1X' then
update tmarcacionesALL as tmarca set ingreso = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
ELSIF mmarcaciones.mar_tipo = 'S' OR mmarcaciones.mar_tipo = '4X' then
  --IF mmarcaciones.mar_fechahora::time > '00:00:00' 
    IF nombredia <> mmarcaciones.dia then
     update tmarcacionesALL as tmarca set salida = mmarcaciones.mar_fechahora  , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date - CAST('1 days' AS INTERVAL);
    ELSE   update tmarcacionesALL as tmarca set salida = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
    END IF;
ELSIF mmarcaciones.mar_tipo = 'IR' OR mmarcaciones.mar_tipo = '2X' then
    IF nombredia <> mmarcaciones.dia then
     update tmarcacionesALL as tmarca set ingresorefrigerio = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date - CAST('1 days' AS INTERVAL);
    ELSE update tmarcacionesALL as tmarca set ingresorefrigerio = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
    END IF;
ELSIF mmarcaciones.mar_tipo = 'SR' OR mmarcaciones.mar_tipo = '3X' then
    IF nombredia <> mmarcaciones.dia then 
    update tmarcacionesALL as tmarca set salidarefrigerio = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date - CAST('1 days' AS INTERVAL);
      ELSE update tmarcacionesALL as tmarca set salidarefrigerio = mmarcaciones.mar_fechahora , fuerahorario = true where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
     END IF;
END IF;
END LOOP;

FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcacionesALL SET e_comision = true, h_comision= tmarcacionesALL.horas_trabajadas 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcacionesALL SET e_vacaciones = true , h_vacaciones = tmarcacionesALL.horas_atrabajar 
  , tipodescripcion =  rvacaciones.tip_nombre 
  WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcacionesALL SET e_medico= true , h_medico = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcacionesALL SET e_permisos = true , h_permisos = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcacionesALL SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcacionesALL SET e_compensacion  = true , h_compensacion  = tmarcacionesALL.horas_atrabajar
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
      
END LOOP;
            
 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALL';
END;
$$;


ALTER FUNCTION asistencias.fun_global1(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_global2(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_global2(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_salidarefrigerio time without time zone, dhr_ingresorefrigerio time without time zone, dhr_dia character varying, dhr_tolingreso integer, dhr_tolingresorefrigerio integer, dhr_tiemporefrigerio integer, dhr_day character varying, dhr_nocturno boolean, descripcion_marc character varying, ingreso timestamp without time zone, salida timestamp without time zone, ingresorefrigerio timestamp without time zone, salidarefrigerio timestamp without time zone, ingresoextra timestamp without time zone, salidaextra timestamp without time zone, ingresorefrigerioextra timestamp without time zone, salidarefrigerioextra timestamp without time zone, ingresoextra2 character varying, salidaextra2 character varying, ingresorefrigerioextra2 character varying, salidarefrigerioextra2 character varying, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, e_comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, tipodescripcion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD; 
  nombredia character varying; 
  mmarcaciones RECORD;
  ingresotemp character varying;
  marcacionesx RECORD;
  descripcionmarcacion character varying;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALL (
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,
  
are_codigo integer,
are_nombre character varying(50),

pue_codigo integer,
pue_nombre character varying(50),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,
--fuerahorario boolean,
dhr_ingreso time without time zone,
dhr_salida time without time zone,
dhr_salidarefrigerio time without time zone,
dhr_ingresorefrigerio time without time zone,
dhr_dia character varying(12),
dhr_tolingreso integer,
dhr_tolingresorefrigerio integer,
dhr_tiemporefrigerio integer,
dhr_day character varying(12),
dhr_nocturno boolean NOT NULL DEFAULT false,

descripcion_marc character varying,
ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,

ingresoextra timestamp without time zone,
salidaextra timestamp without time zone,
ingresorefrigerioextra timestamp without time zone,
salidarefrigerioextra timestamp without time zone,

--descripcion_marc2 character varying,
ingresoextra2 character varying,
salidaextra2 character varying,
ingresorefrigerioextra2 character varying,
salidarefrigerioextra2 character varying,

horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
tipodescripcion varchar(100)
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,
dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,descripcion_marc,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,tipodescripcion)
(
select 
f.emp_razon,f.emp_ruc,f.emp_direccion,f.cal_tipo,
f.tra_codigo,f.tra_nombre,f.tra_apellidopaterno,f.tra_apellidomaterno,
f.tra_dni,f.tra_identificador,f.tra_estado,
f.are_codigo ,f.are_nombre ,f.pue_codigo ,f.pue_nombre ,f.hor_codigo ,f.hor_nombre ,
f.fht_fecha , 
f.dhr_ingreso,f.dhr_salida,f.dhr_salidarefrigerio ,f.dhr_ingresorefrigerio,
f.dhr_dia ,f.dhr_tolingreso,f.dhr_tolingresorefrigerio ,f.dhr_tiemporefrigerio , f.dhr_day, f.dhr_nocturno,'Horario Normal',
f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  - coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 ))/*/3600*/ as horasdia,
case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso ) 
   then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600 */
   else 0 end as IngresoTarde,
case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
   then extract(epoch from age( f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio ))/* /3600 */
   else 0 end   as TardeRefrigerio,

   f.tipodescripcion
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,
are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,hor.hor_codigo ,hor.hor_nombre ,
fht.fht_fecha ,
dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_salidarefrigerio ,dhr.dhr_ingresorefrigerio,
dhr.dhr_dia ,dhr.dhr_tolingreso,dhr.dhr_tolingresorefrigerio ,dhr.dhr_tiemporefrigerio, dhr.dhr_day ,dhr.dhr_nocturno,
case when cal.cal_tipo ='N' then
(case 
when dhr.dhr_ingreso <> '00:00:00' THEN
(case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I'  and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I'  and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end)
END)
END 
as ingreso,
case when cal.cal_tipo ='N' then
(CASE
when dhr.dhr_salida <> '00:00:00' THEN
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S'  and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end 
END)
END 
 as salida,
 case when cal.cal_tipo ='N' then
( case
 when dhr.dhr_salidarefrigerio <> '00:00:00' THEN
 case when dhr.dhr_nocturno 
   then (case when (dhr.dhr_salidarefrigerio::time < '23:59:59'::time and dhr.dhr_salidarefrigerio::time > '19:00:00'::time)  THEN (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR'  and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1) ELSE (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR'  and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date)+ CAST('1 days' AS INTERVAL)  and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1) END)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR'  and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end
  
END )
END
 as ingresorefrigerio,
 case when cal.cal_tipo ='N' then
( case
 when dhr.dhr_ingresorefrigerio <> '00:00:00' THEN
 case when dhr.dhr_nocturno 
   then (case when (dhr.dhr_ingresorefrigerio::time < '23:59:59'::time and dhr.dhr_ingresorefrigerio::time > '19:00:00'::time)  THEN (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date)  and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1) ELSE (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1) END)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end 
END)
END
 as salidarefrigerio,

/*
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salida,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingresorefrigerio,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salidarefrigerio,
*/
(extract(epoch from age( 
case when dhr.dhr_nocturno 
  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
  else cast(now() as date)+ dhr.dhr_salida end
  ,cast(now() as date) + dhr.dhr_ingreso  
  ) ) -(dhr.dhr_tiemporefrigerio *60)  ) /*/3600*/  as nhoras,

case when cal.cal_tipo ='N' then null else 'Feriado' end as tipodescripcion

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
, asistencias.tblempresa_emp as emp
where 
fht.fht_fecha  BETWEEN fechaini and fechafin and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador  )  end)
and tra.tra_estado = true
) as f);

--extra
/*FOR mmarcaciones IN SELECT mar.mar_fechahora, mar.tra_codigo,mar.mar_tipo ,(select dia_semana(mar.mar_fechahora::date)) as dia  from asistencias.tblmarcaciones_mar as mar 
inner join asistencias.tblfechahorario_fht as fht on mar.tra_codigo = fht.tra_codigo and mar.mar_fechahora::date = fht.fht_fecha
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day') 
where mar.mar_tipo= '1X' OR mar.mar_tipo= '2X' OR mar.mar_tipo= '3X' OR mar.mar_tipo= '4X'   mar.mar_fechahora between fechaini and fechafin 
LOOP

--select count(*) from tmarcacionesALL as tmar where   tmar. = mmarcaciones.tra_codigo 

select marca.dhr_dia INTO nombredia from tmarcacionesALL as marca where marca.tra_codigo = mmarcaciones.tra_codigo and marca.fecha = mmarcaciones.mar_fechahora::date;  
IF  mmarcaciones.mar_tipo = '1X' then
