          ELSE update tmarcacionesALL as tmarca set salidarefrigerioextra = mmarcaciones.mar_fechahora , salidarefrigerioextra2 = concat_ws('n',tmarca.salidarefrigerioextra2,cast( to_char(mmarcaciones.mar_fechahora, 'HH24:MI:SS') as varchar))/*, descripcion_marc = 'Horas Extra Turno'*/ where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
         END IF;
    END IF;
