        ELSE   update tmarcacionesALL as tmarca set salidaextra = mmarcaciones.mar_fechahora  , salidaextra2 = concat_ws('n',tmarca.salidaextra2,cast( to_char(mmarcaciones.mar_fechahora, 'HH24:MI:SS') as varchar))/*, descripcion_marc = 'Permiso'*/ where tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = mmarcaciones.mar_fechahora::date;
