FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcacionesALL SET e_comision = true, h_comision= tmarcacionesALL.horas_trabajadas 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcacionesALL SET e_vacaciones = true , h_vacaciones = tmarcacionesALL.horas_atrabajar 
    , tipodescripcion =  rvacaciones.tip_nombre , ingreso = null,salida = null,salidarefrigerio = null,ingresorefrigerio = null
  WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcacionesALL SET e_medico= true , h_medico = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcacionesALL SET e_permisos = true , h_permisos = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcacionesALL SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALL.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcacionesALL SET e_compensacion  = true , h_compensacion  = tmarcacionesALL.horas_atrabajar
        WHERE tmarcacionesALL.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALL.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
      
END LOOP;
            
 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALL';
END;
$$;


ALTER FUNCTION asistencias.fun_global3(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_globalbat(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_globalbat(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_salidarefrigerio time without time zone, dhr_ingresorefrigerio time without time zone, dhr_dia character varying, dhr_tolingreso integer, dhr_tolingresorefrigerio integer, dhr_tiemporefrigerio integer, dhr_day character varying, dhr_nocturno boolean, ingreso timestamp without time zone, salida timestamp without time zone, ingresorefrigerio timestamp without time zone, salidarefrigerio timestamp without time zone, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, e_comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, tipodescripcion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD;  
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALLbat (
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,
  
are_codigo integer,
are_nombre character varying(50),

pue_codigo integer,
pue_nombre character varying(50),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,

dhr_ingreso time without time zone,
dhr_salida time without time zone,
dhr_salidarefrigerio time without time zone,
dhr_ingresorefrigerio time without time zone,
dhr_dia character varying(12),
dhr_tolingreso integer,
dhr_tolingresorefrigerio integer,
dhr_tiemporefrigerio integer,
dhr_day character varying(12),
dhr_nocturno boolean NOT NULL DEFAULT false,

ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,

horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
tipodescripcion varchar(100)
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,
dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,tipodescripcion)
(
select 
f.emp_razon,f.emp_ruc,f.emp_direccion,f.cal_tipo,
f.tra_codigo,f.tra_nombre,f.tra_apellidopaterno,f.tra_apellidomaterno,
f.tra_dni,f.tra_identificador,f.tra_estado,
f.are_codigo ,f.are_nombre ,f.pue_codigo ,f.pue_nombre ,f.hor_codigo ,f.hor_nombre ,
f.fht_fecha ,
f.dhr_ingreso,f.dhr_salida,f.dhr_salidarefrigerio ,f.dhr_ingresorefrigerio,
f.dhr_dia ,f.dhr_tolingreso,f.dhr_tolingresorefrigerio ,f.dhr_tiemporefrigerio , f.dhr_day, f.dhr_nocturno,
 f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  - coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 ))/*/3600*/ as horasdia,
case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso ) 
   then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600 */
   else 0 end as IngresoTarde,
case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
   then extract(epoch from age( f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio ))/* /3600 */
   else 0 end   as TardeRefrigerio,

   f.tipodescripcion
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,
are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,hor.hor_codigo ,hor.hor_nombre ,
fht.fht_fecha ,
dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_salidarefrigerio ,dhr.dhr_ingresorefrigerio,
dhr.dhr_dia ,dhr.dhr_tolingreso,dhr.dhr_tolingresorefrigerio ,dhr.dhr_tiemporefrigerio, dhr.dhr_day ,dhr.dhr_nocturno,

case 
when cal.cal_tipo <>'N'  then null
when dhr.dhr_ingreso ='00:00:00'  then null
when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end
as ingreso,
case 
when cal.cal_tipo <>'N'  then null
when dhr.dhr_salida ='00:00:00'  then null
when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end as salida,
 case 
 when cal.cal_tipo <>'N'  then null
 when dhr.dhr_salidarefrigerio ='00:00:00'  then null
 when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end as ingresorefrigerio,
 case 
 when cal.cal_tipo <>'N'  then null
 when dhr.dhr_salidarefrigerio ='00:00:00'  then null 
 when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end as salidarefrigerio,

/*
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salida,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingresorefrigerio,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salidarefrigerio,
*/
(extract(epoch from age( 
case when dhr.dhr_nocturno 
	then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
	else cast(now() as date)+ dhr.dhr_salida end
	,cast(now() as date) + dhr.dhr_ingreso	
	) ) -(dhr.dhr_tiemporefrigerio *60)  ) /*/3600*/  as nhoras,

case when cal.cal_tipo ='N' then null else 'Feriado' end as tipodescripcion

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
, asistencias.tblempresa_emp as emp
where 
fht.fht_fecha  BETWEEN fechaini and fechafin and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador  )  end)
and tra.tra_estado = true
) as f);

FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
	UPDATE tmarcacionesALLbat SET e_comision = true, h_comision= tmarcacionesALLbat.horas_trabajadas 
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
	UPDATE tmarcacionesALLbat SET e_vacaciones = true , h_vacaciones = tmarcacionesALLbat.horas_atrabajar 
	, tipodescripcion =  rvacaciones.tip_nombre	
	,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null
	WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
	UPDATE tmarcacionesALLbat SET e_medico= true , h_medico = tmarcacionesALLbat.horas_atrabajar
	, tipodescripcion =  rvacaciones.tip_nombre	
	,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
	UPDATE tmarcacionesALLbat SET e_permisos = true , h_permisos = tmarcacionesALLbat.horas_atrabajar
	, tipodescripcion =  rvacaciones.tip_nombre	
	,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null	
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
	UPDATE tmarcacionesALLbat SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALLbat.horas_atrabajar
	, tipodescripcion =  rvacaciones.tip_nombre	
	,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null	
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
	UPDATE tmarcacionesALLbat SET e_compensacion  = true , h_compensacion  = tmarcacionesALLbat.horas_atrabajar
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     


      
END LOOP;

--·         Mario Cuzzi Morán – Gerente General
--·         Milagros Zegarra Huerta – Asesora Legal
--·         Fernando Canedo Abuapara – Jefe Consultoría Empresarial

UPDATE tmarcacionesALLbat SET
	ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null	
        WHERE tmarcacionesALLbat.tra_codigo in (370 ,372, 384);


                    
 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALLbat';
END;
$$;


ALTER FUNCTION asistencias.fun_globalbat(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_globalbat_2(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_globalbat_2(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, tra_mostrarmarcacion boolean, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_salidarefrigerio time without time zone, dhr_ingresorefrigerio time without time zone, dhr_dia character varying, dhr_tolingreso integer, dhr_tolingresorefrigerio integer, dhr_tiemporefrigerio integer, dhr_day character varying, dhr_nocturno boolean, ingreso timestamp without time zone, salida timestamp without time zone, ingresorefrigerio timestamp without time zone, salidarefrigerio timestamp without time zone, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, e_comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, tipodescripcion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD;  
  par_area integer;
  par_codtrabajador varchar;
  par_horario integer;

  rexcepciones RECORD;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALLbat (
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,
tra_mostrarmarcacion boolean DEFAULT false,
  
are_codigo integer,
are_nombre character varying(50),

pue_codigo integer,
pue_nombre character varying(50),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,

dhr_ingreso time without time zone,
dhr_salida time without time zone,
dhr_salidarefrigerio time without time zone,
dhr_ingresorefrigerio time without time zone,
dhr_dia character varying(12),
dhr_tolingreso integer,
dhr_tolingresorefrigerio integer,
dhr_tiemporefrigerio integer,
dhr_day character varying(12),
dhr_nocturno boolean NOT NULL DEFAULT false,


ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,

horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
tipodescripcion varchar(100)
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,tra_mostrarmarcacion,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,
dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,tipodescripcion)
(
select 
f.emp_razon,f.emp_ruc,f.emp_direccion,f.cal_tipo,
f.tra_codigo,f.tra_nombre,f.tra_apellidopaterno,f.tra_apellidomaterno,
f.tra_dni,f.tra_identificador,f.tra_estado,f.tra_mostrarmarcacion,
f.are_codigo ,f.are_nombre ,f.pue_codigo ,f.pue_nombre ,f.hor_codigo ,f.hor_nombre ,
f.fht_fecha ,
f.dhr_ingreso,f.dhr_salida,f.dhr_salidarefrigerio ,f.dhr_ingresorefrigerio,
f.dhr_dia ,f.dhr_tolingreso,f.dhr_tolingresorefrigerio ,f.dhr_tiemporefrigerio , f.dhr_day, f.dhr_nocturno, 
 f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  - coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 ))/*/3600*/ as horasdia,
case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso ) 
   then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600 */
   else 0 end as IngresoTarde,
case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
   then extract(epoch from age( f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio ))/* /3600 */
   else 0 end   as TardeRefrigerio,

   f.tipodescripcion
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,tra.tra_mostrarmarcacion,
are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,hor.hor_codigo ,hor.hor_nombre ,
fht.fht_fecha ,
dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_salidarefrigerio ,dhr.dhr_ingresorefrigerio,
dhr.dhr_dia ,dhr.dhr_tolingreso,dhr.dhr_tolingresorefrigerio ,dhr.dhr_tiemporefrigerio, dhr.dhr_day ,dhr.dhr_nocturno, 

/*case

when NOT tra.tra_mostrarmarcacion  
THEN (*/ 
case 
--when cal.cal_tipo <>'N'  then null
when dhr.dhr_ingreso ='00:00:00'  then null
when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end/*)
--ELSE 
  -- (null)
end */as ingreso,
/*case

when NOT tra.tra_mostrarmarcacion  
THEN (*/ 
case 
--when cal.cal_tipo <>'N'  then null
when dhr.dhr_salida ='00:00:00'  then null
when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end /*)end*/ as salida,
/*case

when NOT tra.tra_mostrarmarcacion  
THEN ( */
 case 
 --when cal.cal_tipo <>'N'  then null
 when dhr.dhr_salidarefrigerio ='00:00:00'  then null
 when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end/*) end*/ as ingresorefrigerio,
/*case

when NOT tra.tra_mostrarmarcacion  
THEN ( */
 case 
 --when cal.cal_tipo <>'N'  then null
 when dhr.dhr_salidarefrigerio ='00:00:00'  then null 
 when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end/*) end*/ as salidarefrigerio,

/*
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salida,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingresorefrigerio,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salidarefrigerio,
*/
(extract(epoch from age( 
case when dhr.dhr_nocturno 
	then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
	else cast(now() as date)+ dhr.dhr_salida end
	,cast(now() as date) + dhr.dhr_ingreso	
	) ) -(dhr.dhr_tiemporefrigerio *60)  ) /*/3600*/  as nhoras,

case when cal.cal_tipo ='N' then null else 'Feriado' end as tipodescripcion

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
, asistencias.tblempresa_emp as emp
where 
fht.fht_fecha  BETWEEN fechaini and fechafin and
cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador  )  end)

) as f);

FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
	UPDATE tmarcacionesALLbat SET e_comision = true, h_comision= tmarcacionesALLbat.horas_trabajadas 
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
	UPDATE tmarcacionesALLbat SET e_vacaciones = true , h_vacaciones = tmarcacionesALLbat.horas_atrabajar 
	, tipodescripcion =  rvacaciones.tip_nombre	
	,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null
	WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
	UPDATE tmarcacionesALLbat SET e_medico= true , h_medico = tmarcacionesALLbat.horas_atrabajar
	, tipodescripcion =  rvacaciones.tip_nombre	
	,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
	UPDATE tmarcacionesALLbat SET e_permisos = true , h_permisos = tmarcacionesALLbat.horas_atrabajar
	, tipodescripcion =  rvacaciones.tip_nombre	
	,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null	
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
	UPDATE tmarcacionesALLbat SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALLbat.horas_atrabajar
	, tipodescripcion =  rvacaciones.tip_nombre	
	,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null	
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
	UPDATE tmarcacionesALLbat SET e_compensacion  = true , h_compensacion  = tmarcacionesALLbat.horas_atrabajar
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     


      
END LOOP;

--·         Mario Cuzzi Morán – Gerente General
--·         Milagros Zegarra Huerta – Asesora Legal
--·         Fernando Canedo Abuapara – Jefe Consultoría Empresarial

/*UPDATE tmarcacionesALLbat SET
	ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null	
        WHERE tmarcacionesALLbat.tra_codigo in (370 ,372, 384);*/


FOR rexcepciones IN  select * from tmarcacionesALLbat as tmar where  tmar.tra_mostrarmarcacion = TRUE LOOP

IF cast (rexcepciones.tra_identificador as varchar) = cast ( codtrabajador as varchar) THEN 
DELETE FROM tmarcacionesALLbat as tm WHERE  tm.tra_mostrarmarcacion = TRUE and tm.tra_identificador =  codtrabajador;

select emp.emp_razon,emp.emp_ruc,are.are_codigo ,are.are_nombre ,tra.tra_codigo ,tra.tra_nombre ,tra.tra_apellidopaterno,tra.tra_apellidomaterno,tra.tra_dni,tra.tra_identificador, pue.pue_nombre,TRUE  
from asistencias.tbltrabajadores_tra as tra inner join  asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo, asistencias.tblempresa_emp as emp
WHERE  tra.tra_mostrarmarcacion = TRUE and tra.tra_identificador = codtrabajador;
 END IF;  

 IF cast (rexcepciones.hor_codigo as varchar) = cast ( codhorario as varchar) THEN 
DELETE FROM tmarcacionesALLbat as tm WHERE  tm.tra_mostrarmarcacion = TRUE and tm.hor_codigo =  codhorario;

select emp.emp_razon,emp.emp_ruc,are.are_codigo ,are.are_nombre ,tra.tra_codigo ,tra.tra_nombre ,tra.tra_apellidopaterno,tra.tra_apellidomaterno,tra.tra_dni,tra.tra_identificador, pue.pue_nombre,TRUE  
from asistencias.tbltrabajadores_tra as tra inner join  asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo, asistencias.tblempresa_emp as emp
WHERE  tra.tra_mostrarmarcacion = TRUE and hor.hor_codigo = codhorario;
 END IF;  

IF cast (rexcepciones.are_codigo as varchar) = cast ( codarea as varchar) THEN 
DELETE FROM tmarcacionesALLbat as tm WHERE  tm.tra_mostrarmarcacion = TRUE and tm.are_codigo =  codarea;

select emp.emp_razon,emp.emp_ruc,are.are_codigo ,are.are_nombre ,tra.tra_codigo ,tra.tra_nombre ,tra.tra_apellidopaterno,tra.tra_apellidomaterno,tra.tra_dni,tra.tra_identificador, pue.pue_nombre,TRUE  
from asistencias.tbltrabajadores_tra as tra inner join  asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo, asistencias.tblempresa_emp as emp
WHERE  tra.tra_mostrarmarcacion = TRUE and are.are_codigo  = codarea;
 END IF;  



END LOOP;
                    
 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALLbat';
END;
$$;


ALTER FUNCTION asistencias.fun_globalbat_2(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_globalbat_3(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_globalbat_3(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, emp_direccion character varying, feriado character, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, tra_estado boolean, tra_mostrarmarcacion boolean, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, hor_codigo integer, hor_nombre character varying, fecha date, dhr_ingreso time without time zone, dhr_salida time without time zone, dhr_salidarefrigerio time without time zone, dhr_ingresorefrigerio time without time zone, dhr_dia character varying, dhr_tolingreso integer, dhr_tolingresorefrigerio integer, dhr_tiemporefrigerio integer, dhr_day character varying, dhr_nocturno boolean, ingreso timestamp without time zone, salida timestamp without time zone, ingresorefrigerio timestamp without time zone, salidarefrigerio timestamp without time zone, horas_atrabajar double precision, horas_trabajadas double precision, horas_tardeingreso double precision, horas_tardesalida double precision, e_comision boolean, e_vacaciones boolean, e_medico boolean, e_permisos boolean, e_permisosjustificado boolean, e_compensacion boolean, h_comision double precision, h_vacaciones double precision, h_medico double precision, h_permisos double precision, h_permisosjustificado double precision, h_compensacion double precision, tipodescripcion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD;  
  par_area integer;
  par_codtrabajador varchar;
  par_horario integer;

  rexcepciones RECORD;
  rrows RECORD;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tmarcacionesALLbat (
emp_razon character varying(50),
emp_ruc character varying(30),
emp_direccion character varying(200),

feriado char(1),

tra_codigo integer,
tra_nombre character varying(50),
tra_apellidopaterno character varying(50),
tra_apellidomaterno character varying(50),
tra_dni character varying(8),
tra_identificador character varying(20),
tra_estado boolean DEFAULT true,
tra_mostrarmarcacion boolean DEFAULT false,
  
are_codigo integer,
are_nombre character varying(100),

pue_codigo integer,
pue_nombre character varying(100),


hor_codigo integer,
hor_nombre character varying(50),

fecha date,

dhr_ingreso time without time zone,
dhr_salida time without time zone,
dhr_salidarefrigerio time without time zone,
dhr_ingresorefrigerio time without time zone,
dhr_dia character varying(12),
dhr_tolingreso integer,
dhr_tolingresorefrigerio integer,
dhr_tiemporefrigerio integer,
dhr_day character varying(12),
dhr_nocturno boolean NOT NULL DEFAULT false,


ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,

horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
tipodescripcion varchar(100)
);

emp_razon ,emp_ruc ,emp_direccion ,feriado ,
tra_codigo ,tra_nombre ,tra_apellidopaterno,tra_apellidomaterno,
tra_dni,tra_identificador,tra_estado,tra_mostrarmarcacion,
are_codigo,are_nombre,pue_codigo ,pue_nombre ,hor_codigo ,hor_nombre,
fecha,
dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida ,tipodescripcion)
(
select 
--ROW_NUMBER() OVER (ORDER BY f.tra_codigo) AS item,
f.emp_razon,f.emp_ruc,f.emp_direccion,f.cal_tipo,
f.tra_codigo,f.tra_nombre,f.tra_apellidopaterno,f.tra_apellidomaterno,
f.tra_dni,f.tra_identificador,f.tra_estado,f.tra_mostrarmarcacion,
f.are_codigo ,f.are_nombre ,f.pue_codigo ,f.pue_nombre ,f.hor_codigo ,f.hor_nombre ,
f.fht_fecha ,
f.dhr_ingreso,f.dhr_salida,f.dhr_salidarefrigerio ,f.dhr_ingresorefrigerio,
f.dhr_dia ,f.dhr_tolingreso,f.dhr_tolingresorefrigerio ,f.dhr_tiemporefrigerio , f.dhr_day, f.dhr_nocturno, 
 f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  - coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 ))/*/3600*/ as horasdia,
case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso ) 
   then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600 */
   else 0 end as IngresoTarde,
case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
   then extract(epoch from age( f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio ))/* /3600 */
   else 0 end   as TardeRefrigerio,

   f.tipodescripcion
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
emp.emp_razon,emp.emp_ruc,emp.emp_direccion,cal.cal_tipo,
tra.tra_codigo,tra.tra_nombre,tra.tra_apellidopaterno,tra.tra_apellidomaterno,
tra.tra_dni,tra.tra_identificador,tra.tra_estado,tra.tra_mostrarmarcacion,
are.are_codigo ,are.are_nombre ,pue.pue_codigo ,pue.pue_nombre ,hor.hor_codigo ,hor.hor_nombre ,
fht.fht_fecha ,
dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_salidarefrigerio ,dhr.dhr_ingresorefrigerio,
dhr.dhr_dia ,dhr.dhr_tolingreso,dhr.dhr_tolingresorefrigerio ,dhr.dhr_tiemporefrigerio, dhr.dhr_day ,dhr.dhr_nocturno, 

/*case

when NOT tra.tra_mostrarmarcacion  
THEN (*/ 
case 
--when cal.cal_tipo <>'N'  then null
when dhr.dhr_ingreso ='00:00:00'  
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo and  m.mar_tipomarc='L' order by mar_fechahora  limit 1)
when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end/*)
--ELSE 
  -- (null)
end */as ingreso,
/*case

when NOT tra.tra_mostrarmarcacion  
THEN (*/ 
case 
--when cal.cal_tipo <>'N'  then null
when dhr.dhr_salida ='00:00:00'  
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo and  m.mar_tipomarc='L' order by mar_fechahora  desc limit 1)
when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end /*)end*/ as salida,
/*case

when NOT tra.tra_mostrarmarcacion  
THEN ( */
 case 
 --when cal.cal_tipo <>'N'  then null
 when dhr.dhr_salidarefrigerio ='00:00:00'  
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo and  m.mar_tipomarc='L' order by mar_fechahora desc limit 1)
 when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end/*) end*/ as ingresorefrigerio,
/*case

when NOT tra.tra_mostrarmarcacion  
THEN ( */
 case 
 --when cal.cal_tipo <>'N'  then null
 when dhr.dhr_salidarefrigerio ='00:00:00'  
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo and  m.mar_tipomarc='L' order by mar_fechahora desc limit 1)
 when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar2 as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end/*) end*/ as salidarefrigerio,

/*
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salida,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingresorefrigerio,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(mar_fechaHora as date)= 
  case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
  and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salidarefrigerio,
*/
(extract(epoch from age( 
case when dhr.dhr_nocturno 
  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
  else cast(now() as date)+ dhr.dhr_salida end
  ,cast(now() as date) + dhr.dhr_ingreso  
  ) ) -(dhr.dhr_tiemporefrigerio *60)  ) /*/3600*/  as nhoras,

case when cal.cal_tipo ='N' then null else 'Feriado' end as tipodescripcion

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo
inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo

inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
, asistencias.tblempresa_emp as emp
where 
fht.fht_fecha  BETWEEN fechaini and fechafin and
--cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (hor.hor_codigo as varchar) like (case when codhorario = 0 then  '%' else cast ( codhorario as varchar) end) and
cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador  )  end)
--and tra.tra_estado = true
) as f);

FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcacionesALLbat SET e_comision = true, h_comision= tmarcacionesALLbat.horas_trabajadas 
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcacionesALLbat SET e_vacaciones = true , h_vacaciones = tmarcacionesALLbat.horas_atrabajar 
  , tipodescripcion =  rvacaciones.tip_nombre 
  ,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null
  WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcacionesALLbat SET e_medico= true , h_medico = tmarcacionesALLbat.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
  ,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcacionesALLbat SET e_permisos = true , h_permisos = tmarcacionesALLbat.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
  ,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null 
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcacionesALLbat SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcacionesALLbat.horas_atrabajar
  , tipodescripcion =  rvacaciones.tip_nombre 
  ,ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null 
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcacionesALLbat SET e_compensacion  = true , h_compensacion  = tmarcacionesALLbat.horas_atrabajar
        WHERE tmarcacionesALLbat.tra_codigo = rvacaciones.tra_codigo and tmarcacionesALLbat.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     


      
END LOOP;

--·         Mario Cuzzi Morán – Gerente General
--·         Milagros Zegarra Huerta – Asesora Legal
--·         Fernando Canedo Abuapara – Jefe Consultoría Empresarial

/*UPDATE tmarcacionesALLbat SET
  ingreso = null, salida = null, ingresorefrigerio = null, salidarefrigerio = null  
        WHERE tmarcacionesALLbat.tra_codigo in (370 ,372, 384);*/


FOR rexcepciones IN  select tmar.tra_codigo,tmar.tra_identificador,tmar.tra_nombre,tmar.tra_apellidopaterno,tmar.tra_apellidomaterno,tmar.are_codigo 
 from asistencias.tbltrabajadores_tra as tmar
  where  tmar.tra_mostrarmarcacion = TRUE and 
  cast (tmar.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
cast (tmar.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador limit 1  )  end)
  group by tmar.tra_codigo ,tmar.tra_identificador,tmar.tra_nombre,tmar.tra_apellidopaterno,tmar.tra_apellidomaterno,tmar.are_codigo
 LOOP

--IF cast (rexcepciones.tra_identificador as varchar) = cast ( codtrabajador as varchar) THEN 
DELETE FROM tmarcacionesALLbat as tm WHERE  tm.tra_mostrarmarcacion = TRUE and tm.tra_codigo =  rexcepciones.tra_codigo;

select emp.emp_razon,emp.emp_ruc,are.are_codigo ,are.are_nombre ,tra.tra_codigo ,tra.tra_nombre ,tra.tra_apellidopaterno,tra.tra_apellidomaterno,tra.tra_dni,tra.tra_identificador, pue.pue_nombre,TRUE  
from asistencias.tbltrabajadores_tra as tra inner join  asistencias.tblpuestos_pue as pue on pue.pue_codigo = tra.pue_codigo inner join asistencias.tblareas_are as are on are.are_codigo = tra.are_codigo, asistencias.tblempresa_emp as emp
WHERE  tra.tra_mostrarmarcacion = TRUE and tra.tra_codigo = rexcepciones.tra_codigo;

END LOOP;


FOR rrows IN  SELECT are.are_nombre, pue.pue_nombre,are.are_codigo,pue.pue_codigo,htr.*  from asistencias.tblhistorialtrabajadores_htr  as htr 
left join asistencias.tblareas_are as are on are.are_codigo = htr.are_codigo
left join asistencias.tblpuestos_pue as pue on pue.pue_codigo = htr.pue_codigo
where htr.tra_codigo in ( SELECT bat.tra_codigo FROM tmarcacionesALLbat as bat group by bat.tra_codigo order by bat.tra_codigo asc ) 
and cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) 
order by htr.tra_codigo asc , htr.htr_fecinicio asc 

 LOOP

          UPDATE 
            tmarcacionesALLbat 
          SET 
            are_nombre = rrows.are_nombre,
            pue_nombre = rrows.pue_nombre,
            are_codigo = rrows.are_codigo,
            pue_codigo = rrows.pue_codigo

          WHERE 
            tmarcacionesALLbat.tra_codigo = rrows.tra_codigo and tmarcacionesALLbat.fecha BETWEEN rrows.htr_fecinicio and rrows.htr_fecfin;

END LOOP;




                    
 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesALLbat where  (case when  '|| codarea ||'= 0 then  TRUE else  are_codigo  = '||codarea||'  end)   ';
END;
$$;


ALTER FUNCTION asistencias.fun_globalbat_3(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: fun_ingresopermisos(character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_ingresopermisos(fechaini character varying, fechafin character varying, tipopermiso integer, tracodigo integer, usucodigo integer) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE t RECORD;
DECLARE resultado character varying;
DECLARE fechahora_temp time(0);
DECLARE marcodigo_temp INTEGER;
DECLARE tipoInimar varchar;
DECLARE tipoFinmar varchar;
DECLARE fechorIni timestamp(0);
DECLARE fechorFin timestamp(0);

BEGIN

      tra_codigo, 
      tip_codigo, 
      per_fechaini, 
      per_fechafin, 
      per_usrcreacion) 
    VALUES (
      tracodigo,
      tipopermiso,
      fechaini::timestamp(0) without time zone ,
      fechafin::timestamp(0) without time zone ,
      usucodigo);

IF  tipopermiso = 20 OR tipopermiso = 21  OR tipopermiso = 22 OR tipopermiso = 23 OR tipopermiso = 18 OR tipopermiso = 19 THEN

     FOR t IN SELECT 
      tra.tra_codigo,
      tra.are_codigo,
      tra.pue_codigo,                        
      hor.hor_codigo,
      dhr.dhr_ingreso,
      dhr.dhr_salida,
      dhr.dhr_salidarefrigerio,
      dhr.dhr_ingresorefrigerio,
      dhr.dhr_day,
      fht.fht_fecha
    FROM 
      asistencias.tbltrabajadores_tra  tra
      inner join asistencias.tblfechahorario_fht as fht on fht.tra_codigo = tra.tra_codigo
      inner join asistencias.tblhorarios_hor as hor on fht.hor_codigo = hor.hor_codigo
      inner join asistencias.tbldethorarios_dhr dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
      where tra.tra_codigo = tracodigo and  tra.tra_estado and fht.fht_fecha = fechaini::date  and hor.hor_codigo <> 9999
      order by 1
      
     LOOP
     
    	 IF tipopermiso = 20  THEN --PERMISO Mañana
            tipoInimar = '1N';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
            tipoFinmar = '4N';
            fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
         ELSIF tipopermiso = 21 THEN --permiso tarde
            tipoInimar = '1O';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
            tipoFinmar = '4O';
            fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
         ELSIF tipopermiso = 22  THEN -- permiso justificado mañana
            tipoInimar = '1J';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
            tipoFinmar = '4J';
            fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
         ELSIF tipopermiso = 23 THEN -- permiso justificado tarde
            tipoInimar = '1F';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
            tipoFinmar = '4F';
            fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
         ELSIF tipopermiso = 18  THEN -- vacaciones mañana
            tipoInimar = '1V';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
            tipoFinmar = '4V';
            fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
         ELSIF tipopermiso = 19 THEN -- vacaciones tarde
            tipoInimar = '1B';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
            tipoFinmar = '4B';
            fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
         END IF;


                asistencias.tblmarcaciones_mar
              (
                tra_codigo,
                mar_tipo,
                mar_fechahora,
                rel_codigo,
                mar_usrcreacion,
                mar_feccreacion,
                mar_masiva
              )
              values(
              t.tra_codigo,
              tipoInimar, 
              fechorIni,
              1,
              usucodigo,
              now(),
              4
              ),
              (
              t.tra_codigo,
              tipoFinmar, 
              fechorFin,
              1,
              usucodigo,
              now(),
              4
              );
         
      
 	END LOOP;
END IF;
  resultado ='OK';
 RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.fun_ingresopermisos(fechaini character varying, fechafin character varying, tipopermiso integer, tracodigo integer, usucodigo integer) OWNER TO postgres;

--
-- Name: fun_ingresopermisos(character varying, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_ingresopermisos(fechaini character varying, fechafin character varying, tipopermiso integer, tracodigo integer, usucodigo integer, observacion character varying) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE t RECORD;
DECLARE resultado character varying;
DECLARE fechahora_temp time(0);
DECLARE marcodigo_temp INTEGER;
DECLARE tipoInimar varchar;
DECLARE tipoFinmar varchar;
DECLARE fechorIni timestamp(0);
DECLARE fechorFin timestamp(0);

BEGIN

      tra_codigo, 
      tip_codigo, 
      per_fechaini, 
      per_fechafin, 
      per_usrcreacion,
      per_observacion) 
    VALUES (
      tracodigo,
      tipopermiso,
      fechaini::timestamp(0) without time zone ,
      fechafin::timestamp(0) without time zone ,
      usucodigo,
      observacion);

IF  tipopermiso = 20 OR tipopermiso = 21  OR tipopermiso = 22 OR tipopermiso = 23 OR tipopermiso = 18 OR tipopermiso = 19 THEN

     FOR t IN SELECT 
      tra.tra_codigo,
      tra.are_codigo,
      tra.pue_codigo,                        
      hor.hor_codigo,
      dhr.dhr_ingreso,
      dhr.dhr_salida,
      dhr.dhr_salidarefrigerio,
      dhr.dhr_ingresorefrigerio,
      dhr.dhr_day,
      fht.fht_fecha
    FROM 
      asistencias.tbltrabajadores_tra  tra
      inner join asistencias.tblfechahorario_fht as fht on fht.tra_codigo = tra.tra_codigo
      inner join asistencias.tblhorarios_hor as hor on fht.hor_codigo = hor.hor_codigo
      inner join asistencias.tbldethorarios_dhr dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
      where tra.tra_codigo = tracodigo and  tra.tra_estado and fht.fht_fecha = fechaini::date  and hor.hor_codigo <> 9999
      order by 1
      
     LOOP
     
    	 IF tipopermiso = 20  THEN --PERMISO Mañana
            tipoInimar = '1N';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
            tipoFinmar = '4N';
            fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
         ELSIF tipopermiso = 21 THEN --permiso tarde
            tipoInimar = '1O';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
            tipoFinmar = '4O';
            fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
         ELSIF tipopermiso = 22  THEN -- permiso justificado mañana
            tipoInimar = '1J';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
            tipoFinmar = '4J';
            fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
         ELSIF tipopermiso = 23 THEN -- permiso justificado tarde
            tipoInimar = '1F';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
            tipoFinmar = '4F';
            fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
         ELSIF tipopermiso = 18  THEN -- vacaciones mañana
            tipoInimar = '1V';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingreso)::timestamp(0);
            tipoFinmar = '4V';
            fechorFin = (t.fht_fecha ||' ' || t.dhr_salidarefrigerio)::timestamp(0);
         ELSIF tipopermiso = 19 THEN -- vacaciones tarde
            tipoInimar = '1B';
            fechorIni =  (t.fht_fecha || ' ' ||t.dhr_ingresorefrigerio)::timestamp(0);
            tipoFinmar = '4B';
            fechorFin =  (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0);
         END IF;


                asistencias.tblmarcaciones_mar
              (
                tra_codigo,
                mar_tipo,
                mar_fechahora,
                rel_codigo,
                mar_usrcreacion,
                mar_feccreacion,
                mar_masiva
              )
              values(
              t.tra_codigo,
              tipoInimar, 
              fechorIni,
              1,
              usucodigo,
              now(),
              4
              ),
              (
              t.tra_codigo,
              tipoFinmar, 
              fechorFin,
              1,
              usucodigo,
              now(),
              4
              );
         
      
 	END LOOP;
END IF;
  resultado ='OK';
 RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.fun_ingresopermisos(fechaini character varying, fechafin character varying, tipopermiso integer, tracodigo integer, usucodigo integer, observacion character varying) OWNER TO postgres;

--
-- Name: fun_marcacionesnuevos(integer, timestamp without time zone, character varying, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_marcacionesnuevos(tracodigo integer, varfechanew timestamp without time zone, varmarcatipo character varying, varusucodigonew integer) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE t RECORD;
DECLARE resultado character varying;
DECLARE varingreso TIMESTAMP(0);
DECLARE varsalida TIMESTAMP(0);
DECLARE mmarcaciones RECORD;

DECLARE ingresotemp TIMESTAMP without time zone;
DECLARE tracodigotemp integer;
DECLARE arecodigotemp integer;
DECLARE puecodigotemp integer;
DECLARE horcodigotemp integer;
DECLARE fechatemp DATE;
DECLARE nocturnotemp Boolean;
DECLARE tipooperaciontemp CHARACTER VARYING;

DECLARE asicodigo_temp character;

DECLARE contador integer ;
DECLARE fechahoratemp timestamp without time zone;
DECLARE nommarca character varying;
DECLARE operation character varying;
DECLARE atrabajar integer;

DECLARE operaciontipo varchar;


BEGIN

IF varmarcatipo in ('IR','SR','S','2A','3A','4A') AND varfechanew::TIME < '07:00:00'::TIME AND varfechanew::TIME >= '00:00:00'::time  THEN 
     fechatemp := (varfechanew::date -  interval'1 day')::DATE ;
ELSE fechatemp := varfechanew::date;
END IF;

 RAISE NOTICE 'varmarcatipo  %',  varmarcatipo;
IF TRIM(varmarcatipo) in  ('I','IR','SR','S') THEN 

    FOR mmarcaciones IN SELECT  tra.tra_codigo,
    tra.are_codigo,
    tra.pue_codigo,
    hor.hor_codigo,
    fht.fht_fecha,
    dhr.dhr_nocturno,
    varfechanew as mar_fechahora,varmarcatipo as mar_tipo ,(select dia_semana(varfechanew::date )) as dia ,
    dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_ingresorefrigerio,dhr.dhr_salidarefrigerio,dhr.dhr_increfrigerio,dhr.dhr_tiemporefrigerio,
    dhr.dhr_increfrigerio
      from  asistencias.tbltrabajadores_tra as tra 
    inner join asistencias.tblfechahorario_fht as fht on tra.tra_codigo = fht.tra_codigo 
    inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
    inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day') 
    where --mar.mar_tipo = 'I' OR mar.mar_tipo = 'IR' OR mar.mar_tipo = 'SR' OR mar.mar_tipo = 'S' 
     tra.tra_codigo = tracodigo and fechatemp = fht.fht_fecha--  and substring(mar.mar_tipo from 2 for 1) = 'C'
    order by tra.tra_codigo,fht.fht_fecha asc LIMIT 1
    LOOP
    ingresotemp = varfechanew;

    asicodigo_temp = (SELECT  asi.asi_codigo::CHARACTER FROM   asistencias.tblasistencias_asi as asi where asi.tra_codigo = mmarcaciones.tra_codigo and (asi.asi_ingreso = mmarcaciones.mar_fechahora or   asi.asi_ingresorefrigerio = mmarcaciones.mar_fechahora or asi.asi_salidarefrigerio = mmarcaciones.mar_fechahora or  asi.asi_salida = mmarcaciones.mar_fechahora)  limit 1);
  --raise notice 'Value: % %', asicodigo_temp,E'\n';
    IF asicodigo_temp is null THEN 

     -- RAISE NOTICE 'entro  %',  mmarcaciones.mar_tipo;
            IF mmarcaciones.mar_tipo = 'I' THEN 
                 contador :=(SELECT asi.asi_codigo from asistencias.tblasistencias_asi as asi where asi.mar_martipo is null and asi.tra_codigo= tracodigo and asi.asi_fecha = mmarcaciones.fht_fecha and asi.asi_ingreso is null order by asi.asi_ingreso asc,asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc,asi.asi_salida asc,asi.asi_codigo asc limit 1 ) ;
                  --    RAISE NOTICE 'entro  %', contador;
              atrabajar =(extract(epoch from age( case when mmarcaciones.dhr_nocturno then cast(now() as date) + CAST('1 days' AS INTERVAL)+ mmarcaciones.dhr_salida else cast(now() as date)+ mmarcaciones.dhr_salida end ,cast(now() as date) + mmarcaciones.dhr_ingreso  ) ) - (case when mmarcaciones.dhr_increfrigerio then 0 else  (mmarcaciones.dhr_tiemporefrigerio *60)  end) );
                     IF contador is null THEN 
                    ELSE
                      update asistencias.tblasistencias_asi set asi_ingreso = mmarcaciones.mar_fechahora 
                            where asistencias.tblasistencias_asi.asi_codigo = contador;
                    END IF;
            ELSIF mmarcaciones.mar_tipo = 'S' then
                    contador :=(SELECT asi.asi_codigo from asistencias.tblasistencias_asi as asi where asi.mar_martipo is null and asi.tra_codigo= tracodigo and asi.asi_fecha = mmarcaciones.fht_fecha and asi.asi_salida is null order by asi.asi_ingreso asc,asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc,asi.asi_salida asc,asi.asi_codigo asc limit 1 ) ;
                        
                    IF contador is null THEN 
                    ELSE
                        update asistencias.tblasistencias_asi set asi_salida = mmarcaciones.mar_fechahora ,  asi_horas2 =0 , asi_horas_trabajadas = null -- (extract(epoch from age( mmarcaciones.mar_fechahora ,asistencias.tblasistencias_asi.asi_ingreso) )),asi_horas_trabajadas = (extract(epoch from age( mmarcaciones.mar_fechahora ,asistencias.tblasistencias_asi.asi_ingreso) ))/*/3600*/ - case when mmarcaciones.dhr_increfrigerio then 0 else asistencias.tblasistencias_asi.asi_horas1  end 
                        where asistencias.tblasistencias_asi.asi_codigo = contador;
                    END IF;
            ELSIF mmarcaciones.mar_tipo = 'IR'  then
                 contador :=(SELECT asi.asi_codigo from asistencias.tblasistencias_asi as asi where asi.mar_martipo is null and asi.tra_codigo= tracodigo and asi.asi_fecha = mmarcaciones.fht_fecha and asi.asi_salidarefrigerio is null order by asi.asi_ingreso asc,asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc,asi.asi_salida asc,asi.asi_codigo asc limit 1 ) ;
                
                    IF contador is null THEN 
                    ELSE
                        update asistencias.tblasistencias_asi set asi_salidarefrigerio = mmarcaciones.mar_fechahora 
                        where asistencias.tblasistencias_asi.asi_codigo = contador;
                    END IF;
            ELSIF  mmarcaciones.mar_tipo = 'SR'  then
                    contador :=(SELECT asi.asi_codigo from asistencias.tblasistencias_asi as asi where asi.mar_martipo is null and asi.tra_codigo= tracodigo and asi.asi_fecha = mmarcaciones.fht_fecha and asi.asi_ingresorefrigerio is null order by asi.asi_ingreso asc,asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc,asi.asi_salida asc,asi.asi_codigo asc limit 1 ) ;
                
                    IF contador is null THEN 
                    ELSE
                        update asistencias.tblasistencias_asi set asi_ingresorefrigerio = mmarcaciones.mar_fechahora ,  asi_horas1= 0  -- (extract(epoch from age( mmarcaciones.mar_fechahora ,asistencias.tblasistencias_asi.asi_ingresorefrigerio) )) 
                        where asistencias.tblasistencias_asi.asi_codigo = contador;
                    END IF;
            END IF;
     
    END IF;

    END LOOP;
ELSE

   RAISE NOTICE 'entro EXTRA';
    FOR mmarcaciones IN SELECT  tra.tra_codigo,
    tra.are_codigo,
    tra.pue_codigo,
    hor.hor_codigo,
    dhr.dhr_nocturno,
    fht.fht_fecha,
    varfechanew as mar_fechahora,varmarcatipo as mar_tipo ,(select dia_semana(varfechanew::date )) as dia ,
    dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_ingresorefrigerio,dhr.dhr_salidarefrigerio,dhr.dhr_increfrigerio,dhr.dhr_tiemporefrigerio,
    dhr.dhr_increfrigerio
    from asistencias.tbltrabajadores_tra as tra 
    inner join asistencias.tblfechahorario_fht as fht on tra.tra_codigo = fht.tra_codigo --and mar.mar_fechahora::date = fht.fht_fecha
    inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
    inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day') 
    where --mar.mar_tipo <> 'I' AND mar.mar_tipo <> 'IR' AND mar.mar_tipo <> 'SR' AND mar.mar_tipo <> 'S' 
    -- CASE WHEN fechatemp is null then true else mar.mar_fechahora::date = fechatemp end--between fechaini and fechafin
     tra.tra_codigo = tracodigo and fechatemp = fht.fht_fecha---  and substring(mar.mar_tipo from 2 for 1) = 'C'
    order by tra.tra_codigo,mar_fechahora asc LIMIT 1
    LOOP
    --ingresotemp = mmarcaciones.mar_fechahora;
    --fechatemp = mmarcaciones.mar_fechahora::date;

    IF substring(mmarcaciones.mar_tipo from 2 for 1) = 'X' THEN  
      nommarca = 'HORAS EXTRA TURNO';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='A' THEN 
      nommarca = 'TRABAJO AUTORIZADO';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='E' THEN 
      nommarca = 'HORAS EXTRA';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='P' THEN 
      nommarca = 'PERMISO';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='J' THEN 
      nommarca = 'PERMISO JUSTIFICADO MAÑANA';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='C' THEN 
      nommarca = 'COMISIÓN';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='U' THEN 
      nommarca = 'H.EXTRA REMUNERADAS';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='T' THEN 
      nommarca = 'TRAB AUTORIZADO REM';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='O' THEN 
      nommarca = 'PERMISO TARDE';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='N' THEN 
      nommarca = 'PERMISO MAÑANA';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='V' THEN 
      nommarca = 'VACACIONES MAÑANA';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='B' THEN 
      nommarca = 'VACACIONES TARDE';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='F' THEN 
      nommarca = 'PERMISO JUSTIFICADO TARDE';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='D' THEN 
      nommarca = 'VACACIONES';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='G' THEN 
      nommarca = 'PERMISO JUSTIFICADO';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='H' THEN 
      nommarca = 'PERMISO M. JUSTIFICADO MAÑANA';
      operation = null;
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='K' THEN 
      nommarca = 'PERMISO M. JUSTIFICADO TARDE';
      operation = null;
    END IF;

    asicodigo_temp = (SELECT  asi.asi_codigo::CHARACTER FROM   asistencias.tblasistencias_asi as asi where asi.tra_codigo = mmarcaciones.tra_codigo and (asi.asi_ingreso = mmarcaciones.mar_fechahora or   asi.asi_ingresorefrigerio = mmarcaciones.mar_fechahora or asi.asi_salidarefrigerio = mmarcaciones.mar_fechahora or  asi.asi_salida = mmarcaciones.mar_fechahora)  limit 1);
    --raise notice 'Value: % %', asicodigo_temp,E'\n';
    IF asicodigo_temp is null THEN 
 RAISE NOTICE 'entro extra %', mmarcaciones.mar_tipo ;
        IF substring(mmarcaciones.mar_tipo from 2 for 1) in ('X','A','E', 'P','J','C','U','T','O','N','V','B','F','D','G','H','K') THEN 
            IF  substring(mmarcaciones.mar_tipo from 1 for 1) = '1' then
                --  contador = contador +1;
              atrabajar =(extract(epoch from age( case when mmarcaciones.dhr_nocturno then cast(now() as date) + CAST('1 days' AS INTERVAL)+ mmarcaciones.dhr_salida else cast(now() as date)+ mmarcaciones.dhr_salida end ,cast(now() as date) + mmarcaciones.dhr_ingreso  ) ) - (case when mmarcaciones.dhr_increfrigerio then 0 else   (mmarcaciones.dhr_tiemporefrigerio *60)   end) );
                   contador :=(SELECT asi.asi_codigo from asistencias.tblasistencias_asi as asi where asi.mar_martipo = substring(mmarcaciones.mar_tipo from 2 for 1)  and asi.tra_codigo= tracodigo and asi.asi_fecha = mmarcaciones.fht_fecha and asi.asi_ingreso is null order by asi.asi_ingreso asc,asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc,asi.asi_salida asc,asi.asi_codigo asc limit 1 ) ;
                     IF contador is null THEN 
                      RAISE NOTICE 'entro  %', nommarca ;
                    ELSE
                      update asistencias.tblasistencias_asi set asi_ingreso = mmarcaciones.mar_fechahora 
                            where asistencias.tblasistencias_asi.asi_codigo = contador;
                    END IF;
            ELSIF substring(mmarcaciones.mar_tipo from 1 for 1) = '4' then
                    contador :=(SELECT asi.asi_codigo from asistencias.tblasistencias_asi as asi where asi.mar_martipo = substring(mmarcaciones.mar_tipo from 2 for 1)  and asi.tra_codigo= tracodigo and asi.asi_fecha = mmarcaciones.fht_fecha and asi.asi_salida is null order by asi.asi_ingreso asc,asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc,asi.asi_salida asc,asi.asi_codigo asc limit 1 ) ;
                    IF contador is null THEN 
                    ELSE
                        update asistencias.tblasistencias_asi set asi_salida = mmarcaciones.mar_fechahora ,  asi_horas2 =0 , asi_horas_trabajadas = null --asi_horas2 = (extract(epoch from age( mmarcaciones.mar_fechahora ,asistencias.tblasistencias_asi.asi_ingreso) )),asi_horas_trabajadas = (extract(epoch from age( mmarcaciones.mar_fechahora ,asistencias.tblasistencias_asi.asi_ingreso) ))/*/3600*/ - case when mmarcaciones.dhr_increfrigerio then 0 else asistencias.tblasistencias_asi.asi_horas1  end 
                        where asistencias.tblasistencias_asi.asi_codigo = contador;
                    END IF;
            ELSIF substring(mmarcaciones.mar_tipo from 1 for 1) = '2' then
                    contador :=(SELECT asi.asi_codigo from asistencias.tblasistencias_asi as asi where asi.mar_martipo = substring(mmarcaciones.mar_tipo from 2 for 1)  and asi.tra_codigo= tracodigo and asi.asi_fecha = mmarcaciones.fht_fecha and asi.asi_salidarefrigerio is null order by asi.asi_ingreso asc,asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc,asi.asi_salida asc,asi.asi_codigo asc limit 1 ) ;
                    IF contador is null THEN 
                    ELSE
                        update asistencias.tblasistencias_asi set asi_salidarefrigerio = mmarcaciones.mar_fechahora 
                        where asistencias.tblasistencias_asi.asi_codigo = contador;
                    END IF;
            ELSIF  substring(mmarcaciones.mar_tipo from 1 for 1) = '3' then
                     contador :=(SELECT asi.asi_codigo from asistencias.tblasistencias_asi as asi where asi.mar_martipo = substring(mmarcaciones.mar_tipo from 2 for 1)  and asi.tra_codigo= tracodigo and asi.asi_fecha = mmarcaciones.fht_fecha and asi.asi_ingresorefrigerio is null order by asi.asi_ingreso asc,asi.asi_salidarefrigerio asc,asi.asi_ingresorefrigerio asc,asi.asi_salida asc,asi.asi_codigo asc limit 1 ) ;
                    IF contador is null THEN 
                    ELSE
                        update asistencias.tblasistencias_asi set asi_ingresorefrigerio = mmarcaciones.mar_fechahora ,  asi_horas1= 0 -- (extract(epoch from age( mmarcaciones.mar_fechahora ,asistencias.tblasistencias_asi.asi_ingresorefrigerio) )) 
                        where asistencias.tblasistencias_asi.asi_codigo = contador;
                    END IF;
            END IF;
       END IF;
      
    END IF;

    END LOOP;
END IF;

RAISE NOTICE 'FUERA';

PERFORM * from asistencias.fun_actualizarvalores('2019-01-01',0, contador);
/*
WITH subquery AS (
      select * from  asistencias.fun_recalculogeneral ('2019-01-01',0, '0',contador)
      
)
UPDATE asistencias.tblasistencias_asi
SET asi_tardeingreso = subquery.IngresoTarde,
    asi_tardeingresorefrigerio  = subquery.TardeRefrigerio,
    asi_horas_trabajadas    = subquery.horas_trabajadas
FROM subquery
WHERE asistencias.tblasistencias_asi.asi_codigo = subquery.asi_codigo;
*/

  resultado ='OK';
  
RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.fun_marcacionesnuevos(tracodigo integer, varfechanew timestamp without time zone, varmarcatipo character varying, varusucodigonew integer) OWNER TO postgres;

--
-- Name: fun_marcacionmasiva(character varying, integer, integer, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_marcacionmasiva(fechaini character varying, tipopermiso integer, areacodigo integer, usucodigo integer) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE t RECORD;
DECLARE resultado character varying;
DECLARE fechahora_temp time(0);
DECLARE marcodigo_temp INTEGER;
DECLARE martipo_temp character varying;
DECLARE varasicod integer;
DECLARE fechahora_stamp timestamp without time zone;
BEGIN

 FOR t IN SELECT 
  tra.tra_codigo,
  tra.are_codigo,
  tra.pue_codigo,
  hor.hor_codigo,
  dhr.dhr_ingreso,
  dhr.dhr_salida,
  dhr.dhr_day,
  fht.fht_fecha
FROM 
  asistencias.tbltrabajadores_tra  tra
  inner join asistencias.tblfechahorario_fht as fht on fht.tra_codigo = tra.tra_codigo
  inner join asistencias.tblhorarios_hor as hor on fht.hor_codigo = hor.hor_codigo
  inner join asistencias.tbldethorarios_dhr dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
  where tra.are_codigo <> 169 and tra.tra_estado and fht.fht_fecha = fechaini::date and tra.tra_marcacionmasiva and 
  case when areacodigo = 0 then true else tra.are_codigo =  areacodigo  END and tra.tra_codigo not in (373,370,384,372,389,379)  and hor.hor_codigo <> 9999
  order by 1
  
 LOOP  
 
    --´p justificado tarde 23
    IF tipopermiso = 23 then
     select   m.mar_fechahora::time(0),  m.mar_codigo,m.mar_tipo, m.mar_fechahora INTO fechahora_temp,marcodigo_temp,martipo_temp,fechahora_stamp from asistencias.tblmarcaciones_mar as m
    where m.tra_codigo = t.tra_codigo and m.mar_fechahora::date = t.fht_fecha and m.mar_tipo <> 'I' and SUBSTRING(m.mar_tipo from 1 for 1 ) not in ('1','4')
    order by m.mar_fechahora desc limit 1;
    elsif tipopermiso = 22 then  --p justificado mañana 22
     select   m.mar_fechahora::time(0), m.mar_codigo,m.mar_tipo, m.mar_fechahora INTO fechahora_temp,marcodigo_temp,martipo_temp,fechahora_stamp from asistencias.tblmarcaciones_mar as m
    where m.tra_codigo = t.tra_codigo and m.mar_fechahora::date = t.fht_fecha  and SUBSTRING(m.mar_tipo from 1 for 1 ) not in ('1','4')
    order by m.mar_fechahora asc limit 1;
    end if;
  
 IF tipopermiso in (23,22)  THEN
  RAISE NOTICE 'entro  %', tipopermiso;
            IF SUBSTRING(martipo_temp from  1 for  1)  = '2' or martipo_temp  = 'IR' THEN 
               IF  martipo_temp = 'IR'  THEN 
                    UPDATE 
                       asistencias.tblasistencias_asi 
                      SET   asi_salidarefrigerio =null , asi_horas_trabajadas =0 ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                      WHERE  tra_codigo = t.tra_codigo and  mar_martipo is null and  asi_salidarefrigerio::timestamp(0) = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha returning asi_codigo INTO varasicod;
              ELSE
                     UPDATE 
                      asistencias.tblasistencias_asi  
                        SET  asi_salidarefrigerio =null , asi_horas_trabajadas =0 ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo and  mar_martipo = SUBSTRING(martipo_temp from  2 for  1) and  asi_salidarefrigerio::timestamp(0) = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod; 
              end if;

                  UPDATE 
                      asistencias.tblasistencias_asi
                   SET asi_salidarefrigerio = fechahora_stamp WHERE asi_codigo = varasicod;

            ELSIF SUBSTRING(martipo_temp from  1 for  1)  = '3' or martipo_temp = 'SR' THEN 
                IF  martipo_temp = 'SR' THEN 
                  UPDATE 
                      asistencias.tblasistencias_asi  
                        SET  asi_ingresorefrigerio =null , asi_tardeingresorefrigerio =0 ,asi_horas_trabajadas =0 , asi_horas2=0,   asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and  asi_ingresorefrigerio::timestamp(0)  = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod;
              ELSE
                UPDATE 
                    asistencias.tblasistencias_asi  
                    SET  asi_ingresorefrigerio =null , asi_tardeingresorefrigerio =0 ,asi_horas_trabajadas =0 , asi_horas2=0,   asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                    WHERE  tra_codigo = t.tra_codigo  and  mar_martipo = SUBSTRING(martipo_temp from  2 for  1) and  asi_ingresorefrigerio::timestamp(0) =  fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod; 
              end if;
                   UPDATE 
                      asistencias.tblasistencias_asi
                   SET asi_tardeingresorefrigerio = fechahora_stamp WHERE asi_codigo = varasicod;
            ELSIF SUBSTRING(martipo_temp from  1 for  1)  = '4' or martipo_temp = 'S' or (TRIM(martipo_temp) = 'ST' and tipopermiso = 23)THEN 
            RAISE NOTICE 'sal  %', martipo_temp;
                IF  martipo_temp = 'S' or (TRIM(martipo_temp) = 'ST' and tipopermiso = 23)  THEN 
                    IF   TRIM(martipo_temp) = 'ST' THEN 
                        UPDATE 
                        asistencias.tblasistencias_asi  
                        SET  asi_salida =null , asi_horas_trabajadas =0 , asi_horas2=0 , asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and  asi_salida is NULL and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod;
                    ELSE
                      UPDATE 
                        asistencias.tblasistencias_asi  
                        SET  asi_salida =null , asi_horas_trabajadas =0 , asi_horas2=0 , asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and  asi_salida::timestamp(0) = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod;
                    end IF;
              ELSE
                UPDATE 
                    asistencias.tblasistencias_asi  
                    SET  asi_salida =null , asi_horas_trabajadas =0 , asi_horas2=0 , asi_fecmodificacion = now() 
                    WHERE  tra_codigo = t.tra_codigo  and  mar_martipo = SUBSTRING(martipo_temp from  2 for  1) and  asi_salida::timestamp(0) = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod; 
              end if;
              RAISE NOTICE 'entro  %', tipopermiso;
                   UPDATE 
                      asistencias.tblasistencias_asi
                   SET asi_salida = fechahora_stamp WHERE asi_codigo = varasicod;
            ELSIF SUBSTRING(martipo_temp from  1 for  1)  = '1' or martipo_temp = 'I' or (TRIM(martipo_temp)  = 'ST' and tipopermiso = 22) THEN 
                 IF martipo_temp = 'I'  or  (TRIM(martipo_temp)  = 'ST' and tipopermiso = 22) THEN 
                    IF TRIM(martipo_temp)  = 'ST' THEN 
                        UPDATE 
                        asistencias.tblasistencias_asi  
                        SET  asi_ingreso=null , asi_horas_trabajadas =0 , asi_tardeingreso = 0 ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and asi_ingreso is NULL and asi_fecha = t.fht_fecha RETURNING asi_codigo  INTO varasicod;

                    ELSE
                      UPDATE 
                        asistencias.tblasistencias_asi  
                        SET  asi_ingreso=null , asi_horas_trabajadas =0 , asi_tardeingreso = 0 ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and asi_ingreso::timestamp(0) =  fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod;
                    END IF;
              ELSE
                  UPDATE 
                    asistencias.tblasistencias_asi  
                    SET  asi_ingreso=null , asi_horas_trabajadas =0 , asi_tardeingreso = 0 ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                    WHERE  tra_codigo = t.tra_codigo  and  mar_martipo = SUBSTRING(martipo_temp from  2 for  1) and asi_ingreso::timestamp(0) =  fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod; 
              end if;
                    UPDATE 
                      asistencias.tblasistencias_asi
                   SET asi_ingreso = fechahora_stamp WHERE asi_codigo = varasicod;
            END IF;


            PERFORM asistencias.fun_actualizarvalores ( t.fht_fecha , 0, varasicod );

            

 END IF;

 IF tipopermiso = 23  THEN 
  
  IF fechahora_temp < t.dhr_salida then 
       
          UPDATE 
            asistencias.tblmarcaciones_mar 
          SET 
            mar_tipo = 'S',
            mar_usrmodificacion = usucodigo,
            mar_fecmodificacion = now()

          WHERE 
            mar_codigo = marcodigo_temp;
              
          
            asistencias.tblmarcaciones_mar
          (
            tra_codigo,
            mar_tipo,
            mar_fechahora,
            rel_codigo,
            mar_usrcreacion,
            mar_feccreacion,
            mar_masiva
          )
          values(
          t.tra_codigo,
          '1F', 
          (t.fht_fecha || ' ' ||to_char((fechahora_temp + interval '1 minute') ::time(0), 'HH24:MI')::time(0))::timestamp(0),
          1,
          usucodigo,
          now(),
          1
          ),
          (
          t.tra_codigo,
          '4F', 
          (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0),
          1,
          usucodigo,
          now(),
          1
          );
     end if;      
  ELSIF    tipopermiso = 22  THEN

   UPDATE 
      asistencias.tblmarcaciones_mar 
    SET 
      mar_tipo = 'I',
      mar_usrmodificacion = usucodigo,
      mar_fecmodificacion = now()

    WHERE 
      mar_codigo = marcodigo_temp;
        
    
      asistencias.tblmarcaciones_mar
    (
      tra_codigo,
      mar_tipo,
      mar_fechahora,
      rel_codigo,
      mar_usrcreacion,
      mar_feccreacion,
      mar_masiva
    )
  values(
    t.tra_codigo,
    '1J', 
    (t.fht_fecha ||' ' || t.dhr_ingreso)::timestamp(0),
    1,
    usucodigo,
    now(),
    1
    ),
    (
    t.tra_codigo,
    '4J', 
    (t.fht_fecha || ' ' ||to_char((fechahora_temp - interval '1 minute') ::time(0), 'HH24:MI')::time(0))::timestamp(0),
    1,
    usucodigo,
    now(),
    1
    );
 end if;
 
 END LOOP;
  resultado ='OK';
 RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.fun_marcacionmasiva(fechaini character varying, tipopermiso integer, areacodigo integer, usucodigo integer) OWNER TO postgres;

--
-- Name: fun_marcacionmasiva(character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_marcacionmasiva(fechaini character varying, tipopermiso integer, areacodigo integer, usucodigo integer, fechafin character varying) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE t RECORD;
DECLARE tot RECORD;
DECLARE resultado character varying;
DECLARE fechahora_temp time(0);
DECLARE marcodigo_temp INTEGER;
DECLARE martipo_temp character varying;
DECLARE varasicod integer;
DECLARE fechahora_stamp timestamp without time zone;
DECLARE varMartipoIN character varying;
DECLARE varMartipoOUT character varying;
BEGIN


IF tipopermiso = 24 THEN
  
  FOR tot IN SELECT 
      tra.tra_codigo,
      tra.are_codigo,
      tra.pue_codigo
    --  hor.hor_codigo
    FROM 
      asistencias.tbltrabajadores_tra  tra
      --inner join asistencias.tblfechahorario_fht as fht on fht.tra_codigo = tra.tra_codigo
     -- inner join asistencias.tblhorarios_hor as hor on fht.hor_codigo = hor.hor_codigo
      where tra.are_codigo <> 169 and tra.tra_estado  and tra.tra_marcacionmasiva and 
      case when areacodigo = 0 then true else tra.are_codigo =  areacodigo  END and tra.tra_codigo not in (373,370,384,372,389,379)  --and hor.hor_codigo <> 9999
      order by 1
      
     LOOP  

          PERFORM asistencias.fun_ingresopermisos( fechaini , fechafin ,  tipopermiso , tot.tra_codigo , usucodigo ,NULL);

     END LOOP;

ELSE 

     FOR t IN SELECT 
      tra.tra_codigo,
      tra.are_codigo,
      tra.pue_codigo,
      hor.hor_codigo,
      dhr.dhr_ingreso,
      dhr.dhr_salida,
      dhr.dhr_day,
      fht.fht_fecha
    FROM 
      asistencias.tbltrabajadores_tra  tra
      inner join asistencias.tblfechahorario_fht as fht on fht.tra_codigo = tra.tra_codigo
      inner join asistencias.tblhorarios_hor as hor on fht.hor_codigo = hor.hor_codigo
      inner join asistencias.tbldethorarios_dhr dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
      where tra.are_codigo <> 169 and tra.tra_estado and fht.fht_fecha = fechaini::date and tra.tra_marcacionmasiva and 
      case when areacodigo = 0 then true else tra.are_codigo =  areacodigo  END and tra.tra_codigo not in (373,370,384,372,389,379)  and hor.hor_codigo <> 9999
      order by 1
      
     LOOP  
     
        --´p justificado tarde 23
        IF tipopermiso IN  (23 , 26) then
         select   m.mar_fechahora::time(0),  m.mar_codigo,m.mar_tipo, m.mar_fechahora INTO fechahora_temp,marcodigo_temp,martipo_temp,fechahora_stamp from asistencias.tblmarcaciones_mar as m
        where m.tra_codigo = t.tra_codigo and m.mar_fechahora::date = t.fht_fecha and m.mar_tipo <> 'I' and SUBSTRING(m.mar_tipo from 1 for 1 ) not in ('1','4')
        order by m.mar_fechahora desc limit 1;
        elsif tipopermiso IN (22, 25) then  --p justificado mañana 22
         select   m.mar_fechahora::time(0), m.mar_codigo,m.mar_tipo, m.mar_fechahora INTO fechahora_temp,marcodigo_temp,martipo_temp,fechahora_stamp from asistencias.tblmarcaciones_mar as m
        where m.tra_codigo = t.tra_codigo and m.mar_fechahora::date = t.fht_fecha  and SUBSTRING(m.mar_tipo from 1 for 1 ) not in ('1','4')
        order by m.mar_fechahora asc limit 1;
        end if;
      
     IF tipopermiso in (23,22,25,26)  THEN
      RAISE NOTICE 'entro  %', tipopermiso;
                IF SUBSTRING(martipo_temp from  1 for  1)  = '2' or martipo_temp  = 'IR' THEN 
                   IF  martipo_temp = 'IR'  THEN 
                        UPDATE 
                           asistencias.tblasistencias_asi 
                          SET   asi_salidarefrigerio =null , asi_horas_trabajadas = NULL ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                          WHERE  tra_codigo = t.tra_codigo and  mar_martipo is null and  asi_salidarefrigerio::timestamp(0) = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha returning asi_codigo INTO varasicod;
                  ELSE
                         UPDATE 
                          asistencias.tblasistencias_asi  
                            SET  asi_salidarefrigerio =null , asi_horas_trabajadas = NULL ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                            WHERE  tra_codigo = t.tra_codigo and  mar_martipo = SUBSTRING(martipo_temp from  2 for  1) and  asi_salidarefrigerio::timestamp(0) = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod; 
                  end if;

                      UPDATE 
                          asistencias.tblasistencias_asi
                       SET asi_salidarefrigerio = fechahora_stamp WHERE asi_codigo = varasicod;

                ELSIF SUBSTRING(martipo_temp from  1 for  1)  = '3' or martipo_temp = 'SR' THEN 
                    IF  martipo_temp = 'SR' THEN 
                      UPDATE 
                          asistencias.tblasistencias_asi  
                            SET  asi_ingresorefrigerio =null , asi_tardeingresorefrigerio =0 ,asi_horas_trabajadas = NULL , asi_horas2=0,   asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                            WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and  asi_ingresorefrigerio::timestamp(0)  = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod;
                  ELSE
                    UPDATE 
                        asistencias.tblasistencias_asi  
                        SET  asi_ingresorefrigerio =null , asi_tardeingresorefrigerio =0 ,asi_horas_trabajadas = NULL , asi_horas2=0,   asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo  and  mar_martipo = SUBSTRING(martipo_temp from  2 for  1) and  asi_ingresorefrigerio::timestamp(0) =  fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod; 
                  end if;
                       UPDATE 
                          asistencias.tblasistencias_asi
                       SET asi_tardeingresorefrigerio = fechahora_stamp WHERE asi_codigo = varasicod;
                ELSIF SUBSTRING(martipo_temp from  1 for  1)  = '4' or martipo_temp = 'S' or (TRIM(martipo_temp) = 'ST' and tipopermiso IN (23 , 26) )THEN 
                RAISE NOTICE 'sal  %', martipo_temp;
                    IF  martipo_temp = 'S' or (TRIM(martipo_temp) = 'ST' and tipopermiso in (23,26))  THEN 
                        IF   TRIM(martipo_temp) = 'ST' THEN 
                            UPDATE 
                            asistencias.tblasistencias_asi  
                            SET  asi_salida =null , asi_horas_trabajadas = NULL , asi_horas2=0 , asi_fecmodificacion = now() 
                            WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and  asi_salida is NULL and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod;
                        ELSE
                          UPDATE 
                            asistencias.tblasistencias_asi  
                            SET  asi_salida =null , asi_horas_trabajadas = NULL , asi_horas2=0 , asi_fecmodificacion = now() 
                            WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and  asi_salida::timestamp(0) = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod;
                        end IF;
                  ELSE
                    UPDATE 
                        asistencias.tblasistencias_asi  
                        SET  asi_salida =null , asi_horas_trabajadas = NULL, asi_horas2=0 , asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo  and  mar_martipo = SUBSTRING(martipo_temp from  2 for  1) and  asi_salida::timestamp(0) = fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod; 
                  end if;
                  RAISE NOTICE 'entro  %', tipopermiso;
                       UPDATE 
                          asistencias.tblasistencias_asi
                       SET asi_salida = fechahora_stamp WHERE asi_codigo = varasicod;
                ELSIF SUBSTRING(martipo_temp from  1 for  1)  = '1' or martipo_temp = 'I' or (TRIM(martipo_temp)  = 'ST' and tipopermiso IN (22,25) ) THEN 
                     IF martipo_temp = 'I'  or  (TRIM(martipo_temp)  = 'ST' and tipopermiso in (22,25)) THEN 
                        IF TRIM(martipo_temp)  = 'ST' THEN 
                            UPDATE 
                            asistencias.tblasistencias_asi  
                            SET  asi_ingreso=null , asi_horas_trabajadas = NULL , asi_tardeingreso = 0 ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                            WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and asi_ingreso is NULL and asi_fecha = t.fht_fecha RETURNING asi_codigo  INTO varasicod;

                        ELSE
                          UPDATE 
                            asistencias.tblasistencias_asi  
                            SET  asi_ingreso=null , asi_horas_trabajadas = NULL , asi_tardeingreso = 0 ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                            WHERE  tra_codigo = t.tra_codigo  and  mar_martipo is null and asi_ingreso::timestamp(0) =  fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod;
                        END IF;
                  ELSE
                      UPDATE 
                        asistencias.tblasistencias_asi  
                        SET  asi_ingreso=null , asi_horas_trabajadas = NULL , asi_tardeingreso = 0 ,  asi_usrmodificacion = usucodigo, asi_fecmodificacion = now() 
                        WHERE  tra_codigo = t.tra_codigo  and  mar_martipo = SUBSTRING(martipo_temp from  2 for  1) and asi_ingreso::timestamp(0) =  fechahora_stamp::timestamp(0) and asi_fecha = t.fht_fecha RETURNING asi_codigo INTO varasicod; 
                  end if;
                        UPDATE 
                          asistencias.tblasistencias_asi
                       SET asi_ingreso = fechahora_stamp WHERE asi_codigo = varasicod;
                END IF;


                PERFORM asistencias.fun_actualizarvalores ( t.fht_fecha , 0, varasicod );

                

     END IF;





     IF tipopermiso in (23,26)  THEN 
      
      IF fechahora_temp < t.dhr_salida then 
           
              UPDATE 
                asistencias.tblmarcaciones_mar 
              SET 
                mar_tipo = 'S',
                mar_usrmodificacion = usucodigo,
                mar_fecmodificacion = now()

              WHERE 
                mar_codigo = marcodigo_temp;

                IF tipopermiso = 23 THEN
                    varMartipoIN = '1F'; 
                    varMartipoOUT = '4F';
                ELSIF tipopermiso = 26 THEN 
                    varMartipoIN = '1K'; 
                    varMartipoOUT = '4K';
                END IF;
                  
              
                asistencias.tblmarcaciones_mar
              (
                tra_codigo,
                mar_tipo,
                mar_fechahora,
                rel_codigo,
                mar_usrcreacion,
                mar_feccreacion,
                mar_masiva
              )
              values(
              t.tra_codigo,
              varMartipoIN, 
              (t.fht_fecha || ' ' ||to_char((fechahora_temp + interval '1 minute') ::time(0), 'HH24:MI')::time(0))::timestamp(0),
              1,
              usucodigo,
              now(),
              1
              ),
              (
              t.tra_codigo,
              varMartipoOUT, 
              (t.fht_fecha ||' ' || t.dhr_salida)::timestamp(0),
              1,
              usucodigo,
              now(),
              1
              );
      end if;      
    ELSIF    tipopermiso in (22,25)  THEN

       UPDATE 
          asistencias.tblmarcaciones_mar 
        SET 
          mar_tipo = 'I',
          mar_usrmodificacion = usucodigo,
          mar_fecmodificacion = now()

        WHERE 
          mar_codigo = marcodigo_temp;
            
            IF tipopermiso = 22 THEN
                varMartipoIN = '1J'; 
                varMartipoOUT = '4J';
            ELSIF tipopermiso = 25 THEN 
                varMartipoIN = '1H'; 
                varMartipoOUT = '4H';
            END IF;
        
          asistencias.tblmarcaciones_mar
        (
          tra_codigo,
          mar_tipo,
          mar_fechahora,
          rel_codigo,
          mar_usrcreacion,
          mar_feccreacion,
          mar_masiva
        )
      values(
        t.tra_codigo,
        varMartipoIN, 
        (t.fht_fecha ||' ' || t.dhr_ingreso)::timestamp(0),
        1,
        usucodigo,
        now(),
        1
        ),
        (
        t.tra_codigo,
        varMartipoOUT, 
        (t.fht_fecha || ' ' ||to_char((fechahora_temp - interval '1 minute') ::time(0), 'HH24:MI')::time(0))::timestamp(0),
        1,
        usucodigo,
        now(),
        1
        );

    
    end if;
     
     END LOOP;

END IF;
  resultado ='OK';
 RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.fun_marcacionmasiva(fechaini character varying, tipopermiso integer, areacodigo integer, usucodigo integer, fechafin character varying) OWNER TO postgres;

--
-- Name: fun_mensual(character, character varying, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_mensual(par_fecha character, trabajadorcodigo character varying, vararecodigo integer) RETURNS TABLE(tra_codigo integer, tra_nomcompleto character varying, tra_dni character varying, are_codigo integer, are_nombre character varying, pue_codigo integer, pue_nombre character varying, rep_horas_trabajadas double precision, rep_trabajo_comision double precision, rep_vacaciones double precision, rep_medico double precision, rep_permiso_justificado double precision, rep_horas_atrabajar double precision, rep_tardanzas_ingreso double precision, rep_tardanzas_refrigerio double precision, rep_permisos_personal double precision, rep_extras double precision, rep_compensacion double precision, rep_trabajo_oficina double precision, rep_diferencia double precision, rep_diferencia_acumulada double precision, rep_horas_extras_remuneradas double precision, rep_horas_trabajadas_dia1 double precision, rep_horas_trabajadas_dia2 double precision, rep_horas_trabajadas_dia3 double precision, rep_horas_trabajadas_dia4 double precision, rep_horas_trabajadas_dia5 double precision, rep_horas_trabajadas_dia6 double precision, rep_horas_trabajadas_dia7 double precision, rep_horas_trabajadas_dia8 double precision, rep_horas_trabajadas_dia9 double precision, rep_horas_trabajadas_dia10 double precision, rep_horas_trabajadas_dia11 double precision, rep_horas_trabajadas_dia12 double precision, rep_horas_trabajadas_dia13 double precision, rep_horas_trabajadas_dia14 double precision, rep_horas_trabajadas_dia15 double precision, rep_horas_trabajadas_dia16 double precision, rep_horas_trabajadas_dia17 double precision, rep_horas_trabajadas_dia18 double precision, rep_horas_trabajadas_dia19 double precision, rep_horas_trabajadas_dia20 double precision, rep_horas_trabajadas_dia21 double precision, rep_horas_trabajadas_dia22 double precision, rep_horas_trabajadas_dia23 double precision, rep_horas_trabajadas_dia24 double precision, rep_horas_trabajadas_dia25 double precision, rep_horas_trabajadas_dia26 double precision, rep_horas_trabajadas_dia27 double precision, rep_horas_trabajadas_dia28 double precision, rep_horas_trabajadas_dia29 double precision, rep_horas_trabajadas_dia30 double precision, rep_horas_trabajadas_dia31 double precision, rep_nombre_dia1 character varying, rep_nombre_dia2 character varying, rep_nombre_dia3 character varying, rep_nombre_dia4 character varying, rep_nombre_dia5 character varying, rep_nombre_dia6 character varying, rep_nombre_dia7 character varying, rep_nombre_dia8 character varying, rep_nombre_dia9 character varying, rep_nombre_dia10 character varying, rep_nombre_dia11 character varying, rep_nombre_dia12 character varying, rep_nombre_dia13 character varying, rep_nombre_dia14 character varying, rep_nombre_dia15 character varying, rep_nombre_dia16 character varying, rep_nombre_dia17 character varying, rep_nombre_dia18 character varying, rep_nombre_dia19 character varying, rep_nombre_dia20 character varying, rep_nombre_dia21 character varying, rep_nombre_dia22 character varying, rep_nombre_dia23 character varying, rep_nombre_dia24 character varying, rep_nombre_dia25 character varying, rep_nombre_dia26 character varying, rep_nombre_dia27 character varying, rep_nombre_dia28 character varying, rep_nombre_dia29 character varying, rep_nombre_dia30 character varying, rep_nombre_dia31 character varying, rep_diaslaborados integer, rep_diasfaltas integer, rep_diaspermiso integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD;  
  tmar2 RECORD;
  varTracodigo character varying;
 -- trep RECORD;
BEGIN
varTracodigo := '0';
IF trabajadorcodigo <> '' THEN
    select tem.tra_codigo::character varying
    INTO varTracodigo
    from asistencias.tbltrabajadores_tra as tem where tem.tra_identificador = CAST(trabajadorcodigo AS VARCHAR);
END IF;

--Desde este punto es una tabla temporal de la horas extras
CREATE TEMPORARY TABLE tmarcacionesExtras (
cod integer,
tipo character varying,
tra_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
ingresoR timestamp without time zone,
salidaR timestamp without time zone,
hor_codigo integer,
horas1 double precision default 0,--tarde regrigerio
horas2 double precision default 0,
horas double precision default 0, -- horas trabajadas
hora_atrabajar double precision default 0,
tardeingreso double precision default 0,
tarderefrigerio double precision default 0
); 
  asi.asi_ingreso ,asi.asi_salida,asi.asi_salidarefrigerio,asi.asi_ingresorefrigerio ,
  asi.asi_horas_atrabajar,asi.asi_horas_trabajadas,
  case when asi.asi_tardeingreso > 0 then asi.asi_tardeingreso else 0 end
  ,case when asi.asi_tardeingresorefrigerio > 0 then asi.asi_tardeingresorefrigerio else 0 end ,
  asi.hor_codigo
  --,case when asi.mar_martipo in ('A','X') then  asi.asi_horas_trabajadas + coalesce(extract(epoch from age( asi.asi_ingresorefrigerio,asi.asi_salidarefrigerio)),0)  else asi.asi_horas_trabajadas   end    
  from asistencias.tblasistencias_asi as asi
 WHERE cast(asi.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end)
 and EXTRACT(year from asi.asi_fecha) =  EXTRACT(year from par_fecha::date) and EXTRACT(month from asi.asi_fecha) =  EXTRACT(month from par_fecha::date)
 and asi.mar_martipo is not null and asi.mar_martipo <> 'U');

--****************************************************************************************************
--segunda tablatempral temporal 
 CREATE TEMPORARY TABLE tmarcaciones (
feriado char(1),
tra_codigo integer,
hor_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,
horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision default 0,
horas_tardesalida double precision default 0,
tipo character varying,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,
e_permisomasivojustificado boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision,
h_permisomasivojustificado double precision,

horas_trabajadas_remuneradas double precision

);

--ingresa las marcacaiones normales y remuneradas
ingreso, salida, ingresorefrigerio ,salidarefrigerio,
horas_atrabajar, horas_trabajadas, horas_tardeingreso,horas_tardesalida,tipo,horas_trabajadas_remuneradas)
(select cal.cal_tipo ,asi.tra_codigo, asi.hor_codigo,asi.asi_fecha,
  asi.asi_ingreso ,asi.asi_salida,asi.asi_salidarefrigerio,asi.asi_ingresorefrigerio ,
  asi.asi_horas_atrabajar, asi.asi_horas_trabajadas,
  case when asi.asi_tardeingreso > 0 then asi.asi_tardeingreso else 0 end
  ,case when asi.asi_tardeingresorefrigerio > 0 then asi.asi_tardeingresorefrigerio else 0 end 
  , asi.mar_martipo,
  CASE WHEN asi.asi_horas_trabajadas = asi.asi_horas_atrabajar THEN 0 ELSE asi.asi_horas_atrabajar END 
   from asistencias.tblasistencias_asi as asi
  inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = asi.asi_fecha
 WHERE cast(asi.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end)
 and EXTRACT(year from asi.asi_fecha) =  EXTRACT(year from par_fecha::date) and EXTRACT(month from asi.asi_fecha) =  EXTRACT(month from par_fecha::date)
 and (asi.mar_martipo is null or asi.mar_martipo = 'U' ) );

---llena lo dias sin marcacaiones
cal.cal_tipo,
tra.tra_codigo,
hor.hor_codigo,
fht.fht_fecha,
(extract(epoch from age( 
case when dhr.dhr_nocturno 
  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
  else cast(now() as date)+ dhr.dhr_salida end
  ,cast(now() as date) + dhr.dhr_ingreso  
  ) ) - (case when dhr.dhr_increfrigerio then  0 else (dhr.dhr_tiemporefrigerio *60)  end) )/*/3600*/  as nhoras

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo and tra.tra_estado
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
--left join asistencias.tblasistencias_asi as asi on fht.fht_fecha <> asi.asi_fecha
WHERE cast(tra.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end)
and EXTRACT(year from fht.fht_fecha) =  EXTRACT(year from par_fecha::date) and EXTRACT(month from fht.fht_fecha) =  EXTRACT(month from par_fecha::date) and
 fht.fht_fecha not in (
 select asi.asi_fecha from asistencias.tblasistencias_asi as asi where  EXTRACT(year from asi.asi_fecha) =  EXTRACT(year from par_fecha::date) and EXTRACT(month from asi.asi_fecha) =  EXTRACT(month from par_fecha::date) and
 cast(asi.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end ) and (asi.mar_martipo is null ) order by asi.asi_fecha )
order  by fht.fht_fecha asc
);

--ingresa los permisos
FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo  left join asistencias.tbltrabajadores_tra as a on p.tra_codigo = a.tra_codigo where
                cast(P.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end) LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
  UPDATE tmarcaciones SET e_comision = true, h_comision= tmarcaciones.horas_trabajadas
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
  UPDATE tmarcaciones SET e_vacaciones = true , h_vacaciones = tmarcaciones.horas_atrabajar 
  WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin and 
        CASE WHEN rvacaciones.are_codigo IN (161,171) THEN  tmarcaciones.feriado <> 'F' and  TRIM(to_char(tmarcaciones.fecha, 'Day'))  <> TRIM('Sunday   ') ELSE TRUE END and 
        case when rvacaciones.are_codigo = 161 and rvacaciones.tra_codigo <> 371 then    TRIM(to_char(tmarcaciones.fecha, 'Day'))  <> TRIM('Saturday ') else true  END  ;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
  UPDATE tmarcaciones SET e_medico= true , h_medico = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
  UPDATE tmarcaciones SET e_permisos = true , h_permisos = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
  UPDATE tmarcaciones SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
  UPDATE tmarcaciones SET e_compensacion  = true , h_compensacion  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
  -- permiso masivo justificado
   IF rvacaciones.tip_codigo = 24 THEN 
   UPDATE tmarcaciones SET e_permisomasivojustificado  = true , h_permisomasivojustificado  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;       
END LOOP;

