 FOR tra2 IN Select * from  asistencias.tbltrabajadores_tra as trab  
            inner join asistencias.tblareas_are as are on are.are_codigo = trab.are_codigo
            inner join asistencias.tblpuestos_pue as pue on pue.pue_codigo = trab.pue_codigo
            WHERE cast(trab.tra_codigo as varchar)  LIKE (case  when varTracodigo::int = 0 then '%' ELSE varTracodigo end) LOOP 

--horas trabajadas 1
(coalesce((select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo  and t.tipo is null AND t.feriado  <>'F'),0)
  +coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and   td.tipo ='A'),0)) /3600,
--trabajo de comicion 2
(coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo   ),0)
  +coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.tipo ='C'),0))/3600,

--VACACIONES 3
(coalesce((  select sum(t.h_vacaciones ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and   t.feriado  <>'F')  ,0)
  +coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and   td.tipo in ('V','B','D')),0))/3600,
--MEDICO 4
(coalesce((select sum(t.h_medico  ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo   ),0)
  +coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.tipo ='M'),0))/3600,

--permisos Justificado 5
(coalesce((select sum(t.h_permisosjustificado ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo ),0)
  +coalesce((select sum(t.h_permisomasivojustificado ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo ),0)
  +coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and   td.tipo in ('J','F','G','H','K')),0))/3600,

--horas A trabajaR 6
(select sum(t.horas_atrabajar ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and   t.feriado  <>'F' and t.tipo is null)/3600,

--horas tardansas ingreso  7
coalesce(((select sum(t.horas_tardeingreso  ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and   t.feriado  <>'F')/3600),0)
+ coalesce(((select sum(t.horas_tardesalida  ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and   t.feriado  <>'F')/3600),0)
+coalesce(((select sum(te.tardeingreso  ) from tmarcacionesExtras as te where te.tra_codigo = tra2.tra_codigo   )/3600),0)
+coalesce(((select sum(te.tarderefrigerio  ) from tmarcacionesExtras as te where te.tra_codigo = tra2.tra_codigo   )/3600),0),
--
--horas tardansas tardanza refrigerio 8
coalesce(((select sum(t.horas_tardeingreso  ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and   t.feriado  <>'F')/3600),0)
+ coalesce(((select sum(t.horas_tardesalida  ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and   t.feriado  <>'F')/3600),0)
+coalesce(((select sum(te.tardeingreso  ) from tmarcacionesExtras as te where te.tra_codigo = tra2.tra_codigo   )/3600),0)
+coalesce(((select sum(te.tarderefrigerio  ) from tmarcacionesExtras as te where te.tra_codigo = tra2.tra_codigo   )/3600),0),

--permisos Personales 9
(coalesce((select sum(t.h_permisos   ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo   ),0)
  +coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.tipo IN ('P' , 'O', 'N')),0))/3600,

--Extras 10
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and   td.tipo in ('X' , 'E')),0)/3600,

--compensacion 11
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and   td.tipo ='S'),0)/3600,

--horas extras remuneradas 12
(coalesce((select sum(td.horas_trabajadas) from tmarcaciones  as td where td.tra_codigo = tra2.tra_codigo and   td.tipo ='U'),0))/3600,

--TRABAJO AUTORIZADO REMUNERADO 13
(coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and   td.tipo ='T'),0))/3600,

--Permiso Mañana Tarde 14
(coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and   td.tipo ='O'),0))/3600,

--horas debio trabajadar2 15
(coalesce((select sum(t2.horas_trabajadas_remuneradas ) from tmarcaciones as t2 where t2.tra_codigo = tra2.tra_codigo and  t2.tipo = 'U'),0))/3600
  );
 
 END LOOP;
