WITH subquery AS (
     select 
    a.tra_codigo,
    (sum(dia1)/3600) dia1,
    (sum(dia2)/3600) dia2,
    (sum(dia3)/3600) dia3,
    (sum(dia4)/3600) dia4,
    (sum(dia5)/3600) dia5,
    (sum(dia6)/3600) dia6,
    (sum(dia7)/3600) dia7,
    (sum(dia8)/3600) dia8,
    (sum(dia9)/3600) dia9,
    (sum(dia10)/3600) dia10,
    (sum(dia11)/3600) dia11,
    (sum(dia12)/3600) dia12,
    (sum(dia13)/3600) dia13,
    (sum(dia14)/3600) dia14,
    (sum(dia15)/3600) dia15,
    (sum(dia16)/3600) dia16,
    (sum(dia17)/3600) dia17,
    (sum(dia18)/3600) dia18,
    (sum(dia19)/3600) dia19,
    (sum(dia20)/3600) dia20,
    (sum(dia21)/3600) dia21,
    (sum(dia22)/3600) dia22,
    (sum(dia23)/3600) dia23,
    (sum(dia24)/3600) dia24,
    (sum(dia25)/3600) dia25,
    (sum(dia26)/3600) dia26,
    (sum(dia27)/3600) dia27,
    (sum(dia28)/3600) dia28,
    (sum(dia29)/3600) dia29,
    (sum(dia30)/3600) dia30,
    (sum(dia31)/3600) dia31
    from
    (
    Select 
    ma.tra_codigo,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=1
    THEN ma.horas_trabajadas END),0) dia1,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=2
    THEN ma.horas_trabajadas END),0) dia2,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=3
    THEN ma.horas_trabajadas END),0) dia3,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=4
    THEN ma.horas_trabajadas END),0) dia4,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=5
    THEN ma.horas_trabajadas END),0) dia5,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=6
    THEN ma.horas_trabajadas END),0) dia6,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=7
    THEN ma.horas_trabajadas END),0) dia7,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=8
    THEN ma.horas_trabajadas END),0) dia8,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=9
    THEN ma.horas_trabajadas END),0) dia9,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=10
    THEN ma.horas_trabajadas END),0) dia10,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=11
    THEN ma.horas_trabajadas END),0) dia11,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=12
    THEN ma.horas_trabajadas END),0) dia12,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=13
    THEN ma.horas_trabajadas END),0) dia13,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=14
    THEN ma.horas_trabajadas END),0) dia14,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=15
    THEN ma.horas_trabajadas END),0) dia15,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=16
    THEN ma.horas_trabajadas END),0) dia16,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=17
    THEN ma.horas_trabajadas END),0) dia17,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=18
    THEN ma.horas_trabajadas END),0) dia18,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=19
    THEN ma.horas_trabajadas END),0) dia19,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=20
    THEN ma.horas_trabajadas END),0) dia20,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=21
    THEN ma.horas_trabajadas END),0) dia21,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=22
    THEN ma.horas_trabajadas END),0) dia22,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=23
    THEN ma.horas_trabajadas END),0) dia23,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=24
    THEN ma.horas_trabajadas END),0) dia24,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=25
    THEN ma.horas_trabajadas END),0) dia25,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=26
    THEN ma.horas_trabajadas END),0) dia26,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=27
    THEN ma.horas_trabajadas END),0) dia27,
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=28
    THEN ma.horas_trabajadas END),0) dia28,
    case when  5 > date_part('day' ,(par_fecha::date + interval '28 day')) then null else
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=29
    THEN ma.horas_trabajadas END),0) END dia29,
    case when  5 > date_part('day' ,(par_fecha::date + interval '28 day')) then null else
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=30
    THEN ma.horas_trabajadas END),0) END dia30,
    case when  5 > date_part('day' ,(par_fecha::date + interval '28 day')) then null else
    COALESCE((CASE WHEN
    date_part('day',ma.fecha)=31
    THEN ma.horas_trabajadas END),0) END dia31
    from
    tmarcaciones as ma
    order by ma.tra_codigo ASC, ma.fecha asc
    ) as a
    group by a.tra_codigo
)
UPDATE trespuestas
SET 
    horas_trabajadas_dia1 = subquery.dia1,
