    horas_trabajadas_dia26 = subquery.dia26,
    horas_trabajadas_dia27 = subquery.dia27,
    horas_trabajadas_dia28 = subquery.dia28,
    horas_trabajadas_dia29 = subquery.dia29,
    horas_trabajadas_dia30 = subquery.dia30,
    horas_trabajadas_dia31 = subquery.dia31
    FROM subquery
WHERE trespuestas.tra_codigo = subquery.tra_codigo;

WITH subquery AS (
     select 
    ndia1,
    ndia2,
    ndia3,
    ndia4,
    ndia5,
    ndia6,
    ndia7,
    ndia8,
    ndia9,
    ndia10,
    ndia11,
    ndia12,
    ndia13,
    ndia14,
    ndia15,
    ndia16,
    ndia17,
    ndia18,
    ndia19,
    ndia20,
    ndia21,
    ndia22,
    ndia23,
    ndia24,
    ndia25,
    ndia26,
    ndia27,
    ndia28,
    ndia29,
    ndia30,
    ndia31
    from
    (
    Select 
    SUBSTRING(public.dia_semana((par_fecha::date + interval'0 day')::date), 1,1)  ndia1,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'1 day')::date), 1,1)  ndia2,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'2 day')::date), 1,1)  ndia3,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'3 day')::date), 1,1)  ndia4,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'4 day')::date), 1,1)  ndia5,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'5 day')::date), 1,1)  ndia6,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'6 day')::date), 1,1)  ndia7,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'7 day')::date), 1,1)  ndia8,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'8 day')::date), 1,1)  ndia9,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'9 day')::date), 1,1)  ndia10,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'10 day')::date), 1,1)  ndia11,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'11 day')::date), 1,1)  ndia12,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'12 day')::date), 1,1)  ndia13,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'13 day')::date), 1,1)  ndia14,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'14 day')::date), 1,1)  ndia15,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'15 day')::date), 1,1)  ndia16,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'16 day')::date), 1,1)  ndia17,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'17 day')::date), 1,1)  ndia18,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'18 day')::date), 1,1)  ndia19,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'19 day')::date), 1,1)  ndia20,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'20 day')::date), 1,1)  ndia21,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'21 day')::date), 1,1)  ndia22,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'22 day')::date), 1,1)  ndia23,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'23 day')::date), 1,1)  ndia24,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'24 day')::date), 1,1)  ndia25,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'25 day')::date), 1,1)  ndia26,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'26 day')::date), 1,1)  ndia27,
    SUBSTRING(public.dia_semana((par_fecha::date + interval'27 day')::date), 1,1)  ndia28,

    case when  5 > date_part('day' ,(par_fecha::date + interval '28 day')) then '' else
    SUBSTRING(public.dia_semana((par_fecha::date + interval'28 day')::date), 1,1) END ndia29,
    case when  5 > date_part('day' ,(par_fecha::date + interval '29 day')) then '' else
    SUBSTRING(public.dia_semana((par_fecha::date + interval'29 day')::date), 1,1) END ndia30,
    case when  5 > date_part('day' ,(par_fecha::date + interval '30 day')) then '' else
    SUBSTRING(public.dia_semana((par_fecha::date + interval'30 day')::date), 1,1) END ndia31
    from
    tmarcaciones as ma
    order by ma.fecha asc
    ) as a
    group by 
    ndia1,
    ndia2,
    ndia3,
    ndia4,
    ndia5,
    ndia6,
    ndia7,
    ndia8,
    ndia9,
    ndia10,
    ndia11,
    ndia12,
    ndia13,
    ndia14,
    ndia15,
    ndia16,
    ndia17,
    ndia18,
    ndia19,
    ndia20,
    ndia21,
    ndia22,
    ndia23,
    ndia24,
    ndia25,
    ndia26,
    ndia27,
    ndia28,
    ndia29,
    ndia30,
    ndia31
)
UPDATE trespuestas
SET     
    nombre_dia1 = subquery.ndia1,
    nombre_dia2 = subquery.ndia2,
    nombre_dia3 = subquery.ndia3,
    nombre_dia4 = subquery.ndia4,
    nombre_dia5 = subquery.ndia5,
    nombre_dia6 = subquery.ndia6,
    nombre_dia7 = subquery.ndia7,
    nombre_dia8 = subquery.ndia8,
    nombre_dia9 = subquery.ndia9,
    nombre_dia10 = subquery.ndia10,
    nombre_dia11 = subquery.ndia11,
    nombre_dia12 = subquery.ndia12,
    nombre_dia13 = subquery.ndia13,
    nombre_dia14 = subquery.ndia14,
    nombre_dia15 = subquery.ndia15,
    nombre_dia16 = subquery.ndia16,
    nombre_dia17 = subquery.ndia17,
    nombre_dia18 = subquery.ndia18,
    nombre_dia19 = subquery.ndia19,
    nombre_dia20 = subquery.ndia20,
    nombre_dia21 = subquery.ndia21,
    nombre_dia22 = subquery.ndia22,
    nombre_dia23 = subquery.ndia23,
    nombre_dia24 = subquery.ndia24,
    nombre_dia25 = subquery.ndia25,
    nombre_dia26 = subquery.ndia26,
    nombre_dia27 = subquery.ndia27,
    nombre_dia28 = subquery.ndia28,
    nombre_dia29 = subquery.ndia29,
    nombre_dia30 = subquery.ndia30,
    nombre_dia31 = subquery.ndia31
    FROM subquery;

WITH subquery AS (
   select 
    a.tra_codigo,
    sum(horas_trabajadas) dias_trabajados,
    sum(faltas) faltas,
    sum(per) permiso_dias
     from(
    select 
    t.tra_codigo,
    t.fecha,
    case when  t.horas_trabajadas > 0 and t.horas_trabajadas is not null then 
    1 else 0 end  horas_trabajadas,
    case when t.horas_atrabajar > 0 and (t.horas_trabajadas = 0 or t.horas_trabajadas is  null) then 
    1  else 0 end faltas,
    case when  t.e_permisos then 1
      when  t.e_permisosjustificado then 1 
      when  t.e_permisomasivojustificado then 1 
      else 0 End per
     from
     tmarcaciones  as t
     
     group by 
     t.horas_trabajadas
     ,t.horas_atrabajar,
     t.fecha,
     t.tra_codigo,
     t.e_permisos,
     t.e_permisosjustificado,
     t.e_permisomasivojustificado
     order by t.tra_codigo asc, t.fecha asc
    ) as a
     group by a.tra_codigo
   
)
UPDATE trespuestas
SET     
    res_diaslaborados = subquery.dias_trabajados,
    res_diasfaltas = subquery.faltas,
    res_diaspermiso = subquery.permiso_dias
    FROM subquery
    where trespuestas.tra_codigo = subquery.tra_codigo;
 
   
   

