CREATE TEMPORARY TABLE treporte (
tra_codigo integer,
tra_nombrecompleto character varying,
tra_dni character varying,
are_codigo integer,
are_nombre character varying,
pue_codigo integer,
pue_nombre character varying,

rep_horas_trabajadas double precision,--1
