rep_horas_extras_remuneradas double precision,--14

rep_horas_trabajadas_dia1 double precision DEFAULT 0,
rep_horas_trabajadas_dia2 double precision DEFAULT 0,
rep_horas_trabajadas_dia3 double precision DEFAULT 0,
rep_horas_trabajadas_dia4 double precision DEFAULT 0,
rep_horas_trabajadas_dia5 double precision DEFAULT 0,
