rep_horas_trabajadas_dia22 double precision DEFAULT 0,
rep_horas_trabajadas_dia23 double precision DEFAULT 0,
rep_horas_trabajadas_dia24 double precision DEFAULT 0,
rep_horas_trabajadas_dia25 double precision DEFAULT 0,
