rep_horas_trabajadas_dia29 double precision DEFAULT 0,
rep_horas_trabajadas_dia30 double precision DEFAULT 0,
rep_horas_trabajadas_dia31 double precision DEFAULT 0,

rep_nombre_dia1 VARCHAR,
rep_nombre_dia2 VARCHAR,
rep_nombre_dia3 VARCHAR,
rep_nombre_dia4 VARCHAR,
rep_nombre_dia5 VARCHAR,
rep_nombre_dia6 VARCHAR,
rep_nombre_dia7 VARCHAR,
rep_nombre_dia8 VARCHAR,
rep_nombre_dia9 VARCHAR,
rep_nombre_dia10 VARCHAR,
rep_nombre_dia11 VARCHAR,
rep_nombre_dia12 VARCHAR,
rep_nombre_dia13 VARCHAR,
rep_nombre_dia14 VARCHAR,
rep_nombre_dia15 VARCHAR,
rep_nombre_dia16 VARCHAR,
rep_nombre_dia17 VARCHAR,
rep_nombre_dia18 VARCHAR,
rep_nombre_dia19 VARCHAR,
