rep_nombre_dia30 VARCHAR,
rep_nombre_dia31 VARCHAR,

rep_diaslaborados integer,
rep_diasfaltas integer,
rep_diaspermiso integer
);

  
    ( Select trep.tra_codigo, trep.tra_nombrecompleto,trep.tra_dni,trep.are_codigo,trep.are_nombre,trep.pue_codigo,trep.pue_nombre,
---horas trabajadas
coalesce(trep.res_horas_trabajadas, 0) +coalesce(trep.res_vacaciones , 0) +coalesce(trep.res_medico , 0) + coalesce(trep.res_permiso_justificado , 0) + coalesce(trep.res_horas_debio_trabajar2 , 0) - coalesce(trep.res_permisos_personal , 0) as ene_1, -- - coalesce(trep.res_tardanzas_ingreso , 0)

--trabajo comision
coalesce(trep.res_trabajo_comision , 0) as ene_2,

--vacaciones
coalesce(trep.res_vacaciones , 0) as ene_3,

--descanso medico
coalesce(trep.res_medico , 0) as ene_4,

--permiso justificado
coalesce(trep.res_permiso_justificado , 0) as ene_5,

--debio trabajar
coalesce(trep.res_horas_atrabajar , 0) as ene_6,

--tardanzas ingreso
coalesce(trep.res_tardanzas_ingreso , 0) as ene_7,

--tardanzas refrigerio
coalesce(trep.res_tardanzas_refrigerio , 0) as ene__7,

--permiso
coalesce(trep.res_permisos_personal , 0) as ene_8,

--horas extra seguridad
coalesce(trep.res_extras , 0) as ene_9,

--compensacion horas
coalesce(trep.res_compensacion , 0) as ene_10,

--trabajo oficina
coalesce(trep.res_horas_trabajadas, 0) + coalesce(trep.res_horas_debio_trabajar2 , 0) - coalesce(trep.res_permisos_personal , 0) - (coalesce(trep.res_tardanzas_ingreso , 0)+coalesce(trep.res_tardanzas_refrigerio , 0))  - coalesce(trep.res_trabajo_comision , 0)   as ene_11,

--diferencia
coalesce(trep.res_horas_trabajadas, 0) +coalesce(trep.res_vacaciones , 0) +coalesce(trep.res_medico , 0) + coalesce(trep.res_permiso_justificado , 0) + coalesce(trep.res_horas_debio_trabajar2 , 0) - coalesce(trep.res_permisos_personal , 0) - (coalesce(trep.res_tardanzas_ingreso , 0)+coalesce(trep.res_tardanzas_refrigerio , 0)) - coalesce(trep.res_horas_atrabajar , 0) as ene_12,

--diferencia acumulada 
coalesce(trep.res_horas_trabajadas, 0) +coalesce(trep.res_vacaciones , 0) +coalesce(trep.res_medico , 0) + coalesce(trep.res_permiso_justificado , 0) + coalesce(trep.res_horas_debio_trabajar2 , 0) - coalesce(trep.res_permisos_personal , 0) - (coalesce(trep.res_tardanzas_ingreso , 0)+coalesce(trep.res_tardanzas_refrigerio , 0)) -coalesce(trep.res_horas_atrabajar , 0) as ene_13,

 --horas extras remuneradas

coalesce(trep.res_horas_extras_remuneradas , 0) + coalesce(trep.res_trabajo_autorizado_remunerado , 0) as ene_14,
coalesce(trep.horas_trabajadas_dia1 ,0),
coalesce(trep.horas_trabajadas_dia2 ,0),
coalesce(trep.horas_trabajadas_dia3 ,0),
coalesce(trep.horas_trabajadas_dia4 ,0),
coalesce(trep.horas_trabajadas_dia5 ,0),
coalesce(trep.horas_trabajadas_dia6 ,0),
coalesce(trep.horas_trabajadas_dia7 ,0),
coalesce(trep.horas_trabajadas_dia8 ,0),
coalesce(trep.horas_trabajadas_dia9 ,0),
coalesce(trep.horas_trabajadas_dia10 ,0),
coalesce(trep.horas_trabajadas_dia11 ,0),
coalesce(trep.horas_trabajadas_dia12 ,0),
coalesce(trep.horas_trabajadas_dia13 ,0),
coalesce(trep.horas_trabajadas_dia14 ,0),
coalesce(trep.horas_trabajadas_dia15 ,0),
coalesce(trep.horas_trabajadas_dia16 ,0),
coalesce(trep.horas_trabajadas_dia17 ,0),
coalesce(trep.horas_trabajadas_dia18 ,0),
coalesce(trep.horas_trabajadas_dia19 ,0),
coalesce(trep.horas_trabajadas_dia20 ,0),
coalesce(trep.horas_trabajadas_dia21 ,0),
coalesce(trep.horas_trabajadas_dia22 ,0),
coalesce(trep.horas_trabajadas_dia23 ,0),
coalesce(trep.horas_trabajadas_dia24 ,0),
coalesce(trep.horas_trabajadas_dia25 ,0),
coalesce(trep.horas_trabajadas_dia26 ,0),
coalesce(trep.horas_trabajadas_dia27 ,0),
coalesce(trep.horas_trabajadas_dia28 ,0),
coalesce(trep.horas_trabajadas_dia29 ,0),
coalesce(trep.horas_trabajadas_dia30 ,0),
coalesce(trep.horas_trabajadas_dia31 ,0),

trep.nombre_dia1 ,
trep.nombre_dia2 ,
trep.nombre_dia3 ,
trep.nombre_dia4 ,
trep.nombre_dia5 ,
trep.nombre_dia6 ,
trep.nombre_dia7 ,
trep.nombre_dia8 ,
trep.nombre_dia9 ,
trep.nombre_dia10 ,
trep.nombre_dia11 ,
trep.nombre_dia12 ,
trep.nombre_dia13 ,
trep.nombre_dia14 ,
trep.nombre_dia15 ,
trep.nombre_dia16 ,
trep.nombre_dia17 ,
trep.nombre_dia18 ,
trep.nombre_dia19 ,
trep.nombre_dia20 ,
trep.nombre_dia21 ,
trep.nombre_dia22 ,
trep.nombre_dia23 ,
trep.nombre_dia24 ,
trep.nombre_dia25 ,
trep.nombre_dia26 ,
trep.nombre_dia27 ,
trep.nombre_dia28 ,
trep.nombre_dia29 ,
trep.nombre_dia30 ,
trep.nombre_dia31 ,
COALESCE(trep.res_diaslaborados ,0),
COALESCE(trep.res_diasfaltas ,0),
COALESCE(trep.res_diaspermiso ,0)
 from trespuestas as trep);

            
 RETURN QUERY EXECUTE 'SELECT * FROM treporte order by 2';
END;
$$;


ALTER FUNCTION asistencias.fun_mensual(par_fecha character, trabajadorcodigo character varying, vararecodigo integer) OWNER TO postgres;

--
-- Name: fun_recalculogeneral(date, integer, character varying, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_recalculogeneral(fechaini date, codhorario integer, codtrabajador character varying, asicodigo integer) RETURNS TABLE(asi_codigo integer, tra_codigo integer, asi_fecha date, asi_ingreso timestamp without time zone, asi_ingresorefrigerio timestamp without time zone, asi_salidarefrigerio timestamp without time zone, asi_salida timestamp without time zone, mar_martipo character varying, ingresotarde double precision, tarderefrigerio double precision, horas_trabajadas double precision, horas_atrabajar double precision, dia_semana character varying, hor_codigo integer, dhr_nocturno boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD; 
  nombredia character varying; 
  rtmarcacion RECORD;
  ingresotemp character varying;
  marcacionesx RECORD;
  descripcionmarcacion character varying;
  codtra integer ;
  vartipo character varying ;
  varsalida time;
  varingreso time;
  varingresorefrigerio time;
  varsalidarefrigerio time;
  varfecha date;
  
  fechatemp date; 
  tratemp integer;
  tipotemp character varying;
  counts integer;
BEGIN
--****************************************************************************************************
--segunda tablatempral temporal 


CREATE TEMPORARY TABLE tasistencias (
  asi_codigo integer,
  tra_codigo integer,
  asi_fecha date,
  asi_ingreso timestamp,
  asi_ingresorefrigerio timestamp,
  asi_salidarefrigerio timestamp,
  asi_salida timestamp,
  mar_martipo varchar,
  ingresotarde double precision,
  tarderefrigerio double precision,
  horas_trabajadas double precision,
  horas_atrabajar double precision,
  dia_semana character varying,
  hor_codigo integer,
  dhr_nocturno boolean
);

IF codtrabajador <> '0' THEN 
  codtra := (select tr.tra_codigo from asistencias.tbltrabajadores_tra as tr where tr.tra_identificador in (codtrabajador) limit 1);
ELSE 
  codtra := 0;
END if;


  Select tm.asi_codigo ,tm.tra_codigo ,tm.asi_fecha, tm.asi_ingreso,tm.asi_salidarefrigerio,tm.asi_ingresorefrigerio,tm.asi_salida,tm.mar_martipo,
     
      CASE WHEN tm.hor_codigo <> 131 THEN
        CASE WHEN COALESCE(tm.mar_martipo,'IN') in ('IN') THEN
                 case  when (tm.asi_ingreso> tm.asi_fecha+ dhr.dhr_ingreso+ interval '1min' * dhr.dhr_tolingreso )
                    then extract(epoch from age(tm.asi_ingreso, tm.asi_fecha+ dhr.dhr_ingreso )) /*/3600*/
                 else 0 end
            WHEN COALESCE(tm.mar_martipo,'IN') in ('X') and  hor.hor_codigo <> 116 THEN
         case  when (tm.asi_ingreso> tm.asi_fecha+ dhr.dhr_ingreso+ interval '1min' * dhr.dhr_tolingreso )
                    then extract(epoch from age(tm.asi_ingreso, tm.asi_fecha+ dhr.dhr_ingreso )) /*/3600*/
                 else 0 end

        ELSE 0
        END
      ELSE 0 END as IngresoTarde,


      CASE WHEN tm.hor_codigo <> 131 THEN
        CASE WHEN COALESCE(tm.mar_martipo,'IN') in ('IN') THEN
                  CASE WHEN dhr.dhr_nocturno 
                       THEN
                            case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                  then extract(epoch from age(tm.asi_ingresorefrigerio, (tm.asi_fecha + INTERVAL'1 DAY')+ (dhr.dhr_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                            else 0 end

                       ELSE
                            case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                  --then extract(epoch from age(tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute'))  )) /*/3600 */
                                  then extract(epoch from age(tm.asi_ingresorefrigerio, tm.asi_fecha+ (dhr.dhr_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                            else 0 end
                       END
             WHEN COALESCE(tm.mar_martipo,'IN') in ('X')  and  hor.hor_codigo <> 116 THEN
                   CASE WHEN dhr.dhr_nocturno 
                       THEN
                             case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                     -- then extract(epoch from age(tm.asi_ingresorefrigerio ,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) )) /*/3600 */
                                  then extract(epoch from age(tm.asi_ingresorefrigerio , (tm.asi_fecha + INTERVAL'1 DAY')+ (dhr.dhr_salidarefrigerio  + (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                             else 0 end
                       ELSE
                            case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                     -- then extract(epoch from age(tm.asi_ingresorefrigerio ,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) )) /*/3600 */
                                  then extract(epoch from age(tm.asi_ingresorefrigerio , tm.asi_fecha+ (dhr.dhr_salidarefrigerio  + (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                             else 0 end
                       END
        ELSE 0
        END
      ELSE 0  END as TardeRefrigerio,

        CASE WHEN tm.mar_martipo = 'U' THEN
                  case when   tm.asi_horas_trabajadas > tm.asi_horas_atrabajar 
                          THEN   (tm.asi_horas_trabajadas - tm.asi_horas_atrabajar )
                       WHEN tm.asi_horas_trabajadas = tm.asi_horas_atrabajar 
                          THEN tm.asi_horas_trabajadas
                       ELSE   0 
                  END 
              WHEN  tm.mar_martipo IN ('A','X') THEN
             -- TM.asi_horas_trabajadas + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
    case when tm.hor_codigo = 116 then 
      (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -    coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )  ) + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
    else
      (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -  case when dhr.dhr_increfrigerio then 0 else   coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )   end ) -- + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
                end
        ELSE  
           -- case when  (tm.asi_horas_trabajadas is null or tm.asi_horas_trabajadas = 0) and tm.asi_salida is not null then 
                 (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -  case when dhr.dhr_increfrigerio then 0 else  coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )   end ) /*/3600*/
           --  else  tm.asi_horas_trabajadas end 
                
        END as horasdia,
        (extract(epoch from age( 
        case when dhr.dhr_nocturno 
          then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
          else cast(now() as date)+ dhr.dhr_salida end
          ,cast(now() as date) + dhr.dhr_ingreso  
         ) ) - (case when dhr.dhr_increfrigerio then 0 else  (dhr.dhr_tiemporefrigerio *60)  end) )/*/3600*/  as nhoras,
        dia_semana(tm.asi_fecha::date ),tm.hor_codigo,dhr.dhr_nocturno
       from  asistencias.tblasistencias_asi as tm  
      inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = tm.hor_codigo and hor.hor_codigo <> 9999
      inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = tm.hor_codigo  and dhr.dhr_day =  to_char(tm.asi_fecha , 'Day')
       where tm.asi_tipomarca not in ('ERROR','S/T') and 
        tm.tra_codigo::character varying like case when codtra = 0 then '%' else codtra::character varying end and tm.asi_codigo::character varying like case when asicodigo = 0 then '%' else asicodigo::character varying end  --case when codtrabajador = '0' then true else tm.tra_codigo = codtra end  
      and extract(year from tm.asi_fecha) = case when extract(year from fechaini::date) > 2002 then  extract(year from fechaini::date) else extract(year from tm.asi_fecha) end  --and tm.asi_codigo in ( select * from asistencias.tblasistencias_asi where (asi_horas_trabajadas is null or asi_horas_trabajadas  = 0) and asi_salida is not null and asi_ingreso is not null)
       order by tm.tra_codigo ASC,tm.asi_ingreso ASC,tm.asi_salidarefrigerio asc, tm.asi_ingresorefrigerio asc , tm.asi_salida asc
);
tipotemp = '0';
counts = 0;
counts = (select count(*) from tasistencias);
  
IF counts = 1 THEN 
  SELECT s.asi_fecha,s.tra_codigo,s.mar_martipo INTO fechatemp,tratemp,tipotemp  FROM tasistencias AS s;
END IF;
IF tipotemp is null THEN 
  
          Select tm.asi_codigo ,tm.tra_codigo ,tm.asi_fecha, tm.asi_ingreso,tm.asi_salidarefrigerio,tm.asi_ingresorefrigerio,tm.asi_salida,tm.mar_martipo,
             
              CASE WHEN tm.hor_codigo <> 131 THEN
                CASE WHEN COALESCE(tm.mar_martipo,'IN') in ('IN') THEN
                         case  when (tm.asi_ingreso> tm.asi_fecha+ dhr.dhr_ingreso+ interval '1min' * dhr.dhr_tolingreso )
                            then extract(epoch from age(tm.asi_ingreso, tm.asi_fecha+ dhr.dhr_ingreso )) /*/3600*/
                         else 0 end
                    WHEN COALESCE(tm.mar_martipo,'IN') in ('X') and  hor.hor_codigo <> 116 THEN
                 case  when (tm.asi_ingreso> tm.asi_fecha+ dhr.dhr_ingreso+ interval '1min' * dhr.dhr_tolingreso )
                            then extract(epoch from age(tm.asi_ingreso, tm.asi_fecha+ dhr.dhr_ingreso )) /*/3600*/
                         else 0 end

                ELSE 0
                END
              ELSE 0 END as IngresoTarde,


              CASE WHEN tm.hor_codigo <> 131 THEN
                CASE WHEN COALESCE(tm.mar_martipo,'IN') in ('IN') THEN
                          CASE WHEN dhr.dhr_nocturno 
                               THEN
                                    case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                          then extract(epoch from age(tm.asi_ingresorefrigerio, (tm.asi_fecha + INTERVAL'1 DAY')+ (dhr.dhr_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                                    else 0 end

                               ELSE
                                    case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                          --then extract(epoch from age(tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute'))  )) /*/3600 */
                                          then extract(epoch from age(tm.asi_ingresorefrigerio, tm.asi_fecha+ (dhr.dhr_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                                    else 0 end
                               END
                     WHEN COALESCE(tm.mar_martipo,'IN') in ('X')  and  hor.hor_codigo <> 116 THEN
                           CASE WHEN dhr.dhr_nocturno 
                               THEN
                                     case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                             -- then extract(epoch from age(tm.asi_ingresorefrigerio ,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) )) /*/3600 */
                                          then extract(epoch from age(tm.asi_ingresorefrigerio , (tm.asi_fecha + INTERVAL'1 DAY')+ (dhr.dhr_salidarefrigerio  + (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                                     else 0 end
                               ELSE
                                    case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                             -- then extract(epoch from age(tm.asi_ingresorefrigerio ,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) )) /*/3600 */
                                          then extract(epoch from age(tm.asi_ingresorefrigerio , tm.asi_fecha+ (dhr.dhr_salidarefrigerio  + (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                                     else 0 end
                               END
                ELSE 0
                END
              ELSE 0  END as TardeRefrigerio,

                CASE WHEN tm.mar_martipo = 'U' THEN
                          case when   tm.asi_horas_trabajadas > tm.asi_horas_atrabajar 
                                  THEN   (tm.asi_horas_trabajadas - tm.asi_horas_atrabajar )
                               WHEN tm.asi_horas_trabajadas = tm.asi_horas_atrabajar 
                                  THEN tm.asi_horas_trabajadas
                               ELSE   0 
                          END 
                      WHEN  tm.mar_martipo IN ('A','X') THEN
                     -- TM.asi_horas_trabajadas + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
            case when tm.hor_codigo = 116 then 
              (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -    coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )  ) + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
            else
              (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -  case when dhr.dhr_increfrigerio then 0 else   coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )   end ) -- + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
                        end
                ELSE  
                   -- case when  (tm.asi_horas_trabajadas is null or tm.asi_horas_trabajadas = 0) and tm.asi_salida is not null then 
                         (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -  case when dhr.dhr_increfrigerio then 0 else  coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )   end ) /*/3600*/
                   --  else  tm.asi_horas_trabajadas end 
                        
                END as horasdia,
                (extract(epoch from age( 
                case when dhr.dhr_nocturno 
                  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
                  else cast(now() as date)+ dhr.dhr_salida end
                  ,cast(now() as date) + dhr.dhr_ingreso  
                 ) ) - (case when dhr.dhr_increfrigerio then 0 else  (dhr.dhr_tiemporefrigerio *60)  end) )/*/3600*/  as nhoras,
                dia_semana(tm.asi_fecha::date ),tm.hor_codigo,dhr.dhr_nocturno
               from  asistencias.tblasistencias_asi as tm  
              inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = tm.hor_codigo and hor.hor_codigo <> 9999
              inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = tm.hor_codigo  and dhr.dhr_day =  to_char(tm.asi_fecha , 'Day')
               where tm.asi_tipomarca not in ('ERROR','S/T') and 
                tm.tra_codigo =  tratemp --and tm.asi_codigo::character varying like case when asicodigo = 0 then '%' else asicodigo::character varying end  --case when codtrabajador = '0' then true else tm.tra_codigo = codtra end  
             -- and extract(year from tm.asi_fecha) = case when extract(year from fechaini::date) > 2002 then  extract(year from fechaini::date) else extract(year from tm.asi_fecha) end  --and tm.asi_codigo in ( select * from asistencias.tblasistencias_asi where (asi_horas_trabajadas is null or asi_horas_trabajadas  = 0) and asi_salida is not null and asi_ingreso is not null)
              and tm.asi_fecha = fechatemp and tm.mar_martipo is not null
               order by tm.tra_codigo ASC,tm.asi_ingreso ASC,tm.asi_salidarefrigerio asc, tm.asi_ingresorefrigerio asc , tm.asi_salida asc
        );

ELSIF tipotemp IN ('V','B','J','F','O','N','H','K')    THEN 

          Select tm.asi_codigo ,tm.tra_codigo ,tm.asi_fecha, tm.asi_ingreso,tm.asi_salidarefrigerio,tm.asi_ingresorefrigerio,tm.asi_salida,tm.mar_martipo,
             
              CASE WHEN tm.hor_codigo <> 131 THEN
                CASE WHEN COALESCE(tm.mar_martipo,'IN') in ('IN') THEN
                         case  when (tm.asi_ingreso> tm.asi_fecha+ dhr.dhr_ingreso+ interval '1min' * dhr.dhr_tolingreso )
                            then extract(epoch from age(tm.asi_ingreso, tm.asi_fecha+ dhr.dhr_ingreso )) /*/3600*/
                         else 0 end
                    WHEN COALESCE(tm.mar_martipo,'IN') in ('X') and  hor.hor_codigo <> 116 THEN
                 case  when (tm.asi_ingreso> tm.asi_fecha+ dhr.dhr_ingreso+ interval '1min' * dhr.dhr_tolingreso )
                            then extract(epoch from age(tm.asi_ingreso, tm.asi_fecha+ dhr.dhr_ingreso )) /*/3600*/
                         else 0 end

                ELSE 0
                END
              ELSE 0 END as IngresoTarde,


              CASE WHEN tm.hor_codigo <> 131 THEN
                CASE WHEN COALESCE(tm.mar_martipo,'IN') in ('IN') THEN
                          CASE WHEN dhr.dhr_nocturno 
                               THEN
                                    case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                          then extract(epoch from age(tm.asi_ingresorefrigerio, (tm.asi_fecha + INTERVAL'1 DAY')+ (dhr.dhr_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                                    else 0 end

                               ELSE
                                    case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                          --then extract(epoch from age(tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute'))  )) /*/3600 */
                                          then extract(epoch from age(tm.asi_ingresorefrigerio, tm.asi_fecha+ (dhr.dhr_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                                    else 0 end
                               END
                     WHEN COALESCE(tm.mar_martipo,'IN') in ('X')  and  hor.hor_codigo <> 116 THEN
                           CASE WHEN dhr.dhr_nocturno 
                               THEN
                                     case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                             -- then extract(epoch from age(tm.asi_ingresorefrigerio ,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) )) /*/3600 */
                                          then extract(epoch from age(tm.asi_ingresorefrigerio , (tm.asi_fecha + INTERVAL'1 DAY')+ (dhr.dhr_salidarefrigerio  + (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                                     else 0 end
                               ELSE
                                    case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                                             -- then extract(epoch from age(tm.asi_ingresorefrigerio ,tm.asi_salidarefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute')) )) /*/3600 */
                                          then extract(epoch from age(tm.asi_ingresorefrigerio , tm.asi_fecha+ (dhr.dhr_salidarefrigerio  + (dhr.dhr_tiemporefrigerio * (interval '1 minute')) ) )) /*/3600 */
                                     else 0 end
                               END
                ELSE 0
                END
              ELSE 0  END as TardeRefrigerio,

                CASE WHEN tm.mar_martipo = 'U' THEN
                          case when   tm.asi_horas_trabajadas > tm.asi_horas_atrabajar 
                                  THEN   (tm.asi_horas_trabajadas - tm.asi_horas_atrabajar )
                               WHEN tm.asi_horas_trabajadas = tm.asi_horas_atrabajar 
                                  THEN tm.asi_horas_trabajadas
                               ELSE   0 
                          END 
                      WHEN  tm.mar_martipo IN ('A','X') THEN
                     -- TM.asi_horas_trabajadas + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
            case when tm.hor_codigo = 116 then 
              (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -    coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )  ) + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
            else
              (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -  case when dhr.dhr_increfrigerio then 0 else   coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )   end ) -- + coalesce(extract(epoch from age(TM.asi_ingresorefrigerio,TM.asi_salidarefrigerio)),0)
                        end
                ELSE  
                   -- case when  (tm.asi_horas_trabajadas is null or tm.asi_horas_trabajadas = 0) and tm.asi_salida is not null then 
                         (extract(epoch from age( tm.asi_salida,tm.asi_ingreso))  -  case when dhr.dhr_increfrigerio then 0 else  coalesce( extract(epoch from age( tm.asi_ingresorefrigerio,tm.asi_salidarefrigerio) ),0 )   end ) /*/3600*/
                   --  else  tm.asi_horas_trabajadas end 
                        
                END as horasdia,
                (extract(epoch from age( 
                case when dhr.dhr_nocturno 
                  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
                  else cast(now() as date)+ dhr.dhr_salida end
                  ,cast(now() as date) + dhr.dhr_ingreso  
                 ) ) - (case when dhr.dhr_increfrigerio then 0 else  (dhr.dhr_tiemporefrigerio *60)  end) )/*/3600*/  as nhoras,
                dia_semana(tm.asi_fecha::date ),tm.hor_codigo,dhr.dhr_nocturno
               from  asistencias.tblasistencias_asi as tm  
              inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = tm.hor_codigo and hor.hor_codigo <> 9999
              inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = tm.hor_codigo  and dhr.dhr_day =  to_char(tm.asi_fecha , 'Day')
               where tm.asi_tipomarca not in ('ERROR','S/T') and 
                tm.tra_codigo =  tratemp --and tm.asi_codigo::character varying like case when asicodigo = 0 then '%' else asicodigo::character varying end  --case when codtrabajador = '0' then true else tm.tra_codigo = codtra end  
             -- and extract(year from tm.asi_fecha) = case when extract(year from fechaini::date) > 2002 then  extract(year from fechaini::date) else extract(year from tm.asi_fecha) end  --and tm.asi_codigo in ( select * from asistencias.tblasistencias_asi where (asi_horas_trabajadas is null or asi_horas_trabajadas  = 0) and asi_salida is not null and asi_ingreso is not null)
              and tm.asi_fecha = fechatemp and tm.mar_martipo is  null
               order by tm.tra_codigo ASC,tm.asi_ingreso ASC,tm.asi_salidarefrigerio asc, tm.asi_ingresorefrigerio asc , tm.asi_salida asc
        );

END IF;



FOR rtmarcacion IN    
                 select t.*,dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_salidarefrigerio,dhr.dhr_ingresorefrigerio , dhr.hor_codigo,dhr.dhr_day, dhr.dhr_tiemporefrigerio, tra.are_codigo
                 from tasistencias as t
                left join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = t.hor_codigo and dhr.dhr_day =  to_char(t.asi_fecha , 'Day')
                left join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = t.tra_codigo
                  where t.asi_fecha in (select x.asi_fecha from tasistencias as x where x.mar_martipo IN('V','B','J','F','O','N','H','K')) and (t.mar_martipo is null or t.mar_martipo in ('V','B','J','F','O','N','H','K')) 
                 ORDER BY t.asi_fecha ASC,t.mar_martipo asc--,t.asi_ingreso asc, t.asi_ingresorefrigerio asc
LOOP
    

    IF vartipo is null  then 
      vartipo = rtmarcacion.mar_martipo ;
      varsalida = rtmarcacion.asi_salida;
      varingreso = rtmarcacion.asi_ingreso;
      varfecha = rtmarcacion.asi_fecha;
      varingresorefrigerio  = rtmarcacion.asi_ingresorefrigerio;
      varsalidarefrigerio = rtmarcacion.asi_salidarefrigerio;
  --  raise notice 'fecha: %', varfecha;
    end if;
    
    IF vartipo in ('V','J','N') and rtmarcacion.mar_martipo is null and rtmarcacion.are_codigo <> 171  THEN 
   -- raise notice 'asiingre: %', rtmarcacion.asi_ingreso;
  --  raise notice 'dhringrere: %', rtmarcacion.dhr_ingresorefrigerio;
      IF rtmarcacion.asi_ingreso::time(0) >= (rtmarcacion.dhr_ingresorefrigerio)::time(0)  then 

      UPDATE tasistencias  set  ingresotarde = 0,tarderefrigerio = case when rtmarcacion.dhr_ingresorefrigerio::time(0) <> '00:00:00'::time(0) then   extract(epoch from age(rtmarcacion.asi_ingreso::timestamp(0),  (rtmarcacion.asi_fecha+ rtmarcacion.dhr_ingresorefrigerio)::timestamp(0) )) else 0 end
      where tasistencias.asi_fecha = varfecha and tasistencias.tra_codigo = rtmarcacion.tra_codigo and tasistencias.hor_codigo = rtmarcacion.hor_codigo and tasistencias.mar_martipo is null and tasistencias.asi_ingreso = rtmarcacion.asi_ingreso;
   --   raise notice 'entro: ';
      ELSIF rtmarcacion.asi_ingreso::time(0) <= (rtmarcacion.dhr_ingresorefrigerio)::time(0) then 
        UPDATE tasistencias  set  ingresotarde = 0,tarderefrigerio =0
      where tasistencias.asi_fecha = varfecha and tasistencias.tra_codigo = rtmarcacion.tra_codigo and tasistencias.hor_codigo = rtmarcacion.hor_codigo and tasistencias.mar_martipo is null and tasistencias.asi_ingreso = rtmarcacion.asi_ingreso;
      end IF;
   --   raise notice 'value: %', vartipo;
      vartipo  = NULL;

    ELSIF vartipo in ('B','F','O') and rtmarcacion.mar_martipo is null and rtmarcacion.are_codigo <> 171  then 
      

      UPDATE tasistencias  set tarderefrigerio =0 , ingresotarde =  extract(epoch from age(rtmarcacion.asi_ingreso::timestamp(0), (rtmarcacion.asi_fecha+ rtmarcacion.dhr_ingreso)::timestamp(0) )) 
      where tasistencias.asi_fecha = varfecha and tasistencias.tra_codigo = rtmarcacion.tra_codigo and tasistencias.hor_codigo = rtmarcacion.hor_codigo and tasistencias.mar_martipo is null and tasistencias.asi_ingreso = rtmarcacion.asi_ingreso;
   --   raise notice 'Value: %', vartipo;
      vartipo  = NULL;

    ELSIF vartipo in ('H') and rtmarcacion.mar_martipo is null  AND rtmarcacion.are_codigo <> 171 then
      IF rtmarcacion.asi_ingresorefrigerio IS NULL or  rtmarcacion.asi_salidarefrigerio IS NULL  THEN      
          UPDATE tasistencias  set tarderefrigerio = 0  , ingresotarde =  0 --extract(epoch from age(rtmarcacion.asi_ingreso::timestamp(0), (rtmarcacion.asi_fecha+ rtmarcacion.dhr_ingreso)::timestamp(0) )) 
          where tasistencias.asi_fecha = varfecha and tasistencias.tra_codigo = rtmarcacion.tra_codigo and tasistencias.hor_codigo = rtmarcacion.hor_codigo and tasistencias.mar_martipo is null and tasistencias.asi_ingreso = rtmarcacion.asi_ingreso;
     -- raise notice 'Value1: %', vartipo;
     -- raise notice 'varingresorefrigerio: %', varingresorefrigerio;
     -- raise notice 'varsalidarefrigerio: %', varsalidarefrigerio;
    ELSE
     -- raise notice 'Value2: %', vartipo;
     --  raise notice 'varingresorefrigerio: %',  rtmarcacion.asi_ingresorefrigerio;
     -- raise notice 'varsalidarefrigerio: %', rtmarcacion.asi_salidarefrigerio;
          UPDATE tasistencias  set  ingresotarde = 0 ,tarderefrigerio =  extract(epoch from age(rtmarcacion.asi_salidarefrigerio, rtmarcacion.asi_fecha+ (rtmarcacion.dhr_salidarefrigerio +  (rtmarcacion.dhr_tiemporefrigerio * (interval '1 minute')) ) ))
          where tasistencias.asi_fecha = varfecha and tasistencias.tra_codigo = rtmarcacion.tra_codigo and tasistencias.hor_codigo = rtmarcacion.hor_codigo and tasistencias.mar_martipo is null and tasistencias.asi_ingreso = rtmarcacion.asi_ingreso;

      END IF;
     vartipo  = NULL;

     ELSIF vartipo in ('K') and rtmarcacion.mar_martipo is null  AND rtmarcacion.are_codigo <> 171 then
      IF rtmarcacion.asi_ingresorefrigerio IS NULL or  rtmarcacion.asi_salidarefrigerio IS NULL  THEN      
          UPDATE tasistencias  set tarderefrigerio = 0  ,ingresotarde = extract(epoch from age(rtmarcacion.asi_ingreso::timestamp(0), (rtmarcacion.asi_fecha+ rtmarcacion.dhr_ingreso)::timestamp(0) )) 
          where tasistencias.asi_fecha = varfecha and tasistencias.tra_codigo = rtmarcacion.tra_codigo and tasistencias.hor_codigo = rtmarcacion.hor_codigo and tasistencias.mar_martipo is null and tasistencias.asi_ingreso = rtmarcacion.asi_ingreso;
   --   raise notice 'Value: %', vartipo;
      ELSE 
         UPDATE tasistencias  set  ingresotarde = extract(epoch from age(rtmarcacion.asi_ingreso::timestamp(0), (rtmarcacion.asi_fecha+ rtmarcacion.dhr_ingreso)::timestamp(0) ))  ,tarderefrigerio =  extract(epoch from age(rtmarcacion.asi_salidarefrigerio, rtmarcacion.asi_fecha + (rtmarcacion.dhr_salidarefrigerio +  (rtmarcacion.dhr_tiemporefrigerio * (interval '1 minute')) ) ))
         where tasistencias.asi_fecha = varfecha and tasistencias.tra_codigo = rtmarcacion.tra_codigo and tasistencias.hor_codigo = rtmarcacion.hor_codigo and tasistencias.mar_martipo is null and tasistencias.asi_ingreso = rtmarcacion.asi_ingreso;
      END IF;
     vartipo  = NULL;

    ELSIF vartipo in ('V','J','N','B','F','O','H','K') and rtmarcacion.mar_martipo is null  AND rtmarcacion.are_codigo = 171 then
      UPDATE tasistencias  set  ingresotarde = 0,tarderefrigerio =0
      where  tasistencias.asi_fecha = varfecha and tasistencias.tra_codigo = rtmarcacion.tra_codigo and tasistencias.hor_codigo = rtmarcacion.hor_codigo and tasistencias.mar_martipo is null and tasistencias.asi_ingreso = rtmarcacion.asi_ingreso;  
     vartipo  = NULL;
    END IF;

      
END LOOP;

IF counts = 1 and tipotemp is null THEN
  DELETE FROM tasistencias  WHERE tasistencias.asi_codigo <> asicodigo;
END IF; 


            
 RETURN QUERY EXECUTE 'SELECT * FROM tasistencias order by tra_codigo asc, asi_fecha asc , asi_ingreso asc , asi_ingresorefrigerio asc, asi_salidarefrigerio asc , asi_salida asc';
 drop table tasistencias;
END;
$$;


ALTER FUNCTION asistencias.fun_recalculogeneral(fechaini date, codhorario integer, codtrabajador character varying, asicodigo integer) OWNER TO postgres;

--
-- Name: fun_tardanzasll(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.fun_tardanzasll(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(emp_razon character varying, emp_ruc character varying, tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, pue_nombre character varying, fecha date, tipodescripcion character varying, tardansa character varying, tardansarefrigerio character varying, are_nombre character varying, dhr_dia character varying, hora1 character varying, hora2 character varying, hora3 character varying, hora4 character varying, are_codigo integer, tiptardansa character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY select 
f.emp_razon ,f.emp_ruc,
f.tra_codigo ,f.tra_nombre ,f.tra_apellidopaterno,f.tra_apellidomaterno, f.tra_dni,f.tra_identificador,
f.pue_nombre,f.fecha ,
--dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
CASE WHEN (f.tipodescripcion is  null) and (f.dhr_ingreso is not null or f.dhr_salida is not null or f.dhr_salidarefrigerio is not null or f.dhr_ingresorefrigerio is not null) 
       THEN 'Marco'
     WHEN (f.tipodescripcion is null) THEN 'No Marco'
       ELSE f.tipodescripcion
END as tipodescripcion
/*,tra_estado,
are_codigo,are_nombre,pue_codigo  ,hor_codigo ,hor_nombre,

dhr_ingreso,dhr_salida ,dhr_salidarefrigerio ,dhr_ingresorefrigerio ,
dhr_dia ,dhr_tolingreso ,dhr_tolingresorefrigerio ,dhr_tiemporefrigerio ,dhr_day,dhr_nocturno ,
ingreso,salida,ingresorefrigerio ,salidarefrigerio ,horas_atrabajar 
,horas_trabajadas ,horas_tardeingreso,horas_tardesalida */

, case when f.hor_codigo<>9999 then (cast(CASE WHEN (to_char(ingreso, 'hh:MI')) > to_char((dhr_ingreso + dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN ingreso - (cast(ingreso as date)+ dhr_ingreso) END as varchar) ) end  as tardansa
, case when f.hor_codigo<>9999 then ( cast(CASE WHEN (to_char(salidarefrigerio + dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((ingresorefrigerio + dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI') 
 THEN salidarefrigerio - (ingresorefrigerio  + dhr_tiemporefrigerio * (interval '1 minute')) END as varchar) ) end as tardansarefrigerio,

/*
 ,cast( CASE WHEN (to_char(f.ingreso, 'hh:MI')) > to_char((f.dhr_ingreso + f.dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
 THEN 'IT' else '' END as varchar)as tardansa 
, cast( CASE WHEN (to_char(f.salidarefrigerio + f.dhr_tolingresorefrigerio * (interval '1 minute')  , 'hh:MI')) > to_char((f.ingresorefrigerio + f.dhr_tiemporefrigerio * (interval '1 minute')), 'hh:MI') 
 THEN 'TR' else '' END as varchar)as tardansarefrigerio,*/
 f.are_nombre,
 f.dhr_dia,
cast( to_char(f.ingreso, 'HH24:MI:SS') as varchar)as hora1,  
cast( to_char(f.salidarefrigerio, 'HH24:MI:SS') as varchar) as hora2,
cast( to_char(f.ingresorefrigerio, 'HH24:MI:SS') as varchar) as hora3,
cast( to_char(f.salida, 'HH24:MI:SS') as varchar)  as hora4  ,
  f.are_codigo,
  cast('' as varchar) as tiptardansa
 from asistencias.fun_global 
 ( fechaini ,  fechafin ,  codarea ,  codhorario ,  codtrabajador )as f
 order by f.are_codigo , f.tra_codigo , f.fecha ;
--('2016-01-01','2019-01-01', 0,0,'') as f



    
END;
$$;


ALTER FUNCTION asistencias.fun_tardanzasll(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

