,horas_trabajadas ,horas_tardeingreso,horas_tardesalida */

, case when f.hor_codigo<>9999 then (cast(CASE WHEN (to_char(ingreso, 'hh:MI')) > to_char((dhr_ingreso + dhr_tolingreso * (interval '1 minute')), 'hh:MI') 
