ALTER FUNCTION asistencias.fun_tardanzasll2(fechaini date, fechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: horariosdiasmasivo(character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.horariosdiasmasivo(fechaini character varying, fechafin character varying, traid integer, horid integer, limits integer, offsets integer) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$DECLARE

 
 DECLARE trab RECORD;
 resultado character varying;
BEGIN

resultado ='Error';


 FOR trab IN Select tra.tra_codigo  from asistencias.tbltrabajadores_tra as tra where (case when traid = 0 then true else tra.tra_codigo=traid end ) limit  limits offset offsets
 LOOP
 
      asistencias.tblfechahorario_fht
    ( tra_codigo,
      hor_codigo,
      fht_fecha,
      fht_usrcreacion,
      fht_feccreacion
    )
    
    select 
    trab.tra_codigo
    horid,
    i::date,
    1,
    now()
    from generate_series(fechaini, 
      fechafin, '1 day'::interval) i;
	
 END LOOP;
 
 resultado ='OK';
 RETURN QUERY  select resultado;
END;$$;


ALTER FUNCTION asistencias.horariosdiasmasivo(fechaini character varying, fechafin character varying, traid integer, horid integer, limits integer, offsets integer) OWNER TO postgres;

