CREATE FUNCTION asistencias.horariotrabajadordelete(v_tra_codigo integer, v_fht_fecha date) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE
v_respuesta int =0;
v_codigo bigint=0;

BEGIN 
select fht_codigo  
INTO v_codigo  
from asistencias.tblfechahorario_fht  
where tra_codigo=v_tra_codigo and fht_fecha = v_fht_fecha;


-- IF v_ent_id IS NULL THEN 
IF v_codigo IS NOT NULL THEN
DELETE FROM asistencias.tblfechahorario_fht
    where v_codigo = fht_codigo;

END IF;

RETURN v_respuesta;

END;
$$;


ALTER FUNCTION asistencias.horariotrabajadordelete(v_tra_codigo integer, v_fht_fecha date) OWNER TO postgres;

