   SET  tra_codigo=v_tra_codigo, hor_codigo=v_hor_codigo, fht_fecha=v_fht_fecha, 
   fht_usrmodificacion=v_usuario, fht_fecmodificacion=now()
 WHERE fht_codigo=v_codigo;

--actualiza las marcaciones en registro reloj, con el nuevo horario
/*FOR mar_update IN select mar_codigo, tra_codigo, cast(mar_fechahora as date) as fecha, to_char(cast(mar_fechahora as time),'HH24:MI:SS') as hora from asistencias.tblmarcaciones_mar as mar 
where mar.tra_codigo = v_tra_codigo and cast(mar.mar_fechahora as date) = v_fht_fecha 
LOOP

select * into v_tipo from asistencias.psgtipo(mar_update.hora::varchar,v_tra_codigo,mar_update.fecha);
update asistencias.tblmarcaciones_mar as mar SET mar_tipo = v_tipo where mar.mar_codigo = mar_update.mar_codigo;
 
END LOOP;*/

END IF;

RETURN v_respuesta;

END;
$$;


ALTER FUNCTION asistencias.horariotrabajadorfecha(v_tra_codigo integer, v_hor_codigo integer, v_fht_fecha date, v_usuario integer) OWNER TO postgres;

--
-- Name: marcacionfuncion(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.marcacionfuncion(parfechaini date, parfechafin date) RETURNS TABLE(area character varying, fecha date, reloj character varying, idtrabajador integer, cargo character varying, nrodocumento character varying, nombre character varying, marcaciones character varying, nromarcaciones integer, impresion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE

 DECLARE fechaini DATE;
 c integer;
 i integer = 0;
 ahora varchar(20);
 DECLARE fechafin DATE;
 tarea varchar(50);
 tfecha varchar(10);
 tidtrabajador integer;
 thora varchar(100);
 treloj varchar(100);
 ttipo varchar(100); 
 ttipohora varchar(100);
 DECLARE done BOOLEAN  DEFAULT FALSE; 
 DECLARE curmarcaciones CURSOR FOR SELECT m.tra_codigo, 
 to_char(m.mar_fechahora, 'yyyy-MM-dd') as fecha, 
 array_to_string(array_agg( to_char(m.mar_fechahora, 'HH24:MI')  ) , ' ')  as hora   ,
-- to_char(m.mar_fechahora, 'HH24:MI') as hora, 
-- r.rel_descripcion as reloj, 
 array_to_string(array_agg( r.rel_descripcion  ) , ' ')  as reloj,
-- m.mar_tipo as tipo,
      array_to_string(array_agg(m.mar_tipo) , ' ') as tipo, 
 array_to_string(array_agg(m.mar_tipo ||'='||  to_char(m.mar_fechahora, 'HH24:MI')  ) , ' ') as tipohora
     from asistencias.tblmarcaciones_mar as m 
     inner join asistencias.tblrelojes_rel as r on m.rel_codigo = r.rel_codigo
     where CAST(to_char(mar_fechahora, 'yyyy-MM-dd') as DATE) between parfechaini and parfechafin

       group by to_char(m.mar_fechahora, 'yyyy-MM-dd'), tra_codigo, fecha ,r.rel_descripcion     

	order by m.tra_codigo, fecha;       
--     order by tra_codigo, mar_fechahora;
 /*DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;*/
BEGIN



 CREATE TEMPORARY TABLE tmarcaciones (

 area VARCHAR(50) DEFAULT '',
 fecha DATE DEFAULT NULL,
 reloj VARCHAR(50) DEFAULT '',
 idtrabajador INTEGER,
 cargo VARCHAR(50) DEFAULT '',
 nrodocumento varchar(8),
 nombre VARCHAR(100) DEFAULT '',
 marcaciones VARCHAR DEFAULT '',
 nromarcaciones INTEGER DEFAULT 0,
 impresion varchar
 );

  fechaini:=parfechaini;
  fechafin:=parfechafin;
  ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS'); 
 
 while fechaini <= fechafin LOOP
       select are.are_nombre, fechaini, tra.tra_codigo, car.pue_nombre, tra.tra_dni, (tra.tra_apellidopaterno || ' ' || tra.tra_apellidomaterno || ' ' || tra.tra_nombre), ahora  
         from asistencias.tbltrabajadores_tra tra 
         left join asistencias.tblpuestos_pue car ON car.pue_codigo =tra.pue_codigo
         left join asistencias.tblareas_are are on are.are_codigo=tra.are_codigo;        
    
       
     fechaini = CAST(fechaini as DATE) + CAST('1 days' AS INTERVAL); 
 END LOOP; 
 
 
 EXECUTE 'Select count(*) from tmarcaciones' into c;
 
 OPEN curmarcaciones;
 LOOP
   FETCH curmarcaciones INTO tidtrabajador, tfecha, thora, treloj, ttipo, ttipohora;
   IF i= c THEN
      EXIT;
   END IF;
   i=i+1;   
   update tmarcaciones set marcaciones = ttipohora , nromarcaciones=tmarcaciones.nromarcaciones+1, reloj = treloj
     where tmarcaciones.idtrabajador = tidtrabajador
     and to_char(tmarcaciones.fecha, 'yyyy-MM-dd') = tfecha;
   
 END LOOP;
 CLOSE curmarcaciones;
 

 RETURN QUERY EXECUTE  'select * from tmarcaciones order by area';

 DROP TABLE tmarcaciones;

END;
$$;


ALTER FUNCTION asistencias.marcacionfuncion(parfechaini date, parfechafin date) OWNER TO postgres;

--
-- Name: marcacionfuncion_area(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.marcacionfuncion_area(parfechaini date, parfechafin date, cod_area integer) RETURNS TABLE(area character varying, fecha date, reloj character varying, idtrabajador integer, cargo character varying, nrodocumento character varying, nombre character varying, marcaciones character varying, nromarcaciones integer, impresion character varying, areacodigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE

 DECLARE fechaini DATE;
 c integer;
 i integer = 0;
 ahora varchar(20);
 DECLARE fechafin DATE;
 tarea varchar(50);
 tfecha varchar(10);
 tidtrabajador integer;
 thora varchar(100);
 treloj varchar(100);
 ttipo varchar(100); 
 ttipohora varchar(100);
 DECLARE done BOOLEAN  DEFAULT FALSE; 
 DECLARE curmarcaciones CURSOR FOR SELECT m.tra_codigo, 
 to_char(m.mar_fechahora, 'yyyy-MM-dd') as fecha, 
 array_to_string(array_agg( to_char(m.mar_fechahora, 'HH24:MI')  ) , ' ')  as hora   ,
 array_to_string(array_agg( r.rel_descripcion  ) , ' ')  as reloj,
      array_to_string(array_agg(m.mar_tipo) , ' ') as tipo, 
 array_to_string(array_agg(m.mar_tipo ||'='||  to_char(m.mar_fechahora, 'HH24:MI')  ) , ' ') as tipohora
     from asistencias.tblmarcaciones_mar as m 
     inner join asistencias.tblrelojes_rel as r on m.rel_codigo = r.rel_codigo
     where CAST(to_char(mar_fechahora, 'yyyy-MM-dd') as DATE) between parfechaini and parfechafin
       group by to_char(m.mar_fechahora, 'yyyy-MM-dd'), tra_codigo, fecha ,r.rel_descripcion     
	order by m.tra_codigo, fecha;       
 /*DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;*/
BEGIN



 CREATE TEMPORARY TABLE tmarcaciones (

 area VARCHAR(50) DEFAULT '',
 fecha DATE DEFAULT NULL,
 reloj VARCHAR(100) DEFAULT '',
 idtrabajador INTEGER,
 cargo VARCHAR(50) DEFAULT '',
 nrodocumento varchar(8),
 nombre VARCHAR(100) DEFAULT '',
 marcaciones VARCHAR DEFAULT '',
 nromarcaciones INTEGER DEFAULT 0,
 impresion varchar,
 areacodigo INTEGER
 );

  fechaini:=parfechaini;
  fechafin:=parfechafin;
  ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS'); 
 
 while fechaini <= fechafin LOOP
       select are.are_nombre, fechaini, tra.tra_codigo, car.pue_nombre, tra.tra_dni, (tra.tra_apellidopaterno || ' ' || tra.tra_apellidomaterno || ' ' || tra.tra_nombre), ahora,  are.are_codigo  
         from asistencias.tbltrabajadores_tra tra 
         left join asistencias.tblpuestos_pue car ON car.pue_codigo =tra.pue_codigo
         left join asistencias.tblareas_are are on are.are_codigo=tra.are_codigo
         WHERE are.are_codigo = cod_area;        
    
       
     fechaini = CAST(fechaini as DATE) + CAST('1 days' AS INTERVAL); 
 END LOOP; 
 
 
 EXECUTE 'Select count(*) from tmarcaciones' into c;
 
 OPEN curmarcaciones;
