 DECLARE done BOOLEAN  DEFAULT FALSE; 
 DECLARE curmarcaciones CURSOR FOR SELECT m.tra_codigo, 
 to_char(m.mar_fechahora, 'yyyy-MM-dd') as fecha, 
 array_to_string(array_agg( to_char(m.mar_fechahora, 'HH24:MI')  ) , ' ')  as hora   ,
 array_to_string(array_agg( r.rel_descripcion  ) , ' ')  as reloj,
      array_to_string(array_agg(m.mar_tipo) , ' ') as tipo, 
 array_to_string(array_agg(m.mar_tipo ||'='||  to_char(m.mar_fechahora, 'HH24:MI')  ) , ' ') as tipohora
     from asistencias.tblmarcaciones_mar as m 
     inner join asistencias.tblrelojes_rel as r on m.rel_codigo = r.rel_codigo
     where CAST(to_char(mar_fechahora, 'yyyy-MM-dd') as DATE) between parfechaini and parfechafin
