 idtrabajador INTEGER,
 cargo VARCHAR(50) DEFAULT '',
 nrodocumento varchar(8),
 nombre VARCHAR(100) DEFAULT '',
 marcaciones VARCHAR DEFAULT '',
 nromarcaciones INTEGER DEFAULT 0,
 impresion varchar
 
 );

  fechaini:=parfechaini;
  fechafin:=parfechafin;
  ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS'); 
 
 while fechaini <= fechafin LOOP
       select are.are_nombre, fechaini, tra.tra_codigo, car.pue_nombre, tra.tra_dni, (tra.tra_apellidopaterno || ' ' || tra.tra_apellidomaterno || ' ' || tra.tra_nombre), ahora
