         left join asistencias.tblareas_are are on are.are_codigo=tra.are_codigo;    
    
       
     fechaini = CAST(fechaini as DATE) + CAST('1 days' AS INTERVAL); 
 END LOOP; 
 
 
 EXECUTE 'Select count(*) from tmarcaciones' into c;
 
 OPEN curmarcaciones;
 LOOP
    FETCH curmarcaciones INTO tidtrabajador, tfecha, thora, treloj, ttipo, ttipohora; 
--   FETCH curmarcaciones INTO tidtrabajador, tfecha, thora, treloj, ttipo;
   IF i= c THEN
      EXIT;
   END IF;
   i=i+1;   
   update tmarcaciones set marcaciones = 
     ttipohora, 
     nromarcaciones=tmarcaciones.nromarcaciones+1, 
     reloj = treloj
     where tmarcaciones.idtrabajador = tidtrabajador
     and to_char(tmarcaciones.fecha, 'yyyy-MM-dd') = tfecha;
   
 END LOOP;
 CLOSE curmarcaciones;
 

 RETURN QUERY EXECUTE  'select * from tmarcaciones WHERE idtrabajador = ' || cod_trabajador || ' order by area';

