         left join asistencias.tblareas_are are on are.are_codigo=tra.are_codigo;        
    
       
     fechaini = CAST(fechaini as DATE) + CAST('1 days' AS INTERVAL); 
 END LOOP; 
 */
 
 EXECUTE 'Select count(*) from tmarcaciones' into c;
 
 OPEN curmarcaciones;
 LOOP
   FETCH curmarcaciones INTO tidtrabajador, tfecha, thora, treloj, ttipo, ttipohora;
   IF i= c THEN
      EXIT;
   END IF;
   i=i+1;   
   update tmarcaciones set marcaciones = ttipohora , nromarcaciones=tmarcaciones.nromarcaciones+1, reloj = treloj
     where tmarcaciones.idtrabajador = tidtrabajador
     and to_char(tmarcaciones.fecha, 'yyyy-MM-dd') = tfecha;
   
 END LOOP;
 CLOSE curmarcaciones;
 

 RETURN QUERY EXECUTE  'select * from tmarcaciones order by area';

 DROP TABLE tmarcaciones;

END;
$$;


ALTER FUNCTION asistencias.marcacionfuncionall(parfechaini date, parfechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: marcacionfuncionall2(date, date, integer, integer, character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.marcacionfuncionall2(parfechaini date, parfechafin date, codarea integer, codhorario integer, codtrabajador character varying) RETURNS TABLE(area character varying, fecha date, reloj character varying, idtrabajador integer, cargo character varying, nrodocumento character varying, nombre character varying, marcaciones character varying, nromarcaciones integer, impresion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE

 DECLARE fechaini DATE;
 c integer;
 i integer = 0;
 ahora varchar(20);
 DECLARE fechafin DATE;
 tarea varchar(50);
 tfecha varchar(10);
 tidtrabajador integer;
 thora varchar(100);
 treloj varchar(100);
 ttipo varchar(100); 
 ttipohora varchar(100); 
 DECLARE done BOOLEAN  DEFAULT FALSE; 
 DECLARE curmarcaciones CURSOR FOR SELECT m.tra_codigo, 
 to_char(m.mar_fechahora, 'yyyy-MM-dd') as fecha, 
 array_to_string(array_agg( to_char(m.mar_fechahora, 'HH24:MI')  ) , ' ')  as hora   ,
 array_to_string(array_agg( r.rel_descripcion  ) , ' ')  as reloj,
      array_to_string(array_agg(m.mar_tipo) , ' ') as tipo, 
 array_to_string(array_agg(m.mar_tipo ||'='||  to_char(m.mar_fechahora, 'HH24:MI')  ) , ' ') as tipohora
     from asistencias.tblmarcaciones_mar as m 
     inner join asistencias.tblrelojes_rel as r on m.rel_codigo = r.rel_codigo
     where CAST(to_char(mar_fechahora, 'yyyy-MM-dd') as DATE) between parfechaini and parfechafin
       group by to_char(m.mar_fechahora, 'yyyy-MM-dd'), tra_codigo, fecha ,r.rel_descripcion     
  order by m.tra_codigo, fecha;       

     
 /*DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;*/
BEGIN



 CREATE TEMPORARY TABLE tmarcaciones (

 area VARCHAR(100) DEFAULT '',
 fecha DATE DEFAULT NULL,
 reloj VARCHAR DEFAULT '',
 idtrabajador INTEGER,
 cargo VARCHAR(50) DEFAULT '',
 nrodocumento varchar(8),
 nombre VARCHAR(100) DEFAULT '',
 marcaciones VARCHAR DEFAULT '',
 nromarcaciones INTEGER DEFAULT 0,
 impresion varchar
 
 );

  fechaini:=parfechaini;
  fechafin:=parfechafin;
  ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS'); 
 
 while fechaini <= fechafin LOOP
       select are.are_nombre, fechaini, tra.tra_codigo, car.pue_nombre, tra.tra_dni, (tra.tra_apellidopaterno || ' ' || tra.tra_apellidomaterno || ' ' || tra.tra_nombre), ahora
         from asistencias.tbltrabajadores_tra tra 
         left join asistencias.tblpuestos_pue car ON car.pue_codigo =tra.pue_codigo
         left join asistencias.tblareas_are are on are.are_codigo=tra.are_codigo
         left join asistencias.tbltrabajadoreshorarios_tho as tho on tra.tra_codigo = tho.tra_codigo
         left join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = tho.hor_codigo
         where 
             --fht.fht_fecha  BETWEEN fechaini and fechafin and
              cast (are.are_codigo as varchar) like (case when codarea = 0 then  '%' else cast ( codarea as varchar) end) and
               case when codhorario <> 0 then ( cast (hor.hor_codigo as varchar) like (case when 0 = 0 then  '%' else cast ( 0 as varchar) end)) else true end and
              cast (tra.tra_codigo as varchar) like (case when codtrabajador = '' then  '%' else (select cast ( tm.tra_codigo as varchar)  from asistencias.tbltrabajadores_tra as tm where tm.tra_identificador= codtrabajador  )  end);
              
    
       
     fechaini = CAST(fechaini as DATE) + CAST('1 days' AS INTERVAL); 
 END LOOP; 
 
 
 EXECUTE 'Select count(*) from tmarcaciones' into c;
 
 OPEN curmarcaciones;
 LOOP
    FETCH curmarcaciones INTO tidtrabajador, tfecha, thora, treloj, ttipo, ttipohora; 
--   FETCH curmarcaciones INTO tidtrabajador, tfecha, thora, treloj, ttipo;
   IF i= c THEN
      EXIT;
   END IF;
   i=i+1;   
   update tmarcaciones set marcaciones = ttipohora, nromarcaciones=tmarcaciones.nromarcaciones+1, reloj = treloj
     where tmarcaciones.idtrabajador = tidtrabajador
     and to_char(tmarcaciones.fecha, 'yyyy-MM-dd') = tfecha;
   
 END LOOP;
 CLOSE curmarcaciones;
 

 RETURN QUERY EXECUTE  'select * from tmarcaciones order by area';

 DROP TABLE tmarcaciones;

END;
$$;


ALTER FUNCTION asistencias.marcacionfuncionall2(parfechaini date, parfechafin date, codarea integer, codhorario integer, codtrabajador character varying) OWNER TO postgres;

--
-- Name: migra_marcaciones(character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.migra_marcaciones(tracodigo character varying) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE t RECORD;
DECLARE resultado character varying;
DECLARE varingreso TIMESTAMP(0);
DECLARE varsalida TIMESTAMP(0);
DECLARE mmarcaciones RECORD;

DECLARE ingresotemp TIMESTAMP without time zone;
DECLARE tracodigotemp integer;
DECLARE arecodigotemp integer;
DECLARE puecodigotemp integer;
DECLARE horcodigotemp integer;
DECLARE fechatemp DATE;
DECLARE nocturnotemp Boolean;
DECLARE tipooperaciontemp CHARACTER VARYING;

DECLARE asicodigo_temp character;

DECLARE contador integer ;
DECLARE fechahoratemp timestamp without time zone;
DECLARE nommarca character varying;
DECLARE atrabajar integer;

DECLARE tipoFinmar varchar;
DECLARE fechorIni timestamp(0);
DECLARE fechorFin timestamp(0);



BEGIN


CREATE TEMPORARY TABLE tmarcaciones (
registro integer,
tra_codigo integer,
are_codigo integer,
pue_codigo integer,
hor_codigo integer,
tipomarc character varying,
fecha date,
ingreso timestamp(0) without time zone,
salida timestamp(0) without time zone,
ingresorefrigerio timestamp(0) without time zone,
salidarefrigerio timestamp(0) without time zone,
nocturno Boolean,
tipooperacion character VARYING,
horas_tardeingreso double precision,
horas_tarderefrigerio double precision,
horas_atrabajar double precision,
horas_trabajadas double precision,
martipo character varying,
horas1 integer default 0,
horas2 integer default 0,
dias CHARACTER VARYING
);

 select 
ROW_NUMBER() OVER (ORDER BY tra_codigo) AS item,
f.tra_codigo ,
f.are_codigo,
f.pue_codigo,
f.hor_codigo ,
'NORMAL' as tipomarc,
 f.fht_fecha,
f.ingreso ,
 f.salida , 
 f.ingresorefrigerio , 
 f.salidarefrigerio,
 f.dhr_nocturno,
 '' as tipooperacion,
CASE WHEN f.hor_codigo <> 131 THEN
  CASE WHEN  f.salida::time < f.dhr_ingresorefrigerio::time THEN
      case when f.ingreso::time > f.dhr_ingreso::time then
         extract(epoch from age(f.ingreso,f.fht_fecha+f.dhr_ingreso  )) 
        else 0 end
  ELSE
     CASE WHEN  f.ingreso::time > f.dhr_salidarefrigerio::time  THEN
      case when f.ingreso::time > f.dhr_ingresorefrigerio::time then 0 else 0 end
     ELSE
       case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso )
        then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600*/
        else 0 end 
     END   
     
  END 
ELSE 0 END as IngresoTarde
,
CASE WHEN f.hor_codigo <> 131 THEN
  CASE WHEN  f.ingreso::time > f.dhr_salidarefrigerio::time  THEN
      case when f.ingreso::time > f.dhr_ingresorefrigerio::time then
         extract(epoch from age(f.ingreso,f.fht_fecha+f.dhr_ingresorefrigerio )) 
        else 0 end
  ELSE
       CASE WHEN  f.salida::time < f.dhr_ingresorefrigerio::time THEN
          case when f.ingreso::time > f.dhr_ingreso::time then 0 else 0 end
       ELSE     
          case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
          then
           extract(epoch from age( 
            f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio )) /*/3600 */
          else 0 end 
       END
  END   
ELSE 0 END as TardeRefrigerio,
f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  -  case when f.dhr_increfrigerio then 0 else coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 )  end )/*/3600*/ as horasdia,
null,0,0,(select dia_semana(f.ingreso::date )) as dia

from(
select 
--cal.cal_tipo,
tra.tra_codigo,
tra.are_codigo,
tra.pue_codigo,
hor.hor_codigo,
fht.fht_fecha, 
dhr.dhr_ingreso , 
dhr.dhr_salida  , 
dhr.dhr_salidarefrigerio ,
dhr.dhr_ingresorefrigerio , 
dhr_tolingreso ,
dhr_tolingresorefrigerio , 
dhr.dhr_tiemporefrigerio ,
 dhr.dhr_day  ,
  dhr.dhr_nocturno,
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end
as ingreso,
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end as salida,
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end as ingresorefrigerio,
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end as salidarefrigerio,


(extract(epoch from age( 
case when dhr.dhr_nocturno 
  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
  else cast(now() as date)+ dhr.dhr_salida end
  ,cast(now() as date) + dhr.dhr_ingreso  
  ) ) - (case when dhr.dhr_increfrigerio then 0 else (dhr.dhr_tiemporefrigerio *60)  end) )/*/3600*/  as nhoras,

dhr.dhr_increfrigerio 

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo  and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
--inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
WHERE cast(tra.tra_codigo as varchar)  LIKE (case  when tracodigo::int = 0 then '%' ELSE tracodigo end)
--and extract(year from fht.fht_fecha, ::date) = anio::INTEGER
) as f where  f.ingreso is not null or f.salida is not null or f.ingresorefrigerio is not null or f.salidarefrigerio is not null ;

contador :=(SELECT MAX(registro) from tmarcaciones as tmar) ;

FOR mmarcaciones IN SELECT  mar.tra_codigo,
tra.are_codigo,
tra.pue_codigo,
hor.hor_codigo,
dhr.dhr_nocturno,
mar.mar_fechahora,mar.mar_tipo ,(select dia_semana(mar.mar_fechahora::date )) as dia ,
dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_ingresorefrigerio,dhr.dhr_salidarefrigerio,dhr.dhr_increfrigerio,dhr.dhr_tiemporefrigerio
  from asistencias.tblmarcaciones_mar as mar 
inner join asistencias.tbltrabajadores_tra as tra on mar.tra_codigo = tra.tra_codigo
inner join asistencias.tblfechahorario_fht as fht on mar.tra_codigo = fht.tra_codigo and mar.mar_fechahora::date = fht.fht_fecha
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day') 
where mar.mar_tipo <> 'I' AND mar.mar_tipo <> 'IR' AND mar.mar_tipo <> 'SR' AND mar.mar_tipo <> 'S' --AND  mar.mar_fechahora::date between fechaini and fechafin
and cast(tra.tra_codigo as varchar)  LIKE (case  when tracodigo::int = 0 then '%' ELSE tracodigo end)--  and substring(mar.mar_tipo from 2 for 1) = 'C'
order by mar.tra_codigo,mar.mar_fechahora asc
LOOP
ingresotemp = mmarcaciones.mar_fechahora;
fechatemp = mmarcaciones.mar_fechahora::date;

IF substring(mmarcaciones.mar_tipo from 2 for 1) = 'X' THEN  
    nommarca = 'HORAS EXTRA TURNO';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='A' THEN 
  nommarca = 'TRABAJO AUTORIZADO';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='E' THEN 
  nommarca = 'HORAS EXTRA';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='P' THEN 
  nommarca = 'PERMISO';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='J' THEN 
  nommarca = 'PERMISO JUSTIFICADO MAÑANA';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='C' THEN 
  nommarca = 'COMISIÓN';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='U' THEN 
  nommarca = 'H.EXTRA REMUNERADAS';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='T' THEN 
  nommarca = 'TRAB AUTORIZADO REM';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='O' THEN 
  nommarca = 'PERMISO TARDE';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='N' THEN 
  nommarca = 'PERMISO MAÑANA';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='V' THEN 
  nommarca = 'VACACIONES MAÑANA';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='I' THEN 
  nommarca = 'VACACIONES TARDE';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='F' THEN 
  nommarca = 'PERMISO JUSTIFICADO TARDE';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='D' THEN 
  nommarca = 'VACACIONES';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='G' THEN 
  nommarca = 'PERMISO JUSTIFICADO';
END IF;

asicodigo_temp = (SELECT  asi.asi_codigo::CHARACTER FROM   asistencias.tblasistencias_asi as asi where asi.tra_codigo = mmarcaciones.tra_codigo and (asi.asi_ingreso = mmarcaciones.mar_fechahora or   asi.asi_ingresorefrigerio = mmarcaciones.mar_fechahora or asi.asi_salidarefrigerio = mmarcaciones.mar_fechahora or  asi.asi_salida = mmarcaciones.mar_fechahora)  limit 1);
--raise notice 'Value: % %', asicodigo_temp,E'\n';
IF asicodigo_temp is null THEN 

      IF mmarcaciones.mar_tipo ='ST' THEN 
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1) in ('X','A','E', 'P','J','C','U','T','O','N','V','I','F','D','G') THEN 
        IF  substring(mmarcaciones.mar_tipo from 1 for 1) = '1' then
              contador = contador +1;
          atrabajar =(extract(epoch from age( case when mmarcaciones.dhr_nocturno then cast(now() as date) + CAST('1 days' AS INTERVAL)+ mmarcaciones.dhr_salida else cast(now() as date)+ mmarcaciones.dhr_salida end ,cast(now() as date) + mmarcaciones.dhr_ingreso  ) ) - (case when mmarcaciones.dhr_increfrigerio then 0 else (mmarcaciones.dhr_tiemporefrigerio *60)  end) );
              fechahoratemp = mmarcaciones.mar_fechahora;
              
        ELSIF substring(mmarcaciones.mar_tipo from 1 for 1) = '4' then
            IF ingresotemp::time >= '00:00:00'::time AND  ingresotemp::time < '07:00:00'::time  then
                update tmarcaciones  set salida = mmarcaciones.mar_fechahora ,  tipomarc = nommarca ,horas2 = (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingreso) )),horas_trabajadas = (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingreso) ))/*/3600*/ - tmarcaciones.horas1  
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp - CAST('1 days' AS INTERVAL) and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            ELSE
                update tmarcaciones set salida = mmarcaciones.mar_fechahora ,  tipomarc = nommarca, horas2 = (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingreso) )),horas_trabajadas = (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingreso) ))/*/3600*/ - tmarcaciones.horas1   
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            END IF;
        ELSIF substring(mmarcaciones.mar_tipo from 1 for 1) = '2' then
            IF ingresotemp::time >= '00:00:00'::time AND  ingresotemp::time < '07:00:00'::time  then
                update tmarcaciones  set ingresorefrigerio = mmarcaciones.mar_fechahora , tipomarc = nommarca 
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp - CAST('1 days' AS INTERVAL) and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            ELSE
                update tmarcaciones  set ingresorefrigerio = mmarcaciones.mar_fechahora , tipomarc = nommarca 
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            END IF;
        ELSIF  substring(mmarcaciones.mar_tipo from 1 for 1) = '3' then
            IF ingresotemp::time >= '00:00:00'::time AND  ingresotemp::time < '07:00:00'::time  then
                update tmarcaciones  set salidarefrigerio = mmarcaciones.mar_fechahora  , tipomarc = nommarca, horas1= (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingresorefrigerio) )) 
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp - CAST('1 days' AS INTERVAL) and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            ELSE
                update tmarcaciones  set salidarefrigerio = mmarcaciones.mar_fechahora  , tipomarc = nommarca, horas1= (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingresorefrigerio) )) 
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            END IF;
        END IF;
    ELSE 
    --raise notice 'Value: % %',mmarcaciones.mar_tipo,E'\n';
    END IF;
END IF;

END LOOP;


WITH subquery AS (
      Select tm.registro ,
      CASE WHEN tm.hor_codigo <> 131 AND tm.martipo in ('O','N') THEN
        CASE WHEN  tm.salida::time < dhr.dhr_ingresorefrigerio::time AND dhr.dhr_nocturno = false THEN
            case when tm.ingreso::time > dhr.dhr_ingreso::time then
               extract(epoch from age(tm.ingreso,tm.fecha+dhr.dhr_ingreso  )) 
              else 0 end
        ELSE
           CASE WHEN  tm.ingreso::time > dhr.dhr_salidarefrigerio::time AND dhr.dhr_nocturno = false  THEN
            case when tm.ingreso::time > dhr.dhr_ingresorefrigerio::time then 0 else 0 end
           ELSE
             case  when (tm.ingreso> tm.fecha+ dhr.dhr_ingreso+ interval '1min' * dhr.dhr_tolingreso )
              then extract(epoch from age(tm.ingreso, tm.fecha+ dhr.dhr_ingreso )) /*/3600*/
              else 0 end 
           END   
           
        END 
      ELSE 0 END as IngresoTarde,
      CASE WHEN tm.hor_codigo <> 131 AND tm.martipo in ('O','N') THEN
        CASE WHEN  tm.ingreso::time > dhr.dhr_salidarefrigerio::time AND dhr.dhr_nocturno = false THEN
            case when tm.ingreso::time > dhr.dhr_ingresorefrigerio::time then
               extract(epoch from age(tm.ingreso,tm.fecha+dhr.dhr_ingresorefrigerio )) 
              else 0 end
        ELSE
             CASE WHEN  tm.salida::time < dhr.dhr_ingresorefrigerio::time AND dhr.dhr_nocturno = false THEN
                case when tm.ingreso::time > dhr.dhr_ingreso::time then 0 else 0 end
             ELSE     
                case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                then
                 extract(epoch from age( 
                  tm.salidarefrigerio,tm.ingresorefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute'))  )) /*/3600 */
                else 0 end 
             END
        END   
      ELSE 0 END as TardeRefrigerio,
        CASE WHEN tm.martipo = 'U' THEN
              case when   tm.horas_trabajadas > tm.horas_atrabajar 
                      THEN   (tm.horas_trabajadas - tm.horas_atrabajar )
                   WHEN tm.horas_trabajadas = tm.horas_atrabajar 
                      THEN tm.horas_trabajadas
                   ELSE   0 
              END 
        ELSE 
              tm.horas_trabajadas
        END as horasdia
       from  tmarcaciones as tm  
      inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = tm.hor_codigo and hor.hor_codigo <> 9999
      inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = tm.hor_codigo  and dhr.dhr_day =  to_char(tm.fecha , 'Day')
       where tipomarc not in ('ERROR','S/T','NORMAL') order by tm.tra_codigo,tm.ingreso
)
UPDATE tmarcaciones
SET horas_tardeingreso = subquery.IngresoTarde,
    horas_tarderefrigerio  = subquery.TardeRefrigerio,
    horas_trabajadas    = subquery.horasdia
FROM subquery
WHERE tmarcaciones.registro = subquery.registro;



  asi_salidarefrigerio,  asi_ingresorefrigerio,  asi_salida,  asi_nocturno, asi_tipooperacion, asi_tardeingreso,
  asi_tardeingresorefrigerio, asi_horas_atrabajar, asi_horas_trabajadas, mar_martipo, asi_horas1, asi_horas2,asi_dias)
select 
tra_codigo,are_codigo,pue_codigo,tipomarc,hor_codigo,fecha,ingreso,
ingresorefrigerio,salidarefrigerio,salida,nocturno,tipooperacion,horas_tardeingreso,
horas_tarderefrigerio,horas_atrabajar,horas_trabajadas,martipo,horas1,horas2,dias 
 from tmarcaciones  where tipomarc<>'S/T' and tipomarc<>'ERROR' order by fecha asc, ingreso asc;


    
  resultado ='OK';
RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.migra_marcaciones(tracodigo character varying) OWNER TO postgres;

--
-- Name: migra_marcaciones2(character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.migra_marcaciones2(tracodigo character varying) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE t RECORD;
DECLARE resultado character varying;
DECLARE varingreso TIMESTAMP(0);
DECLARE varsalida TIMESTAMP(0);
DECLARE mmarcaciones RECORD;

DECLARE ingresotemp TIMESTAMP without time zone;
DECLARE tracodigotemp integer;
DECLARE arecodigotemp integer;
DECLARE puecodigotemp integer;
DECLARE horcodigotemp integer;
DECLARE fechatemp DATE;
DECLARE nocturnotemp Boolean;
DECLARE tipooperaciontemp CHARACTER VARYING;

DECLARE asicodigo_temp character;

DECLARE contador integer ;
DECLARE fechahoratemp timestamp without time zone;
DECLARE nommarca character varying;
DECLARE atrabajar integer;

DECLARE tipoFinmar varchar;
DECLARE fechorIni timestamp(0);
DECLARE fechorFin timestamp(0);



BEGIN


CREATE TEMPORARY TABLE tmarcaciones (
registro integer,
tra_codigo integer,
are_codigo integer,
pue_codigo integer,
hor_codigo integer,
tipomarc character varying,
fecha date,
ingreso timestamp(0) without time zone,
salida timestamp(0) without time zone,
ingresorefrigerio timestamp(0) without time zone,
salidarefrigerio timestamp(0) without time zone,
nocturno Boolean,
tipooperacion character VARYING,
horas_tardeingreso double precision,
horas_tarderefrigerio double precision,
horas_atrabajar double precision,
horas_trabajadas double precision,
martipo character varying,
horas1 integer default 0,
horas2 integer default 0,
dias CHARACTER VARYING
);

 select 
ROW_NUMBER() OVER (ORDER BY tra_codigo) AS item,
f.tra_codigo ,
f.are_codigo,
f.pue_codigo,
f.hor_codigo ,
'NORMAL' as tipomarc,
 f.fht_fecha,
f.ingreso ,
 f.salida , 
 f.ingresorefrigerio , 
 f.salidarefrigerio,
 f.dhr_nocturno,
 '' as tipooperacion,
CASE WHEN f.hor_codigo <> 131 THEN
  CASE WHEN  f.salida::time < f.dhr_ingresorefrigerio::time THEN
      case when f.ingreso::time > f.dhr_ingreso::time then
         extract(epoch from age(f.ingreso,f.fht_fecha+f.dhr_ingreso  )) 
        else 0 end
  ELSE
     CASE WHEN  f.ingreso::time > f.dhr_salidarefrigerio::time  THEN
      case when f.ingreso::time > f.dhr_ingresorefrigerio::time then 0 else 0 end
     ELSE
       case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso )
        then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600*/
        else 0 end 
     END   
     
  END 
ELSE 0 END as IngresoTarde
,
CASE WHEN f.hor_codigo <> 131 THEN
  CASE WHEN  f.ingreso::time > f.dhr_salidarefrigerio::time  THEN
      case when f.ingreso::time > f.dhr_ingresorefrigerio::time then
         extract(epoch from age(f.ingreso,f.fht_fecha+f.dhr_ingresorefrigerio )) 
        else 0 end
  ELSE
       CASE WHEN  f.salida::time < f.dhr_ingresorefrigerio::time THEN
          case when f.ingreso::time > f.dhr_ingreso::time then 0 else 0 end
       ELSE     
          case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
          then
           extract(epoch from age( 
            f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio )) /*/3600 */
          else 0 end 
       END
  END   
ELSE 0 END as TardeRefrigerio,
f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  -  case when f.dhr_increfrigerio then 0 else coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 )  end )/*/3600*/ as horasdia,
null,0,0,(select dia_semana(f.ingreso::date )) as dia

from(
select 
--cal.cal_tipo,
tra.tra_codigo,
tra.are_codigo,
tra.pue_codigo,
hor.hor_codigo,
fht.fht_fecha, 
dhr.dhr_ingreso , 
dhr.dhr_salida  , 
dhr.dhr_salidarefrigerio ,
dhr.dhr_ingresorefrigerio , 
dhr_tolingreso ,
dhr_tolingresorefrigerio , 
dhr.dhr_tiemporefrigerio ,
 dhr.dhr_day  ,
  dhr.dhr_nocturno,
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end
as ingreso,
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end as salida,
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end as ingresorefrigerio,
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end as salidarefrigerio,


(extract(epoch from age( 
case when dhr.dhr_nocturno 
  then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
  else cast(now() as date)+ dhr.dhr_salida end
  ,cast(now() as date) + dhr.dhr_ingreso  
  ) ) - (case when dhr.dhr_increfrigerio then 0 else (dhr.dhr_tiemporefrigerio *60)  end) )/*/3600*/  as nhoras,

dhr.dhr_increfrigerio 

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo and hor.hor_codigo <> 9999
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo  and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
--inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
WHERE cast(tra.tra_codigo as varchar)  LIKE (case  when tracodigo::int = 0 then '%' ELSE tracodigo end)
and extract(year from fht.fht_fecha::date) = 2021::INTEGER
) as f where  f.ingreso is not null or f.salida is not null or f.ingresorefrigerio is not null or f.salidarefrigerio is not null ;

contador :=(SELECT MAX(registro) from tmarcaciones as tmar) ;

FOR mmarcaciones IN SELECT  mar.tra_codigo,
tra.are_codigo,
tra.pue_codigo,
hor.hor_codigo,
dhr.dhr_nocturno,
mar.mar_fechahora,mar.mar_tipo ,(select dia_semana(mar.mar_fechahora::date )) as dia ,
dhr.dhr_ingreso,dhr.dhr_salida,dhr.dhr_ingresorefrigerio,dhr.dhr_salidarefrigerio,dhr.dhr_increfrigerio,dhr.dhr_tiemporefrigerio
  from asistencias.tblmarcaciones_mar as mar 
inner join asistencias.tbltrabajadores_tra as tra on mar.tra_codigo = tra.tra_codigo
inner join asistencias.tblfechahorario_fht as fht on mar.tra_codigo = fht.tra_codigo and mar.mar_fechahora::date = fht.fht_fecha
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day') 
where mar.mar_tipo <> 'I' AND mar.mar_tipo <> 'IR' AND mar.mar_tipo <> 'SR' AND mar.mar_tipo <> 'S' --AND  mar.mar_fechahora::date between fechaini and fechafin
and cast(tra.tra_codigo as varchar)  LIKE (case  when tracodigo::int = 0 then '%' ELSE tracodigo end)--  and substring(mar.mar_tipo from 2 for 1) = 'C'
and extract(year from fht.fht_fecha::date) = 2021::INTEGER
order by mar.tra_codigo,mar.mar_fechahora asc
LOOP
ingresotemp = mmarcaciones.mar_fechahora;
fechatemp = mmarcaciones.mar_fechahora::date;

IF substring(mmarcaciones.mar_tipo from 2 for 1) = 'X' THEN  
    nommarca = 'HORAS EXTRA TURNO';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='A' THEN 
  nommarca = 'TRABAJO AUTORIZADO';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='E' THEN 
  nommarca = 'HORAS EXTRA';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='P' THEN 
  nommarca = 'PERMISO';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='J' THEN 
  nommarca = 'PERMISO JUSTIFICADO MAÑANA';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='C' THEN 
  nommarca = 'COMISIÓN';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='U' THEN 
  nommarca = 'H.EXTRA REMUNERADAS';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='T' THEN 
  nommarca = 'TRAB AUTORIZADO REM';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='O' THEN 
  nommarca = 'PERMISO TARDE';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='N' THEN 
  nommarca = 'PERMISO MAÑANA';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='V' THEN 
  nommarca = 'VACACIONES MAÑANA';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='I' THEN 
  nommarca = 'VACACIONES TARDE';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='F' THEN 
  nommarca = 'PERMISO JUSTIFICADO TARDE';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='D' THEN 
  nommarca = 'VACACIONES';
ELSIF substring(mmarcaciones.mar_tipo from 2 for 1)='G' THEN 
  nommarca = 'PERMISO JUSTIFICADO';
END IF;

asicodigo_temp = (SELECT  asi.asi_codigo::CHARACTER FROM   asistencias.tblasistencias_asi as asi where asi.tra_codigo = mmarcaciones.tra_codigo and (asi.asi_ingreso = mmarcaciones.mar_fechahora or   asi.asi_ingresorefrigerio = mmarcaciones.mar_fechahora or asi.asi_salidarefrigerio = mmarcaciones.mar_fechahora or  asi.asi_salida = mmarcaciones.mar_fechahora)  limit 1);
--raise notice 'Value: % %', asicodigo_temp,E'\n';
IF asicodigo_temp is null THEN 

      IF mmarcaciones.mar_tipo ='ST' THEN 
    ELSIF substring(mmarcaciones.mar_tipo from 2 for 1) in ('X','A','E', 'P','J','C','U','T','O','N','V','I','F','D','G') THEN 
        IF  substring(mmarcaciones.mar_tipo from 1 for 1) = '1' then
              contador = contador +1;
          atrabajar =(extract(epoch from age( case when mmarcaciones.dhr_nocturno then cast(now() as date) + CAST('1 days' AS INTERVAL)+ mmarcaciones.dhr_salida else cast(now() as date)+ mmarcaciones.dhr_salida end ,cast(now() as date) + mmarcaciones.dhr_ingreso  ) ) - (case when mmarcaciones.dhr_increfrigerio then 0 else (mmarcaciones.dhr_tiemporefrigerio *60)  end) );
              fechahoratemp = mmarcaciones.mar_fechahora;
              
        ELSIF substring(mmarcaciones.mar_tipo from 1 for 1) = '4' then
            IF ingresotemp::time >= '00:00:00'::time AND  ingresotemp::time < '07:00:00'::time  then
                update tmarcaciones  set salida = mmarcaciones.mar_fechahora ,  tipomarc = nommarca ,horas2 = (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingreso) )),horas_trabajadas = (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingreso) ))/*/3600*/ - tmarcaciones.horas1  
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp - CAST('1 days' AS INTERVAL) and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            ELSE
                update tmarcaciones set salida = mmarcaciones.mar_fechahora ,  tipomarc = nommarca, horas2 = (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingreso) )),horas_trabajadas = (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingreso) ))/*/3600*/ - tmarcaciones.horas1   
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            END IF;
        ELSIF substring(mmarcaciones.mar_tipo from 1 for 1) = '2' then
            IF ingresotemp::time >= '00:00:00'::time AND  ingresotemp::time < '07:00:00'::time  then
                update tmarcaciones  set ingresorefrigerio = mmarcaciones.mar_fechahora , tipomarc = nommarca 
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp - CAST('1 days' AS INTERVAL) and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            ELSE
                update tmarcaciones  set ingresorefrigerio = mmarcaciones.mar_fechahora , tipomarc = nommarca 
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            END IF;
        ELSIF  substring(mmarcaciones.mar_tipo from 1 for 1) = '3' then
            IF ingresotemp::time >= '00:00:00'::time AND  ingresotemp::time < '07:00:00'::time  then
                update tmarcaciones  set salidarefrigerio = mmarcaciones.mar_fechahora  , tipomarc = nommarca, horas1= (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingresorefrigerio) )) 
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp - CAST('1 days' AS INTERVAL) and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            ELSE
                update tmarcaciones  set salidarefrigerio = mmarcaciones.mar_fechahora  , tipomarc = nommarca, horas1= (extract(epoch from age( mmarcaciones.mar_fechahora ,tmarcaciones.ingresorefrigerio) )) 
                where tmarcaciones.registro = contador; --tmarca.tra_codigo = mmarcaciones.tra_codigo and tmarca.fecha = fechatemp and tmarca.ingreso::timestamp(0) = fechahoratemp::timestamp(0) ;
            END IF;
        END IF;
    ELSE 
    --raise notice 'Value: % %',mmarcaciones.mar_tipo,E'\n';
    END IF;
END IF;

END LOOP;


WITH subquery AS (
      Select tm.registro ,
      CASE WHEN tm.hor_codigo <> 131 AND tm.martipo in ('O','N') THEN
        CASE WHEN  tm.salida::time < dhr.dhr_ingresorefrigerio::time AND dhr.dhr_nocturno = false THEN
            case when tm.ingreso::time > dhr.dhr_ingreso::time then
               extract(epoch from age(tm.ingreso,tm.fecha+dhr.dhr_ingreso  )) 
              else 0 end
        ELSE
           CASE WHEN  tm.ingreso::time > dhr.dhr_salidarefrigerio::time AND dhr.dhr_nocturno = false  THEN
            case when tm.ingreso::time > dhr.dhr_ingresorefrigerio::time then 0 else 0 end
           ELSE
             case  when (tm.ingreso> tm.fecha+ dhr.dhr_ingreso+ interval '1min' * dhr.dhr_tolingreso )
              then extract(epoch from age(tm.ingreso, tm.fecha+ dhr.dhr_ingreso )) /*/3600*/
              else 0 end 
           END   
           
        END 
      ELSE 0 END as IngresoTarde,
      CASE WHEN tm.hor_codigo <> 131 AND tm.martipo in ('O','N') THEN
        CASE WHEN  tm.ingreso::time > dhr.dhr_salidarefrigerio::time AND dhr.dhr_nocturno = false THEN
            case when tm.ingreso::time > dhr.dhr_ingresorefrigerio::time then
               extract(epoch from age(tm.ingreso,tm.fecha+dhr.dhr_ingresorefrigerio )) 
              else 0 end
        ELSE
             CASE WHEN  tm.salida::time < dhr.dhr_ingresorefrigerio::time AND dhr.dhr_nocturno = false THEN
                case when tm.ingreso::time > dhr.dhr_ingreso::time then 0 else 0 end
             ELSE     
                case when (dhr.dhr_ingresorefrigerio<> dhr.dhr_salidarefrigerio) 
                then
                 extract(epoch from age( 
                  tm.salidarefrigerio,tm.ingresorefrigerio +  (dhr.dhr_tiemporefrigerio * (interval '1 minute'))  )) /*/3600 */
                else 0 end 
             END
        END   
      ELSE 0 END as TardeRefrigerio,
        CASE WHEN tm.martipo = 'U' THEN
              case when   tm.horas_trabajadas > tm.horas_atrabajar 
                      THEN   (tm.horas_trabajadas - tm.horas_atrabajar )
                   WHEN tm.horas_trabajadas = tm.horas_atrabajar 
                      THEN tm.horas_trabajadas
                   ELSE   0 
              END 
        ELSE 
              tm.horas_trabajadas
        END as horasdia
       from  tmarcaciones as tm  
      inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = tm.hor_codigo and hor.hor_codigo <> 9999
      inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = tm.hor_codigo  and dhr.dhr_day =  to_char(tm.fecha , 'Day')
       where tipomarc not in ('ERROR','S/T','NORMAL') order by tm.tra_codigo,tm.ingreso
)
UPDATE tmarcaciones
SET horas_tardeingreso = subquery.IngresoTarde,
    horas_tarderefrigerio  = subquery.TardeRefrigerio,
    horas_trabajadas    = subquery.horasdia
FROM subquery
WHERE tmarcaciones.registro = subquery.registro;



  asi_salidarefrigerio,  asi_ingresorefrigerio,  asi_salida,  asi_nocturno, asi_tipooperacion, asi_tardeingreso,
  asi_tardeingresorefrigerio, asi_horas_atrabajar, asi_horas_trabajadas, mar_martipo, asi_horas1, asi_horas2,asi_dias)
select 
tra_codigo,are_codigo,pue_codigo,tipomarc,hor_codigo,fecha,ingreso,
ingresorefrigerio,salidarefrigerio,salida,nocturno,tipooperacion,horas_tardeingreso,
horas_tarderefrigerio,horas_atrabajar,horas_trabajadas,martipo,horas1,horas2,dias 
 from tmarcaciones  where tipomarc<>'S/T' and tipomarc<>'ERROR' order by fecha asc, ingreso asc;


    
  resultado ='OK';
RETURN QUERY  select resultado;
END;
$$;


ALTER FUNCTION asistencias.migra_marcaciones2(tracodigo character varying) OWNER TO postgres;

--
-- Name: migrar_datos_new(); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.migrar_datos_new() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  DECLARE
  BEGIN
  
    PERFORM asistencias.fun_marcacionesnuevos ( new.tra_codigo, new.mar_fechahora, new.mar_tipo::character varying,1);
  	
  	--select * from asistencias.fun_marcacionesnuevos ( new.tra_codigo, new.mar_fechahora, new.mar_tipo::character varying,1);
	--IF NEW.rel_codigo <> 1 THEN --1 es el reloj manual,
	--	PERFORM asistencias.fun_marcacionesnuevos ( new.tra_codigo, new.mar_fechahora, new.mar_tipo::character varying,1);
  	--ELSIF NEW.mar_masiva in (1,2,3,4)  THEN   -- 1 marcacaion masiva 2 marcapc 3 marcamovil 4 permisos con marcaciones
	--	PERFORM asistencias.fun_marcacionesnuevos ( new.tra_codigo, new.mar_fechahora, new.mar_tipo::character varying,1);
    --END IF;
   RETURN NEW;
  END;
$$;


ALTER FUNCTION asistencias.migrar_datos_new() OWNER TO postgres;

--
-- Name: migrar_datos_new_backup(); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.migrar_datos_new_backup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  DECLARE
  BEGIN
  	--select * from asistencias.fun_marcacionesnuevos ( new.tra_codigo, new.mar_fechahora, new.mar_tipo::character varying,1);
	IF NEW.rel_codigo <> 1 THEN --1 es el reloj manual,
		PERFORM asistencias.fun_marcacionesnuevos ( new.tra_codigo, new.mar_fechahora, new.mar_tipo::character varying,1);
  	ELSIF NEW.mar_masiva in (1,2,3,4)  THEN   -- 1 marcacaion masiva 2 marcapc 3 marcamovil 4 permisos con marcaciones
		PERFORM asistencias.fun_marcacionesnuevos ( new.tra_codigo, new.mar_fechahora, new.mar_tipo::character varying,1);
    END IF;
    RETURN NEW;
  END;
$$;


ALTER FUNCTION asistencias.migrar_datos_new_backup() OWNER TO postgres;

--
-- Name: psgasistencias(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistencias(fechaini date, fechafin date) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  mar1 varchar(50),
  mar2 varchar(50),
  hora1 varchar(50),
  hora2 varchar(50),
  mar3 varchar(50),
  mar4 varchar(50),
  hora3 varchar(50),
  hora4 varchar(50),
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20), 
  are_codigo INTEGER  
 );
 
 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');
 

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 
 inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo 
 inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo 
 inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin LOOP
            
       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
               FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
               IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 
               END IF;  
            END LOOP;
      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
      
             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday'  THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
			  IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);
              END IF;    
             END LOOP;
           
               
            
             
            
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m 
 inner join asistencias.tblfechahorario_fht as t on t.fht_fecha = cast(m.mar_fechahora as date) and t.tra_codigo = m.tra_codigo
 --inner join asistencias.tbltrabajadoreshorarios_tho as t on m.tra_codigo = t.tra_codigo 
 inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo 
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo and d.dhr_day = to_char(m .mar_fechahora, 'Day')  
 where m.mar_tipo in ('I','IR','SR','S') LOOP
           
      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora) <= pg_catalog.time(rmarca.dhr_ingreso)+ interval '1min' * rmarca.dhr_tolingreso THEN
              
              UPDATE caltemp2 SET tipo= 'Marco', mar1 = '', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 
              flag = to_char(rmarca.mar_fechahora, 'HH24:MI:SS');
              UPDATE caltemp2 SET tipo= 'Marco', mar1 = 'IT', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF;
     /*cambios todo SR po IR y al reves */
      IF rmarca.mar_tipo = 'IR' THEN
             UPDATE caltemp2 SET tipo= 'Marco', mar2 = '', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      
      END IF;
      /****/
      
      IF (rmarca.mar_tipo = 'SR' and (rmarca.mar_fechahora) >
      (
	Select  (m1.mar_fechaHora) + (rmarca.dhr_tolingresorefrigerio * (interval '1 minute')) + (rmarca.dhr_tiemporefrigerio * (interval '1 minute'))  as tiempo from asistencias.tblmarcaciones_mar as m1 where CAST(to_char(m1.mar_fechaHora  , 'yyyy-MM-dd') as date) =  CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)
	and m1.mar_tipo='IR'
	and m1.tra_codigo =rmarca.tra_codigo 
	order by m1.mar_fechaHora
	limit 1 offset 0)
      )
      THEN
               UPDATE caltemp2 SET tipo= 'Marco', mar3 = 'TR', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
     ELSEIF rmarca.mar_tipo = 'SR' THEN
     UPDATE caltemp2 SET tipo= 'Marco', mar3 = '', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF; 
      /*******/
      IF rmarca.mar_tipo = 'S' THEN
               UPDATE caltemp2 SET tipo= 'Marco', mar4 = '', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF;
      
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
    
     
      
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 
 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1,  hora2,
                    mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';
END;
$$;


ALTER FUNCTION asistencias.psgasistencias(fechaini date, fechafin date) OWNER TO postgres;

--
-- Name: psgasistencias_area(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistencias_area(fechaini date, fechafin date, codarea integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  mar1 varchar(50),
  mar2 varchar(50),
  hora1 varchar(50),
  hora2 varchar(50),
  mar3 varchar(50),
  mar4 varchar(50),
  hora3 varchar(50),
  hora4 varchar(50),
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20),
  are_codigo INTEGER  
 );
 
  ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');
 

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin  and r.are_codigo = codarea LOOP
        
     IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP   
           IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                 day := 'Lunes';
           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                 day := 'Martes';
           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                 day:= 'Miercoles';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                 day:= 'Jueves';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                 day:= 'Viernes';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                 day:= 'Sabado';                              
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                 day:= 'Domingo';  
           END IF;
               IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 
               END IF;  
         END LOOP;  
         
      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
          FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP   
             IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                   day := 'Lunes';
             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                   day := 'Martes';
             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                   day:= 'Miercoles';
             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                   day:= 'Jueves';
             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                   day:= 'Viernes';
             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                   day:= 'Sabado';                              
             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                   day:= 'Domingo';  
             END IF;
           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);  
               END IF;  
         END LOOP; 
           
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m 
 inner join asistencias.tblfechahorario_fht as t on t.fht_fecha = cast(m.mar_fechahora as date) and t.tra_codigo = m.tra_codigo
-- inner join asistencias.tbltrabajadoreshorarios_tho as t on m.tra_codigo = t.tra_codigo 
 inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo 
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo and d.dhr_day = to_char(m .mar_fechahora, 'Day')
 where m.mar_tipo in ('I','IR','SR','S') LOOP
           
      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora) <= pg_catalog.time(rmarca.dhr_ingreso)+ interval '1min' * rmarca.dhr_tolingreso THEN
              
              UPDATE caltemp2 SET tipo= 'Marco', mar1 = '', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 
              flag = to_char(rmarca.mar_fechahora, 'HH24:MI:SS');
              UPDATE caltemp2 SET tipo= 'Marco', mar1 = 'IT', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ; 
      END IF;
      IF rmarca.mar_tipo = 'IR' THEN
             UPDATE caltemp2 SET tipo= 'Marco', mar2 = '', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      
      END IF; 
      /****/
      IF (rmarca.mar_tipo = 'SR' and (rmarca.mar_fechahora) > 
      (
	Select  (m1.mar_fechaHora) + (rmarca.dhr_tolingresorefrigerio * (interval '1 minute')) + (rmarca.dhr_tiemporefrigerio * (interval '1 minute'))  as tiempo from asistencias.tblmarcaciones_mar as m1 where CAST(to_char(m1.mar_fechaHora  , 'yyyy-MM-dd') as date) =  CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)
	and m1.mar_tipo='IR'
	and m1.tra_codigo =rmarca.tra_codigo 
	order by m1.mar_fechaHora
	limit 1 offset 0)
       ) 
      THEN
               UPDATE caltemp2 SET tipo= 'Marco', mar3 = 'TR', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
     ELSEIF rmarca.mar_tipo = 'SR' THEN
     UPDATE caltemp2 SET tipo= 'Marco', mar3 = '', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF; 
      /*******/
      IF rmarca.mar_tipo = 'S' THEN
               UPDATE caltemp2 SET tipo= 'Marco', mar4 = '', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF;       
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
    
     
     
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 
 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1, hora2,
                    mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';
END;
$$;


ALTER FUNCTION asistencias.psgasistencias_area(fechaini date, fechafin date, codarea integer) OWNER TO postgres;

--
-- Name: psgasistencias_area_oficial(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistencias_area_oficial(fechaini date, fechafin date, codarea integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE

 result varchar(10);

 codigoTrabajador Integer;

 martipo varchar(10);

 flag varchar(100);

 ramdomnumero varchar(10);

 day varchar(20);

 ahora varchar(20);

 DECLARE r RECORD;

 DECLARE rfecha RECORD;

 DECLARE rmarca RECORD;

 DECLARE rvacaciones RECORD;

 DECLARE det RECORD;
 DECLARE l RECORD;
 DECLARE j RECORD;
 DECLARE q RECORD;
 DECLARE calt RECORD;
 DECLARE mhdi RECORD;
 DECLARE mhdf RECORD;


BEGIN

 CREATE TEMPORARY TABLE caltemp2(

  

  tra_codigo INTEGER,

  tra_nombre varchar(50),

  tra_apellidopaterno varchar(50),

  tra_apellidomaterno varchar(50),

  tra_dni varchar(8),

  tra_identificador varchar(50),

  are_nombre varchar(50),

  pue_nombre varchar(50),

  fecha DATE, 

  mar1 varchar(50),

  mar2 varchar(50),

  hora1 varchar(50),

  hora2 varchar(50),

  mar3 varchar(50),

  mar4 varchar(50),

  hora3 varchar(50),

  hora4 varchar(50),

  tipo varchar(50),

  dia VARCHAR(20),

  ahora varchar(20),

  are_codigo INTEGER  

 );

 

  ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');

 



 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t 

 inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 

 inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo

 inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  

 inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo LOOP 

      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin  and r.are_codigo = codarea and suc_codigo=r.suc_codigo LOOP

        

     IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin

     and cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer) THEN

         

         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP   

           IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                 day := 'Lunes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                 day := 'Martes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                 day:= 'Miercoles';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                 day:= 'Jueves';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                 day:= 'Viernes';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                 day:= 'Sabado';                              

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                 day:= 'Domingo';  

           END IF;

               IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 

               END IF;  

         END LOOP;  

         

      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 

      and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer) THEN

          

          FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP   

             IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                   day := 'Lunes';

             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                   day := 'Martes';

             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                   day:= 'Miercoles';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                   day:= 'Jueves';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                   day:= 'Viernes';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                   day:= 'Sabado';                              

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                   day:= 'Domingo';  

             END IF;

           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);  

               END IF;  

         END LOOP; 

           

      END IF;

                       

      END LOOP;

      

      

 END LOOP;



 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m

 inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo

 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP

           

      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora)

       <= pg_catalog.time(rmarca.dhr_ingreso) THEN

              

       IF pg_catalog.time(rmarca.mar_fechahora)<= pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = pg_catalog.time(rmarca.dhr_ingreso)- CAST(ramdomnumero || ' min' AS interval) 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

	   ELSEIF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

       		

            UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

        END IF;



      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) 

      and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 

              

             IF pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) + interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = pg_catalog.time(rmarca.dhr_ingreso)+ CAST(ramdomnumero || ' min' AS interval) 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

	   ELSEIF pg_catalog.time(rmarca.mar_fechahora)  < pg_catalog.time(rmarca.dhr_ingreso)+ interval '5min' THEN
       		
            UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
        END IF;  
      END IF;

      

      

    
      /*******/
IF rmarca.mar_tipo = 'S' THEN

		 IF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_salida)+ interval '5min' THEN

                  ramdomnumero= floor((random()*6));

                UPDATE caltemp2 SET tipo = 'Marco',mar4 = '',
                hora4 = pg_catalog.time(rmarca.dhr_salida) + CAST(ramdomnumero || ' min' AS interval) 
                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                    

           ELSE
           UPDATE caltemp2 SET tipo = 'Marco',mar4 = '',

                hora4 =pg_catalog.time(rmarca.mar_fechahora)  
                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                        
           
            END IF;           
      END IF;

END LOOP;  


FOR calt IN 
select * from caltemp2
loop

    FOR mhdi IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS')as timei ,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') asc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', mar2 = '', hora2 = mhdi.timei 
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;
               

               end loop;

      FOR mhdf IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS') as timef,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') desc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', mar3 = '', hora3 = mhdf.timef
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;

               end loop;    

end loop;


FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
              
      FOR rvacaciones IN 
       Select * from asistencias.tblpermisos_per as p
       inner join asistencias.tbltipopermisos_tip as tp on p.tip_codigo = tp.tip_codigo
       inner join asistencias.tbltrabajadores_tra as t on t.tra_codigo=p.tra_codigo
       inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
       inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo 
       where t.tra_codigo=r.tra_codigo
       and  cast( (SELECT extract(week from CAST(p.per_fechafin as date))) as integer)=CAST(g.hro_semana AS integer)
         or cast( (SELECT extract(week from CAST(p.per_fechaini as date))) as integer)=CAST(g.hro_semana AS integer)
 
       LOOP 
                    
          IF rvacaciones.tip_escalat =TRUE THEN    

                UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre,hora1='',hora2='',hora3='',hora4=''  
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;

          ELSEIF rvacaciones.tip_escalat =FALSE THEN  
			
          FOR q IN select * from asistencias.tbldethorarios_dhr d where d.hor_codigo=rvacaciones.hor_codigo
          LOOP 
       			UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=q.dhr_ingreso,mar2 = 'P',hora2=q.dhr_salidarefrigerio,mar3 = 'P',hora3=q.dhr_ingresorefrigerio,mar4 = 'P',hora4=q.dhr_salida 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo
                and upper(TRIM(to_char(pg_catalog.date(caltemp2.fecha),'day')))=upper(TRIM(q.dhr_day)) 
                and caltemp2.fecha > pg_catalog.date(rvacaciones.per_fechaini) 
                and caltemp2.fecha < pg_catalog.date(rvacaciones.per_fechafin);
          END LOOP;
          
          FOR l IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo and
                    upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechaini),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 

                    if pg_catalog.time(rvacaciones.per_fechaini) < l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=l.dhr_ingreso,mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if; 
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar4 = 'P',hora4=l.dhr_salida  
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    
                   end LOOP;

                          
                    FOR j IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo 
                    and upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechafin),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 
                    
                     if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salida THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio,mar4 = 'P',hora4=j.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
 
                  
                   end LOOP;                
          
                                   
          END IF;   
 

      END LOOP;

 END LOOP;

 

 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1, hora2,

                    mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';

END;
$$;


ALTER FUNCTION asistencias.psgasistencias_area_oficial(fechaini date, fechafin date, codarea integer) OWNER TO postgres;

--
-- Name: psgasistencias_codigo(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistencias_codigo(fechaini date, fechafin date, codigo integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora  varchar(20);
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  mar1 varchar(50),
  mar2 varchar(50),
  hora1 varchar(50),
  hora2 varchar(50),
  mar3 varchar(50),
  mar4 varchar(50),
  hora3 varchar(50),
  hora4 varchar(50),
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20),
  are_codigo INTEGER  
 );
 
 
 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin and r.tra_codigo = codigo LOOP
        
      IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
          FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 
             IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                   day := 'Lunes';
             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                   day := 'Martes';
             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                   day:= 'Miercoles';
             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                   day:= 'Jueves';
             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                   day:= 'Viernes';
             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                   day:= 'Sabado';                              
             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                   day:= 'Domingo';  
             END IF;
          IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 
               END IF;  
          END LOOP;     
          
       ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
           IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                 day := 'Lunes';
           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                 day := 'Martes';
           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                 day:= 'Miercoles';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                 day:= 'Jueves';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                 day:= 'Viernes';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                 day:= 'Sabado';                              
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                 day:= 'Domingo';  
           END IF;
           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo); 
           END IF;  
         END LOOP;    
          
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m 
  inner join asistencias.tblfechahorario_fht as t on t.fht_fecha = cast(m.mar_fechahora as date) and t.tra_codigo = m.tra_codigo
-- inner join asistencias.tbltrabajadoreshorarios_tho as t on m.tra_codigo = t.tra_codigo 
 inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo 
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo and d.dhr_day = to_char(m .mar_fechahora, 'Day') 
 where m.mar_tipo in ('I','IR','SR','S') LOOP
           
      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora) <= pg_catalog.time(rmarca.dhr_ingreso)+ interval '1min' * rmarca.dhr_tolingreso THEN
              
              UPDATE caltemp2 SET tipo= 'Marco', mar1 = '', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 
              flag = to_char(rmarca.mar_fechahora, 'HH24:MI:SS');
              UPDATE caltemp2 SET tipo= 'Marco', mar1 = 'IT', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;  
      END IF;
      IF rmarca.mar_tipo = 'IR' THEN
             UPDATE caltemp2 SET tipo= 'Marco', mar2 = '', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      
      END IF;
      /****/
      IF (rmarca.mar_tipo = 'SR' and (rmarca.mar_fechahora) > 
      (
	Select  (m1.mar_fechaHora) + (rmarca.dhr_tolingresorefrigerio * (interval '1 minute')) + (rmarca.dhr_tiemporefrigerio * (interval '1 minute'))  as tiempo from asistencias.tblmarcaciones_mar as m1 where CAST(to_char(m1.mar_fechaHora  , 'yyyy-MM-dd') as date) =  CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)
	and m1.mar_tipo='IR'
	and m1.tra_codigo =rmarca.tra_codigo 
	order by m1.mar_fechaHora
	limit 1 offset 0)
       ) 
      THEN
               UPDATE caltemp2 SET tipo= 'Marco', mar3 = 'TR', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
     ELSEIF rmarca.mar_tipo = 'SR' THEN
     UPDATE caltemp2 SET tipo= 'Marco', mar3 = '', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF; 
      /*******/
      IF rmarca.mar_tipo = 'S' THEN
               UPDATE caltemp2 SET tipo= 'Marco', mar4 = '', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF;      
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
    
     
     
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 
 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1, hora2, mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';
END;
$$;


ALTER FUNCTION asistencias.psgasistencias_codigo(fechaini date, fechafin date, codigo integer) OWNER TO postgres;

--
-- Name: psgasistencias_codigo_back(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistencias_codigo_back(fechaini date, fechafin date, codigo integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE

 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora  varchar(20);
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
DECLARE l RECORD;
DECLARE j RECORD;
DECLARE q RECORD;

	BEGIN

 DROP TABLE IF EXISTS caltemp2;
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  mar1 varchar(50),
  mar2 varchar(50),
  hora1 varchar(50),
  hora2 varchar(50),
  mar3 varchar(50),
  mar4 varchar(50),
  hora3 varchar(50),
  hora4 varchar(50),
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20),
  are_codigo INTEGER  

 );

 

 

 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');



 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t 

 inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 

 inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo

 inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  

 inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo LOOP 

      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin and r.tra_codigo = codigo and suc_codigo=r.suc_codigo LOOP

        

      IF rfecha.cal_tipo = 'F' 
      and rfecha.cal_fecha >= r.hor_fechainicio 
      and rfecha.cal_fecha <= r.hor_fechafin 
      and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer)
      and  TRIM(upper((r.hro_año))) =TRIM(upper(to_char(CAST(rfecha.cal_fecha as date),'yyyy'))) THEN

         

       FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 

             IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                   day := 'Lunes';

             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                   day := 'Martes';

             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                   day:= 'Miercoles';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                   day:= 'Jueves';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                   day:= 'Viernes';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                   day:= 'Sabado';                              

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                   day:= 'Domingo';  

             END IF;

          IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 

               END IF;  

          END LOOP;     

          

       ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin

       and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer)
       and  TRIM(upper((r.hro_año))) =TRIM(upper(to_char(CAST(rfecha.cal_fecha as date),'yyyy'))) THEN

         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP

           IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                 day := 'Lunes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                 day := 'Martes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                 day:= 'Miercoles';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                 day:= 'Jueves';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                 day:= 'Viernes';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                 day:= 'Sabado';                              

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                 day:= 'Domingo';  

           END IF;

           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo); 

           END IF;  

         END LOOP;    

          

      END IF;

                       

      END LOOP;

      

      

 END LOOP;



 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m

 inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo

 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP

           

      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora) <= pg_catalog.time(rmarca.dhr_ingreso)+ interval '1min' * rmarca.dhr_tolingreso THEN

              

              UPDATE caltemp2 SET tipo= 'Marco', mar1 = '', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 

              flag = to_char(rmarca.mar_fechahora, 'HH24:MI:SS');

              UPDATE caltemp2 SET tipo= 'Marco', mar1 = 'IT', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;  

      END IF;

      IF rmarca.mar_tipo = 'IR' THEN

             UPDATE caltemp2 SET tipo= 'Marco', mar2 = '', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

      

      END IF;

      /****/

      IF rmarca.mar_tipo = 'SR' and to_char(rmarca.mar_fechahora,'hh:MI') > to_char((rmarca.dhr_ingresorefrigerio + rmarca.dhr_tolingresorefrigerio * (interval '1 minute')), 'hh:MI') THEN

               UPDATE caltemp2 SET tipo= 'Marco', mar3 = 'TR', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

     ELSEIF rmarca.mar_tipo = 'SR' THEN

     UPDATE caltemp2 SET tipo= 'Marco', mar3 = '', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

      END IF; 

      /*******/

      IF rmarca.mar_tipo = 'S' THEN

               UPDATE caltemp2 SET tipo= 'Marco', mar4 = '', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

      END IF;      

END LOOP;  



 
FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
              
      FOR rvacaciones IN 
       Select * from asistencias.tblpermisos_per as p
       inner join asistencias.tbltipopermisos_tip as tp on p.tip_codigo = tp.tip_codigo
       inner join asistencias.tbltrabajadores_tra as t on t.tra_codigo=p.tra_codigo
       inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
       inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo 
       where t.tra_codigo=r.tra_codigo
       and  cast( (SELECT extract(week from CAST(p.per_fechafin as date))) as integer)=CAST(g.hro_semana AS integer)
         or cast( (SELECT extract(week from CAST(p.per_fechaini as date))) as integer)=CAST(g.hro_semana AS integer)
 
       LOOP 
                    
          IF rvacaciones.tip_escalat =TRUE THEN    

                UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;

          ELSEIF rvacaciones.tip_escalat =FALSE THEN  
			
          FOR q IN select * from asistencias.tbldethorarios_dhr d where d.hor_codigo=rvacaciones.hor_codigo
          LOOP 
       			UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=q.dhr_ingreso,mar2 = 'P',hora2=q.dhr_salidarefrigerio,mar3 = 'P',hora3=q.dhr_ingresorefrigerio,mar4 = 'P',hora4=q.dhr_salida 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo
                and upper(TRIM(to_char(pg_catalog.date(caltemp2.fecha),'day')))=upper(TRIM(q.dhr_day)) 
                and caltemp2.fecha > pg_catalog.date(rvacaciones.per_fechaini) 
                and caltemp2.fecha < pg_catalog.date(rvacaciones.per_fechafin);
          END LOOP;
          
          FOR l IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo and
                    upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechaini),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 

                    if pg_catalog.time(rvacaciones.per_fechaini) < l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=l.dhr_ingreso,mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if; 
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar4 = 'P',hora4=l.dhr_salida  
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    
                   end LOOP;

                          
                    FOR j IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo 
                    and upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechafin),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 
                    
                     if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salida THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio,mar4 = 'P',hora4=j.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
 
                  
                   end LOOP;                
 
                   
                                   
          END IF;   

      

      END LOOP;

 

 END LOOP;


 

 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1, hora2, mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';

END;
$$;


ALTER FUNCTION asistencias.psgasistencias_codigo_back(fechaini date, fechafin date, codigo integer) OWNER TO postgres;

--
-- Name: psgasistencias_codigo_oficial(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistencias_codigo_oficial(fechaini date, fechafin date, codigo integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE

 result varchar(10);

 codigoTrabajador Integer;

 martipo varchar(10);

 flag varchar(100);

 ramdomnumero varchar(10);

 day varchar(20);

 ahora  varchar(20);

 DECLARE r RECORD;

 DECLARE rfecha RECORD;

 DECLARE rmarca RECORD;

 DECLARE rvacaciones RECORD;

 DECLARE det RECORD;
 DECLARE q RECORD;
 DECLARE l RECORD;
 DECLARE j RECORD;
 DECLARE calt RECORD;
 DECLARE mhdi RECORD;
 DECLARE mhdf RECORD;


BEGIN

 CREATE TEMPORARY TABLE caltemp2(

  

  tra_codigo INTEGER,

  tra_nombre varchar(50),

  tra_apellidopaterno varchar(50),

  tra_apellidomaterno varchar(50),

  tra_dni varchar(8),

  tra_identificador varchar(50),

  are_nombre varchar(50),

  pue_nombre varchar(50),

  fecha DATE, 

  mar1 varchar(50),

  mar2 varchar(50),

  hora1 varchar(50),

  hora2 varchar(50),

  mar3 varchar(50),

  mar4 varchar(50),

  hora3 varchar(50),

  hora4 varchar(50),

  tipo varchar(50),

  dia VARCHAR(20),

  ahora varchar(20),

  are_codigo INTEGER  

 );

 

 

 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');



 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t 

 inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 

 inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo

 inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  

 inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo LOOP 

      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin and r.tra_codigo = codigo and suc_codigo=r.suc_codigo LOOP

        

      IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 

      and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer)THEN

         

       FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 

             IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                   day := 'Lunes';

             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                   day := 'Martes';

             ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                   day:= 'Miercoles';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                   day:= 'Jueves';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                   day:= 'Viernes';

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                   day:= 'Sabado';                              

             ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                   day:= 'Domingo';  

             END IF;

          IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 

               END IF;  

          END LOOP;     

          

       ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin

       and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer) THEN

         

         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP

           IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                 day := 'Lunes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                 day := 'Martes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                 day:= 'Miercoles';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                 day:= 'Jueves';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                 day:= 'Viernes';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                 day:= 'Sabado';                              

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                 day:= 'Domingo';  

           END IF;

           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo); 

           END IF;  

         END LOOP;    

          

      END IF;

                       

      END LOOP;

      

      

 END LOOP;



 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m

 inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo

 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP

           

      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora)

       <= pg_catalog.time(rmarca.dhr_ingreso) THEN

              

       IF pg_catalog.time(rmarca.mar_fechahora)<= pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = pg_catalog.time(rmarca.dhr_ingreso)- CAST(ramdomnumero || ' min' AS interval) 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

	   ELSEIF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

       		

            UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

        END IF;



      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) 

      and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 

              

             IF pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) + interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = pg_catalog.time(rmarca.dhr_ingreso)+ CAST(ramdomnumero || ' min' AS interval) 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

	   ELSEIF pg_catalog.time(rmarca.mar_fechahora)  < pg_catalog.time(rmarca.dhr_ingreso)+ interval '5min' THEN

       		

            UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

        END IF;  



      END IF;

      

      

      /*******/

      IF rmarca.mar_tipo = 'S' THEN

          IF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_salida)+ interval '5min' THEN

                  ramdomnumero= floor((random()*6));


                UPDATE caltemp2 SET tipo = 'Marco',mar4 = '',

                hora4 = pg_catalog.time(rmarca.dhr_salida) + CAST(ramdomnumero || ' min' AS interval) 

                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                    

                  

           ELSE
           UPDATE caltemp2 SET tipo = 'Marco',mar4 = '',

                hora4 =pg_catalog.time(rmarca.mar_fechahora)  

                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                        
           
            END IF;           

      END IF;
END LOOP;  


FOR calt IN 
select * from caltemp2
loop

    FOR mhdi IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS')as timei ,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') asc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', mar2 = '', hora2 = mhdi.timei 
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;
               

               end loop;

      FOR mhdf IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS') as timef,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') desc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', mar3 = '', hora3 = mhdf.timef
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;

               end loop;    

end loop;


FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
              
      FOR rvacaciones IN 
       Select * from asistencias.tblpermisos_per as p
       inner join asistencias.tbltipopermisos_tip as tp on p.tip_codigo = tp.tip_codigo
       inner join asistencias.tbltrabajadores_tra as t on t.tra_codigo=p.tra_codigo
       inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
       inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo 
       where t.tra_codigo=r.tra_codigo
       and  cast( (SELECT extract(week from CAST(p.per_fechafin as date))) as integer)=CAST(g.hro_semana AS integer)
         or cast( (SELECT extract(week from CAST(p.per_fechaini as date))) as integer)=CAST(g.hro_semana AS integer)
 
       LOOP 
                    
          IF rvacaciones.tip_escalat =TRUE THEN    

                UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre,hora1='',hora2='',hora3='',hora4=''  
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;

          ELSEIF rvacaciones.tip_escalat =FALSE THEN  
			
          FOR q IN select * from asistencias.tbldethorarios_dhr d where d.hor_codigo=rvacaciones.hor_codigo
          LOOP 
       			UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=q.dhr_ingreso,mar2 = 'P',hora2=q.dhr_salidarefrigerio,mar3 = 'P',hora3=q.dhr_ingresorefrigerio,mar4 = 'P',hora4=q.dhr_salida 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo
                and upper(TRIM(to_char(pg_catalog.date(caltemp2.fecha),'day')))=upper(TRIM(q.dhr_day)) 
                and caltemp2.fecha > pg_catalog.date(rvacaciones.per_fechaini) 
                and caltemp2.fecha < pg_catalog.date(rvacaciones.per_fechafin);
          END LOOP;
          
          FOR l IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo and
                    upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechaini),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 

                    if pg_catalog.time(rvacaciones.per_fechaini) < l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=l.dhr_ingreso,mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if; 
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar4 = 'P',hora4=l.dhr_salida  
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    
                   end LOOP;

                          
                    FOR j IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo 
                    and upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechafin),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 
                    
                     if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salida THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio,mar4 = 'P',hora4=j.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
 
                  
                   end LOOP;                                   
                                   
          END IF;        

      END LOOP;

 END LOOP;

 

 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1, hora2, mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo,tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';

END;
$$;


ALTER FUNCTION asistencias.psgasistencias_codigo_oficial(fechaini date, fechafin date, codigo integer) OWNER TO postgres;

--
-- Name: psgasistencias_horario(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistencias_horario(fechaini date, fechafin date, codhorario integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  mar1 varchar(50),
  mar2 varchar(50),
  hora1 varchar(50),
  hora2 varchar(50),
  mar3 varchar(50),
  mar4 varchar(50),
  hora3 varchar(50),
  hora4 varchar(50),
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20),
  are_codigo INTEGER  
 );
 
 
 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS'); 

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin and r.hor_codigo = codhorario LOOP
        
      IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
          IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                 day := 'Lunes';
           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                 day := 'Martes';
           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                 day:= 'Miercoles';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                 day:= 'Jueves';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                 day:= 'Viernes';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                 day:= 'Sabado';                              
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                 day:= 'Domingo';  
           END IF;
           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 
           END IF;  
          END LOOP;        
           
      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
           IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                 day := 'Lunes';
           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                 day := 'Martes';
           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                 day:= 'Miercoles';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                 day:= 'Jueves';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                 day:= 'Viernes';
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                 day:= 'Sabado';                              
           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                 day:= 'Domingo';  
           END IF; 
           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo); 
           END IF;  
         END LOOP;  
           
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m 
 inner join asistencias.tblfechahorario_fht as t on t.fht_fecha = cast(m.mar_fechahora as date) and t.tra_codigo = m.tra_codigo
 --inner join asistencias.tbltrabajadoreshorarios_tho as t on m.tra_codigo = t.tra_codigo 
 inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo 
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo and d.dhr_day = to_char(m .mar_fechahora, 'Day') 
 where m.mar_tipo in ('I','IR','SR','S') LOOP
           
      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora) <= pg_catalog.time(rmarca.dhr_ingreso)+ interval '1min' * rmarca.dhr_tolingreso THEN
              
              UPDATE caltemp2 SET tipo= 'Marco', mar1 = '', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 
              flag = to_char(rmarca.mar_fechahora, 'HH24:MI:SS');
              UPDATE caltemp2 SET tipo= 'Marco', mar1 = 'IT', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ; 
      END IF;
      IF rmarca.mar_tipo = 'IR' THEN
             UPDATE caltemp2 SET tipo= 'Marco', mar2 = '', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      
      END IF;
      /****/
      IF (rmarca.mar_tipo = 'SR' and (rmarca.mar_fechahora) > 
      (
	Select  (m1.mar_fechaHora) + (rmarca.dhr_tolingresorefrigerio * (interval '1 minute')) + (rmarca.dhr_tiemporefrigerio * (interval '1 minute'))  as tiempo from asistencias.tblmarcaciones_mar as m1 where CAST(to_char(m1.mar_fechaHora  , 'yyyy-MM-dd') as date) =  CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)
	and m1.mar_tipo='IR'
	and m1.tra_codigo =rmarca.tra_codigo 
	order by m1.mar_fechaHora
	limit 1 offset 0)
       ) 

      THEN
               UPDATE caltemp2 SET tipo= 'Marco', mar3 = 'TR', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
     ELSEIF rmarca.mar_tipo = 'SR' THEN
     UPDATE caltemp2 SET tipo= 'Marco', mar3 = '', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF; 
      /*******/
      IF rmarca.mar_tipo = 'S' THEN
               UPDATE caltemp2 SET tipo= 'Marco', mar4 = '', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      END IF;        
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
    
     
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 
 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1, hora2, mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';
END;
$$;


ALTER FUNCTION asistencias.psgasistencias_horario(fechaini date, fechafin date, codhorario integer) OWNER TO postgres;

--
-- Name: psgasistencias_horario_oficial(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistencias_horario_oficial(fechaini date, fechafin date, codhorario integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE

 result varchar(10);

 codigoTrabajador Integer;

 martipo varchar(10);

 flag varchar(100);

 ramdomnumero varchar(10);

 day varchar(20);

 ahora varchar(20);

 DECLARE r RECORD;

 DECLARE rfecha RECORD;

 DECLARE rmarca RECORD;

 DECLARE rvacaciones RECORD;

 DECLARE det RECORD;
 DECLARE j RECORD;
 DECLARE l RECORD;
 DECLARE q RECORD;
 DECLARE calt RECORD;
 DECLARE mhdi RECORD;
 DECLARE mhdf RECORD;


BEGIN

 CREATE TEMPORARY TABLE caltemp2(

  

  tra_codigo INTEGER,

  tra_nombre varchar(50),

  tra_apellidopaterno varchar(50),

  tra_apellidomaterno varchar(50),

  tra_dni varchar(8),

  tra_identificador varchar(50),

  are_nombre varchar(50),

  pue_nombre varchar(50),

  fecha DATE, 

  mar1 varchar(50),

  mar2 varchar(50),

  hora1 varchar(50),

  hora2 varchar(50),

  mar3 varchar(50),

  mar4 varchar(50),

  hora3 varchar(50),

  hora4 varchar(50),

  tipo varchar(50),

  dia VARCHAR(20),

  ahora varchar(20),

  are_codigo INTEGER  

 );

 

 

 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS'); 



 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t 

 inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 

 inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo

 inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  

 inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo LOOP 

      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin and r.hor_codigo = codhorario and suc_codigo=r.suc_codigo LOOP

      IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin

          and cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer) THEN
      
         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP

          IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                 day := 'Lunes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                 day := 'Martes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                 day:= 'Miercoles';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                 day:= 'Jueves';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                 day:= 'Viernes';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                 day:= 'Sabado';                              

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                 day:= 'Domingo';  

           END IF;

           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 

           END IF;  

          END LOOP;        

           

      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 

      and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer)THEN

         

         FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP

           IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                 day := 'Lunes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                 day := 'Martes';

           ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                 day:= 'Miercoles';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                 day:= 'Jueves';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                 day:= 'Viernes';

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                 day:= 'Sabado';                              

           ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                 day:= 'Domingo';  

           END IF; 

           IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo); 

           END IF;  

         END LOOP;  

           

      END IF;
                       
      END LOOP;
            
 END LOOP;



 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m

 inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo

 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP

           

      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora)

       <= pg_catalog.time(rmarca.dhr_ingreso) THEN
              
       IF pg_catalog.time(rmarca.mar_fechahora)<= pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = pg_catalog.time(rmarca.dhr_ingreso)- CAST(ramdomnumero || ' min' AS interval) 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
              
	   ELSEIF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

            UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
            

        END IF;

      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) 

      and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 
              
             IF pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) + interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = pg_catalog.time(rmarca.dhr_ingreso)+ CAST(ramdomnumero || ' min' AS interval) 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;              

	   ELSEIF pg_catalog.time(rmarca.mar_fechahora)  < pg_catalog.time(rmarca.dhr_ingreso)+ interval '5min' THEN
       		
            UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
             

        END IF;  

      END IF;

      
      /*******/

      IF rmarca.mar_tipo = 'S' THEN

           IF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_salida)+ interval '5min' THEN

                  ramdomnumero= floor((random()*6));

                UPDATE caltemp2 SET tipo = 'Marco',mar4 = '',
                hora4 = pg_catalog.time(rmarca.dhr_salida) + CAST(ramdomnumero || ' min' AS interval) 
                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                    

           ELSE
           UPDATE caltemp2 SET tipo = 'Marco',mar4 = '',

                hora4 =pg_catalog.time(rmarca.mar_fechahora)  
                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                        
           
            END IF;           
      END IF;
END LOOP;  


FOR calt IN 
select * from caltemp2
loop

    FOR mhdi IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS')as timei ,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') asc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', mar2 = '', hora2 = mhdi.timei 
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;
               

               end loop;

      FOR mhdf IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS') as timef,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') desc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', mar3 = '', hora3 = mhdf.timef
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;

               end loop;    

end loop;


FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
              
      FOR rvacaciones IN 
       Select * from asistencias.tblpermisos_per as p
       inner join asistencias.tbltipopermisos_tip as tp on p.tip_codigo = tp.tip_codigo
       inner join asistencias.tbltrabajadores_tra as t on t.tra_codigo=p.tra_codigo
       inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
       inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo 
       where t.tra_codigo=r.tra_codigo
       and  cast( (SELECT extract(week from CAST(p.per_fechafin as date))) as integer)=CAST(g.hro_semana AS integer)
         or cast( (SELECT extract(week from CAST(p.per_fechaini as date))) as integer)=CAST(g.hro_semana AS integer)
 
       LOOP 
                    
          IF rvacaciones.tip_escalat =TRUE THEN    

                UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre,hora1='',hora2='',hora3='',hora4=''  
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;

          ELSEIF rvacaciones.tip_escalat =FALSE THEN  
			
          FOR q IN select * from asistencias.tbldethorarios_dhr d where d.hor_codigo=rvacaciones.hor_codigo
          LOOP 
       			UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=q.dhr_ingreso,mar2 = 'P',hora2=q.dhr_salidarefrigerio,mar3 = 'P',hora3=q.dhr_ingresorefrigerio,mar4 = 'P',hora4=q.dhr_salida 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo
                and upper(TRIM(to_char(pg_catalog.date(caltemp2.fecha),'day')))=upper(TRIM(q.dhr_day)) 
                and caltemp2.fecha > pg_catalog.date(rvacaciones.per_fechaini) 
                and caltemp2.fecha < pg_catalog.date(rvacaciones.per_fechafin);
          END LOOP;
          
          FOR l IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo and
                    upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechaini),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 

                    if pg_catalog.time(rvacaciones.per_fechaini) < l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=l.dhr_ingreso,mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if; 
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar4 = 'P',hora4=l.dhr_salida  
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    
                   end LOOP;

                          
                    FOR j IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo 
                    and upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechafin),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 
                    
                     if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salida THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio,mar4 = 'P',hora4=j.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
 
                  
                   end LOOP;                
 
                   
                                   
          END IF;   

      

      END LOOP;

 

 END LOOP;

 

 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1, hora2, mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo,tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';

END;
$$;


ALTER FUNCTION asistencias.psgasistencias_horario_oficial(fechaini date, fechafin date, codhorario integer) OWNER TO postgres;

--
-- Name: psgasistenciasoficial(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgasistenciasoficial(fechaini date, fechafin date) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, hora3 character varying, mar3 character varying, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer)
    LANGUAGE plpgsql
    AS $$
DECLARE

 result varchar(10);

 codigoTrabajador Integer;

 martipo varchar(10);

 flag varchar(100);

 ramdomnumero varchar(10);

 day varchar(20);

 ahora varchar(20);

 DECLARE r RECORD;

 DECLARE rfecha RECORD;

 DECLARE rmarca RECORD;

 DECLARE rvacaciones RECORD;

 DECLARE det RECORD;
DECLARE j RECORD;
DECLARE l RECORD;
DECLARE q RECORD;
DECLARE calt RECORD;
 DECLARE mhdi RECORD;
 DECLARE mhdf RECORD;

BEGIN

 CREATE TEMPORARY TABLE caltemp2(

  tra_codigo INTEGER,

  tra_nombre varchar(50),

  tra_apellidopaterno varchar(50),

  tra_apellidomaterno varchar(50),

  tra_dni varchar(8),

  tra_identificador varchar(50),

  are_nombre varchar(50),

  pue_nombre varchar(50),

  fecha DATE, 

  mar1 varchar(50),

  mar2 varchar(50),

  hora1 varchar(50),

  hora2 varchar(50),

  mar3 varchar(50),

  mar4 varchar(50),

  hora3 varchar(50),

  hora4 varchar(50),

  tipo varchar(50),

  dia VARCHAR(20),

  ahora varchar(20), 

  are_codigo INTEGER  

 );

 

 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');

 



 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t 

 inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 

 inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo

 inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  

 inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo LOOP 

      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin and suc_codigo=r.suc_codigo LOOP

            

       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 

       and cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer) THEN

              

        FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 

                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                       day := 'Lunes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                       day := 'Martes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                       day:= 'Miercoles';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                       day:= 'Jueves';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                       day:= 'Viernes';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                       day:= 'Sabado';                              

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                       day:= 'Domingo';  

                 END IF;

               IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 

               END IF;  

            END LOOP;

      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 

       and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer) THEN

      

             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP

                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN

                       day := 'Lunes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                       day := 'Martes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday'  THEN  

                       day:= 'Miercoles';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                       day:= 'Jueves';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                       day:= 'Viernes';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                       day:= 'Sabado';                              

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                       day:= 'Domingo';  

                 END IF;

			  IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN


                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,

                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);

              END IF;    

             END LOOP;

           

               

            

             

            

      END IF;

                       

      END LOOP;

      

      

 END LOOP;



  FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m

 inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo

 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP

           

      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora)

       <= pg_catalog.time(rmarca.dhr_ingreso) THEN

              

       IF pg_catalog.time(rmarca.mar_fechahora)<= pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = pg_catalog.time(rmarca.dhr_ingreso)- CAST(ramdomnumero || ' min' AS interval) 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

	   ELSEIF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

       		

            UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

        END IF;



      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) 

      and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 

              

             IF pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) + interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = pg_catalog.time(rmarca.dhr_ingreso)+ CAST(ramdomnumero || ' min' AS interval) 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

	   ELSEIF pg_catalog.time(rmarca.mar_fechahora)  < pg_catalog.time(rmarca.dhr_ingreso)+ interval '5min' THEN

       		

            UPDATE caltemp2 

              SET tipo= 'Marco',

                 mar1 = '', 

                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 

              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 

              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  

              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              

        END IF;  



      END IF;

      

     /*cambios todo SR po IR y al reves */

     
      /*******/

IF rmarca.mar_tipo = 'S' THEN

           IF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_salida)+ interval '5min' THEN

                  ramdomnumero= floor((random()*6));

                UPDATE caltemp2 SET tipo = 'Marco',mar4 = '',
                hora4 = pg_catalog.time(rmarca.dhr_salida) + CAST(ramdomnumero || ' min' AS interval) 
                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                    

           ELSE
           UPDATE caltemp2 SET tipo = 'Marco',mar4 = '',

                hora4 =pg_catalog.time(rmarca.mar_fechahora)  
                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                        
           
            END IF;           
      END IF;      

END LOOP;   


FOR calt IN 
select * from caltemp2
loop

    FOR mhdi IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS')as timei ,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') asc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', mar2 = '', hora2 = mhdi.timei 
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;
               

               end loop;

      FOR mhdf IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS') as timef,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') desc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', mar3 = '', hora3 = mhdf.timef
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;

               end loop;    

end loop;




 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
              
      FOR rvacaciones IN 
       Select * from asistencias.tblpermisos_per as p
       inner join asistencias.tbltipopermisos_tip as tp on p.tip_codigo = tp.tip_codigo
       inner join asistencias.tbltrabajadores_tra as t on t.tra_codigo=p.tra_codigo
       inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
       inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo 
       where t.tra_codigo=r.tra_codigo
       and  cast( (SELECT extract(week from CAST(p.per_fechafin as date))) as integer)=CAST(g.hro_semana AS integer)
         or cast( (SELECT extract(week from CAST(p.per_fechaini as date))) as integer)=CAST(g.hro_semana AS integer)
 
       LOOP 
                    
          IF rvacaciones.tip_escalat =TRUE THEN    

                UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre,hora1='',hora2='',hora3='',hora4=''  
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;

          ELSEIF rvacaciones.tip_escalat =FALSE THEN  
			
          FOR q IN select * from asistencias.tbldethorarios_dhr d where d.hor_codigo=rvacaciones.hor_codigo
          LOOP 
       			UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=q.dhr_ingreso,mar2 = 'P',hora2=q.dhr_salidarefrigerio,mar3 = 'P',hora3=q.dhr_ingresorefrigerio,mar4 = 'P',hora4=q.dhr_salida 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo
                and upper(TRIM(to_char(pg_catalog.date(caltemp2.fecha),'day')))=upper(TRIM(q.dhr_day)) 
                and caltemp2.fecha > pg_catalog.date(rvacaciones.per_fechaini) 
                and caltemp2.fecha < pg_catalog.date(rvacaciones.per_fechafin);
          END LOOP;
          
          FOR l IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo and
                    upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechaini),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 

                    if pg_catalog.time(rvacaciones.per_fechaini) < l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=l.dhr_ingreso,mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if; 
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar2 = 'P',hora2=l.dhr_salidarefrigerio,mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar3 = 'P',hora3=l.dhr_ingresorefrigerio,mar4 = 'P',hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar4 = 'P',hora4=l.dhr_salida  
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    
                   end LOOP;

                          
                    FOR j IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo 
                    and upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechafin),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 
                    
                     if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingreso THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salida THEN
                     UPDATE caltemp2 SET tipo ='Perm.Horas',mar1 = 'P',hora1=j.dhr_ingreso,mar2 = 'P',hora2=j.dhr_salidarefrigerio,mar3 = 'P',hora3=j.dhr_ingresorefrigerio,mar4 = 'P',hora4=j.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
 
                  
                   end LOOP;                
                                                       
          END IF;   
      
      END LOOP;
 
 END LOOP;

 

 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1,  hora2,

                    mar2, hora3, mar3, hora4, mar4, tipo, dia, ahora, are_codigo  FROM caltemp2 order by are_codigo,tra_nombre, tra_apellidopaterno, tra_apellidomaterno, fecha';

END;
$$;


ALTER FUNCTION asistencias.psgasistenciasoficial(fechaini date, fechafin date) OWNER TO postgres;

--
-- Name: psgcardex(character); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgcardex(anio character) RETURNS TABLE(tra_codigo integer, ene_1 double precision, feb_1 double precision, mar_1 double precision, abr_1 double precision, may_1 double precision, jun_1 double precision, jul_1 double precision, ago_1 double precision, set_1 double precision, act_1 double precision, nov_1 double precision, dic_1 double precision, ene_2 double precision, feb_2 double precision, mar_2 double precision, abr_2 double precision, may_2 double precision, jun_2 double precision, jul_2 double precision, ago_2 double precision, set_2 double precision, act_2 double precision, nov_2 double precision, dic_2 double precision, ene_3 double precision, feb_3 double precision, mar_3 double precision, abr_3 double precision, may_3 double precision, jun_3 double precision, jul_3 double precision, ago_3 double precision, set_3 double precision, act_3 double precision, nov_3 double precision, dic_3 double precision, ene_4 double precision, feb_4 double precision, mar_4 double precision, abr_4 double precision, may_4 double precision, jun_4 double precision, jul_4 double precision, ago_4 double precision, set_4 double precision, act_4 double precision, nov_4 double precision, dic_4 double precision, ene_5 double precision, feb_5 double precision, mar_5 double precision, abr_5 double precision, may_5 double precision, jun_5 double precision, jul_5 double precision, ago_5 double precision, set_5 double precision, act_5 double precision, nov_5 double precision, dic_5 double precision, ene_6 double precision, feb_6 double precision, mar_6 double precision, abr_6 double precision, may_6 double precision, jun_6 double precision, jul_6 double precision, ago_6 double precision, set_6 double precision, act_6 double precision, nov_6 double precision, dic_6 double precision, ene_7 double precision, feb_7 double precision, mar_7 double precision, abr_7 double precision, may_7 double precision, jun_7 double precision, jul_7 double precision, ago_7 double precision, set_7 double precision, act_7 double precision, nov_7 double precision, dic_7 double precision, ene_8 double precision, feb_8 double precision, mar_8 double precision, abr_8 double precision, may_8 double precision, jun_8 double precision, jul_8 double precision, ago_8 double precision, set_8 double precision, act_8 double precision, nov_8 double precision, dic_8 double precision, ene_9 double precision, feb_9 double precision, mar_9 double precision, abr_9 double precision, may_9 double precision, jun_9 double precision, jul_9 double precision, ago_9 double precision, set_9 double precision, act_9 double precision, nov_9 double precision, dic_9 double precision, ene_10 double precision, feb_10 double precision, mar_10 double precision, abr_10 double precision, may_10 double precision, jun_10 double precision, jul_10 double precision, ago_10 double precision, set_10 double precision, act_10 double precision, nov_10 double precision, dic_10 double precision)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD;  
BEGIN
--Desde este punto es una tabla temporal de la horas extras
CREATE TEMPORARY TABLE tmarcacionesExtras (
cod integer,
tipo char(1),
tra_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
ingresoR timestamp without time zone,
salidaR timestamp without time zone,
horas1 double precision default 0,
horas2 double precision default 0,
horas double precision default 0
); 
codigosTem := 1;

FOR r IN select * from asistencias.tblmarcaciones_mar as mar where mar.mar_tipo in ('1C','4C',  '1V', '4V' ,'1M','4M','1J','4J', '1P','4P', '1L','4L' , '1X','2X', '3X','4X' )
		order by mar.tra_codigo , mar.mar_fechahora LOOP
      IF substring(r.mar_tipo from  1 for 1)  = '1'  THEN
	codigosTem  =codigosTem   +1;      
	values (codigosTem  , substring(r.mar_tipo from  2 for 1),  r.tra_codigo , cast(r.mar_fechahora as date) , r.mar_fechahora );
      ELSEIF substring(r.mar_tipo from 1 for 1)  = '2' THEN
        update tmarcacionesExtras set ingresoR = r.mar_fechahora
        where tmarcacionesExtras.cod =codigosTem  ;      
      ELSEIF substring(r.mar_tipo from 1 for 1)  = '3' THEN
        update tmarcacionesExtras set salidaR = r.mar_fechahora , horas1 = (extract(epoch from age( r.mar_fechahora ,tmarcacionesExtras.ingresoR) ))/*/3600*/
        where tmarcacionesExtras.cod =codigosTem  ;
      ELSEIF substring(r.mar_tipo from 1 for 1)  = '4' THEN
        update tmarcacionesExtras set salida = r.mar_fechahora , horas2 = (extract(epoch from age( r.mar_fechahora ,tmarcacionesExtras.ingreso) ))/*/3600 */
        , horas = (extract(epoch from age( r.mar_fechahora ,tmarcacionesExtras.ingreso) ))/*/3600*/ - tmarcacionesExtras.horas1
        where tmarcacionesExtras.cod =codigosTem  ;                      
      END IF;    
END LOOP;

--****************************************************************************************************
--segunda tablatempral temporal 
 CREATE TEMPORARY TABLE tmarcaciones (
feriado char(1),
tra_codigo integer,
hor_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,
horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,

e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision
);

ingreso, salida, ingresorefrigerio ,salidarefrigerio,
horas_atrabajar, horas_trabajadas, horas_tardeingreso,horas_tardesalida)
(
select f.cal_tipo , f.tra_codigo , f.hor_codigo , f.fht_fecha,
f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,
f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  -  case when f.dhr_increfrigerio then 0 else coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 )  end )/*/3600*/ as horasdia
,
case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso )
then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /*/3600*/
else 0 end as IngresoTarde
,
case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
then
 extract(epoch from age( 
  f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio )) /*/3600 */
else 0 end 
  as TardeRefrigerio
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
cal.cal_tipo,
tra.tra_codigo,
hor.hor_codigo,
fht.fht_fecha, 
dhr.dhr_ingreso , dhr.dhr_salida  , 
dhr.dhr_salidarefrigerio , dhr.dhr_ingresorefrigerio , 
dhr_tolingreso , dhr_tolingresorefrigerio , 
dhr.dhr_tiemporefrigerio , dhr.dhr_day  , dhr.dhr_nocturno,
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo  order by mar_fechahora desc limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  limit 1)
end
as ingreso,
case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora  desc limit 1)
 end as salida,
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end as ingresorefrigerio,
 case when dhr.dhr_nocturno 
   then (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) and m.tra_codigo= tra.tra_codigo order by mar_fechahora limit 1)
   else (Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo order by mar_fechahora desc limit 1)
 end as salidarefrigerio,
/*
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingreso,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salida,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingresorefrigerio,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salidarefrigerio,
*/

(extract(epoch from age( 
case when dhr.dhr_nocturno 
	then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
	else cast(now() as date)+ dhr.dhr_salida end
	,cast(now() as date) + dhr.dhr_ingreso	
	) ) - (case when dhr.dhr_increfrigerio then 0 else (dhr.dhr_tiemporefrigerio *60)  end) )/*/3600*/  as nhoras,

dhr.dhr_increfrigerio	

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
) as f);

FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
	UPDATE tmarcaciones SET e_comision = true, h_comision= tmarcaciones.horas_trabajadas
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
	UPDATE tmarcaciones SET e_vacaciones = true , h_vacaciones = tmarcaciones.horas_atrabajar 
	WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
	UPDATE tmarcaciones SET e_medico= true , h_medico = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
	UPDATE tmarcaciones SET e_permisos = true , h_permisos = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
	UPDATE tmarcaciones SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
	UPDATE tmarcaciones SET e_compensacion  = true , h_compensacion  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
      
END LOOP;

