-- Name: psgcardexold1(character); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgcardexold1(anio character) RETURNS TABLE(tra_codigo integer, ene_1 double precision, feb_1 double precision, mar_1 double precision, abr_1 double precision, may_1 double precision, jun_1 double precision, jul_1 double precision, ago_1 double precision, set_1 double precision, act_1 double precision, nov_1 double precision, dic_1 double precision, ene_2 double precision, feb_2 double precision, mar_2 double precision, abr_2 double precision, may_2 double precision, jun_2 double precision, jul_2 double precision, ago_2 double precision, set_2 double precision, act_2 double precision, nov_2 double precision, dic_2 double precision, ene_3 double precision, feb_3 double precision, mar_3 double precision, abr_3 double precision, may_3 double precision, jun_3 double precision, jul_3 double precision, ago_3 double precision, set_3 double precision, act_3 double precision, nov_3 double precision, dic_3 double precision, ene_4 double precision, feb_4 double precision, mar_4 double precision, abr_4 double precision, may_4 double precision, jun_4 double precision, jul_4 double precision, ago_4 double precision, set_4 double precision, act_4 double precision, nov_4 double precision, dic_4 double precision, ene_5 double precision, feb_5 double precision, mar_5 double precision, abr_5 double precision, may_5 double precision, jun_5 double precision, jul_5 double precision, ago_5 double precision, set_5 double precision, act_5 double precision, nov_5 double precision, dic_5 double precision, ene_6 double precision, feb_6 double precision, mar_6 double precision, abr_6 double precision, may_6 double precision, jun_6 double precision, jul_6 double precision, ago_6 double precision, set_6 double precision, act_6 double precision, nov_6 double precision, dic_6 double precision, ene_7 double precision, feb_7 double precision, mar_7 double precision, abr_7 double precision, may_7 double precision, jun_7 double precision, jul_7 double precision, ago_7 double precision, set_7 double precision, act_7 double precision, nov_7 double precision, dic_7 double precision)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
  rvacaciones RECORD;
  tra2 RECORD;  
BEGIN
--Desde este punto es una tabla temporal de la horas extras
CREATE TEMPORARY TABLE tmarcacionesExtras (
cod integer,
tipo char(1),
tra_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
horas double precision default 0
); 
codigosTem := 1;


FOR r IN select * from asistencias.tblmarcaciones_mar as mar where mar.mar_tipo in ('1C','2C',  '1V', '2V' ,'1M','2M','1P','2P' )
		order by mar.tra_codigo , mar.mar_fechahora LOOP
      IF substring(r.mar_tipo from  1 for 1)  = '1'  THEN
	codigosTem  =codigosTem   +1;      
	values (codigosTem  , substring(r.mar_tipo from  2 for 1),  r.tra_codigo , cast(r.mar_fechahora as date) , r.mar_fechahora );
      ELSEIF substring(r.mar_tipo from 1 for 1)  = '2' THEN
        update tmarcacionesExtras set salida = r.mar_fechahora , horas = (extract(epoch from age( r.mar_fechahora ,tmarcacionesExtras.ingreso) ))/3600        
        where tmarcacionesExtras.cod =codigosTem  ;      
        
      END IF;    
END LOOP;

--****************************************************************************************************
--segunda tablatempral temporal 
 CREATE TEMPORARY TABLE tmarcaciones (
feriado char(1),
tra_codigo integer,
hor_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
ingresorefrigerio timestamp without time zone,
salidarefrigerio timestamp without time zone,
horas_atrabajar double precision,
horas_trabajadas double precision,
horas_tardeingreso double precision,
horas_tardesalida double precision,


e_comision boolean ,
e_vacaciones boolean,
e_medico boolean ,
e_permisos boolean,
e_permisosjustificado boolean,
e_compensacion boolean,

h_comision double precision,
h_vacaciones double precision,
h_medico double precision,
h_permisos double precision,
h_permisosjustificado double precision,
h_compensacion double precision
);

ingreso, salida, ingresorefrigerio ,salidarefrigerio,
horas_atrabajar, horas_trabajadas, horas_tardeingreso,horas_tardesalida)
(
select f.cal_tipo , f.tra_codigo , f.hor_codigo , f.fht_fecha,
f.ingreso , f.salida , f.ingresorefrigerio , f.salidarefrigerio,
f.nhoras,
(extract(epoch from age( f.salida,f.ingreso))  - coalesce( extract(epoch from age( f.salidarefrigerio,f.ingresorefrigerio) ),0 ))/3600 as horasdia
,
case  when (f.ingreso> f.fht_fecha+ f.dhr_ingreso+ interval '1min' * f.dhr_tolingreso )
then extract(epoch from age(f.ingreso, f.fht_fecha+ f.dhr_ingreso )) /3600
else 0 end as IngresoTarde
,
case when (f.dhr_ingresorefrigerio<> f.dhr_salidarefrigerio) 
then
 extract(epoch from age( 
  f.ingresorefrigerio +  (f.dhr_tiemporefrigerio * (interval '1 minute')) ,f.salidarefrigerio )) /3600 
else 0 end 
  as TardeRefrigerio
--, f.ingresorefrigerio  + interval '1min' * f.dhr_tiemporefrigerio 
from(
select 
cal.cal_tipo,
tra.tra_codigo,
hor.hor_codigo,
fht.fht_fecha, 
dhr.dhr_ingreso , dhr.dhr_salida  , 
dhr.dhr_salidarefrigerio , dhr.dhr_ingresorefrigerio , 
dhr_tolingreso , dhr_tolingresorefrigerio , 
dhr.dhr_tiemporefrigerio , dhr.dhr_day  , dhr.dhr_nocturno,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'I' and  cast(m.mar_fechaHora as date)= cast(fht.fht_fecha as date) and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingreso,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'S' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salida,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'IR' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as ingresorefrigerio,
(Select mar_fechahora from asistencias.tblmarcaciones_mar as m where m.mar_tipo = 'SR' and  cast(mar_fechaHora as date)= 
	case when dhr.dhr_nocturno then cast(fht.fht_fecha as date) + CAST('1 days' AS INTERVAL) else cast(fht.fht_fecha as date) end
	and m.tra_codigo= tra.tra_codigo 
order by mar_fechahora  limit 1)as salidarefrigerio,


(extract(epoch from age( 
case when dhr.dhr_nocturno 
	then cast(now() as date) + CAST('1 days' AS INTERVAL)+ dhr.dhr_salida 
	else cast(now() as date)+ dhr.dhr_salida end
	,cast(now() as date) + dhr.dhr_ingreso	
	) ) -(dhr.dhr_tiemporefrigerio *60)  )/3600  as nhoras

from asistencias.tblfechahorario_fht as fht
inner join asistencias.tbltrabajadores_tra as tra on tra.tra_codigo = fht.tra_codigo
inner join asistencias.tblhorarios_hor  as hor on hor.hor_codigo = fht.hor_codigo
inner join asistencias.tbldethorarios_dhr as dhr on dhr.hor_codigo = fht.hor_codigo and dhr.dhr_day =  to_char(fht.fht_fecha , 'Day')
inner join asistencias.tblcalendario_cal AS  cal on cal.cal_fecha = fht.fht_fecha
) as f);

FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP
   --comicion dia 
   IF rvacaciones.tip_codigo = 17 THEN 
	UPDATE tmarcaciones SET e_comision = true, h_comision= tmarcaciones.horas_trabajadas
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --vacaciones dia
   IF rvacaciones.tip_codigo = 4 THEN 
	UPDATE tmarcaciones SET e_vacaciones = true , h_vacaciones = tmarcaciones.horas_atrabajar 
	WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --medicos dias
   IF rvacaciones.tip_codigo = 6 THEN
	UPDATE tmarcaciones SET e_medico= true , h_medico = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;
   --permisos dias 
   IF rvacaciones.tip_codigo = 15 THEN 
	UPDATE tmarcaciones SET e_permisos = true , h_permisos = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --permisos justificado 
   IF rvacaciones.tip_codigo = 14 THEN 
	UPDATE tmarcaciones SET e_permisosjustificado  = true , h_permisosjustificado  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                  
   --compensacion 
   IF rvacaciones.tip_codigo = 16 THEN 
	UPDATE tmarcaciones SET e_compensacion  = true , h_compensacion  = tmarcaciones.horas_atrabajar
        WHERE tmarcaciones.tra_codigo = rvacaciones.tra_codigo and tmarcaciones.fecha 
        between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
   END IF;                     
      
END LOOP;

--*************************************************************************************************************************---
--la tablas de arriba se han creado para estas 


CREATE TEMPORARY TABLE trespuestas (
tra_codigo integer,
ene_1 double precision,
feb_1 double precision,
mar_1 double precision,
abr_1 double precision,
may_1 double precision,
jun_1 double precision,
jul_1 double precision,
ago_1 double precision,
set_1 double precision,
