set_7 double precision,
act_7 double precision,
nov_7 double precision,
dic_7 double precision

);



 FOR tra2 IN Select * from  asistencias.tbltrabajadores_tra LOOP 
--horas trabajadas 1
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-04-01' as date ) and cast (anio || '-04-30' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-05-01' as date ) and cast (anio || '-05-31' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-06-01' as date ) and cast (anio || '-06-30' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-07-01' as date ) and cast (anio || '-07-31' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-08-01' as date ) and cast (anio || '-08-31' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-09-01' as date ) and cast (anio || '-09-30' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-10-01' as date ) and cast (anio || '-10-31' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-11-01' as date ) and cast (anio || '-11-30' as date )),
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-12-01' as date ) and cast (anio || '-12-31' as date )),
--trabajo de comicion 2
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-04-01' as date ) and cast (anio || '-04-30' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-04-01' as date ) and cast (anio || '-04-30' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-05-01' as date ) and cast (anio || '-05-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-05-01' as date ) and cast (anio || '-05-31' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-06-01' as date ) and cast (anio || '-06-30' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-06-01' as date ) and cast (anio || '-06-30' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-07-01' as date ) and cast (anio || '-07-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-07-01' as date ) and cast (anio || '-07-31' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-08-01' as date ) and cast (anio || '-08-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-08-01' as date ) and cast (anio || '-08-31' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-09-01' as date ) and cast (anio || '-09-30' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-09-01' as date ) and cast (anio || '-09-30' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-10-01' as date ) and cast (anio || '-10-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-10-01' as date ) and cast (anio || '-10-31' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-11-01' as date ) and cast (anio || '-11-30' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-11-01' as date ) and cast (anio || '-11-30' as date ) and td.tipo ='C'),0),
coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-12-01' as date ) and cast (anio || '-12-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha  between cast (anio || '-12-01' as date ) and cast (anio || '-12-31' as date ) and td.tipo ='C'),0),

--VACACIONES 3
coalesce((  select sum(t.h_vacaciones ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date ) and td.tipo ='V'),0),
coalesce((select sum(t.h_vacaciones ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date ) and td.tipo ='V'),0),
coalesce((select sum(t.h_vacaciones) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date ) and td.tipo ='V'),0),
coalesce((select sum(t.h_vacaciones) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-04-01' as date ) and cast (anio || '-04-30' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-04-01' as date ) and cast (anio || '-04-30' as date ) and td.tipo ='V'),0),
coalesce((select sum(t.h_vacaciones) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-05-01' as date ) and cast (anio || '-05-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-05-01' as date ) and cast (anio || '-05-31' as date ) and td.tipo ='V'),0),
