 FOR tra2 IN Select * from  asistencias.tbltrabajadores_tra LOOP 
--horas trabajadas 1
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date )) /3600,
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date )) /3600,
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date )) /3600,
