(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-08-01' as date ) and cast (anio || '-08-31' as date )) /3600,
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-09-01' as date ) and cast (anio || '-09-30' as date )) /3600,
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-10-01' as date ) and cast (anio || '-10-31' as date )) /3600,
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-11-01' as date ) and cast (anio || '-11-30' as date )) /3600,
(select sum(t.horas_trabajadas) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-12-01' as date ) and cast (anio || '-12-31' as date )) /3600,
--trabajo de comicion 2
(coalesce((select sum(t.h_comision) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date ) and td.tipo ='C'),0))/3600,
