	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-05-01' as date ) and cast (anio || '-05-31' as date ) and td.tipo ='V'),0),
(coalesce((select sum(t.h_vacaciones) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-06-01' as date ) and cast (anio || '-06-30' as date )),0)
