	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-06-01' as date ) and cast (anio || '-06-30' as date ) and td.tipo ='P'),0))/3600,
(coalesce((select sum(t.h_permisos  ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-07-01' as date ) and cast (anio || '-07-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-07-01' as date ) and cast (anio || '-07-31' as date ) and td.tipo ='P'),0))/3600,
(coalesce((select sum(t.h_permisos  ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-08-01' as date ) and cast (anio || '-08-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-08-01' as date ) and cast (anio || '-08-31' as date ) and td.tipo ='P'),0))/3600,
(coalesce((select sum(t.h_permisos ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha  between cast (anio || '-09-01' as date ) and cast (anio || '-09-30' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-09-01' as date ) and cast (anio || '-09-30' as date ) and td.tipo ='P'),0))/3600,
(coalesce((select sum(t.h_permisos ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-10-01' as date ) and cast (anio || '-10-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-10-01' as date ) and cast (anio || '-10-31' as date ) and td.tipo ='P'),0))/3600,
(coalesce((select sum(t.h_permisos ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-11-01' as date ) and cast (anio || '-11-30' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-11-01' as date ) and cast (anio || '-11-30' as date ) and td.tipo ='P'),0))/3600,
(coalesce((select sum(t.h_permisos ) from tmarcaciones as t where t.tra_codigo = tra2.tra_codigo and  t.fecha between cast (anio || '-12-01' as date ) and cast (anio || '-12-31' as date )),0)
	+coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-12-01' as date ) and cast (anio || '-12-31' as date ) and td.tipo ='P'),0))/3600,	

--Extras 9
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-04-01' as date ) and cast (anio || '-04-30' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-05-01' as date ) and cast (anio || '-05-31' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-06-01' as date ) and cast (anio || '-06-30' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-07-01' as date ) and cast (anio || '-07-31' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-08-01' as date ) and cast (anio || '-08-31' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-09-01' as date ) and cast (anio || '-09-30' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-10-01' as date ) and cast (anio || '-10-31' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-11-01' as date ) and cast (anio || '-11-30' as date ) and td.tipo ='X'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-12-01' as date ) and cast (anio || '-12-31' as date ) and td.tipo ='X'),0)/3600,

--compensacion 10
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-01-01' as date ) and cast (anio || '-01-31' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-02-01' as date ) and cast (anio || '-02-28' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-03-01' as date ) and cast (anio || '-03-31' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-04-01' as date ) and cast (anio || '-04-30' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-05-01' as date ) and cast (anio || '-05-31' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-06-01' as date ) and cast (anio || '-06-30' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-07-01' as date ) and cast (anio || '-07-31' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-08-01' as date ) and cast (anio || '-08-31' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-09-01' as date ) and cast (anio || '-09-30' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-10-01' as date ) and cast (anio || '-10-31' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-11-01' as date ) and cast (anio || '-11-30' as date ) and td.tipo ='S'),0)/3600,
coalesce((select sum(td.horas) from tmarcacionesExtras  as td where td.tra_codigo = tra2.tra_codigo and  td.fecha between cast (anio || '-12-01' as date ) and cast (anio || '-12-31' as date ) and td.tipo ='S'),0)/3600
	);
  
 END LOOP;


            
 RETURN QUERY EXECUTE 'SELECT * FROM trespuestas';
END;
$$;


ALTER FUNCTION asistencias.psgcardexold2(anio character) OWNER TO postgres;

--
-- Name: psghorasextras_codigo(date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psghorasextras_codigo(fechax date, codigo integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora4 character varying, mar4 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer, horah character varying, extra time without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora  varchar(20);
 horaextra TIME;
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  mar4 varchar(50),
  hora4 varchar(50),
  horah varchar(50),
  extra TIME,
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20),
  are_codigo INTEGER  
 );
 
 
 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');


FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m inner join asistencias.tbltrabajadores_tra as tra 
on m.tra_codigo = tra.tra_codigo
inner join asistencias.tblareas_are as a on tra.are_codigo = a.are_codigo
inner join asistencias.tblpuestos_pue as p on tra.pue_codigo = p.pue_codigo
inner join  asistencias.tbltrabajadoreshorarios_tho as t
on m.tra_codigo = t.tra_codigo inner join asistencias.tblhorarios_hor as h 
on t.hor_codigo = h.hor_codigo inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
WHERE  tra.tra_codigo = codigo and m.mar_tipo = 'S' and to_char(m.mar_fechahora, 'yyyy-MM-dd') = to_char(fechax, 'yyyy-MM-dd')
and to_char(m.mar_fechahora, 'Day') = d.dhr_day
LOOP
           IF rmarca.dhr_salida <> pg_catalog.time('00:00:00') AND  CAST(to_char(rmarca.mar_fechahora, 'HH24:MI:SS') as TIME) >= rmarca.dhr_salida THEN
                  horaextra = CAST(to_char(rmarca.mar_fechahora, 'HH24:MI:SS') as TIME) - rmarca.dhr_salida;                  
                  
                  tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora4, mar4, tipo, dia, ahora,
                  are_codigo, horah, extra)
                  VALUES (rmarca.tra_codigo, rmarca.tra_nombre, rmarca.tra_apellidopaterno, rmarca. tra_apellidomaterno
                  ,rmarca.tra_dni, rmarca.tra_identificador, rmarca.are_nombre, rmarca.pue_nombre, fechax, to_char(rmarca.mar_fechahora, 'HH24:MI:SS'), '', '', ''
                  , ahora, rmarca.are_codigo, rmarca.dhr_salida, horaextra );
           END IF;
           
        
END LOOP;  

 
 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno,
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora4, mar4, tipo, dia, ahora, are_codigo, horah, extra  FROM caltemp2 order by are_codigo, tra_apellidopaterno, fecha';
 DROP TABLE caltemp2;
END;
$$;


ALTER FUNCTION asistencias.psghorasextras_codigo(fechax date, codigo integer) OWNER TO postgres;

--
-- Name: psgmarcaciones(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgmarcaciones(fechaini date, fechafin date) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, hora1 character varying, mar1 character varying, hora2 character varying, mar2 character varying, tipo character varying, dia character varying, ahora character varying, are_codigo integer, reloj character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
 DECLARE temp2 RECORD;
 
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre VARCHAR(50),
  tra_apellidopaterno VARCHAR(50),
  tra_apellidomaterno VARCHAR(50),
  tra_dni varchar(8),
  tra_identificador VARCHAR(50),
  are_nombre VARCHAR(50),
  pue_nombre VARCHAR(50),
  fecha DATE, 
  mar1 VARCHAR(50) DEFAULT '',
  mar2 VARCHAR(50) DEFAULT '',
  hora1 VARCHAR(50) DEFAULT '' ,
  hora2 VARCHAR(50) DEFAULT '',
  tipo VARCHAR(50),
  dia VARCHAR(20),
  ahora VARCHAR(20), 
  are_codigo INTEGER,
  reloj VARCHAR(20)  
 );
 

 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');
 

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin LOOP
            
       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
               FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
               IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 
               END IF;  
            END LOOP;
      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
      
             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday'  THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
			  IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);
              END IF;    
             END LOOP;
           
               
            
             
            
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m inner join asistencias.tbltrabajadoreshorarios_tho as t on m.tra_codigo = t.tra_codigo inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo inner join asistencias.tblrelojes_rel as rel on m.rel_codigo = rel.rel_codigo LOOP
           
      IF rmarca.mar_tipo = 'I' THEN
           
           FOR temp2 IN Select * from caltemp2 LOOP
               
                IF to_char(temp2.fecha, 'yyyy-MM-dd') = to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') THEN
                       UPDATE caltemp2 SET tipo= 'Marco', mar1 = 'I=' || to_char(rmarca.mar_fechahora, 'HH24:MI') || 'I=' || temp2.hora1 , reloj = rmarca.rel_descripcion WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
                ELSE
                       UPDATE caltemp2 SET tipo= 'Marco', mar1 = 'I=' || to_char(rmarca.mar_fechahora, 'HH24:MI'), hora1 =to_char(rmarca.mar_fechahora, 'HH24:MI'),  reloj = rmarca.rel_descripcion WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ; 
                END IF; 
                
           END LOOP;
             
             
      
      
      END IF;
          
      
      IF rmarca.mar_tipo = 'S' THEN
      
      UPDATE caltemp2 SET tipo= 'Marco', mar2 = 'S=', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI'), reloj = rmarca.rel_descripcion WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
            
      END IF;
      
     
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
    
     
      
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 

 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, 
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, hora1, mar1,  hora2,
                    mar2, tipo, dia, ahora, are_codigo, reloj  FROM caltemp2 order by are_codigo, tra_apellidopaterno, fecha';
END;
$$;


ALTER FUNCTION asistencias.psgmarcaciones(fechaini date, fechafin date) OWNER TO postgres;

--
-- Name: psgmarcacionestemext(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgmarcacionestemext(fechaini date, fechafin date) RETURNS TABLE(cod integer, tipo character, tra_codigo integer, fecha date, ingreso timestamp without time zone, salida timestamp without time zone, horas double precision)
    LANGUAGE plpgsql
    AS $$
DECLARE
 codigosTem Integer;
  r RECORD; 
BEGIN
CREATE TEMPORARY TABLE tmarcacionesExtras (
cod integer,
tipo char(1),
tra_codigo integer,
fecha date,
ingreso timestamp without time zone,
salida timestamp without time zone,
horas double precision
); 
codigosTem := 1;


FOR r IN select * from asistencias.tblmarcaciones_mar as mar where mar.mar_tipo in ('1C','2C',  '1V', '2V' ,'1M','2M','1P','2P' )
		order by mar.tra_codigo , mar.mar_fechahora LOOP
      IF substring(r.mar_tipofrom from  1 for 1)  = '1'  THEN
	values (codigosTem  , substring(r.mar_tipofrom from  2 for 1),  r.tra_codigo , cast(r.mar_fechahora as date) , r.mar_fechahora );
	codigosTem  =codigosTem   +1;
      ELSEIF substring(r.mar_tipofrom from 1 for 1)  = '2' THEN
        update tmarcacionesExtras set salida = r.mar_fechahora , horas = (extract(epoch from age( r.mar_fechahora ,ingreso) ))/3600        
        where cod =codigosTem  ;      
        
      END IF;    
END LOOP;
            
 RETURN QUERY EXECUTE 'SELECT * FROM tmarcacionesExtras';
END;
$$;


ALTER FUNCTION asistencias.psgmarcacionestemext(fechaini date, fechafin date) OWNER TO postgres;

--
-- Name: psgresumen(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgresumen(fechaini date, fechafin date) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, fecha date, ingreso character varying, salida character varying, are_codigo integer, total character varying, tot double precision, suma integer, ahora character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 total INTERVAL;
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
 DECLARE rtotal RECORD;
 DECLARE rr RECORD;
 DECLARE N RECORD;
 cont INTEGER;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(100),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(100),
  pue_nombre varchar(100),
  fecha DATE, 
  ingreso varchar(50) DEFAULT 'NULL',
  ing DOUBLE PRECISION  DEFAULT '0.0',
  sal DOUBLE PRECISION  DEFAULT '0.0',
  salida varchar(50) DEFAULT 'NULL',
  are_codigo INTEGER ,
  dia VARCHAR(20),
  total VARCHAR(500),
  suma INTEGER,
  ahora VARCHAR(500)
 );
 
 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');
 cont := 0;

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo  LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin LOOP
            
       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
               FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                       day := to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                       day:= to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= to_char(rfecha.cal_fecha, 'Day');                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= to_char(rfecha.cal_fecha, 'Day');  
                 END IF;
               IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, are_codigo, dia, ahora) values (r.tra_codigo, r.tra_apellidopaterno ||' '|| r.tra_apellidomaterno ||' '|| r.tra_nombre, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, r.are_codigo, day,  ahora); 
               END IF;  
            END LOOP;
      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
      
             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                       day := to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                       day:= to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= to_char(rfecha.cal_fecha, 'Day');
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= to_char(rfecha.cal_fecha, 'Day');                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= to_char(rfecha.cal_fecha, 'Day');  
                 END IF;  
			  IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, are_codigo, dia, ahora) values (r.tra_codigo, r.tra_apellidopaterno ||' '|| r.tra_apellidomaterno ||' '|| r.tra_nombre, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, r.are_codigo, day,  ahora);
              END IF;    
             END LOOP;
     
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m inner join asistencias.tbltrabajadoreshorarios_tho as t on m.tra_codigo = t.tra_codigo inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP
           
      IF rmarca.mar_tipo  = 'I' THEN       
              IF  pg_catalog.time(rmarca.mar_fechahora) > pg_catalog.time(rmarca.dhr_ingreso) THEN
              UPDATE caltemp2 SET ing= (EXTRACT(EPOCH FROM  pg_catalog.time(rmarca.mar_fechahora) - CAST(now() AS TIME WITHOUT TIME ZONE)) - EXTRACT(EPOCH FROM  pg_catalog.time(rmarca.dhr_ingreso) -  CAST(now() AS TIME WITHOUT TIME ZONE)))/60 ,
              ingreso = ROUND(CAST(EXTRACT(EPOCH FROM  pg_catalog.time(rmarca.mar_fechahora) - CAST(now() AS TIME WITHOUT TIME ZONE)) - EXTRACT(EPOCH FROM  pg_catalog.time(rmarca.dhr_ingreso) -  CAST(now() AS TIME WITHOUT TIME ZONE))AS NUMERIC)/60,0)  || 't' WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
              ELSEIF  pg_catalog.time(rmarca.mar_fechahora) <=  pg_catalog.time(rmarca.dhr_ingreso) THEN
              UPDATE caltemp2 SET ing = 0, ingreso = 'OK' WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
              END IF;
      ELSEIF rmarca.mar_tipo = 'S' THEN
              IF  pg_catalog.time(rmarca.mar_fechahora) >  pg_catalog.time(rmarca.dhr_salida) THEN 
              UPDATE caltemp2 SET sal = 0, salida = 'OK' WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
              ELSEIF  pg_catalog.time(rmarca.mar_fechahora) <=    pg_catalog.time(rmarca.dhr_salida) THEN 
              UPDATE caltemp2 SET sal = 0, salida = 'OK'  WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
              END IF;     
      END IF;
      
END LOOP;  



FOR r IN Select * from  asistencias.tbltrabajadores_tra as t LOOP 
    
     
      
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET ingreso = '', salida = '' WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
END LOOP;

FOR rtotal IN Select * from caltemp2 as c
WHERE c.fecha between fechaini and fechafin LOOP
         
        IF rtotal.ingreso = 'NULL' and rtotal.salida = 'NULL' THEN
           UPDATE caltemp2 SET suma = 0 WHERE caltemp2.tra_codigo = rtotal.tra_codigo and caltemp2.fecha = rtotal.fecha ;
        ELSEIF rtotal.ingreso = 'NULL'AND rtotal.salida <> 'NULL' THEN
           UPDATE caltemp2 SET suma = 1 WHERE caltemp2.tra_codigo = rtotal.tra_codigo and caltemp2.fecha = rtotal.fecha;
        ELSEIF rtotal.ingreso <> 'NULL'AND rtotal.salida = 'NULL' THEN
           UPDATE caltemp2 SET suma = 1 WHERE caltemp2.tra_codigo = rtotal.tra_codigo and caltemp2.fecha = rtotal.fecha;        
        ELSEIF rtotal.ingreso = ''AND rtotal.salida = '' THEN
           UPDATE caltemp2 SET suma = 0 WHERE caltemp2.tra_codigo = rtotal.tra_codigo and caltemp2.fecha = rtotal.fecha;        
        ELSEIF rtotal.ingreso = ''  THEN
           UPDATE caltemp2 SET suma = 0 WHERE caltemp2.tra_codigo = rtotal.tra_codigo and caltemp2.fecha = rtotal.fecha;        
        ELSEIF  rtotal.salida = '' THEN
           UPDATE caltemp2 SET suma = 0 WHERE caltemp2.tra_codigo = rtotal.tra_codigo and caltemp2.fecha = rtotal.fecha;        
        
        ELSE 
           UPDATE caltemp2 SET suma = 2 WHERE caltemp2.tra_codigo = rtotal.tra_codigo and caltemp2.fecha = rtotal.fecha;            
        END IF;
            
END LOOP; 

FOR n IN Select * from caltemp2 as c
WHERE c.fecha between fechaini and fechafin LOOP
         
        
           UPDATE caltemp2 SET ingreso = '', salida = '' WHERE caltemp2.ingreso = 'NULL' and caltemp2.salida = 'NULL';
           UPDATE caltemp2 SET ingreso = ''  WHERE caltemp2.ingreso = 'NULL';
           UPDATE caltemp2 SET salida = ''  WHERE caltemp2.salida = 'NULL';
            
END LOOP;
 
RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre,
                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, ingreso , salida,  are_codigo, total, CAST(ROUND(CAST(ing  as NUMERIC)) as DOUBLE PRECISION) as tot, suma, ahora  FROM caltemp2 order by  tra_nombre, are_codigo, fecha';
END;
$$;


