      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m inner join asistencias.tbltrabajadoreshorarios_tho as t on m.tra_codigo = t.tra_codigo inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo WHERE t.tra_codigo = codigo LOOP
           
      IF rmarca.mar_tipo  = 'I' THEN       
              IF  pg_catalog.time(rmarca.mar_fechahora) > pg_catalog.time(rmarca.dhr_ingreso) THEN
