        IF rtotal.ingreso = 'NULL' and rtotal.salida = 'NULL' THEN
           UPDATE caltemp2 SET suma = 0 WHERE caltemp2.tra_codigo = rtotal.tra_codigo and caltemp2.fecha = rtotal.fecha ;
