    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 total VARCHAR(500);
 tot1 VARCHAR(500);
 tot2 VARCHAR(500);
 hora1 TIME;
 hora2 TIME;
 hora3 TIME;
 hora4 TIME;
 extra TIME;
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
