             END LOOP;
           
               
            
             
            
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m inner join asistencias.tbltrabajadoreshorarios_tho as t
 on m.tra_codigo = t.tra_codigo inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP
     
        
      IF rmarca.mar_tipo  = 'I' THEN
              
              UPDATE caltemp2 SET tipo= 'Marco', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF;
     
      IF rmarca.mar_tipo = 'SR' THEN
      
             UPDATE caltemp2 SET tipo= 'Marco', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS')  WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF; 
      
      IF rmarca.mar_tipo  = 'IR' THEN
      
            UPDATE caltemp2 SET tipo= 'Marco', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date); 
      END IF;       
      
      IF rmarca.mar_tipo = 'S' THEN
               UPDATE caltemp2 SET tipo= 'Marco', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF;
      
      FOR rextra IN select hex.tra_codigo, sum(CAST(hex.hex_extra as INTERVAL)) as extra FROM asistencias.tblhorasextras_hex as hex WHERE hex.tra_codigo = rmarca.tra_codigo group by hex.tra_codigo LOOP
      
      UPDATE caltemp2 set extra =  rextra.extra  WHERE caltemp2.tra_codigo = rextra.tra_codigo;
      
      END LOOP;
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
    
      
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 
FOR suma IN select * from  caltemp2 as c  LOOP

  IF suma.hora4 <> '00:00:00' OR suma.hora2 <> '00:00:00' THEN     
          
          IF suma.hora2 = '00:00:00' and suma.hora3 = '00:00:00' AND suma.hora1 <> '00:00:00' and suma.hora4 <> '00:00:00' THEN
             total =  CAST(suma.hora4 as TIME) - CAST(suma.hora1 as TIME);
          END IF; 
        
          IF suma.hora4 = '00:00:00' and suma.hora3 = '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora1 <> '00:00:00'  THEN
             total = CAST(suma.hora2 as TIME) - CAST(suma.hora1 as TIME);
          END IF; 
          
          IF suma.hora4 <> '00:00:00' and suma.hora3 <> '00:00:00' THEN
              total = CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
          END IF;
          
         
          
          
          IF suma.hora4 <> '00:00:00' and suma.hora3 <> '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora1 <> '00:00:00' THEN
	       tot1 =   CAST(suma.hora3 as TIME) - CAST(suma.hora1 as TIME);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora2 as TIME);
               total =   CAST(tot2 as INTERVAL) + CAST(tot1 as INTERVAL);
               /*          
               tot1 =  pg_catalog.time(suma.hora2) - pg_catalog.time(suma.hora1);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
               total = CAST(tot1 as INTERVAL) + CAST(tot2 as INTERVAL);*/
          END IF;
        
       
       
       pue_nombre, total, ahora, extra)
       VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
        suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra);  
 END IF;         
    
END LOOP;





 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, SUM(CAST(total as interval)), ahora, extra 
                       FROM tareo group by tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, ahora, extra order by tra_apellidopaterno';
END;
$$;


ALTER FUNCTION asistencias.psgtareo_area(fechaini date, fechafin date, cod_area integer) OWNER TO postgres;

--
-- Name: psgtareo_codigo(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgtareo_codigo(fechaini date, fechafin date, codigo integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, total interval, ahora character varying, extra interval)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 total VARCHAR(500);
 tot1 VARCHAR(500);
 tot2 VARCHAR(500);
 hora1 TIME;
 hora2 TIME;
 hora3 TIME;
 hora4 TIME;
 extra TIME;
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
 DECLARE suma RECORD; 
 DECLARE rextra RECORD; 
 DECLARE rtotal RECORD;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  hora1 varchar(50) DEFAULT '00:00:00',
  hora2 varchar(50) DEFAULT '00:00:00',
  hora3 varchar(50) DEFAULT '00:00:00',
  hora4 varchar(50) DEFAULT '00:00:00',
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20), 
  are_codigo INTEGER,  
  total INTERVAL DEFAULT '00:00:00',
  extra INTERVAL
 
 );
 
 CREATE TEMPORARY TABLE tareo(
 
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL 
 );

CREATE TEMPORARY TABLE final(
 
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL 
 );
 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');
 

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin LOOP
            
       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
               FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
                
                     IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                          tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                          r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 
                     END IF;  
               
 				
            END LOOP;
      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
      
             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday'  THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
              
                  IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                        tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                        r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);
                  END IF;
                 
             END LOOP;
           
               
            
             
            
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m inner join asistencias.tbltrabajadoreshorarios_tho as t
 on m.tra_codigo = t.tra_codigo inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP
     
        
      IF rmarca.mar_tipo  = 'I' THEN
              
              UPDATE caltemp2 SET tipo= 'Marco', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF;
     
      IF rmarca.mar_tipo = 'SR' THEN
      
             UPDATE caltemp2 SET tipo= 'Marco', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS')  WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF; 
      
      IF rmarca.mar_tipo  = 'IR' THEN
      
            UPDATE caltemp2 SET tipo= 'Marco', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date); 
      END IF;       
      
      IF rmarca.mar_tipo = 'S' THEN
               UPDATE caltemp2 SET tipo= 'Marco', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF;
      
      FOR rextra IN select hex.tra_codigo, sum(CAST(hex.hex_extra as INTERVAL)) as extra FROM asistencias.tblhorasextras_hex as hex WHERE hex.tra_codigo = rmarca.tra_codigo group by hex.tra_codigo LOOP
      
      UPDATE caltemp2 set extra =  rextra.extra  WHERE caltemp2.tra_codigo = rextra.tra_codigo;
      
      END LOOP;
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
    
      
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 
FOR suma IN select * from  caltemp2 as c  WHERE c.tra_codigo = codigo LOOP

  IF suma.hora4 <> '00:00:00' OR suma.hora2 <> '00:00:00' THEN     
          
          IF suma.hora2 = '00:00:00' and suma.hora3 = '00:00:00' AND suma.hora1 <> '00:00:00' and suma.hora4 <> '00:00:00' THEN
             total =  CAST(suma.hora4 as TIME) - CAST(suma.hora1 as TIME);
          END IF; 
        
          IF suma.hora4 = '00:00:00' and suma.hora3 = '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora1 <> '00:00:00'  THEN
             total = CAST(suma.hora2 as TIME) - CAST(suma.hora1 as TIME);
          END IF; 
          
          IF suma.hora4 <> '00:00:00' and suma.hora3 <> '00:00:00' THEN
              total = CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
          END IF;
          
         
          
          
          IF suma.hora4 <> '00:00:00' and suma.hora3 <> '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora1 <> '00:00:00' THEN
	       tot1 =   CAST(suma.hora3 as TIME) - CAST(suma.hora1 as TIME);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora2 as TIME);
               total =   CAST(tot2 as INTERVAL) + CAST(tot1 as INTERVAL);
               /*          
               tot1 =  pg_catalog.time(suma.hora2) - pg_catalog.time(suma.hora1);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
               total = CAST(tot1 as INTERVAL) + CAST(tot2 as INTERVAL);*/
          END IF;
        
       
       
       pue_nombre, total, ahora, extra)
       VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
        suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra);  
 END IF;         
    
END LOOP;





 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, SUM(CAST(total as interval)), ahora, extra 
                       FROM tareo group by tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, ahora, extra order by tra_apellidopaterno';
END;
$$;


ALTER FUNCTION asistencias.psgtareo_codigo(fechaini date, fechafin date, codigo integer) OWNER TO postgres;

--
-- Name: psgtareo_export(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgtareo_export(fechaini date, fechafin date) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, total interval, ahora character varying, extra interval, totaldias bigint, estado bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 total VARCHAR(500);
 tot1 VARCHAR(500);
 tot2 VARCHAR(500);
 hora1 TIME;
 hora2 TIME;
 hora3 TIME;
 hora4 TIME;
 extra TIME;
 ramdomnumero varchar(10);
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
 DECLARE suma RECORD; 
 DECLARE rextra RECORD; 
 DECLARE rtotal RECORD;
 DECLARE n RECORD;
 DECLARE q RECORD;
 DECLARE l RECORD;
 DECLARE j RECORD;
 DECLARE sumafalse RECORD;
 DECLARE calt RECORD;
 DECLARE mhdi RECORD;
 DECLARE mhdf RECORD;


BEGIN

 CREATE TEMPORARY TABLE caltemp2(

  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  hora1 varchar(50) DEFAULT '00:00:00',
  hora2 varchar(50) DEFAULT '00:00:00',
  hora3 varchar(50) DEFAULT '00:00:00',
  hora4 varchar(50) DEFAULT '00:00:00',
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20), 
  are_codigo INTEGER,  
  total INTERVAL DEFAULT '00:00:00',
  extra INTERVAL,
  islaboro INTEGER
 );

 

 CREATE TEMPORARY TABLE tareo(

  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL,
  totaldias integer,
  estado integer DEFAULT 0


 );



CREATE TEMPORARY TABLE final(

  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL 

 );

 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');


FOR r IN Select * from  asistencias.tbltrabajadores_tra as t 
 inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 
 inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo
 inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
 inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo   LOOP 

      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin and suc_codigo=r.suc_codigo LOOP
          
       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 
       and cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer)
       and  TRIM(upper((r.hro_año))) =TRIM(upper(to_char(CAST(rfecha.cal_fecha as date),'yyyy'))) THEN

              

        FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 

                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                       day := 'Lunes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                       day := 'Martes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                       day:= 'Miercoles';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                       day:= 'Jueves';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                       day:= 'Viernes';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                       day:= 'Sabado';                              

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                       day:= 'Domingo';  

                 END IF;

               IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 

               END IF;  

            END LOOP;

      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 

       and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer)
       and  TRIM(upper((r.hro_año))) =TRIM(upper(to_char(CAST(rfecha.cal_fecha as date),'yyyy'))) THEN

      

             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP

                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN

                       day := 'Lunes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                       day := 'Martes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday'  THEN  

                       day:= 'Miercoles';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                       day:= 'Jueves';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                       day:= 'Viernes';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                       day:= 'Sabado';                              

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                       day:= 'Domingo';  

                 END IF;

        IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);

              END IF;    

             END LOOP;
            

      END IF;
      
      END LOOP;

 END LOOP;
/*************************************************/

/************************************************/






  FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m
 inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP

           

      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora)

       <= pg_catalog.time(rmarca.dhr_ingreso) THEN

              

       IF pg_catalog.time(rmarca.mar_fechahora)<= pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 
              SET tipo= 'Marco',                  
                hora1 = pg_catalog.time(rmarca.dhr_ingreso)- CAST(ramdomnumero || ' min' AS interval) 
              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 
              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  
              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
         

     ELSEIF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN
          
            UPDATE caltemp2 
              SET tipo= 'Marco',            
                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 
              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 
              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  
              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
            
        END IF;

      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) 
      and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 
            
        IF pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) + interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 
              SET tipo= 'Marco',                 
                hora1 = pg_catalog.time(rmarca.dhr_ingreso)+ CAST(ramdomnumero || ' min' AS interval) 
              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 
              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  
              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;          

     ELSEIF pg_catalog.time(rmarca.mar_fechahora)  < pg_catalog.time(rmarca.dhr_ingreso)+ interval '5min' THEN        

            UPDATE caltemp2 
              SET tipo= 'Marco',              
                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 
              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 
              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  
              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              
        END IF;  


      END IF;

      

     /*cambios todo SR po IR y al reves */

      

     
      /*******/

IF rmarca.mar_tipo = 'S' THEN

          IF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_salida)+ interval '5min' THEN

                  ramdomnumero= floor((random()*6));


                UPDATE caltemp2 SET tipo = 'Marco',
                hora4 = pg_catalog.time(rmarca.dhr_salida) + CAST(ramdomnumero || ' min' AS interval) 
                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                                    

           ELSEIF pg_catalog.time(rmarca.mar_fechahora)<= pg_catalog.time(rmarca.dhr_salida)+ interval '5min' THEN     

                  ramdomnumero= floor((random()*6));

              UPDATE caltemp2 
                   SET tipo = 'Marco',                       
                      hora4 = pg_catalog.time(rmarca.dhr_salida)  - CAST(ramdomnumero || ' min' AS interval) 
                       WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

            END IF;           

      END IF;      

END LOOP;   

FOR calt IN 
select * from caltemp2
loop

    FOR mhdi IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS')as timei ,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') asc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', hora2 = mhdi.timei 
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;
               

               end loop;

      FOR mhdf IN Select  to_char(m.mar_fechahora, 'HH24:MI:SS') as timef,*  from asistencias.tblmarcaciones_mar as m
               inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
               inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
               where m.tra_codigo=calt.tra_codigo
               and cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE)= CAST (calt.fecha AS date)
               and TRIM(d.dhr_day) = TRIM(to_char(cast(to_char(m.mar_fechahora,'yyyy-MM-dd')as DATE), 'Day'))
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME)>= d.dhr_salidarefrigerio
               and cast(to_char(m.mar_fechahora, 'HH24:MI:SS')as TIME) <= d.dhr_ingresorefrigerio
               order by to_char(m.mar_fechahora, 'HH24:MI:SS') desc               
               limit 1
               loop

               UPDATE caltemp2 
               SET tipo= 'Marco', hora3 = mhdf.timef
               WHERE caltemp2.tra_codigo = calt.tra_codigo 
               and caltemp2.fecha = calt.fecha;

               end loop;    

end loop;





FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
              
      FOR rvacaciones IN 
       Select * from asistencias.tblpermisos_per as p
       inner join asistencias.tbltipopermisos_tip as tp on p.tip_codigo = tp.tip_codigo
       inner join asistencias.tbltrabajadores_tra as t on t.tra_codigo=p.tra_codigo
       inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
       inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo 
       where t.tra_codigo=r.tra_codigo
       and  cast( (SELECT extract(week from CAST(p.per_fechafin as date))) as integer)=CAST(g.hro_semana AS integer)
         or cast( (SELECT extract(week from CAST(p.per_fechaini as date))) as integer)=CAST(g.hro_semana AS integer)
 
       LOOP 
                    
          IF rvacaciones.tip_escalat =TRUE THEN    

                UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre,hora1='00:00:00',hora2='00:00:00',hora3='00:00:00',hora4='00:00:00' 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;

          ELSEIF rvacaciones.tip_escalat =FALSE THEN  
      
          FOR q IN select * from asistencias.tbldethorarios_dhr d where d.hor_codigo=rvacaciones.hor_codigo
          LOOP 
            UPDATE caltemp2 SET tipo ='Perm.Horas',hora1=q.dhr_ingreso,hora2=q.dhr_salidarefrigerio,hora3=q.dhr_ingresorefrigerio,hora4=q.dhr_salida 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo
                and upper(TRIM(to_char(pg_catalog.date(caltemp2.fecha),'day')))=upper(TRIM(q.dhr_day)) 
                and caltemp2.fecha > pg_catalog.date(rvacaciones.per_fechaini) 
                and caltemp2.fecha < pg_catalog.date(rvacaciones.per_fechafin);
          END LOOP;
          
          FOR l IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo and
                    upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechaini),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 

                    if pg_catalog.time(rvacaciones.per_fechaini) < l.dhr_ingreso THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',
                     hora1=l.dhr_ingreso,
                     hora2=l.dhr_salidarefrigerio,
                     hora3=l.dhr_ingresorefrigerio,
                     hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if; 
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingreso THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora2=l.dhr_salidarefrigerio,                     
                     hora3=l.dhr_ingresorefrigerio,                     
                     hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora3=l.dhr_ingresorefrigerio,                     
                     hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',
                     hora4=l.dhr_salida  
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    
                   end LOOP;

                          
                    FOR j IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo 
                    and upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechafin),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 
                    
                     if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingreso THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora1=j.dhr_ingreso
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora1=j.dhr_ingreso,                     
                     hora2=j.dhr_salidarefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                    
                     hora1=j.dhr_ingreso,                     
                     hora2=j.dhr_salidarefrigerio,                     
                     hora3=j.dhr_ingresorefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salida THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora1=j.dhr_ingreso,                     
                     hora2=j.dhr_salidarefrigerio,                     
                     hora3=j.dhr_ingresorefrigerio,                     
                     hora4=j.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
 
                  
                   end LOOP;                
                                                       
          END IF;   
      
      END LOOP;
 
 END LOOP;


FOR n in select m.tra_codigo,to_char(m.mar_fechahora,'dd-MM-yyyy') as fechan,count(m.*) 
from asistencias.tblmarcaciones_mar m
inner join asistencias.tbltrabajadores_tra t on t.tra_codigo=m.tra_codigo
where t.tra_fiscalizacion=true
 group by m.tra_codigo,to_char(m.mar_fechahora,'dd-MM-yyyy')
 order by m.tra_codigo,to_char(m.mar_fechahora,'dd-MM-yyyy') LOOP

  UPDATE caltemp2 SET islaboro =1  WHERE caltemp2.tra_codigo = n.tra_codigo 
      and  to_char(caltemp2.fecha,'dd-MM-yyyy') = n.fechan
            and ( caltemp2.hora1 <> ''
            or  caltemp2.hora2 <> ''
            or  caltemp2.hora3 <> ''
            or  caltemp2.hora4 <> '') ;

 END LOOP;

 
FOR sumafalse IN select * from  caltemp2 as c inner join asistencias.tbltrabajadores_tra t 
on  c.tra_codigo=t.tra_codigo where  t.tra_fiscalizacion=false LOOP

              pue_nombre, total, ahora, extra,totaldias,estado)
           VALUES (sumafalse.tra_codigo, sumafalse.tra_nombre, sumafalse.tra_apellidopaterno, sumafalse.tra_apellidomaterno, sumafalse.tra_dni, sumafalse.tra_identificador,
              sumafalse.are_nombre, sumafalse.pue_nombre,'08:00:00', ahora, sumafalse.extra,1,0);  
END LOOP;

FOR suma IN select * from  caltemp2 as c inner join asistencias.tbltrabajadores_tra t 
on  c.tra_codigo=t.tra_codigo where  t.tra_fiscalizacion=true LOOP
  
          IF suma.hora1 = '00:00:00' and suma.hora2 = '00:00:00' AND suma.hora3 = '00:00:00' and suma.hora4 <> '00:00:00' THEN /*0001*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             
          END IF; 

          IF suma.hora1 = '00:00:00' and suma.hora2 = '00:00:00' AND suma.hora3 <> '00:00:00' and suma.hora4 = '00:00:00' THEN /*0010*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF; 
          IF suma.hora1 = '00:00:00' and suma.hora2 <> '00:00:00' AND suma.hora3 = '00:00:00' and suma.hora4 = '00:00:00' THEN /*0100*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF; 
          IF suma.hora1 = '00:00:00' and suma.hora2 <> '00:00:00' AND suma.hora3 = '00:00:00' and suma.hora4 <> '00:00:00' THEN /*0101*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF; 
          IF suma.hora1 = '00:00:00' and suma.hora2 <> '00:00:00' AND suma.hora3 <> '00:00:00' and suma.hora4 = '00:00:00' THEN/*0110*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF; 
          IF suma.hora1 = '00:00:00' and suma.hora2 <> '00:00:00' AND suma.hora3 <> '00:00:00' and suma.hora4 <> '00:00:00' THEN/*0111*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF; 
          IF suma.hora1 <> '00:00:00' and suma.hora2 = '00:00:00' AND suma.hora3 = '00:00:00' and suma.hora4 = '00:00:00' THEN/*1000*/

              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  

          END IF; 
          IF suma.hora1 <> '00:00:00' and suma.hora2 = '00:00:00' AND suma.hora3 = '00:00:00' and suma.hora4 <> '00:00:00' THEN/*1001*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF;
          IF suma.hora1 <> '00:00:00' and suma.hora2 = '00:00:00' AND suma.hora3 <> '00:00:00' and suma.hora4 = '00:00:00' THEN/*1010*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF;
          IF suma.hora1 <> '00:00:00' and suma.hora2 = '00:00:00' AND suma.hora3 <> '00:00:00' and suma.hora4 <> '00:00:00' THEN/*1011*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF;
          IF suma.hora1 <> '00:00:00' and suma.hora2 <> '00:00:00' AND suma.hora3 = '00:00:00' and suma.hora4 <> '00:00:00' THEN/*1101*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF;
          IF suma.hora1 <> '00:00:00' and suma.hora2 <> '00:00:00' AND suma.hora3 <> '00:00:00' and suma.hora4 = '00:00:00' THEN/*1110*/
              pue_nombre, total, ahora, extra,totaldias,estado)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre,0, ahora, suma.extra,suma.islaboro,1);  
             

          END IF;        
 

        
     IF suma.hora1 <> '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora3 = '00:00:00' and suma.hora4 = '00:00:00' THEN

             total = CAST(suma.hora2 as TIME) - CAST(suma.hora1 as TIME);

                 pue_nombre, total, ahora, extra,totaldias)
                 VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
                  suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra,suma.islaboro);
          
     END IF; 
          
          IF suma.hora1 = '00:00:00' and suma.hora2 = '00:00:00' and suma.hora3 <> '00:00:00' and suma.hora4 <> '00:00:00'  THEN

             total = CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);

             pue_nombre, total, ahora, extra,totaldias)
             VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra,suma.islaboro);         
     END IF;

    IF suma.hora1 <> '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora3 <> '00:00:00' and suma.hora4 <> '00:00:00' THEN
	       tot1 =   CAST(suma.hora3 as TIME) - CAST(suma.hora1 as TIME);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora2 as TIME);
               total =   CAST(tot2 as INTERVAL) + CAST(tot1 as INTERVAL);
/*
               tot1 =  pg_catalog.time(suma.hora2) - pg_catalog.time(suma.hora1);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
               total = CAST(tot1 as INTERVAL) + CAST(tot2 as INTERVAL);*/
              pue_nombre, total, ahora, extra,totaldias)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra,suma.islaboro);  
          
    END IF;


END LOOP;



 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, SUM(CAST(total as interval)), ahora, extra,sum(totaldias),sum(estado) 
                       FROM tareo group by tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, ahora, extra order by tra_apellidopaterno';

END;
$$;


ALTER FUNCTION asistencias.psgtareo_export(fechaini date, fechafin date) OWNER TO postgres;

--
-- Name: psgtareo_export_new(date, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgtareo_export_new(fechaini date, fechafin date) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, total interval, ahora character varying, extra interval, totaldias bigint, estado bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 total VARCHAR(500);
 tot1 VARCHAR(500);
 tot2 VARCHAR(500);
 hora1 TIME;
 hora2 TIME;
 hora3 TIME;
 hora4 TIME;
 extra TIME;
 ramdomnumero varchar(10);
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
 DECLARE suma RECORD; 
 DECLARE rextra RECORD; 
 DECLARE rtotal RECORD;
 DECLARE n RECORD;
 DECLARE q RECORD;
 DECLARE l RECORD;
 DECLARE j RECORD;

BEGIN

 CREATE TEMPORARY TABLE caltemp2(

  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  hora1 varchar(50) DEFAULT '00:00:00',
  hora2 varchar(50) DEFAULT '00:00:00',
  hora3 varchar(50) DEFAULT '00:00:00',
  hora4 varchar(50) DEFAULT '00:00:00',
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20), 
  are_codigo INTEGER,  
  total INTERVAL DEFAULT '00:00:00',
  extra INTERVAL,
  islaboro INTEGER
 );

 

 CREATE TEMPORARY TABLE tareo(

  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL,
  totaldias integer,
  estado integer DEFAULT 0


 );



CREATE TEMPORARY TABLE final(

  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL 

 );

 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');


FOR r IN Select * from  asistencias.tbltrabajadores_tra as t 
 inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 
 inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo
 inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
 inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo where tra_fiscalizacion=true LOOP 

      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin and suc_codigo=r.suc_codigo LOOP
          
       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 
       and cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer)
       and  TRIM(upper((r.hro_año))) =TRIM(upper(to_char(CAST(rfecha.cal_fecha as date),'yyyy'))) THEN

              

        FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 

                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN

                       day := 'Lunes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                       day := 'Martes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  

                       day:= 'Miercoles';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                       day:= 'Jueves';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                       day:= 'Viernes';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                       day:= 'Sabado';                              

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                       day:= 'Domingo';  

                 END IF;

               IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 

               END IF;  

            END LOOP;

      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin 

       and  cast( (SELECT extract(week from CAST(rfecha.cal_fecha as date))) as integer)=CAST(r.hro_semana AS integer)
       and  TRIM(upper((r.hro_año))) =TRIM(upper(to_char(CAST(rfecha.cal_fecha as date),'yyyy'))) THEN

      

             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP

                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN

                       day := 'Lunes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN

                       day := 'Martes';

                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday'  THEN  

                       day:= 'Miercoles';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN

                       day:= 'Jueves';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN

                       day:= 'Viernes';

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN

                       day:= 'Sabado';                              

                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN

                       day:= 'Domingo';  

                 END IF;

        IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN

                    tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                    r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);

              END IF;    

             END LOOP;
            

      END IF;
      
      END LOOP;

 END LOOP;



  FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m
 inner join asistencias.tblhorarios_hor as h on h.hor_codigo = m.hor_codigo
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP

           

      IF rmarca.mar_tipo  = 'I' and  pg_catalog.time(rmarca.mar_fechahora)

       <= pg_catalog.time(rmarca.dhr_ingreso) THEN

              

       IF pg_catalog.time(rmarca.mar_fechahora)<= pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 
              SET tipo= 'Marco',                  
                hora1 = pg_catalog.time(rmarca.dhr_ingreso)- CAST(ramdomnumero || ' min' AS interval) 
              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 
              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  
              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
         

     ELSEIF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_ingreso)- interval '5min' THEN
          
            UPDATE caltemp2 
              SET tipo= 'Marco',            
                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 
              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 
              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  
              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
            
        END IF;

      ELSEIF rmarca.mar_tipo = 'I' and  pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) 
      and pg_catalog.time(rmarca.mar_fechahora - rmarca.dhr_ingreso) <= pg_catalog.time(interval '1439min') THEN 
            
        IF pg_catalog.time(rmarca.mar_fechahora) >= pg_catalog.time(rmarca.dhr_ingreso) + interval '5min' THEN

         ramdomnumero= floor((random()*6));

         UPDATE caltemp2 
              SET tipo= 'Marco',                 
                hora1 = pg_catalog.time(rmarca.dhr_ingreso)+ CAST(ramdomnumero || ' min' AS interval) 
              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 
              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  
              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;          

     ELSEIF pg_catalog.time(rmarca.mar_fechahora)  < pg_catalog.time(rmarca.dhr_ingreso)+ interval '5min' THEN        

            UPDATE caltemp2 
              SET tipo= 'Marco',              
                hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') 
              WHERE caltemp2.tra_codigo = rmarca.tra_codigo 
              and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date)  
              and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

              
        END IF;  


      END IF;

      

     /*cambios todo SR po IR y al reves */

      

      IF rmarca.mar_tipo = 'IR' THEN

             UPDATE caltemp2 SET tipo= 'Marco', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
      
      END IF;

      /****/

      IF rmarca.mar_tipo = 'SR' and to_char(rmarca.mar_fechahora,'hh:MI') > to_char((rmarca.dhr_ingresorefrigerio + rmarca.dhr_tolingresorefrigerio * (interval '1 minute')), 'hh:MI') THEN

               UPDATE caltemp2 SET tipo= 'Marco', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;
 

     ELSEIF rmarca.mar_tipo = 'SR' THEN

     
     UPDATE caltemp2 SET tipo= 'Marco', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

      END IF; 

      /*******/

IF rmarca.mar_tipo = 'S' THEN

          IF pg_catalog.time(rmarca.mar_fechahora)  > pg_catalog.time(rmarca.dhr_salida)+ interval '5min' THEN

                  ramdomnumero= floor((random()*6));


                UPDATE caltemp2 SET tipo = 'Marco',
                hora4 = pg_catalog.time(rmarca.dhr_salida) + CAST(ramdomnumero || ' min' AS interval) 
                WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;                                    

           ELSEIF pg_catalog.time(rmarca.mar_fechahora)<= pg_catalog.time(rmarca.dhr_salida)+ interval '5min' THEN     

                  ramdomnumero= floor((random()*6));

              UPDATE caltemp2 
                   SET tipo = 'Marco',                       
                      hora4 = pg_catalog.time(rmarca.dhr_salida)  - CAST(ramdomnumero || ' min' AS interval) 
                       WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date) and rmarca.dhr_day = to_char(rmarca.mar_fechahora, 'Day') ;

            END IF;           

      END IF;      

END LOOP;   



FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
              
      FOR rvacaciones IN 
       Select * from asistencias.tblpermisos_per as p
       inner join asistencias.tbltipopermisos_tip as tp on p.tip_codigo = tp.tip_codigo
       inner join asistencias.tbltrabajadores_tra as t on t.tra_codigo=p.tra_codigo
       inner join asistencias.tblhorariosrotativos_hro g on t.gma_codigo=g.gma_codigo  
       inner join asistencias.tblhorarios_hor as h on g.hor_codigo = h.hor_codigo 
       where t.tra_codigo=r.tra_codigo
       and  cast( (SELECT extract(week from CAST(p.per_fechafin as date))) as integer)=CAST(g.hro_semana AS integer)
         or cast( (SELECT extract(week from CAST(p.per_fechaini as date))) as integer)=CAST(g.hro_semana AS integer)
 
       LOOP 
                    
          IF rvacaciones.tip_escalat =TRUE THEN    

                UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre,hora1='00:00:00',hora2='00:00:00',hora3='00:00:00',hora4='00:00:00' 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;

          ELSEIF rvacaciones.tip_escalat =FALSE THEN  
      
          FOR q IN select * from asistencias.tbldethorarios_dhr d where d.hor_codigo=rvacaciones.hor_codigo
          LOOP 
            UPDATE caltemp2 SET tipo ='Perm.Horas',hora1=q.dhr_ingreso,hora2=q.dhr_salidarefrigerio,hora3=q.dhr_ingresorefrigerio,hora4=q.dhr_salida 
                WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo
                and upper(TRIM(to_char(pg_catalog.date(caltemp2.fecha),'day')))=upper(TRIM(q.dhr_day)) 
                and caltemp2.fecha > pg_catalog.date(rvacaciones.per_fechaini) 
                and caltemp2.fecha < pg_catalog.date(rvacaciones.per_fechafin);
          END LOOP;
          
          FOR l IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo and
                    upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechaini),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 

                    if pg_catalog.time(rvacaciones.per_fechaini) < l.dhr_ingreso THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',
                     hora1=l.dhr_ingreso,
                     hora2=l.dhr_salidarefrigerio,
                     hora3=l.dhr_ingresorefrigerio,
                     hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if; 
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingreso THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora2=l.dhr_salidarefrigerio,                     
                     hora3=l.dhr_ingresorefrigerio,                     
                     hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora3=l.dhr_ingresorefrigerio,                     
                     hora4=l.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechaini) > l.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',
                     hora4=l.dhr_salida  
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechaini);
                    end if;
                    
                   end LOOP;

                          
                    FOR j IN select * from asistencias.tblhorarios_hor as h inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo
                    where h.hor_codigo=rvacaciones.hor_codigo 
                    and upper(TRIM(to_char(pg_catalog.date(rvacaciones.per_fechafin),'day')))=upper(TRIM(d.dhr_day))
                    LOOP 
                    
                     if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingreso THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora1=j.dhr_ingreso
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salidarefrigerio THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora1=j.dhr_ingreso,                     
                     hora2=j.dhr_salidarefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_ingresorefrigerio THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                    
                     hora1=j.dhr_ingreso,                     
                     hora2=j.dhr_salidarefrigerio,                     
                     hora3=j.dhr_ingresorefrigerio
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
                    if pg_catalog.time(rvacaciones.per_fechafin) > j.dhr_salida THEN
                     UPDATE caltemp2 SET 
                     tipo ='Perm.Horas',                     
                     hora1=j.dhr_ingreso,                     
                     hora2=j.dhr_salidarefrigerio,                     
                     hora3=j.dhr_ingresorefrigerio,                     
                     hora4=j.dhr_salida 
                     WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha=pg_catalog.date(rvacaciones.per_fechafin);
                    end if;
 
                  
                   end LOOP;                
                                                       
          END IF;   
      
      END LOOP;
 
 END LOOP;


