                 pue_nombre, total, ahora, extra,totaldias)
                 VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
                  suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra,suma.islaboro);
          
     END IF; 
          
          IF suma.hora1 = '00:00:00' and suma.hora2 = '00:00:00' and suma.hora3 <> '00:00:00' and suma.hora4 <> '00:00:00'  THEN

             total = CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);

             pue_nombre, total, ahora, extra,totaldias)
             VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra,suma.islaboro);         
     END IF;

    IF suma.hora1 <> '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora3 <> '00:00:00' and suma.hora4 <> '00:00:00' THEN
    
	       tot1 =   CAST(suma.hora3 as TIME) - CAST(suma.hora1 as TIME);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora2 as TIME);
               total =   CAST(tot2 as INTERVAL) + CAST(tot1 as INTERVAL);
               /*
               tot1 =  pg_catalog.time(suma.hora2) - pg_catalog.time(suma.hora1);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
               total = CAST(tot1 as INTERVAL) + CAST(tot2 as INTERVAL);*/

              pue_nombre, total, ahora, extra,totaldias)
              VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
              suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra,suma.islaboro);  
          
    END IF;


END LOOP;



 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, SUM(CAST(total as interval)), ahora, extra,sum(totaldias),sum(estado) 
                       FROM tareo group by tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, ahora, extra order by tra_apellidopaterno';

END;
$$;


ALTER FUNCTION asistencias.psgtareo_export_new(fechaini date, fechafin date) OWNER TO postgres;

--
-- Name: psgtareo_horario(date, date, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgtareo_horario(fechaini date, fechafin date, cod_horario integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, total interval, ahora character varying, extra interval)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 total VARCHAR(500);
 tot1 VARCHAR(500);
 tot2 VARCHAR(500);
 hora1 TIME;
 hora2 TIME;
 hora3 TIME;
 hora4 TIME;
 extra TIME;
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
 DECLARE suma RECORD; 
 DECLARE rextra RECORD; 
 DECLARE rtotal RECORD;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE, 
  hora1 varchar(50) DEFAULT '00:00:00',
  hora2 varchar(50) DEFAULT '00:00:00',
  hora3 varchar(50) DEFAULT '00:00:00',
  hora4 varchar(50) DEFAULT '00:00:00',
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20), 
  are_codigo INTEGER,  
  total INTERVAL DEFAULT '00:00:00',
  extra INTERVAL
 
 );
 
 CREATE TEMPORARY TABLE tareo(
 
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL 
 );

CREATE TEMPORARY TABLE final(
 
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(50),
  pue_nombre varchar(50),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL 
 );
 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');
 

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo WHERE h.hor_codigo = cod_horario LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin LOOP
            
       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
               FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
                
                     IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                          tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                          r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 
                     END IF;  
               
 				
            END LOOP;
      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
      
             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday'  THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
              
                  IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                        tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                        r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);
                  END IF;
                 
             END LOOP;
           
               
            
             
            
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m inner join asistencias.tbltrabajadoreshorarios_tho as t
 on m.tra_codigo = t.tra_codigo inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo LOOP
     
        
      IF rmarca.mar_tipo  = 'I' THEN
              
              UPDATE caltemp2 SET tipo= 'Marco', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF;
     
      IF rmarca.mar_tipo = 'SR' THEN
      
             UPDATE caltemp2 SET tipo= 'Marco', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS')  WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF; 
      
      IF rmarca.mar_tipo  = 'IR' THEN
      
            UPDATE caltemp2 SET tipo= 'Marco', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date); 
      END IF;       
      
      IF rmarca.mar_tipo = 'S' THEN
               UPDATE caltemp2 SET tipo= 'Marco', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF;
      
      FOR rextra IN select hex.tra_codigo, sum(CAST(hex.hex_extra as INTERVAL)) as extra FROM asistencias.tblhorasextras_hex as hex WHERE hex.tra_codigo = rmarca.tra_codigo group by hex.tra_codigo LOOP
      
      UPDATE caltemp2 set extra =  rextra.extra  WHERE caltemp2.tra_codigo = rextra.tra_codigo;
      
      END LOOP;
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra LOOP 
    
      
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 
FOR suma IN select * from  caltemp2 as c  LOOP

  IF suma.hora4 <> '00:00:00' OR suma.hora2 <> '00:00:00' THEN     
          
          IF suma.hora2 = '00:00:00' and suma.hora3 = '00:00:00' AND suma.hora1 <> '00:00:00' and suma.hora4 <> '00:00:00' THEN
             total =  CAST(suma.hora4 as TIME) - CAST(suma.hora1 as TIME);
          END IF; 
        
          IF suma.hora4 = '00:00:00' and suma.hora3 = '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora1 <> '00:00:00'  THEN
             total = CAST(suma.hora2 as TIME) - CAST(suma.hora1 as TIME);
          END IF; 
          
          IF suma.hora4 <> '00:00:00' and suma.hora3 <> '00:00:00' THEN
              total = CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
          END IF;
          
         
          
          
          IF suma.hora4 <> '00:00:00' and suma.hora3 <> '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora1 <> '00:00:00' THEN

	       tot1 =   CAST(suma.hora3 as TIME) - CAST(suma.hora1 as TIME);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora2 as TIME);
               total =   CAST(tot2 as INTERVAL) + CAST(tot1 as INTERVAL);
               /*          
               tot1 =  pg_catalog.time(suma.hora2) - pg_catalog.time(suma.hora1);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
               total = CAST(tot1 as INTERVAL) + CAST(tot2 as INTERVAL);*/
          END IF;
        
       
       
       pue_nombre, total, ahora, extra)
       VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
        suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra);  
 END IF;         
    
END LOOP;





 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, SUM(CAST(total as interval)), ahora, extra 
                       FROM tareo group by tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, ahora, extra order by tra_apellidopaterno';
END;
$$;


ALTER FUNCTION asistencias.psgtareo_horario(fechaini date, fechafin date, cod_horario integer) OWNER TO postgres;

--
-- Name: psgtareoall(date, date, character varying, integer, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgtareoall(fechaini date, fechafin date, identificador character varying, arecodigo integer, horcodigo integer) RETURNS TABLE(tra_codigo integer, tra_nombre character varying, tra_apellidopaterno character varying, tra_apellidomaterno character varying, tra_dni character varying, tra_identificador character varying, are_nombre character varying, pue_nombre character varying, total interval, ahora character varying, extra interval)
    LANGUAGE plpgsql
    AS $$
DECLARE
 result varchar(10);
 codigoTrabajador Integer;
 martipo varchar(10);
 flag varchar(100);
 day varchar(20);
 ahora varchar(20);
 total VARCHAR(500);
 tot1 VARCHAR(500);
 tot2 VARCHAR(500);
 hora1 TIME;
 hora2 TIME;
 hora3 TIME;
 hora4 TIME;
 extra TIME;
 DECLARE r RECORD;
 DECLARE rfecha RECORD;
 DECLARE rmarca RECORD;
 DECLARE rvacaciones RECORD;
 DECLARE det RECORD;
 DECLARE suma RECORD; 
 DECLARE rextra RECORD; 
 DECLARE rtotal RECORD;
 DECLARE tracodigo integer;
BEGIN
 CREATE TEMPORARY TABLE caltemp2(
  
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(100),
  pue_nombre varchar(100),
  fecha DATE, 
  hora1 varchar(50) DEFAULT '00:00:00',
  hora2 varchar(50) DEFAULT '00:00:00',
  hora3 varchar(50) DEFAULT '00:00:00',
  hora4 varchar(50) DEFAULT '00:00:00',
  tipo varchar(50),
  dia VARCHAR(20),
  ahora varchar(20), 
  are_codigo INTEGER,  
  total INTERVAL DEFAULT '00:00:00',
  extra INTERVAL
 
 );
 
 CREATE TEMPORARY TABLE tareo(
 
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(100),
  pue_nombre varchar(100),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL 
 );

CREATE TEMPORARY TABLE final(
 
  tra_codigo INTEGER,
  tra_nombre varchar(50),
  tra_apellidopaterno varchar(50),
  tra_apellidomaterno varchar(50),
  tra_dni varchar(8),
  tra_identificador varchar(50),
  are_nombre varchar(100),
  pue_nombre varchar(100),
  fecha DATE,
  total VARCHAR(500) DEFAULT '00:00:00',
  test TIME DEFAULT '00:00:00',
  ahora varchar(20),
  extra INTERVAL 
 );
 ahora := to_char(now(), 'dd/MM/yyyy HH24:MI:SS');

 tracodigo = 0;
 IF identificador <> ''  then 
      tracodigo = (select tr.tra_codigo from asistencias.tbltrabajadores_tra as tr where TRIM(tr.tra_identificador) = TRIM(identificador));
 end IF ;
 

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 
          inner join asistencias.tblpuestos_pue as p on t.pue_codigo = p.pue_codigo inner join asistencias.tbltrabajadoreshorarios_tho as th on t.tra_codigo = th.tra_codigo 
          inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo  where (case when tracodigo = 0 then true else  t.tra_codigo = tracodigo end) and
                                                                                              (case when arecodigo = 0  then  true else t.are_codigo = arecodigo end )and 
                                                                                              ( case when horcodigo = 0 then true else h.hor_codigo = horcodigo end  )    LOOP 
      FOR  rfecha IN Select * from asistencias.tblcalendario_cal WHERE cal_fecha BETWEEN fechaini and fechafin  LOOP
            
       IF rfecha.cal_tipo = 'F' and rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
               FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP 
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday' THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
                
                     IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                          tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                          r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'Feriado', day, ahora, r.are_codigo); 
                     END IF;  
               
        
            END LOOP;
      ELSEIF rfecha.cal_fecha >= r.hor_fechainicio and rfecha.cal_fecha <= r.hor_fechafin THEN
      
             FOR det IN Select * from asistencias.tbldethorarios_dhr where   hor_codigo = r.hor_codigo LOOP
                 IF to_char(rfecha.cal_fecha, 'Day') = 'Monday   ' and  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                       day := 'Lunes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Tuesday  ' THEN
                       day := 'Martes';
                 ELSEIF  to_char(rfecha.cal_fecha, 'Day') = 'Wednesday'  THEN  
                       day:= 'Miercoles';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Thursday ' THEN
                       day:= 'Jueves';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Friday   ' THEN
                       day:= 'Viernes';
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Saturday ' THEN
                       day:= 'Sabado';                              
                 ELSEIF   to_char(rfecha.cal_fecha, 'Day') = 'Sunday   ' THEN
                       day:= 'Domingo';  
                 END IF;
              
                  IF  det.dhr_day = to_char(rfecha.cal_fecha, 'Day') THEN
                        tra_dni, tra_identificador, are_nombre, pue_nombre, fecha, tipo, dia, ahora, are_codigo) values (r.tra_codigo, r.tra_nombre, r.tra_apellidopaterno,
                        r.tra_apellidomaterno, r.tra_dni, r.tra_identificador, r.are_nombre, r.pue_nombre,  rfecha.cal_fecha, 'No Marco', day, ahora, r.are_codigo);
                  END IF;
                 
             END LOOP;
           
               
            
             
            
      END IF;
                       
      END LOOP;
      
      
 END LOOP;

 FOR rmarca IN Select * from asistencias.tblmarcaciones_mar as m inner join asistencias.tbltrabajadoreshorarios_tho as t
 on m.tra_codigo = t.tra_codigo inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo 
 inner join asistencias.tbltrabajadores_tra as tr on tr.tra_codigo = m.tra_codigo inner join asistencias.tblareas_are as a on tr.are_codigo = a.are_codigo 
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo  where (case when tracodigo = 0 then true else  t.tra_codigo = tracodigo end) and
                                                                                              (case when arecodigo = 0  then  true else a.are_codigo = arecodigo end )and 
                                                                                              ( case when horcodigo = 0 then true else h.hor_codigo = horcodigo end  )    LOOP 
     
        
      IF rmarca.mar_tipo  = 'I' THEN
              
              UPDATE caltemp2 SET tipo= 'Marco', hora1 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF;
     
      IF rmarca.mar_tipo = 'SR' THEN
      
             UPDATE caltemp2 SET tipo= 'Marco', hora2 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS')  WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF; 
      
      IF rmarca.mar_tipo  = 'IR' THEN
      
            UPDATE caltemp2 SET tipo= 'Marco', hora3 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date); 
      END IF;       
      
      IF rmarca.mar_tipo = 'S' THEN
               UPDATE caltemp2 SET tipo= 'Marco', hora4 = to_char(rmarca.mar_fechahora, 'HH24:MI:SS') WHERE caltemp2.tra_codigo = rmarca.tra_codigo and caltemp2.fecha = CAST(to_char(rmarca.mar_fechahora, 'yyyy-MM-dd') as date);
             
      END IF;
      
      FOR rextra IN select hex.tra_codigo, sum(CAST(hex.hex_extra as INTERVAL)) as extra FROM asistencias.tblhorasextras_hex as hex WHERE hex.tra_codigo = rmarca.tra_codigo group by hex.tra_codigo LOOP
      
      UPDATE caltemp2 set extra =  rextra.extra  WHERE caltemp2.tra_codigo = rextra.tra_codigo;
      
      END LOOP;
END LOOP;  

 FOR r IN Select * from  asistencias.tbltrabajadores_tra as t inner join asistencias.tbltrabajadoreshorarios_tho as th
 on t.tra_codigo = th.tra_codigo inner join asistencias.tblhorarios_hor as h on th.hor_codigo = h.hor_codigo 
 inner join asistencias.tblareas_are as a on t.are_codigo = a.are_codigo 
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo  where (case when tracodigo = 0 then true else  t.tra_codigo = tracodigo end) and
                                                                                              (case when arecodigo = 0  then  true else a.are_codigo = arecodigo end )and 
                                                                                              ( case when horcodigo = 0 then true else h.hor_codigo = horcodigo end  ) LOOP 
    
      
      FOR rvacaciones IN Select * from asistencias.tblpermisos_per as p inner join asistencias.tbltipopermisos_tip as t on p.tip_codigo = t.tip_codigo LOOP 
      
      IF rvacaciones.tra_codigo = r.tra_codigo THEN
             UPDATE caltemp2 SET tipo = rvacaciones.tip_nombre WHERE caltemp2.tra_codigo = rvacaciones.tra_codigo and caltemp2.fecha between rvacaciones.per_fechaini and  rvacaciones.per_fechafin;
      END IF;
      
      END LOOP;
 
 END LOOP;
 
FOR suma IN select * from  caltemp2 as c  LOOP

  IF suma.hora4 <> '00:00:00' OR suma.hora2 <> '00:00:00' THEN     
         
          IF suma.hora2 = '00:00:00' and suma.hora3 = '00:00:00' AND suma.hora1 <> '00:00:00' and suma.hora4 <> '00:00:00' THEN
             total =  CAST(suma.hora4 as TIME) - CAST(suma.hora1 as TIME);
          END IF; 
        
          IF suma.hora4 = '00:00:00' and suma.hora3 = '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora1 <> '00:00:00'  THEN
             total = CAST(suma.hora2 as TIME) - CAST(suma.hora1 as TIME);
          END IF; 
          
          IF suma.hora4 <> '00:00:00' and suma.hora3 <> '00:00:00' THEN
              total = CAST(suma.hora4 as TIME) - CAST(suma.hora3 as TIME);
          END IF;                   
          
          IF suma.hora4 <> '00:00:00' and suma.hora3 <> '00:00:00' and suma.hora2 <> '00:00:00' and suma.hora1 <> '00:00:00' THEN
               tot1 =   CAST(suma.hora3 as TIME) - CAST(suma.hora1 as TIME);
               tot2 =  CAST(suma.hora4 as TIME) - CAST(suma.hora2 as TIME);
               total =   CAST(tot2 as INTERVAL) + CAST(tot1 as INTERVAL);
          END IF;
           
        
       
       
       pue_nombre, total, ahora, extra)
       VALUES (suma.tra_codigo, suma.tra_nombre, suma.tra_apellidopaterno, suma.tra_apellidomaterno, suma.tra_dni, suma.tra_identificador,
        suma.are_nombre, suma.pue_nombre, total, ahora, suma.extra);  
 END IF;         
    
END LOOP;





 RETURN QUERY EXECUTE 'SELECT tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, SUM(CAST(total as interval)), ahora, extra 
                       FROM tareo group by tra_codigo, tra_nombre, tra_apellidopaterno, tra_apellidomaterno, tra_dni,
                       tra_identificador, are_nombre, pue_nombre, ahora, extra order by tra_apellidopaterno';
END;
$$;


ALTER FUNCTION asistencias.psgtareoall(fechaini date, fechafin date, identificador character varying, arecodigo integer, horcodigo integer) OWNER TO postgres;

--
-- Name: psgtipo(integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgtipo(par_mar_codigo integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
 tipo varchar(10); 
 DECLARE rmarca RECORD;
 DECLARE rcomparar RECORD;
 DECLARE horaSR RECORD;
 horaE time without time zone;
 existe boolean;
 hora time without time zone;
BEGIN
existe=false;
 --CREATE TEMPORARY TABLE caltemp2(
--  tip varchar(50)
 --);
 --FOR horaSR IN Select mar_fechahora::time 
 --from asistencias.tblmarcaciones_mar as mar where mar.mar_tipo = 'IR' and mar.mar_fechahora ::date = fecha and mar.tra_codigo = codigo order by mar_fechahora DESC  LIMIT  1 LOOP
--	horaE:=horaSR.mar_fechahora;
--	existe:=true;
 --END LOOP;
 
 
 SELECT mar.mar_fechahora INTO hora FROM asistencias.tblmarcaciones_mar as mar WHERE mar.mar_codigo = par_mar_codigo;
 
 FOR rmarca IN Select * from asistencias.tblfechahorario_fht as t 
 inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo 
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
 WHERE t.tra_codigo = (SELECT mar.tra_codigo FROM asistencias.tblmarcaciones_mar as mar WHERE mar.mar_codigo = par_mar_codigo)
 and d.dhr_day = to_char((SELECT mar.mar_fechahora::date FROM asistencias.tblmarcaciones_mar as mar WHERE mar.mar_codigo = par_mar_codigo), 'Day') 
 and t.fht_fecha = (SELECT mar.mar_fechahora::date FROM asistencias.tblmarcaciones_mar as mar WHERE mar.mar_codigo = par_mar_codigo)
 LOOP

	IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_ingreso) - interval '90min' AND 
	pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingreso) + interval '60min' THEN
              tipo := 'I';
	ELSE 
		IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salidarefrigerio) 
		AND pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingresorefrigerio) AND existe!= true THEN
			tipo:= 'IR';
		ELSE
			IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salidarefrigerio)  AND 
			pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingresorefrigerio) + interval '50min' THEN
				tipo:= 'SR';
			ELSE
				IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salida) - interval '25min' 
                AND pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_salida) + interval '540min' THEN --9 HORAS DESPUÉS DE LA SALIDA
					tipo := 'S';
				ELSE
					tipo := 'ST';
				END IF;
			END IF;
		END IF;
	END IF;
	
 END LOOP;

 
 RETURN tipo;
END;
$$;


ALTER FUNCTION asistencias.psgtipo(par_mar_codigo integer) OWNER TO postgres;

--
-- Name: psgtipo(character varying, integer, date); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.psgtipo(hora character varying, codigo integer, fecha date) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
 tipo varchar(10); 
 DECLARE rmarca RECORD;
 DECLARE rcomparar RECORD;
 DECLARE horaSR RECORD;
 horaE time without time zone;
 existe boolean;
BEGIN
existe=false;
 CREATE TEMPORARY TABLE caltemp2(
  tip varchar(50)
 );
 FOR horaSR IN Select mar_fechahora::time 
 from asistencias.tblmarcaciones_mar as mar where mar.mar_tipo = 'IR' and mar.mar_fechahora ::date = fecha and mar.tra_codigo = codigo order by mar_fechahora DESC  LIMIT  1 LOOP
	horaE:=horaSR.mar_fechahora;
	existe:=true;
 END LOOP;
 FOR rmarca IN Select * from asistencias.tblfechahorario_fht as t 
 inner join asistencias.tblhorarios_hor as h on t.hor_codigo = h.hor_codigo 
 inner join asistencias.tbldethorarios_dhr as d on h.hor_codigo = d.hor_codigo 
 WHERE t.tra_codigo = codigo and d.dhr_day = to_char(fecha, 'Day') and t.fht_fecha = fecha
 LOOP

	IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_ingreso) - interval '90min' AND 
	pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingreso) + interval '60min' THEN
              tipo := 'I';
	ELSE 
		IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salidarefrigerio) 
		AND pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingresorefrigerio) AND existe!= true THEN
			tipo:= 'IR';
		ELSE
			IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salidarefrigerio)  AND 
			pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingresorefrigerio) + interval '50min' THEN
				tipo:= 'SR';
			ELSE
				IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salida) - interval '25min' 
                AND pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_salida) + interval '540min' THEN --9 HORAS DESPUÉS DE LA SALIDA
					tipo := 'S';
				ELSE
					tipo := 'ST';
				END IF;
			END IF;
		END IF;
	END IF;
	
 END LOOP;

 
 
 RETURN QUERY EXECUTE 'SELECT tip FROM caltemp2';
 DROP TABLE caltemp2;
END;
$$;


