 WHERE t.tra_codigo = codigo and d.dhr_day = to_char(fecha, 'Day') and t.fht_fecha = fecha
 LOOP

	IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_ingreso) - interval '90min' AND 
	pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingreso) + interval '120min' THEN
              tipo := 'I';
	ELSE 
		IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salidarefrigerio) 
		AND pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingresorefrigerio) AND existe!=true THEN
			tipo:= 'IR';
		ELSE
			IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salidarefrigerio)  AND 
			pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_ingresorefrigerio) + interval '50min' THEN
				tipo:= 'SR';
			ELSE
				IF pg_catalog.time(hora) >= pg_catalog.time(rmarca.dhr_salida) - interval '25min' 
                AND pg_catalog.time(hora) <= pg_catalog.time(rmarca.dhr_salida) + interval '540min' THEN --9 HORAS DESPUÉS DE LA SALIDA
					tipo := 'S';
				ELSE
					tipo := 'ST';
				END IF;
			END IF;
		END IF;
	END IF;
	
 END LOOP;

 
 
 RETURN QUERY EXECUTE 'SELECT tip FROM caltemp2';
 DROP TABLE caltemp2;
END;
$$;


