--
-- Name: tipo_corregir(character varying, character varying, integer); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.tipo_corregir(fechaini character varying, fechafin character varying, codigo integer) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$DECLARE

 
 DECLARE Marca RECORD;
declare tipo character varying;
 declare resultado varchar;
BEGIN

resultado ='Error';


 FOR Marca IN Select mar.mar_codigo ,mar.tra_codigo,mar.mar_fechahora::date as fecha,mar.mar_fechahora::time as hora, mar_tipo from asistencias.tblmarcaciones_mar as mar 
where mar.mar_tipo = 'ST' and (case when codigo = 0 then true else mar.tra_codigo=codigo end ) and (case when fechaini<> '' and fechafin <> '' then mar.mar_fechahora::date between fechaini::date  and fechafin::date else true end) order by mar_fechahora DESC   LOOP

	tipo = (select * from asistencias.psgtipo(Marca.hora::character varying,Marca.tra_codigo,Marca.fecha));	

	UPDATE asistencias.tblmarcaciones_mar
		SET mar_tipo=tipo
	WHERE mar_codigo=Marca.mar_codigo;

 END LOOP;
 
 

 resultado ='OK';
 RETURN QUERY  select resultado;
END;$$;


ALTER FUNCTION asistencias.tipo_corregir(fechaini character varying, fechafin character varying, codigo integer) OWNER TO postgres;

--
-- Name: verificar_permisospordia(character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.verificar_permisospordia(cod_trabajador character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  DECLARE flag BOOLEAN=TRUE;
  DECLARE count INT;
BEGIN

SELECT count(*) into count FROM asistencias.tblpermisos_per p 
INNER JOIN asistencias.tbltipopermisos_tip t on p.tip_codigo=t.tip_codigo 
INNER JOIN asistencias.tbltrabajadores_tra b on b.tra_codigo=p.tra_codigo  
WHERE T.tip_escalat=TRUE 
AND (CURRENT_DATE BETWEEN p.per_fechaini and p.per_fechafin)
AND b.tra_identificador=cod_trabajador;

if count=0 THEN
flag=FALSE;
end if;

if count>=1 THEN
flag=true;
end if;
  
return flag;
END;
$$;


ALTER FUNCTION asistencias.verificar_permisospordia(cod_trabajador character varying) OWNER TO postgres;

