-- Name: verificar_permisosporhora(character varying); Type: FUNCTION; Schema: asistencias; Owner: postgres
--

CREATE FUNCTION asistencias.verificar_permisosporhora(cod_trabajador character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  DECLARE flag BOOLEAN=TRUE;
  DECLARE count INT;
BEGIN

SELECT count(*)into count FROM asistencias.tblpermisos_per p 
INNER JOIN asistencias.tbltipopermisos_tip t on p.tip_codigo=t.tip_codigo 
INNER JOIN asistencias.tbltrabajadores_tra b on b.tra_codigo=p.tra_codigo  
WHERE T.tip_escalat=false 
AND (CURRENT_TIMESTAMP BETWEEN p.per_fechaini and p.per_fechafin)
AND b.tra_identificador=cod_trabajador ;

if count=0 THEN
flag=FALSE;
end if;

if count>=1 THEN
flag=true;
end if;
  
return flag;
END;
$$;


