--
-- Name: dia_semana(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dia_semana(date) RETURNS character varying
    LANGUAGE sql IMMUTABLE
    AS $_$
select case extract(dow from $1)
when 0 then 'Domingo'
when 1 then 'Lunes'
when 2 then 'Martes'
when 3 then 'Miercoles'
when 4 then 'Jueves'
when 5 then 'Viernes'
when 6 then 'Sabado'
else ''
end;
$_$;


